# ── Shared helpers ────────────────────────────────────────────────────────────
def _json_default(o):
    """Last-resort JSON encoder for stray DB-native types so a single non-primitive
    value (a UUID primary key, a datetime, a Decimal) can never 500 an ENTIRE
    response. Purely additive: today these types RAISE TypeError in json.dumps —
    this turns the crash into a sane string/number. (Found in prod 2026-06-26:
    intent/history returned CombatLog.id as a UUID and 500'd the whole endpoint.)"""
    import uuid as _uuid
    from datetime import datetime as _dt, date as _date
    from decimal import Decimal as _Dec
    if isinstance(o, _uuid.UUID):
        return str(o)
    if isinstance(o, (_dt, _date)):
        return o.isoformat()
    if isinstance(o, _Dec):
        return float(o)
    raise TypeError(f"Object of type {o.__class__.__name__} is not JSON serializable")


def _json(data: dict, status: int = 200) -> web.Response:
    # SEC (2026-06-01): never leak exception internals to the client. ~29 handlers
    # historically returned {"error_class","error_msg"} on internal_error, exposing
    # SQLAlchemy/PostgreSQL details. Strip them at this single chokepoint — the
    # server-side logger.exception in each handler already captures the detail.
    if isinstance(data, dict) and ("error_class" in data or "error_msg" in data):
        data = {k: v for k, v in data.items() if k not in ("error_class", "error_msg")}
    # Robust serialization: a UUID/datetime/Decimal anywhere in the payload would
    # otherwise raise inside web.json_response and 500 the whole response.
    return web.json_response(
        data, status=status,
        dumps=lambda d: json.dumps(d, default=_json_default))


def _err(code: str, status: int, message: str | None = None) -> web.Response:
    body = {"error": code}
    if message:
        body["message"] = message
    return _json(body, status=status)


def _origin_note(kind: str, item_id: int, lang: str, continent) -> dict | None:
    """MV-9.5 — a disclosure geográfica de UM material, server-resolved.

    Hoje NÃO existe uma única tela em todo o Nivrael que diga onde nasce o
    material que falta na receita: o `Iron Skin Pill` fica cinzento no reino 2
    e o jogo não diz porquê nem onde. Esta é a resposta literal ao *"the world
    is divided likewise the locations to dungeons"* do [jogador].

    Devolve `None` com a flag OFF ⇒ o chamador não emite a key ⇒ o payload dos
    239 do `main` fica byte-idêntico. Nunca levanta — é chamado dentro de loops
    quentes que desenham catálogos inteiros.
    """
    try:
        from core.caravan_engine import origin_note
        return origin_note(str(kind), int(item_id), str(lang or "pt"), continent)
    except Exception:
        logger.debug("origin note failed kind=%s id=%s", kind, item_id, exc_info=True)
        return None


def _prof_xp_payload(player, before: int | None, tier=None) -> dict:
    """QoL-relatos — as keys do XP de ofício no payload, TODAS condicionais.

    Devolve ``{}`` quando não houve ganho (flag `profissoes` OFF ou jogador sem
    ofício), logo ``**_prof_xp_payload(...)`` contribui ZERO bytes e o payload
    do `main` continua byte-idêntico (lição MV-7: payload key nova = SEMPRE
    condicional). UM helper para os 4 pontos de emissão (craft single, craft
    bulk, forja, tribulação) em vez de repetir a idiom quatro vezes.

    `prof_weight_tier`/`prof_weight` só entram quando o tier é conhecido — o
    resumo usa-os para explicar POR QUE o número subiu mais (Lei §10); sem
    eles a superfície cai na linha antiga em vez de mentir um "tier 0".
    """
    from core.profession_engine import prof_weight, prof_xp_delta
    gained = prof_xp_delta(player, before)
    if gained <= 0:
        return {}
    out: dict = {"prof_xp_gained": int(gained)}
    w_tier, w = prof_weight(tier)
    if w_tier:
        out["prof_weight_tier"] = int(w_tier)
        out["prof_weight"] = f"{w:g}"
    return out


def _spirit_root_label(idx: int) -> tuple[str, str]:
    name = SPIRIT_ROOT_NAMES[idx] if 0 <= idx < len(SPIRIT_ROOT_NAMES) else "Low"
    info = SPIRIT_ROOTS.get(name, {})
    return name, info.get("emoji", "🪨")


def _realm_label(realm: int) -> tuple[str, str]:
    name = REALM_NAMES[realm] if 0 <= realm < len(REALM_NAMES) else "Mortal"
    emoji = REALM_EMOJIS[realm] if 0 <= realm < len(REALM_EMOJIS) else "🪨"
    return name, emoji


def _ms(dt: datetime | None) -> int | None:
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return int(dt.timestamp() * 1000)


def _display_name(player: Player) -> str:
    return player.dao_name or player.display_name or player.username or "Cultivator"


# ── Per-user rate limiter (SEC 2026-06-01) ────────────────────────────────────
# Defense-in-depth against headless automation (a player replaying their own
# valid init_data at machine speed) and against hammering reward/claim endpoints.
# Single-worker deploy → in-process token bucket keyed by validated user_id is
# sufficient (move to Redis if the webserver is ever scaled to >1 worker).
from time import monotonic as _monotonic
_RATE_CAPACITY = 15.0       # burst allowance per user
_RATE_REFILL_PER_SEC = 8.0  # sustained requests/sec per user
_rate_buckets: dict[int, list] = {}  # user_id -> [tokens, last_ts]


def _rate_allow(user_id: int) -> bool:
    """Token-bucket throttle. Returns False when the user is over budget."""
    now = _monotonic()
    b = _rate_buckets.get(user_id)
    if b is None:
        _rate_buckets[user_id] = [_RATE_CAPACITY - 1.0, now]
        # opportunistic prune so the dict can't grow unbounded over a long uptime
        if len(_rate_buckets) > 5000:
            stale = [u for u, (_, ts) in _rate_buckets.items() if now - ts > 300]
            for u in stale:
                _rate_buckets.pop(u, None)
        return True
    tokens = min(_RATE_CAPACITY, b[0] + (now - b[1]) * _RATE_REFILL_PER_SEC)
    b[1] = now
    if tokens < 1.0:
        b[0] = tokens
        return False
    b[0] = tokens - 1.0
    return True


# ── Per-IP rate limiter (WEB-A 2026-08-19) ────────────────────────────────────
# A vitrine pública não tem `user_id` — o balde de cima não a pode defender. Aqui
# a chave é o IP (X-Forwarded-For à frente do Coolify, o mesmo que o anti-bot já
# lê). Muito mais apertado que o balde autenticado de propósito: a página faz UM
# pedido por carregamento, logo 10 de rajada + 0,5/s sustentado é folgado para um
# humano a recarregar e estreito para um scraper.
_IP_RATE_CAPACITY = 10.0
_IP_RATE_REFILL_PER_SEC = 0.5
_ip_buckets: dict[str, list] = {}  # ip -> [tokens, last_ts]


def _client_ip(request: web.Request) -> str:
    """O IP do visitante. `X-Forwarded-For` pode trazer a cadeia inteira
    (`cliente, proxy1, proxy2`) — o primeiro elemento é o cliente."""
    xff = request.headers.get("X-Forwarded-For") or ""
    if xff:
        return xff.split(",", 1)[0].strip()[:64]
    return (request.remote or "?")[:64]


# WEB-B Fase 1 — balde PRÓPRIO para `/api/auth/*`. Mesmos números, dict separado:
# um visitante a folhear a vitrine não pode gastar as fichas do seu próprio login,
# nem o contrário. (O balde da vitrine fica exactamente como estava.)
_auth_ip_buckets: dict[str, list] = {}


def _ip_rate_allow(ip: str, buckets: dict | None = None) -> bool:
    """Token-bucket por IP. False quando o visitante passou do orçamento."""
    if buckets is None:
        buckets = _ip_buckets
    now = _monotonic()
    b = buckets.get(ip)
    if b is None:
        buckets[ip] = [_IP_RATE_CAPACITY - 1.0, now]
        if len(buckets) > 5000:
            stale = [k for k, (_, ts) in buckets.items() if now - ts > 300]
            for k in stale:
                buckets.pop(k, None)
        return True
    tokens = min(_IP_RATE_CAPACITY, b[0] + (now - b[1]) * _IP_RATE_REFILL_PER_SEC)
    b[1] = now
    if tokens < 1.0:
        b[0] = tokens
        return False
    b[0] = tokens - 1.0
    return True


# ── WEB-A — a allowlist da vitrine pública ────────────────────────────────────
# ⚠️ ALLOWLIST EXPLÍCITA, NUNCA "tudo o que não escreve". O RECON pediu um 3º
# estado no middleware (pedido SEM credencial); ele vive num PREFIXO PRÓPRIO
# (`/api/vitrine/`) em vez de um conjunto de exceções dentro de
# `/api/miniapp/`. A diferença importa: com o prefixo separado, esquecer de
# atualizar a lista nunca pode expor um handler autenticado — os 261 endpoints
# do jogo continuam a exigir HMAC por não terem outro caminho até eles. Um path
# `/api/vitrine/*` fora desta lista é 404, não "público por omissão".
VITRINE_PUBLIC_PATHS = frozenset({"/api/vitrine/world"})


# ── WEB-B Fase 1 — a allowlist da PORTA (2026-08-21) ─────────────────────────
# Mesmo molde e mesmo motivo do WEB-A: prefixo PRÓPRIO (`/api/auth/`) com lista
# explícita. Estes três caminhos são os únicos alcançáveis sem uma credencial já
# formada — e vivem fora do `/api/miniapp/`, portanto esquecer de actualizar esta
# lista nunca pode expor um handler autenticado. Um `/api/auth/*` fora da lista é
# 404, nunca "público por omissão".
#
# ⚠️ `/api/auth/me` e `/api/auth/logout` EXIGEM o par cookie+header como qualquer
# endpoint do jogo — "público" aqui significa *sem init_data*, não *sem prova*.
AUTH_PUBLIC_PATHS = frozenset({
    "/api/auth/telegram",
    # WEB-B Fase 2 — Google · Apple · e-mail/senha, todos pelo MESMO caminho:
    # os três produzem um ID token do Firebase e a diferença entre eles é uma
    # claim (`sign_in_provider`), não um endpoint. Um endpoint por provider era
    # três superfícies públicas para verificar a mesma assinatura.
    "/api/auth/firebase",
    "/api/auth/logout",
    "/api/auth/me",
})


# ── Auth middleware ───────────────────────────────────────────────────────────
@web.middleware
async def auth_middleware(request: web.Request, handler: Callable[[web.Request], Awaitable[web.StreamResponse]]):
    """Validate init_data on /api/miniapp/* endpoints and attach user_id.

    WEB-A (2026-08-19) — o 3º estado: `/api/vitrine/*` é servido SEM credencial,
    com limitação por IP e com o mundo da vitrine ligado.

    WEB-B Fase 1 (2026-08-21) — o 4º estado, e a ORDEM é o contrato:

        /api/vitrine/*  → sem credencial (WEB-A, intocado)
        /api/auth/*     → a porta: forma uma credencial (allowlist própria)
        /api/miniapp/*  → 1) init_data válido        ← o Telegram de hoje, INTOCADO
                          2) senão: cookie + header  ← a sessão web
                          3) senão: 401

    ⚠️ **O ramo 1 não muda uma linha.** É o que garante que os 248 que jogam hoje
    pelo Telegram não sentem absolutamente nada. O ramo 2 só é alcançado quando
    NÃO há `init_data` válido — logo é inerte para quem entra pelo Telegram. E o
    limitador por `user_id` continua a aplicar-se depois de resolvida a
    identidade, venha ela do HMAC ou do cookie.
    """
    path = request.path

    if path.startswith("/api/auth/"):
        # A PORTA. Sem `user_id` ainda (é o que estes endpoints existem para
        # descobrir), logo a limitação é por IP — no balde próprio do auth.
        if path not in AUTH_PUBLIC_PATHS:
            return _err("not_found", 404)
        if request.method == "OPTIONS":
            return web.Response(status=204, headers={
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Headers": "Content-Type, X-Nivrael-Session",
                "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
            })
        if request.method not in ("GET", "POST"):
            return _err("method_not_allowed", 405)
        if not _ip_rate_allow(_client_ip(request), _auth_ip_buckets):
            return _err("rate_limited", 429)
        # `user_id = None` explícito, como na vitrine: um handler que o leia como
        # id parte de imediato em vez de servir dados de outra pessoa. E NENHUM
        # mundo é ligado aqui — a porta fala só com o plano de controlo, e quem
        # decide o mundo continua a ser `player_active_server` (LEI DUAL-SURFACE).
        request["user_id"] = None
        return await handler(request)

    if path.startswith("/api/vitrine/"):
        if path not in VITRINE_PUBLIC_PATHS:
            return _err("not_found", 404)
        if request.method == "OPTIONS":
            return web.Response(status=204, headers={
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Headers": "Content-Type",
                "Access-Control-Allow-Methods": "GET, OPTIONS",
            })
        if request.method != "GET":
            return _err("method_not_allowed", 405)
        if not _ip_rate_allow(_client_ip(request)):
            return _err("rate_limited", 429)
        # `user_id = None` é o 3º estado explícito: um handler que o leia como se
        # fosse um id parte de imediato em vez de servir dados de outra pessoa.
        request["user_id"] = None
        from core.vitrine import vitrine_world_key
        from database.db import reset_current_world, set_current_world
        world_key = vitrine_world_key()
        request["world_key"] = world_key
        token = set_current_world(world_key)
        try:
            return await handler(request)
        finally:
            reset_current_world(token)

    if not path.startswith("/api/miniapp/"):
        return await handler(request)

    if request.method == "OPTIONS":
        return web.Response(status=204, headers={
            "Access-Control-Allow-Origin": "*",
            "Access-Control-Allow-Headers": "Content-Type",
            "Access-Control-Allow-Methods": "POST, OPTIONS",
        })

    if request.method != "POST":
        return _err("method_not_allowed", 405)

    try:
        payload = await request.json()
    except Exception:
        return _err("bad_json", 400)

    init_data = payload.get("init_data") or ""
    # Sanitize: env vars copy-pasted into Coolify often gain trailing whitespace,
    # newlines, or quote characters. The python-telegram-bot library tolerates
    # some of these; HMAC does not.
    bot_token = os.getenv("BOT_TOKEN", "").strip().strip('"').strip("'")

    # ── RAMO 1 — o Telegram de hoje. INTOCADO. ────────────────────────────────
    # Um `init_data` VÁLIDO resolve a identidade exactamente como antes de
    # 2026-08-21: mesmo validador, mesmo `user`, mesmo log, mesmo throttle. O
    # único acrescento é NÃO devolver 401 aqui dentro — o 401 mudou de sítio (é
    # agora o fim do ramo 2), para que a ausência de `init_data` possa ser uma
    # sessão web em vez de uma recusa.
    user_id = None
    user = {}
    if init_data:
        try:
            parsed = validate_init_data(init_data, bot_token)
        except InitDataError as exc:
            # Generic 401 — don't leak which exact check failed to attackers.
            # Log lengths (not the values themselves) so we can diagnose without
            # leaking the token or initData to the log file.
            # Bot id (the digits before the ':' in the token) is NOT secret —
            # it's visible in @bot links — but it lets us compare against
            # BotFather without leaking the secret half.
            bot_id = bot_token.split(":", 1)[0] if ":" in bot_token else "(no-colon)"
            logger.warning(
                "initData rejected on %s: %s [token_len=%d, bot_id=%s, init_data_len=%d]",
                path, exc, len(bot_token), bot_id, len(init_data),
            )
        else:
            candidate = (parsed.get("user") or {}).get("id")
            if isinstance(candidate, int) and candidate > 0:
                # ⚠️ VÍNCULO (2026-08-26): o `telegram_id` deixou de ser o
                # `player_id` por definição. Quem ligou a conta do Google tem o
                # personagem noutro id — resolver aqui é o que faz "a mesma
                # conta em qualquer plataforma" ser verdade em vez de slogan.
                #
                # Para os 248 isto é um no-op MEDIDO: o backfill aponta cada
                # `telegram:<id>` ao próprio `<id>`, e qualquer falha devolve o
                # `candidate` cru. A validação do HMAC acima não mudou.
                try:
                    from database.control_db import resolve_identity_player_id
                    user_id = await resolve_identity_player_id(
                        "telegram", str(candidate), candidate)
                except Exception:
                    logger.warning("resolução de identidade falhou — id cru",
                                   exc_info=True)
                    user_id = candidate
                user = parsed.get("user") or {}

    # ── RAMO 2 — a sessão web (WEB-B Fase 1). Só se o ramo 1 não resolveu. ────
    # Nunca corre para quem entra pelo Telegram: dentro do Telegram o cliente
    # manda sempre `init_data`, e um `init_data` válido já terminou acima. Um
    # pedido sem cookie — ou COM cookie e sem header — cai no 401 de sempre: o
    # cookie sozinho não autentica.
    if user_id is None:
        try:
            from core.web_session import verify_request_session
            web_sess = await verify_request_session(request)
        except Exception:
            logger.warning("sessão web: verificação falhou em %s", path, exc_info=True)
            web_sess = None
        if web_sess is not None:
            user_id = web_sess.player_id
            # `world/start` lê `tg_user` para nomear o personagem novo. Na web o
            # snapshot vem do widget, gravado no login — o mesmo campo e a mesma
            # forma, para o handler não saber por que porta o jogador entrou.
            user = dict(web_sess.tg_user or {})
            user.setdefault("id", user_id)
            request["web_session"] = web_sess

    if user_id is None:
        return _err("unauthorized", 401)

    # SEC (2026-06-01): per-user throttle (after auth so it's keyed on the
    # HMAC-validated user_id, not a spoofable header). Blunts automation + spam.
    # WEB-B: aplica-se igual à identidade vinda do cookie — a porta muda, o
    # orçamento não.
    if not _rate_allow(user_id):
        return _err("rate_limited", 429)

    request["user_id"] = user_id
    request["tg_user"] = user  # validated Telegram user (id/username/first_name) — not spoofable
    request["payload"] = payload  # let handlers read additional fields

    # ── Multi-Servidor (Fase 2): resolve the player's ACTIVE game world and bind
    # it for the duration of THIS request. The ~628 DB call-sites then route to
    # that world via get_session_factory() with ZERO per-handler changes.
    #
    # • Control/admin routes are world-agnostic (they speak to the control DB, not
    #   a game world) → they SKIP world binding entirely.
    # • Degrade-to-main on ANY error (Lei §1/§5): a control-plane hiccup must never
    #   500 a player. resolve_active_world already falls back to "main" internally;
    #   the outer try/except is belt-and-suspenders.
    # • ContextVar is task-local → the finally-reset is MANDATORY so a world never
    #   leaks between concurrent requests. When CONTROL_DATABASE_URL is unset,
    #   resolve_active_world returns "main" with no DB hit → behaviour is identical
    #   to the single-world deployment.
    if path.startswith("/api/miniapp/lobby/") or path.startswith("/api/miniapp/admin/"):
        return _refresh_session_cookies(request, await handler(request))

    from database.db import set_current_world, reset_current_world
    try:
        from database.control_db import resolve_active_world
        world_key = await resolve_active_world(user_id)
    except Exception:
        logger.warning("world resolution failed for %s — using main", user_id, exc_info=True)
        world_key = "main"
    world_key = world_key or "main"
    request["world_key"] = world_key  # let handlers report the active world cheaply
    token = set_current_world(world_key)
    try:
        resp = await handler(request)
    finally:
        reset_current_world(token)
    return _refresh_session_cookies(request, resp)


def _refresh_session_cookies(request: web.Request, resp: web.StreamResponse) -> web.StreamResponse:
    """Escreve o cookie renovado, quando (e só quando) a janela deslizou.

    No-op absoluto para quem entrou pelo `init_data`: sem `web_session` no
    request não há nada a escrever. E `verify_session` só marca
    `refreshed_cookie` uma vez por hora, portanto isto quase nunca escreve."""
    sess = request.get("web_session")
    if sess is None or not getattr(sess, "refreshed_cookie", None):
        return resp
    try:
        from core.web_session import set_session_cookies
        set_session_cookies(resp, sess.refreshed_cookie, sess.refreshed_csrf, sess.expires_at)
    except Exception:
        # Falhar a renovar é benigno (a sessão continua válida até expirar);
        # falhar a RESPOSTA não seria. Lei §1.
        logger.warning("renovação do cookie de sessão falhou", exc_info=True)
    return resp


# ── 語 A LÍNGUA DAS SUPERFÍCIES PÚBLICAS ──────────────────────────────────────
#
# Report do owner (2026-09-02): *"Idiomas todos rotos mezclados etc, e isso o
# jogador precisa decidir o idioma quando abre o site."*
#
# ⚠️ MEDIDO antes de escrever código: a DETECÇÃO estava certa. Um browser em
# `pt-BR` recebia `<html lang="pt">`, um em `es-ES` recebia `es`. O sistema fez
# exactamente o que foi desenhado. **O que faltava era a SAÍDA** — a porta não
# desenhava um único seletor, e quem caísse na língua errada ficava preso na
# entrada do jogo (Lei §1 partida no pior sítio possível).
#
# E faltava a segunda metade, que é a que produz o *"mezclados"*: mesmo
# escolhendo, a escolha **morria no primeiro clique**. Sem memória entre pedidos
# o servidor voltava ao `Accept-Language` na página seguinte, e o personagem
# novo nascia com a língua do browser em vez da língua escolhida.
#
# O cookie é o que faz a escolha **viajar**: é lido no primeiro byte (nada de
# flash na língua errada, que o `localStorage` não consegue evitar numa página
# renderizada no servidor) e viaja sozinho até ao `/api/auth/firebase`, onde o
# personagem nasce. Uma preferência de idioma não é credencial: não é
# `HttpOnly` (o cliente também a lê) e não é segredo nenhum.
LANG_COOKIE_NAME = "nv_lang"
LANG_COOKIE_MAX_AGE = 60 * 60 * 24 * 365  # um ano: é uma preferência, não uma sessão


def public_lang(request: web.Request) -> str:
    """A língua de uma superfície pública, por ordem de autoridade.

    1. `?lang=` — a escolha EXPLÍCITA de agora manda sempre.
    2. `nv_lang` — a escolha EXPLÍCITA de antes (é isto que faz a escolha durar).
    3. `Accept-Language` — o browser dele.
    4. `PUBLIC_DEFAULT_LANG` (inglês).

    ⚠️ O cookie entra ACIMA do `Accept-Language` de propósito: quem clicou
    disse-o em voz alta, e o browser nunca deve ganhar a uma escolha feita à
    mão — era exactamente esse o *"mezclados"*. Fica ABAIXO do `?lang=` porque
    um link partilhado com língua explícita tem de continuar a valer.
    """
    from core.vitrine import pick_public_lang, SUPPORTED_LANGS
    explicit = str(request.query.get("lang") or "").strip().lower()
    explicit = explicit.replace("_", "-").split("-", 1)[0]
    if explicit in SUPPORTED_LANGS:
        return explicit
    saved = str(request.cookies.get(LANG_COOKIE_NAME) or "").strip().lower()
    if saved in SUPPORTED_LANGS:
        return saved
    return pick_public_lang(None, request.headers.get("Accept-Language"))


def remember_lang(response, request: web.Request, lang: str) -> None:
    """Grava a escolha — mas SÓ quando ela foi explícita (`?lang=`).

    ⚠️ Escrever o cookie em toda a visita transformaria uma DETECÇÃO num
    COMPROMISSO: alguém que caísse em espanhol por causa do browser ficaria
    espanhol para sempre, mesmo depois de mudar o browser. O cookie existe para
    guardar o clique, não o palpite — e por isso só nasce do `?lang=`.
    """
    from core.vitrine import SUPPORTED_LANGS
    chosen = str(request.query.get("lang") or "").strip().lower()
    chosen = chosen.replace("_", "-").split("-", 1)[0]
    if chosen not in SUPPORTED_LANGS or chosen != lang:
        return
    try:
        from core.web_session import cookie_secure
        secure = cookie_secure()
    except Exception:
        secure = True
    try:
        response.set_cookie(LANG_COOKIE_NAME, lang, max_age=LANG_COOKIE_MAX_AGE,
                            httponly=False, secure=secure, samesite="Lax", path="/")
    except Exception:
        # Guardar a preferência é conforto; falhar a servir a página não seria.
        logger.debug("nv_lang: não foi possível gravar o cookie", exc_info=True)


# ── Static file serving ───────────────────────────────────────────────────────
# Tipos de TEXTO — os únicos que vale a pena comprimir. Um PNG/WebP/woff2 já vem
# comprimido: gzipá-lo gasta CPU do servidor para ~0% de ganho (às vezes cresce).
_COMPRESSIBLE_SUFFIXES = frozenset({
    ".js", ".mjs", ".css", ".html", ".htm", ".json", ".webmanifest",
    ".svg", ".xml", ".txt", ".map",
})


async def _serve_file(path: Path, *, cache: str | None = None) -> web.Response:
    if not path.is_file():
        return _err("not_found", 404)
    ctype, _ = mimetypes.guess_type(str(path))
    if ctype is None:
        ctype = "application/octet-stream"
    headers = {}
    if cache:
        headers["Cache-Control"] = cache
    # SPA index — must never be cached, otherwise users keep stale HTML pointing
    # at deleted hashed assets.
    if path.name == "index.html":
        headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    resp = web.FileResponse(path=path, headers=headers)
    # PERF 2026-08-25 (report do owner: "demora MUITO no telefone"). Até aqui o
    # servidor não comprimia NADA e o `dist` não traz assets pré-comprimidos —
    # o bundle do site saía com 568 KB onde 189 KB chegavam. MEDIDO:
    #   index.js 568->189 KB (-67%) · index.css 91->15 KB (-83%)
    # `enable_compression()` sem argumento NEGOCEIA: um cliente que mande
    # `Accept-Encoding: identity` continua a receber os bytes crus (verificado).
    if path.suffix.lower() in _COMPRESSIBLE_SUFFIXES:
        try:
            resp.enable_compression()
        except Exception:
            # Comprimir é optimização; falhar a servir o ficheiro não seria.
            logger.debug("compressão indisponível para %s", path.name, exc_info=True)
    return resp


async def serve_website_root(request: web.Request) -> web.Response:
    """nivrael.com/ — landing page from website/dist (Vite build)."""
    index = WEBSITE_DIST / "index.html"
    if index.is_file():
        return await _serve_file(index)
    # Fallback: dist not built yet (dev). Show a minimal placeholder.
    body = (
        "<!doctype html><meta charset=utf-8>"
        "<title>Nivrael</title>"
        "<style>body{background:#06080f;color:#e2eaff;font:16px system-ui;display:grid;"
        "place-items:center;height:100vh;margin:0;text-align:center}</style>"
        "<div><h1>☯️ Nivrael</h1><p>O caminho da imortalidade aguarda.</p>"
        "<p><a href='https://t.me/Nivrael_RPG' style='color:#c9903a'>Junta-te no Telegram</a></p></div>"
    )
    return web.Response(text=body, content_type="text/html")


async def serve_website_assets(request: web.Request) -> web.Response:
    """website/dist/assets/<file> — Vite hashed bundles. Immutable cache."""
    name = request.match_info["name"]
    # Reject path traversal — Path() resolves "..", but defense in depth.
    if "/" in name or "\\" in name or ".." in name:
        return _err("not_found", 404)
    path = WEBSITE_DIST / "assets" / name
    return await _serve_file(path, cache="public, max-age=31536000, immutable")


async def serve_website_root_file(request: web.Request) -> web.Response:
    """Top-level public files: favicon, manifest, sitemap, OG image, realm pngs."""
    name = request.match_info["name"]
    if "/" in name or "\\" in name or ".." in name:
        return _err("not_found", 404)
    suffix = Path(name).suffix.lower()
    if suffix not in ALLOWED_ROOT_EXTENSIONS:
        return _err("not_found", 404)
    path = WEBSITE_DIST / name
    return await _serve_file(path, cache="public, max-age=86400")


async def serve_miniapp(request: web.Request) -> web.Response:
    """/miniapp — Telegram WebApp HTML. Must be no-cache so updates ship."""
    return await _serve_file(MINIAPP_DIR / "index.html")


