def firebase_web_config() -> dict:
    """A configuração do cliente Firebase, para injectar na porta.

    ⚠️ **NADA disto é secreto** e não é um descuido — é como o Firebase é
    desenhado. A `apiKey` identifica o projecto, não autoriza nada: quem a tiver
    consegue, no máximo, criar uma conta no nosso projecto, que é exactamente o
    que o botão público já faz. Quem protege os dados é a verificação do ID
    token do lado do servidor (`core/firebase_auth.py`) — nunca o segredo destes
    valores. 開 Na edição comunitária NÃO há defaults: cada instância usa o seu
    projecto (`FIREBASE_*` no `.env`), ou não oferece Google/Apple/e-mail.
    """
    pid = (os.getenv("FIREBASE_PROJECT_ID") or "").strip()
    return {
        "apiKey": (os.getenv("FIREBASE_API_KEY") or "").strip(),
        "authDomain": (os.getenv("FIREBASE_AUTH_DOMAIN") or "").strip()
                      or (f"{pid}.firebaseapp.com" if pid else ""),
        "projectId": pid,
        "appId": (os.getenv("FIREBASE_APP_ID") or "").strip(),
    }


def login_bot_username() -> str:
    """O @ do bot para o widget. Env `LOGIN_BOT_USERNAME` manda; senão deriva-se
    do link que a vitrine já usa (Lei §6 — default assado, sem quiz ao owner)."""
    forced = (os.getenv("LOGIN_BOT_USERNAME") or "").strip().lstrip("@")
    if forced:
        return "".join(c for c in forced if c.isalnum() or c == "_")[:64]
    try:
        from core.vitrine import CTA_BOT_URL
        tail = (CTA_BOT_URL or "").rstrip("/").rsplit("/", 1)[-1]
    except Exception:
        tail = ""
    tail = "".join(c for c in tail if c.isalnum() or c == "_")[:64]
    return tail or "Nivrael_bot"


# ── As URLs oficiais são INGLESAS (owner 2026-08-26) ─────────────────────────
#
# *"Quero global, quero inglês. Se tiver alguma coisa em português ou espanhol,
# fora — digo as URLs."* O conteúdo do jogo continua nos 3 idiomas; só o
# ENDEREÇO é que passou a ter uma forma só.
#
# ⚠️ Mas um link que já circulou não se parte (a regra que a F1 escreveu no
# `identidade.md` §4.5). Por isso os antigos `/jogar` `/mundo` `/entrar`
# deixam de SERVIR a página e passam a **301 Moved Permanently** para a
# canónica: quem tem o link antigo continua a chegar, o browser aprende o novo,
# e o Google deixa de indexar três endereços para a mesma página (que é
# conteúdo duplicado e divide o valor do domínio). Uma redirecção é a única
# forma de "tirar de circulação" sem partir nada.
_LEGACY_ROUTE_REDIRECTS = {
    "/jogar": "/play",
    "/jogar/": "/play",
    "/mundo": "/play",
    "/mundo/": "/play",
    "/entrar": "/login",
    "/entrar/": "/login",
    "/privacidade": "/privacy",
    "/privacidade/": "/privacy",
    "/termos": "/terms",
    "/termos/": "/terms",
}


def _permanent_redirect(target: str):
    """Devolve um handler que faz 301 para `target`, preservando a query.

    A query sobrevive de propósito: `/entrar?lang=pt&next=/app` tem de continuar
    a valer depois do salto, senão a redirecção "não parte links" só na aparência.
    """
    async def _handler(request: web.Request) -> web.Response:
        qs = request.query_string
        raise web.HTTPMovedPermanently(location=f"{target}?{qs}" if qs else target)
    return _handler


async def serve_web_login(request: web.Request) -> web.Response:
    """/login (e o sinónimo /entrar) — WEB-B Fase 1: a porta.

    Página autónoma, pelo mesmo motivo do `serve_vitrine`: quem chega aqui não
    tem sessão nenhuma, e o mini-app inteiro assume um jogador.

    Renderizada no servidor por uma razão de contrato, não de gosto: assim a
    página tem **zero copy** (as strings vêm das mesmas 3 locales que o resto do
    jogo) e não é preciso um 4º endpoint público só para as ir buscar. `lang` sai
    do `?lang=` ou do `Accept-Language`, com o fallback da casa (PT).

    Nunca 500: uma porta de entrada partida é a pior das saídas (Lei §1). Se a
    renderização falhar, serve-se o ficheiro cru — o widget continua lá.
    """
    path = MINIAPP_DIR / "login.html"
    if not path.is_file():
        return _err("not_found", 404)
    try:
        from core.i18n import t as i18n_t
        # `?lang=` manda; depois a escolha guardada; depois o browser; depois
        # inglês (owner 2026-08-26). A versão antiga fazia `.split(",")[0]`,
        # que lia só o PRIMEIRO tag do header e ignorava os `q=` — um
        # `de,en;q=0.9` caía no default em vez de cair em inglês.
        lang = public_lang(request)
        html = path.read_text(encoding="utf-8")
        strings = {k: i18n_t(lang, k) for k in WEB_LOGIN_KEYS}
        # O seletor tem de saber para onde apontar sem perder o `next`: quem
        # chega a `/login?next=/app` e troca de língua não pode ser despejado
        # noutro destino (seria a Lei §1 partida pelo próprio conserto).
        _nxt = str(request.query.get("next") or "")
        lang_links = {}
        for _code in ("pt", "en", "es"):
            _qs = {"lang": _code}
            if _nxt:
                _qs["next"] = _nxt
            lang_links[_code] = "/login?" + urlencode(_qs)

        def _in_script(obj) -> str:
            """JSON seguro DENTRO de um <script>. `json.dumps` não escapa
            `</script>` — hoje estas strings vêm das nossas locales e não do
            visitante, logo não é explorável; escapar `<` fecha a categoria
            antes de alguém tornar uma destas strings dinâmica."""
            return json.dumps(obj, ensure_ascii=False).replace("<", "\\u003c")

        html = (html
                .replace("{{LANG}}", lang)
                .replace("{{LANGS}}", _in_script(
                    {"current": lang, "links": lang_links,
                     "labels": {"pt": "Português", "en": "English", "es": "Español"}}))
                .replace("{{TITLE}}", strings["web_login_title"]
                         .replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))
                .replace("{{STRINGS}}", _in_script(strings))
                .replace("{{BOT}}", _in_script(login_bot_username()))
                .replace("{{FIREBASE}}", _in_script(firebase_web_config())))
    except Exception:
        logger.exception("serve_web_login: render falhou — a servir o ficheiro cru")
        return await _serve_file(path)
    resp = web.Response(text=html, content_type="text/html", charset="utf-8")
    # Esta resposta é construída à mão (não passa pelo `_serve_file`), logo a
    # compressão tem de ser ligada aqui — senão a porta era o único HTML do
    # projeto a sair cru.
    try:
        resp.enable_compression()
    except Exception:
        logger.debug("compressão indisponível na porta", exc_info=True)
    # A porta nunca é cacheada: um HTML velho podia apontar para um bot antigo.
    resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    # Um <iframe> nosso noutro site seria clickjacking sobre um botão de login.
    resp.headers["X-Frame-Options"] = "DENY"
    resp.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    # ⚠️ É AQUI que a escolha passa a durar. Sem esta linha o seletor mudava a
    # página de agora e o pedido seguinte voltava ao `Accept-Language` — que é
    # exactamente o *"idiomas mezclados"* de que o owner se queixou.
    remember_lang(resp, request, lang)
    return resp


async def serve_legal_page(request: web.Request) -> web.Response:
    """/privacy e /terms — as paginas legais, nas 3 linguas, URL em ingles.

    Renderizadas no servidor pelo mesmo motivo da porta: zero copy no HTML e
    nada de um endpoint publico so para ir buscar texto.

    ⚠️ Estas paginas NAO sao `noindex`. A porta e (nao ha nada la para indexar),
    mas uma politica de privacidade tem de ser publica e alcancavel — e o Google
    exige-a acessivel para libertar a tela de consentimento do OAuth.
    """
    kind = "terms" if request.path.rstrip("/").endswith("terms") else "privacy"
    try:
        from core.legal import get_document
        lang = public_lang(request)
        doc = get_document(kind, lang)
    except Exception:
        logger.exception("serve_legal_page: falhou (%s)", request.path)
        return _err("not_found", 404)

    def esc(t: str) -> str:
        return (str(t).replace("&", "&amp;").replace("<", "&lt;")
                .replace(">", "&gt;").replace('"', "&quot;"))

    # ⚠️ O texto das seccoes tem `<strong>` de proposito e e NOSSO (vem de
    # `core/legal.py`, nunca do visitante), por isso vai cru. O que passa pelo
    # `esc()` e tudo o que possa vir de fora: o titulo, os cabecalhos e — sim —
    # o email de contacto, que sai de uma env var. Escapar uma env do owner e
    # barato e fecha a categoria antes de alguem lhe pôr aspas.
    from core.legal import CONTACT_EMAIL
    safe_mail = esc(CONTACT_EMAIL)
    body = []
    for head, paras in doc["sections"]:
        body.append("<h2>%s</h2>" % esc(head))
        for para in paras:
            body.append("<p>%s</p>" % para.replace(CONTACT_EMAIL, safe_mail))

    html = LEGAL_TEMPLATE.format(
        lang=esc(doc["lang"]),
        title=esc(doc["title"]),
        intro=esc(doc["intro"]),
        eyebrow=esc(doc.get("eyebrow") or "Nivrael"),
        body=(chr(10) + "      ").join(body),
        updated_label=esc(doc["updated_label"]),
        updated=esc(doc["updated"]),
        back=esc(doc["back"]),
        other_label=esc(doc["other_label"]),
        other_href=esc(doc["other_href"]),
    )
    resp = web.Response(text=html, content_type="text/html", charset="utf-8")
    try:
        resp.enable_compression()
    except Exception:
        logger.debug("compressao indisponivel na pagina legal", exc_info=True)
    # Documento estavel: uma hora de cache poupa o servidor sem esconder uma
    # alteracao por muito tempo. `Vary` porque o texto muda com a lingua.
    resp.headers["Cache-Control"] = "public, max-age=3600"
    resp.headers["Vary"] = "Accept-Language"
    resp.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    return resp


