# ── v14.14b Foundation Recomeço (D-1a) + Quebrar Fundação (D-1b) ─────────────
# Ports handlers/foundation.py — recomeco_command + recomeco_confirm_callback,
# quebrar_fundacao_command + break_begin/answer/_settle_break_trial. Engine
# `core/foundation_engine.py` canonical (RITUAL_REROLL_TABLES, roll_from_table,
# ELEMENTS_Q1/Q2/Q3, SPIRIT_ROOT_FALLBACK_ELEMENT).
async def api_foundation_recomeco_preview(request: web.Request) -> web.Response:
    """READ — eligibility + current foundation/root preview for the newbie grace."""
    from datetime import timedelta as _td
    from handlers.foundation import (
        _is_recomeco_eligible, RECOMECO_MAX_AGE_DAYS, RECOMECO_MAX_REALM,
    )
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        eligible, reason = _is_recomeco_eligible(player)
        age = datetime.now(timezone.utc) - player.created_at
        days_used = age.days
        days_left = max(0, RECOMECO_MAX_AGE_DAYS - days_used)

        sr_idx = player.spirit_root if player.spirit_root is not None else 4
        sr_name, sr_emoji = _spirit_root_label(sr_idx)
        return _json({
            "ok": True,
            "eligible": bool(eligible),
            "reason": reason,
            "foundation_quality": player.foundation_quality,
            "foundation_reroll_used": bool(getattr(player, "foundation_reroll_used", False)),
            "spirit_root": sr_name,
            "spirit_root_emoji": sr_emoji,
            "spirit_root_idx": int(sr_idx),
            "realm": int(player.realm or 0),
            "max_realm": int(RECOMECO_MAX_REALM),
            "days_used": int(days_used),
            "days_left": int(days_left),
            "max_age_days": int(RECOMECO_MAX_AGE_DAYS),
        })


async def api_foundation_recomeco_execute(request: web.Request) -> web.Response:
    """WRITE — execute newbie reroll. Mirrors recomeco_confirm_callback."""
    from handlers.foundation import _is_recomeco_eligible
    from config import SPIRIT_ROOT_WEIGHTS as _SRW  # noqa: F401  (kept for reference)
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        eligible, reason = _is_recomeco_eligible(player)
        if not eligible:
            return _json({"ok": False, "reason": reason or "not_eligible"})

        old_foundation = player.foundation_quality
        old_root = player.spirit_root

        import random
        # Same weights as recomeco_confirm_callback (foundation.py).
        choices = ["low", "medium", "high", "perfect"]
        weights = [40.0, 35.0, 20.0, 5.0]
        new_foundation = random.choices(choices, weights=weights, k=1)[0]

        # Spirit root: same weights, exclude Low (idx 4).
        root_indices = [0, 1, 2, 3, 4]
        root_weights_no_low = [0.01, 1.0, 19.0, 80.0, 0.0]
        new_root = random.choices(root_indices, weights=root_weights_no_low, k=1)[0]

        player.foundation_quality = new_foundation
        player.spirit_root = new_root
        player.foundation_reroll_used = True
        await session.commit()

        from core.foundation_engine import FOUNDATION_QUALITIES
        old_label_key = FOUNDATION_QUALITIES.get(old_foundation or "low", FOUNDATION_QUALITIES["low"])["label_key"] if old_foundation else None
        new_label_key = FOUNDATION_QUALITIES[new_foundation]["label_key"]
        old_root_name, old_root_emoji = _spirit_root_label(old_root if old_root is not None else 4)
        new_root_name, new_root_emoji = _spirit_root_label(new_root)

    return _json({
        "ok": True,
        "old_foundation": old_foundation,
        "old_foundation_label_key": old_label_key,
        "new_foundation": new_foundation,
        "new_foundation_label_key": new_label_key,
        "old_spirit_root": old_root_name,
        "old_spirit_root_emoji": old_root_emoji,
        "new_spirit_root": new_root_name,
        "new_spirit_root_emoji": new_root_emoji,
    })


async def api_foundation_break_preview(request: web.Request) -> web.Response:
    """READ — Quebrar Fundação preview: realm gate, cost, cooldown, question
    answers based on dominant Supreme Dao element."""
    from handlers.foundation import (
        _break_cooldown_remaining, _required_cb, _can_afford_break,
        _dominant_supreme_element, _correct_answers_for,
        BREAK_MIN_REALM, BREAK_COST_STONES, BREAK_COST_ESSENCE, BREAK_CB_PERCENT,
    )
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        realm_ok = player.realm >= BREAK_MIN_REALM
        cooldown = _break_cooldown_remaining(player)
        cooldown_secs = int(cooldown.total_seconds()) if cooldown else 0
        cb_cost = _required_cb(player)
        affordable, missing = _can_afford_break(player)
        element = await _dominant_supreme_element(session, player) if realm_ok else None
        correct = _correct_answers_for(element) if element else None

        return _json({
            "ok": True,
            "eligible": bool(realm_ok and cooldown is None and affordable),
            "realm_ok": bool(realm_ok),
            "min_realm": int(BREAK_MIN_REALM),
            "realm": int(player.realm or 0),
            "cooldown_seconds": cooldown_secs,
            "cooldown_days": int(cooldown.days) if cooldown else 0,
            "affordable": bool(affordable),
            "missing": missing,
            "current_foundation": player.foundation_quality,
            "costs": {
                "cb": int(cb_cost),
                "stones": int(BREAK_COST_STONES),
                "essence": int(BREAK_COST_ESSENCE),
                "cb_percent": float(BREAK_CB_PERCENT),
            },
            "balances": {
                "cb": float(player.cultivation_base or 0),
                "stones": int(player.spirit_stones or 0),
                "essence": int(player.celestial_essence or 0),
            },
            "element": element,
            # correct_answers ARE sent to the client so the UI can hint
            # which choices align with the player's path. Owner directive
            # 2026-05-26: "tudo no mini-app" — hints stay visible.
            "correct_answers": correct,
            "break_count": int(getattr(player, "foundation_break_count", 0) or 0),
        })


async def api_foundation_break_execute(request: web.Request) -> web.Response:
    """WRITE — execute Quebrar Fundação ritual with 3 answers. Mirror chat:
    charge costs IMMEDIATELY (act of breaking IS the cost), then roll from
    RITUAL_REROLL_TABLES[score] where score = correct answers count."""
    from handlers.foundation import (
        _break_cooldown_remaining, _required_cb, _can_afford_break,
        _dominant_supreme_element, _correct_answers_for,
        BREAK_MIN_REALM, BREAK_COST_STONES, BREAK_COST_ESSENCE, BREAK_CB_PERCENT,
    )
    from core.foundation_engine import RITUAL_REROLL_TABLES, roll_from_table, FOUNDATION_QUALITIES

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    answers = payload.get("answers") or []
    if not isinstance(answers, list) or len(answers) != 3:
        return _err("bad_answers", 400)
    answers = [str(a).strip().lower() for a in answers]

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if player.realm < BREAK_MIN_REALM:
            return _json({"ok": False, "reason": "realm_too_low"})
        cooldown = _break_cooldown_remaining(player)
        if cooldown is not None:
            return _json({"ok": False, "reason": "cooldown",
                          "cooldown_seconds": int(cooldown.total_seconds())})
        ok_afford, missing = _can_afford_break(player)
        if not ok_afford:
            return _json({"ok": False, "reason": "missing", "missing": missing})

        # Charge costs immediately (mirror chat).
        cb_cost = _required_cb(player)
        player.cultivation_base = max(0.0, (player.cultivation_base or 0) - cb_cost)
        player.spirit_stones -= BREAK_COST_STONES
        player.celestial_essence = max(0, (player.celestial_essence or 0) - BREAK_COST_ESSENCE)

        # Compute score
        element = await _dominant_supreme_element(session, player)
        correct = _correct_answers_for(element)
        score = sum(1 for i, a in enumerate(answers, 1) if correct.get(i) == a)

        old_foundation = player.foundation_quality
        table = RITUAL_REROLL_TABLES.get(score, RITUAL_REROLL_TABLES[1])
        new_foundation = roll_from_table(table)
        player.foundation_quality = new_foundation
        player.foundation_break_count = (getattr(player, "foundation_break_count", 0) or 0) + 1
        player.last_foundation_break_at = datetime.now(timezone.utc)
        await session.commit()

        old_key = FOUNDATION_QUALITIES.get(old_foundation or "low", FOUNDATION_QUALITIES["low"])["label_key"] if old_foundation else None
        new_info = FOUNDATION_QUALITIES.get(new_foundation, FOUNDATION_QUALITIES["low"])

    return _json({
        "ok": True,
        "score": int(score),
        "element": element,
        "old_foundation": old_foundation,
        "old_foundation_label_key": old_key,
        "new_foundation": new_foundation,
        "new_foundation_label_key": new_info["label_key"],
        "new_foundation_emoji": new_info.get("emoji", "🏯"),
        "delta": {
            "cultivation_base": float(player.cultivation_base or 0),
            "spirit_stones": int(player.spirit_stones or 0),
            "celestial_essence": int(player.celestial_essence or 0),
            "foundation_quality": player.foundation_quality,
        },
    })


# ── v14.14d Apex Reflection Chamber (D-6b) ───────────────────────────────────
# Ports handlers/celestial.py: camara_reflexao_command + _settle_chamber +
# _apex_chamber_enter_callback. Engine `core/celestial_engine.is_apex`.
async def api_apex_chamber_status(request: web.Request) -> web.Response:
    from core.celestial_engine import is_apex
    from handlers.celestial import APEX_INSIGHT_CHANCE_PER_HOUR
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        apex = await is_apex(session, player)
        entered_at = getattr(player, "apex_chamber_entered_at", None)
        elapsed_secs = 0
        if entered_at is not None:
            elapsed_secs = int((datetime.now(timezone.utc) - entered_at).total_seconds())
        insights = int(getattr(player, "divine_law_insights", 0) or 0)
        return _json({
            "ok": True,
            "is_apex": bool(apex),
            "is_meditating": bool(player.is_meditating),
            "entered": entered_at is not None,
            "entered_at_ms": _ms(entered_at),
            "elapsed_seconds": elapsed_secs,
            "elapsed_hours": elapsed_secs // 3600,
            "divine_law_insights": insights,
            "insight_chance_per_hour": float(APEX_INSIGHT_CHANCE_PER_HOUR),
        })


async def api_apex_chamber_enter(request: web.Request) -> web.Response:
    from core.celestial_engine import is_apex
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        if not await is_apex(session, player):
            return _json({"ok": False, "reason": "not_apex"})
        if player.is_meditating:
            return _json({"ok": False, "reason": "already_meditating"})
        # Idempotent: if already entered, keep entered_at (no progress lost).
        if getattr(player, "apex_chamber_entered_at", None) is None:
            player.apex_chamber_entered_at = datetime.now(timezone.utc)
            await session.commit()
        return _json({
            "ok": True,
            "entered_at_ms": _ms(player.apex_chamber_entered_at),
        })


async def api_apex_chamber_exit(request: web.Request) -> web.Response:
    """Settle a chamber session: roll insights for elapsed full hours,
    apply to divine_law_insights, clear entered_at. Mirror _settle_chamber."""
    from core.celestial_engine import is_apex
    from handlers.celestial import _settle_chamber
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        if not await is_apex(session, player):
            return _json({"ok": False, "reason": "not_apex"})
        if getattr(player, "apex_chamber_entered_at", None) is None:
            return _json({"ok": False, "reason": "not_in_chamber"})
        entered = player.apex_chamber_entered_at
        elapsed = (datetime.now(timezone.utc) - entered).total_seconds()
        gained = _settle_chamber(player)
        player.apex_chamber_entered_at = None
        total = int(getattr(player, "divine_law_insights", 0) or 0)
        await session.commit()
    return _json({
        "ok": True,
        "elapsed_seconds": int(elapsed),
        "elapsed_hours": int(elapsed // 3600),
        "insights_gained": int(gained),
        "total_insights": total,
    })


# ── v14.14e Body Tempering dedicated UI ──────────────────────────────────────
# Ports handlers/cultivation.py: tempering_menu_callback + tempering_attempt
# callback (Nine Transformations). Engine `core/body_tempering_engine.py`
# canonical: get_tempering_info, get_next_level_info, can_temper,
# perform_tempering, MAX_TEMPERING_LEVEL, MIN_REALM_REQUIRED.
async def api_body_tempering_status(request: web.Request) -> web.Response:
    # 星 2.1 — the payload has ONE owner, `project_tempering_status` (pure, in
    # the engine): the endpoint, the mini-app dev harness and the §25 guard all
    # read the same shape. Here stays only what needs the session: the TOTAL
    # battle power, computed only when there is a next level to gate.
    from core.body_tempering_engine import project_tempering_status, get_next_level_info
    from core.game_logic import (
        calculate_total_stats,
        get_player_equipment_stats,
        get_active_technique_bonuses,
    )
    from core.alchemy_engine import get_active_buffs
    from core.beast_engine import get_companion_beast, get_companion_bonuses
    from core.dao_engine import get_player_dao_bonuses

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if get_next_level_info(int(player.body_tempering_level or 0)) is None:
            return _json(project_tempering_status(player))

        # Total BP with full multiplier chain (mirror chat).
        _ = await get_active_buffs(session, player.telegram_id)
        stmt_arts = select(PlayerArtifact).where(
            PlayerArtifact.player_id == player.telegram_id,
            PlayerArtifact.is_equipped == True,  # noqa: E712
        )
        arts = (await session.execute(stmt_arts)).scalars().all()
        equip_stats = get_player_equipment_stats(arts) if arts else None
        comp_beast, comp_catalog = await get_companion_beast(session, player.telegram_id)
        comp_bonus = (
            get_companion_bonuses(comp_beast, comp_catalog)
            if (comp_beast and comp_catalog) else None
        )
        dao_bonuses = await get_player_dao_bonuses(session, player.telegram_id, player.realm)
        interior_bonuses = await get_active_technique_bonuses(session, player.telegram_id)
        total_stats = calculate_total_stats(
            player, equip_stats=equip_stats, companion_bonus=comp_bonus,
            dao_bonuses=dao_bonuses, interior_bonuses=interior_bonuses,
        )
        total_bp = int(total_stats.get("total_battle_power", player.battle_power or 0))
        return _json(project_tempering_status(player, total_battle_power=total_bp))


async def api_body_tempering_ascend(request: web.Request) -> web.Response:
    from core.body_tempering_engine import (
        can_temper, perform_tempering, MAX_TEMPERING_LEVEL,
    )
    from core.game_logic import (
        calculate_total_stats,
        get_player_equipment_stats,
        get_active_technique_bonuses,
    )
    from core.alchemy_engine import get_active_buffs
    from core.beast_engine import get_companion_beast, get_companion_bonuses
    from core.dao_engine import get_player_dao_bonuses

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # Recompute total_bp for the gate (mirror chat).
        _ = await get_active_buffs(session, player.telegram_id)
        stmt_arts = select(PlayerArtifact).where(
            PlayerArtifact.player_id == player.telegram_id,
            PlayerArtifact.is_equipped == True,  # noqa: E712
        )
        arts = (await session.execute(stmt_arts)).scalars().all()
        equip_stats = get_player_equipment_stats(arts) if arts else None
        comp_beast, comp_catalog = await get_companion_beast(session, player.telegram_id)
        comp_bonus = (
            get_companion_bonuses(comp_beast, comp_catalog)
            if (comp_beast and comp_catalog) else None
        )
        dao_bonuses = await get_player_dao_bonuses(session, player.telegram_id, player.realm)
        interior_bonuses = await get_active_technique_bonuses(session, player.telegram_id)
        total_stats = calculate_total_stats(
            player, equip_stats=equip_stats, companion_bonus=comp_bonus,
            dao_bonuses=dao_bonuses, interior_bonuses=interior_bonuses,
        )
        total_bp = int(total_stats.get("total_battle_power", player.battle_power or 0))

        check = can_temper(player, total_battle_power=total_bp)
        if not check["can"]:
            return _json({"ok": False, "reason": check.get("reason_key") or "blocked"})

        # Progressão Visível — snapshot Poder de Combate + max HP BEFORE the temper.
        # Gated by `progressao_visivel`. The power delta reuses the already-loaded stats
        # (no extra query); the HP goes through the Alma (soul_max_hp) which on a
        # combate_unificado-ON world DOES fetch the modifier stack (once before + once
        # after) — a cheap, rare user action, not the api_player hot path.
        from database.db import feature_enabled_for_world
        from core.game_logic import display_combat_power as _dcp
        from core.cultivator_soul import soul_max_hp as _smhp
        _pv_on = feature_enabled_for_world("progressao_visivel")
        _power_delta = None
        _hp_before = int(round(await _smhp(session, player))) if _pv_on else 0
        _cp_before = _dcp(total_bp, player) if _pv_on else 0

        result = perform_tempering(player)
        # 減 P7 — a transformacao CONFIRMADA (o `can_temper` ja' passou acima).
        from core.explicacoes import marcar_apto as _explica_apto
        _explica_apto(player, "corpo_transf")

        if _pv_on:
            # perform_tempering raised body_tempering_level + qi_capacity → recompute
            # from the SAME (already-loaded) multipliers, pure, no new queries.
            _stats_after = calculate_total_stats(
                player, equip_stats=equip_stats, companion_bonus=comp_bonus,
                dao_bonuses=dao_bonuses, interior_bonuses=interior_bonuses,
            )
            _bp_after = int(_stats_after.get("total_battle_power", player.battle_power or 0))
            _power_delta = {
                "display_combat_power": {"before": _cp_before, "after": _dcp(_bp_after, player)},
                "max_hp": {"before": _hp_before, "after": int(round(await _smhp(session, player)))},
            }
        await session.commit()

    return _json({
        "ok": True,
        "new_level": int(result["new_level"]),
        "mult": float(result["mult"]),
        "emoji": result.get("emoji", "🔥"),
        "name_key": result.get("name_key"),
        "qi_cap_bonus": int(result.get("qi_cap_bonus", 0)),
        "body_transformed": bool(result.get("body_transformed", False)),
        "essence_cost": int(result.get("essence_cost", 0)),
        "power_delta": _power_delta,
        "delta": {
            "body_tempering_level": int(player.body_tempering_level or 0),
            "body_tempering_progress": int(player.body_tempering_progress or 0),
            "spirit_stones": int(player.spirit_stones or 0),
            "qi": float(player.qi or 0),
            "qi_capacity": float(player.qi_capacity or 100),
            "celestial_essence": int(player.celestial_essence or 0),
        },
    })


# ── v14.14i Dao Partner system 💞 ─────────────────────────────────────────────
# Ports handlers/partner.py (~640 lines) to the mini-app. Engine
# `core/partner_engine.py` is canonical (get_player_partner,
# get_pending_proposals, has/consume_jade_ring, cooldowns, apply_heartbreak,
# increment_intimacy_if_both_online, get_partner_cb_mult). Telegram DM
# notifications are skipped here (no context.bot in mini-app); the target
# learns of incoming proposals via the notifications/inbox `partner_proposal`
# branch (NotifToastStack auto-pops a push toast).
async def _partner_info_payload(session, player) -> dict:
    """Single round-trip snapshot used by /partner/info AND
    /partner/intimacy_ping (after a passive intimacy tick).
    """
    from core.partner_engine import (
        get_player_partner,
        get_pending_proposals,
        get_sent_proposal,
        has_jade_ring,
        get_romantic_cooldown_remaining,
        get_heartbreak_remaining,
        get_partner_cb_mult,
    )
    from database.models import DaoPartnerProposal as _DPP

    now = datetime.now(timezone.utc)
    partner_rec, partner_player = await get_player_partner(session, player.telegram_id)
    pending = await get_pending_proposals(session, player.telegram_id)
    sent_prop = await get_sent_proposal(session, player.telegram_id)

    # Jade ring stack count (chat treats it as boolean — UI wants the actual
    # number so "you have N rings" can flex narratively).
    ring_row = (await session.execute(
        select(PlayerInventory).where(
            PlayerInventory.player_id == player.telegram_id,
            PlayerInventory.item_type == "jade_ring",
        )
    )).scalar_one_or_none()
    ring_count = int(ring_row.quantity) if ring_row and ring_row.quantity else 0
    has_ring = ring_count > 0

    heartbreak_secs = await get_heartbreak_remaining(session, player.telegram_id)
    romantic_secs = await get_romantic_cooldown_remaining(session, player.telegram_id)

    # Resolve proposer names for incoming pending proposals.
    incoming = []
    if pending:
        proposer_ids = [p.proposer_id for p in pending]
        prows = (await session.execute(
            select(Player.telegram_id, Player.dao_name, Player.realm)
            .where(Player.telegram_id.in_(proposer_ids))
        )).all()
        pmap = {row[0]: {"dao_name": row[1], "realm": int(row[2] or 0)} for row in prows}
        for prop in pending:
            info = pmap.get(prop.proposer_id, {})
            remaining = max(0, int((prop.expires_at - now).total_seconds()))
            incoming.append({
                "id": str(prop.id),
                "proposer_id": int(prop.proposer_id),
                "proposer_dao_name": info.get("dao_name") or "—",
                "proposer_realm": info.get("realm", 0),
                "expires_in_seconds": remaining,
                "expires_at_ms": int(prop.expires_at.timestamp() * 1000),
            })

    sent = None
    if sent_prop:
        target = (await session.execute(
            select(Player.telegram_id, Player.dao_name)
            .where(Player.telegram_id == sent_prop.target_id)
        )).first()
        remaining = max(0, int((sent_prop.expires_at - now).total_seconds()))
        sent = {
            "id": str(sent_prop.id),
            "target_id": int(sent_prop.target_id),
            "target_dao_name": (target[1] if target else None) or "—",
            "expires_in_seconds": remaining,
            "expires_at_ms": int(sent_prop.expires_at.timestamp() * 1000),
        }

    partner_block = None
    cb_mult = 1.0
    if partner_rec and partner_player:
        from datetime import timedelta as _td
        cb_mult = await get_partner_cb_mult(session, player.telegram_id)
        cutoff = now - _td(hours=24)
        partner_online = bool(
            partner_player.last_online and partner_player.last_online > cutoff
        )
        married_days = max(0, (now - partner_rec.married_at).days)
        partner_block = {
            "partner_id": int(partner_player.telegram_id),
            "partner_dao_name": partner_player.dao_name or "—",
            "partner_realm": int(partner_player.realm or 0),
            "partner_online_24h": partner_online,
            "intimacy_level": int(partner_rec.intimacy_level or 0),
            "ring_level": int(partner_rec.ring_level or 1),
            "married_days": married_days,
            "married_at_ms": int(partner_rec.married_at.timestamp() * 1000),
            "dual_cult_active": (abs(cb_mult - 1.1) < 1e-6),
            "luck_share": int((partner_player.luck or 0) * 0.05),
        }

    return {
        "ok": True,
        "partner": partner_block,
        "incoming_proposals": incoming,
        "sent_proposal": sent,
        "jade_ring_count": ring_count,
        "has_jade_ring": has_ring,
        "heartbreak_remaining_secs": int(heartbreak_secs),
        "romantic_cooldown_remaining_secs": int(romantic_secs),
        "cb_mult": float(cb_mult),
    }


