async def api_partner_propose(request: web.Request) -> web.Response:
    """WRITE — mirror process_partner_proposal_input (handlers/partner.py).
    Consumes 1 jade_ring, creates DaoPartnerProposal expires_at +48h.
    Gates: not partnered / not in romantic cooldown / has jade ring / target
    exists / not self / target not partnered / target not in romantic cooldown
    / no existing sent proposal.
    """
    from core.partner_engine import (
        get_player_partner,
        get_sent_proposal,
        has_jade_ring,
        consume_jade_ring,
        has_romantic_cooldown,
    )
    from database.models import DaoPartnerProposal as _DPP
    from datetime import timedelta as _td
    from sqlalchemy import delete as _del

    try:
        body = await request.json()
    except Exception:
        body = {}
    target_dao_name = (body.get("target_dao_name") or "").strip()
    if not target_dao_name:
        return _json({"ok": False, "reason": "partner_dao_name_required"})

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # Already partnered?
        rec, _p = await get_player_partner(session, player.telegram_id)
        if rec:
            return _json({"ok": False, "reason": "partner_already_partnered"})

        if await has_romantic_cooldown(session, player.telegram_id):
            return _json({"ok": False, "reason": "partner_cooldown_active"})

        if not await has_jade_ring(session, player.telegram_id):
            return _json({"ok": False, "reason": "partner_no_ring"})

        existing_sent = await get_sent_proposal(session, player.telegram_id)
        if existing_sent:
            return _json({"ok": False, "reason": "partner_already_proposed"})

        # Locate target (case-insensitive on dao_name).
        target = (await session.execute(
            select(Player).where(func.lower(Player.dao_name) == target_dao_name.lower())
        )).scalar_one_or_none()
        if not target:
            return _json({"ok": False, "reason": "partner_not_found"})
        if target.telegram_id == player.telegram_id:
            return _json({"ok": False, "reason": "partner_self_propose"})

        # Target gates.
        rec_t, _pt = await get_player_partner(session, target.telegram_id)
        if rec_t:
            return _json({"ok": False, "reason": "partner_already_partnered"})
        if await has_romantic_cooldown(session, target.telegram_id):
            return _json({"ok": False, "reason": "partner_already_partnered"})

        # Consume jade ring (idempotent at engine level).
        if not await consume_jade_ring(session, player.telegram_id):
            return _json({"ok": False, "reason": "partner_no_ring"})

        # Delete any prior proposal pair between these two.
        await session.execute(
            _del(_DPP).where(
                _DPP.proposer_id == player.telegram_id,
                _DPP.target_id == target.telegram_id,
            )
        )

        now = datetime.now(timezone.utc)
        proposal = _DPP(
            proposer_id=player.telegram_id,
            target_id=target.telegram_id,
            status="pending",
            expires_at=now + _td(hours=48),
        )
        session.add(proposal)
        await session.commit()

        return _json({
            "ok": True,
            "proposal_id": str(proposal.id),
            "target_dao_name": target.dao_name or "—",
            "expires_at_ms": int(proposal.expires_at.timestamp() * 1000),
            "jade_ring_count": int(
                (await session.execute(
                    select(PlayerInventory.quantity).where(
                        PlayerInventory.player_id == player.telegram_id,
                        PlayerInventory.item_type == "jade_ring",
                    )
                )).scalar() or 0
            ),
        })


async def api_partner_respond(request: web.Request) -> web.Response:
    """WRITE — mirror _partner_accept / _partner_reject. {proposal_id, accept}.
    On accept: create DaoPartner row, cancel ALL other pending proposals for
    both players, mark this proposal accepted. On reject: status=rejected.
    """
    from database.models import DaoPartner, DaoPartnerProposal as _DPP
    from core.partner_engine import get_player_partner
    from sqlalchemy import delete as _del, or_ as _or
    import uuid as _uuid

    try:
        body = await request.json()
    except Exception:
        body = {}
    proposal_id_raw = (body.get("proposal_id") or "").strip()
    accept = bool(body.get("accept", False))
    if not proposal_id_raw:
        return _json({"ok": False, "reason": "partner_proposal_invalid"})
    try:
        prop_uuid = _uuid.UUID(proposal_id_raw)
    except ValueError:
        return _json({"ok": False, "reason": "partner_proposal_invalid"})

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        proposal = (await session.execute(
            select(_DPP).where(
                _DPP.id == prop_uuid,
                _DPP.target_id == player.telegram_id,
                _DPP.status == "pending",
            )
        )).scalar_one_or_none()
        if not proposal:
            return _json({"ok": False, "reason": "partner_proposal_not_found"})

        now = datetime.now(timezone.utc)
        if proposal.expires_at < now:
            proposal.status = "expired"
            await session.commit()
            return _json({"ok": False, "reason": "partner_proposal_expired"})

        if not accept:
            proposal.status = "rejected"
            await session.commit()
            return _json({"ok": True, "accepted": False})

        # Accept path — both must still be unpartnered.
        for pid in (proposal.proposer_id, proposal.target_id):
            rec, _ = await get_player_partner(session, pid)
            if rec:
                proposal.status = "cancelled"
                await session.commit()
                return _json({"ok": False, "reason": "partner_already_partnered"})

        p1, p2 = sorted([proposal.proposer_id, proposal.target_id])
        session.add(DaoPartner(
            player1_id=p1,
            player2_id=p2,
            intimacy_level=0,
            married_at=now,
            ring_level=1,
        ))
        proposal.status = "accepted"

        # Cancel ALL other pending proposals involving either player.
        await session.execute(
            _del(_DPP).where(
                _DPP.id != prop_uuid,
                _or(
                    _DPP.proposer_id.in_([proposal.proposer_id, proposal.target_id]),
                    _DPP.target_id.in_([proposal.proposer_id, proposal.target_id]),
                ),
            )
        )
        await session.commit()

        # Resolve proposer dao_name for reveal copy.
        proposer = (await session.execute(
            select(Player.dao_name).where(Player.telegram_id == proposal.proposer_id)
        )).first()
        proposer_name = (proposer[0] if proposer else None) or "—"

        return _json({
            "ok": True,
            "accepted": True,
            "partner_dao_name": proposer_name,
            "partner_id": int(proposal.proposer_id),
            "married_at_ms": int(now.timestamp() * 1000),
        })


async def api_partner_cut_bond(request: web.Request) -> web.Response:
    """WRITE — mirror _partner_cut_execute. Deletes DaoPartner row +
    applies heartbreak (48h romantic cooldown + -10% CB) to BOTH players.
    Requires `confirm: true` in the body (UI does a double-confirm).
    """
    from core.partner_engine import get_player_partner, apply_heartbreak

    try:
        body = await request.json()
    except Exception:
        body = {}
    if not bool(body.get("confirm", False)):
        return _json({"ok": False, "reason": "partner_confirm_required"})

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        partner_rec, partner_player = await get_player_partner(session, player.telegram_id)
        if not partner_rec:
            return _json({"ok": False, "reason": "partner_not_partnered"})

        partner_id = partner_player.telegram_id if partner_player else None
        partner_name = (partner_player.dao_name if partner_player else None) or "—"

        await session.delete(partner_rec)
        await apply_heartbreak(session, player.telegram_id)
        if partner_id:
            await apply_heartbreak(session, partner_id)
        await session.commit()

        return _json({
            "ok": True,
            "partner_dao_name": partner_name,
            "heartbreak_secs": 48 * 3600,
            "romantic_cooldown_secs": 48 * 3600,
        })


async def api_partner_list_proposals(request: web.Request) -> web.Response:
    """READ — pending incoming + outgoing pair (for the Proposals drawer).
    Stable-paged style isn't needed: both lists are tiny (max ~5 active at any
    time, server-side TTL 48h). Single query each side; UI may render both
    inline.
    """
    from core.partner_engine import get_pending_proposals, get_sent_proposal

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        now = datetime.now(timezone.utc)
        pending = await get_pending_proposals(session, player.telegram_id)
        sent_p = await get_sent_proposal(session, player.telegram_id)

        incoming = []
        if pending:
            proposer_ids = [p.proposer_id for p in pending]
            prows = (await session.execute(
                select(Player.telegram_id, Player.dao_name, Player.realm)
                .where(Player.telegram_id.in_(proposer_ids))
            )).all()
            pmap = {r[0]: {"dao_name": r[1], "realm": int(r[2] or 0)} for r in prows}
            for prop in pending:
                info = pmap.get(prop.proposer_id, {})
                incoming.append({
                    "id": str(prop.id),
                    "proposer_dao_name": info.get("dao_name") or "—",
                    "proposer_realm": info.get("realm", 0),
                    "expires_in_seconds": max(0, int((prop.expires_at - now).total_seconds())),
                })

        sent = None
        if sent_p:
            target_row = (await session.execute(
                select(Player.dao_name, Player.realm).where(Player.telegram_id == sent_p.target_id)
            )).first()
            sent = {
                "id": str(sent_p.id),
                "target_dao_name": (target_row[0] if target_row else None) or "—",
                "target_realm": int((target_row[1] if target_row else 0) or 0),
                "expires_in_seconds": max(0, int((sent_p.expires_at - now).total_seconds())),
            }

        return _json({"ok": True, "incoming": incoming, "sent": sent})


async def api_partner_intimacy_ping(request: web.Request) -> web.Response:
    """WRITE — best-effort passive heartbeat. Calls
    increment_intimacy_if_both_online and returns the updated payload so
    the UI can reflect the new intimacy without a second round-trip.
    Cheap; safe to call on tab open (rate-limited via player.last_online
    sliding 1h window inside the engine).
    """
    from core.partner_engine import (
        get_player_partner,
        increment_intimacy_if_both_online,
    )
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        partner_rec, _ = await get_player_partner(session, player.telegram_id)
        ticked = False
        if partner_rec:
            ticked = await increment_intimacy_if_both_online(session, partner_rec)
            if ticked:
                await session.commit()

        payload = await _partner_info_payload(session, player)
        payload["intimacy_ticked"] = bool(ticked)
        return _json(payload)


# ── Dungeons (MA-30) ──────────────────────────────────────────────────────────
# The dungeon "engine" actually lives in handlers/dungeons.py (no core/dungeon_engine.py
# exists). We import its pure helpers (`_do_dungeon_floor`, `_roll_floor_loot`,
# `_merge_bag`, `_lose_90_percent`, `_transfer_bag_to_inventory`,
# `_apply_difficulty_loot_mult`) and replicate the wrapping side-effects (PlayerDungeon
# updates, quest tracking, body tempering, achievements) the chat handler does after
# the helper call. Same pattern MA-27 used for handlers.shop.
DUNGEON_DIFFICULTIES = ["easy", "normal", "hard", "nightmare"]
DUNGEON_DIFF_ORDER = {"easy": 1, "normal": 2, "hard": 3, "nightmare": 4}
DUNGEON_DIFF_LOOT_MULT = {"easy": 0.5, "normal": 1.0, "hard": 2.0, "nightmare": 3.0}
DUNGEON_CATEGORIES = [
    {"key": "mortal",    "min": 0, "max": 2},
    {"key": "spirit",    "min": 3, "max": 5},
    {"key": "celestial", "min": 6, "max": 8},
    {"key": "immortal",  "min": 9, "max": 10},
]


def _dungeon_floor_count(dungeon, difficulty: str) -> int:
    if dungeon.floor_counts and difficulty in dungeon.floor_counts:
        return int(dungeon.floor_counts[difficulty])
    return int(dungeon.floor_count)


def _dungeon_eff_qi_cost(base_cost: int, realm: int) -> int:
    return max(1, int(base_cost * (1 + realm * 0.1)))


def _dungeon_drops_preview(drops: dict, herb_lut: dict, ore_lut: dict, pill_lut: dict,
                           min_realm: int = 0) -> dict:
    """FULL catalog preview: every herb/ore/pill entry + chances + stones range.

    2026-06-12 ([jogadores]): the old top-N cut (herbs[:3]/ores[:2]/
    pills[:2]) silently hid entries — Ancient Battlefield's Heavenly Jade lost
    a weight tie and vanished from the info screen of ALL 4 of its source
    dungeons; [jogador] burned 600k qi sweeping the wrong dungeon. Catalog maxima
    are tiny (≤5 per kind) so the full list is bounded. Each item carries
    ``min_difficulty`` so the client can badge nightmare-gated entries, and
    the qi-pill chance reported is the EFFECTIVE one (mirror of the +0.04
    min_realm≥5 bonus in handlers/dungeons._roll_floor_loot)."""
    from core.scroll_economy_engine import scroll_drop_mult as _scr_drop_mult
    drops = drops or {}
    def _pick(key: str, lut: dict, fallback_emoji: str):
        items = sorted(drops.get(key, []) or [], key=lambda x: -float(x.get("weight", 0)))
        out = []
        for it in items:
            iid = int(it.get("id", 0))
            cat = lut.get(iid) or {}
            entry = {"id": iid, "name": cat.get("name") or f"#{iid}",
                     "emoji": cat.get("emoji") or fallback_emoji}
            if it.get("min_difficulty"):
                entry["min_difficulty"] = it.get("min_difficulty")
            out.append(entry)
        return out
    stones = drops.get("stones") or {}
    qi_pill = float(drops.get("qi_pill_chance", 0) or 0)
    if qi_pill > 0 and int(min_realm or 0) >= 5:
        qi_pill = min(1.0, qi_pill + 0.04)
    return {
        "stones": {"min": int(stones.get("min", 0)), "max": int(stones.get("max", 0))},
        "herbs": _pick("herbs", herb_lut, "🌿"),
        "ores": _pick("ores", ore_lut, "⛏️"),
        "pills": _pick("pills", pill_lut, "💊"),
        "qi_pill_chance": qi_pill,
        # TEC-2 — a vitrine mostra o número CORTADO (display = roll, lição
        # MV-6). Flag OFF ⇒ mult 1.0 ⇒ o mesmo float de sempre.
        "scroll_chance": float(drops.get("scroll_chance", 0) or 0) * _scr_drop_mult(),
        "dao_fragment_chance": float(drops.get("dao_fragment_chance", 0) or 0),
        "pill_chance": float(drops.get("pill_chance", 0) or 0),
    }


def _bag_summary(bag: dict) -> dict:
    """Aggregate bag counts for the client without per-item catalog lookups."""
    bag = bag or {}
    counts = {
        "stones": int(bag.get("stones", 0) or 0),
        "qi_pills": int(bag.get("qi_pills", 0) or 0),
        "scrolls": int(bag.get("scrolls", 0) or 0),
        "dao_fragments": int(bag.get("dao_fragments", 0) or 0),
        "herbs": sum(int(v) for v in (bag.get("herbs") or {}).values()),
        "ores": sum(int(v) for v in (bag.get("ores") or {}).values()),
        "healing_pills": sum(int(v) for v in (bag.get("healing_pills") or {}).values()),
    }
    counts["recipe"] = bag.get("recipe_pill_name")
    counts["total_items"] = sum(v for k, v in counts.items() if isinstance(v, int))
    counts["empty"] = counts["total_items"] == 0 and not counts.get("recipe")
    return counts


async def _resolve_bag_items(session, bag: dict, lang: str | None = None) -> list[dict]:
    """MA-30b — owner request: dungeon result modal must show ITEM NAMES,
    not just "5 herbs". Resolves the per-id keys in `bag` against the
    catalog tables and returns a flat list of {kind, id, name, emoji, count}
    rows. Bulk-fetches each catalog once (zero N+1 even for big bags).

    Empty/missing keys are skipped. Stones/qi_pills/scrolls/dao_fragments
    keep using the aggregate `_bag_summary` rows on the client — only the
    per-id buckets (herbs/ores/healing_pills + recipe) need resolution."""
    bag = bag or {}
    items: list[dict] = []

    # 層 4.3 — o espólio na língua de QUEM o recebe (achado a 08/10: escrevia
    # `r.name`, o nome cru do catálogo em inglês, a jogadores pt/es — o lote 名
    # não o viu). O modal e o recibo só desenham emoji + nome (nenhuma arte é
    # procurada pelo nome), logo traduzir não apaga peça nenhuma — o mesmo
    # raciocínio do `DropsPreview` (3.1). Sem `lang`, o nome cru de antes.
    def _nome(kind: str, r) -> str:
        return catalog_name(lang, kind, r) if lang else r.name

    herb_dict = bag.get("herbs") or {}
    ore_dict = bag.get("ores") or {}
    pill_dict = bag.get("healing_pills") or {}
    herb_ids = [int(k) for k in herb_dict.keys() if str(k).isdigit() and int(herb_dict[k] or 0) > 0]
    ore_ids = [int(k) for k in ore_dict.keys() if str(k).isdigit() and int(ore_dict[k] or 0) > 0]
    pill_ids = [int(k) for k in pill_dict.keys() if str(k).isdigit() and int(pill_dict[k] or 0) > 0]

    if herb_ids:
        rows = (await session.execute(
            select(HerbCatalog).where(HerbCatalog.id.in_(herb_ids))
        )).scalars().all()
        lut = {int(r.id): r for r in rows}
        for hid in herb_ids:
            r = lut.get(hid)
            if not r:
                continue
            items.append({
                "kind": "herb", "id": int(hid),
                "name": _nome("herb", r), "emoji": r.emoji or "🌿",
                "count": int(herb_dict[str(hid)] if str(hid) in herb_dict else herb_dict[hid]),
            })
    if ore_ids:
        rows = (await session.execute(
            select(OreCatalog).where(OreCatalog.id.in_(ore_ids))
        )).scalars().all()
        lut = {int(r.id): r for r in rows}
        for oid in ore_ids:
            r = lut.get(oid)
            if not r:
                continue
            items.append({
                "kind": "ore", "id": int(oid),
                "name": _nome("ore", r), "emoji": r.emoji or "⛏️",
                "count": int(ore_dict[str(oid)] if str(oid) in ore_dict else ore_dict[oid]),
            })
    if pill_ids:
        rows = (await session.execute(
            select(PillCatalog).where(PillCatalog.id.in_(pill_ids))
        )).scalars().all()
        lut = {int(r.id): r for r in rows}
        for pid in pill_ids:
            r = lut.get(pid)
            if not r:
                continue
            items.append({
                "kind": "pill", "id": int(pid),
                "name": _nome("pill", r), "emoji": r.emoji or "💊",
                "count": int(pill_dict[str(pid)] if str(pid) in pill_dict else pill_dict[pid]),
            })

    rp_id = bag.get("recipe_pill_id")
    rp_name = bag.get("recipe_pill_name")
    if rp_id and rp_name:
        items.append({
            "kind": "recipe", "id": int(rp_id),
            "name": rp_name, "emoji": "📜", "count": 1,
        })
    return items


def _player_resources(player) -> dict:
    return {
        "qi": float(player.qi or 0),
        "qi_capacity": float(player.qi_capacity or 100),
        "spirit_stones": int(player.spirit_stones or 0),
    }


async def api_dungeons_list(request: web.Request) -> web.Response:
    """Catalog grouped by realm-tier (Mortal/Spirit/Celestial/Immortal). Each
    dungeon includes drops_preview (top weighted catalog items), per-difficulty
    floor counts, and the player's state (best_difficulty, completed,
    current_floor, current_difficulty). Also surfaces the active run, if any,
    so the UI can jump straight into it."""
    from database.models import DungeonCatalog, PlayerDungeon
    from core.combat_engine import get_current_hp, get_max_hp

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        realm = int(player.realm or 0)

        # MV-1: geografia — com `dungeons_regionais` ON, a lista mostra só os
        # portais do continente atual (+ não-ancorados). OFF → payload de hoje,
        # byte-idêntico (nenhum campo novo é emitido).
        from core.dungeon_regions import (
            regionais_on as _dng_regionais_on,
            dungeon_visible_here as _dng_visible_here,
            elsewhere_summary as _dng_elsewhere_summary,
            player_continent as _dng_player_continent,
            continent_emoji as _dng_continent_emoji,
        )
        _reg_on = _dng_regionais_on()
        # 層 4.3 — o alcance tem UM dono (`core/masmorra.alcance`, com o heal de
        # 23/07) e o corte da expedição aberta só viaja com a onda.
        from core import masmorra as _masmorra

        dungeons = (await session.execute(
            select(DungeonCatalog).order_by(DungeonCatalog.id)
        )).scalars().all()

        ids = [d.id for d in dungeons]
        states_by_id: dict[int, object] = {}
        if ids:
            rows = (await session.execute(
                select(PlayerDungeon).where(
                    PlayerDungeon.player_id == user_id,
                    PlayerDungeon.dungeon_id.in_(ids),
                )
            )).scalars().all()
            states_by_id = {r.dungeon_id: r for r in rows}

        herbs = (await session.execute(select(HerbCatalog))).scalars().all()
        ores = (await session.execute(select(OreCatalog))).scalars().all()
        pills = (await session.execute(select(PillCatalog))).scalars().all()
        # 冶 3.1 — o espólio na língua do jogador. O `DropsPreview` só mostra
        # emoji + nome (nenhuma arte é procurada por ele), logo traduzir não
        # apaga peça nenhuma. Eram 3 leituras que o varredor não via (2.º salto).
        _lg_dg = _pl_lang(player)
        herb_lut = {h.id: {"name": catalog_name(_lg_dg, "herb", h), "emoji": h.emoji or "🌿"} for h in herbs}
        ore_lut = {o.id: {"name": catalog_name(_lg_dg, "ore", o), "emoji": o.emoji or "⛏️"} for o in ores}
        pill_lut = {p.id: {"name": catalog_name(_lg_dg, "pill", p), "emoji": p.emoji or "💊"} for p in pills}

        active_run = None
        categories = []
        for cat in DUNGEON_CATEGORIES:
            cat_dungeons = []
            for d in dungeons:
                if not (cat["min"] <= int(d.min_realm) <= cat["max"]):
                    continue
                pd_row = states_by_id.get(d.id)
                accessible = int(d.min_realm) <= realm <= int(d.max_realm)
                eff_qi = _dungeon_eff_qi_cost(int(d.qi_cost_per_floor), realm)
                fc = {diff: _dungeon_floor_count(d, diff) for diff in DUNGEON_DIFFICULTIES}
                bd = int(pd_row.best_difficulty) if pd_row else 0
                # Fix 2026-07-23 (report [jogador]): o settle do boss esquecia o
                # último andar no max_floor_reached (30 completos → "29").
                # Heal DERIVADO no display para runs antigas: completou na
                # dificuldade X ⇒ alcançou o último andar de X (verdade por
                # construção — zero migration, zero mass-UPDATE).
                # 層 4.3 — a conta mudou de casa, não de valor: o dono é
                # `core/masmorra.alcance`, que o ganho da expedição também lê.
                _mf = (_masmorra.alcance(d, pd_row.max_floor_reached, pd_row.completed, bd)
                       if pd_row else 0)
                state_obj = {
                    "best_difficulty": bd,
                    "best_difficulty_key": DUNGEON_DIFFICULTIES[bd - 1] if bd > 0 else None,
                    "max_floor_reached": _mf,
                    "completed": bool(pd_row.completed) if pd_row else False,
                    "current_floor": int(pd_row.current_floor) if pd_row else 0,
                    "current_difficulty": pd_row.difficulty if pd_row else None,
                }
                entry = {
                    "id": int(d.id),
                    "name": d.name,
                    "emoji": d.emoji or "🗺️",
                    "description": d.description,
                    "min_realm": int(d.min_realm),
                    "max_realm": int(d.max_realm),
                    "base_bp": int(d.base_bp or 0),
                    "qi_cost": int(d.qi_cost_per_floor),
                    "qi_cost_effective": eff_qi,
                    "accessible": accessible,
                    "drops_preview": _dungeon_drops_preview(d.drops or {}, herb_lut, ore_lut, pill_lut,
                                                            min_realm=int(d.min_realm or 0)),
                    "floor_counts": fc,
                    "state": state_obj,
                }
                if _reg_on and getattr(d, "continent", None):
                    entry["continent"] = d.continent
                    entry["continent_emoji"] = _dng_continent_emoji(d.continent)
                # MV-1: portais de outro continente saem da lista (a run ATIVA
                # nunca some — o active_run abaixo corre para todos).
                if _dng_visible_here(d, player):
                    cat_dungeons.append(entry)
                if active_run is None and state_obj["current_floor"] > 0:
                    diff_key = state_obj["current_difficulty"] or "normal"
                    active_run = {
                        "dungeon_id": int(d.id),
                        "name": d.name,
                        "emoji": d.emoji or "🗺️",
                        "current_floor": state_obj["current_floor"],
                        "floor_count": fc.get(diff_key, int(d.floor_count)),
                        "difficulty": state_obj["current_difficulty"],
                        "bag_summary": _bag_summary(pd_row.expedition_bag or {}),
                        # 層 4.3 — o corte (a posição, o alcance, as
                        # dificuldades concluídas), só com a onda
                        **_masmorra.corte_no_payload(d, pd_row),
                    }
            categories.append({
                "key": cat["key"],
                "min": cat["min"],
                "max": cat["max"],
                "dungeons": cat_dungeons,
            })

        try:
            cur_hp, max_hp = await _soul_hp_pair(session, player)
        except Exception:
            # 🩸 2026-09-13 — `player.current_hp or 0` era o MESMO erro que
            # produziu o falso "69% dos activos do s2 sem poder lutar": a
            # coluna e' NULL para quem NUNCA foi ferido, e NULL significa
            # **CHEIO** (`combat_engine.get_current_hp`). Este ramo mostrava
            # `0` de Vitalidade a quem esta' de barra inteira — so' quando o
            # caminho normal falha, mas a mentira era exactamente a mesma.
            from core.combat_engine import get_current_hp as _gch, get_max_hp as _gmh
            try:
                cur_hp, max_hp = float(_gch(player)), float(_gmh(player))
            except Exception:
                cur_hp, max_hp = 0.0, 0.0

    payload = {
        "ok": True,
        "realm": realm,
        "current_hp": cur_hp,
        "max_hp": max_hp,
        **_player_resources(player),
        "categories": categories,
        "active_run": active_run,
    }
    if _reg_on:
        _cur_cont = _dng_player_continent(player)
        payload["regional"] = {
            "continent": _cur_cont,
            "continent_emoji": _dng_continent_emoji(_cur_cont),
            "elsewhere": _dng_elsewhere_summary(dungeons, player),
        }
    return _json(payload)


async def _dungeons_finalize_state(session, player, pd_row) -> dict:
    """Common floor-result envelope reused by enter/advance/retreat. Onda B — the
    HP shown here is the Alma's (== the arena when combate_unificado ON; raw on OFF)."""
    cur_hp, max_hp = await _soul_hp_pair(session, player)
    return {
        "current_hp": cur_hp,
        "max_hp": max_hp,
        **_player_resources(player),
        "bag_summary": _bag_summary(pd_row.expedition_bag or {}),
        "delta": {
            "spirit_stones": int(player.spirit_stones or 0),
        },
    }


async def api_dungeons_enter(request: web.Request) -> web.Response:
    """Enter a dungeon at the chosen difficulty and fight floor 1.

    Mirrors `_dungeon_start_with_stance` in handlers/dungeons.py, but with
    stance="balanced" / focus_tech_id=0 hardcoded (the mini-app v1 doesn't
    surface the picker — see MA-30 deviations). Validates realm gate,
    meditation, HP, qi, and difficulty progression (each tier requires beating
    the previous).
    """
    from database.models import DungeonCatalog, PlayerDungeon
    from handlers.dungeons import (
        _do_dungeon_floor, _merge_bag, _lose_90_percent,
        _transfer_bag_to_inventory,
    )
    from core.combat_engine import get_current_hp
    from core.quest_engine import track_quest

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("dungeon_id")
    difficulty = (payload.get("difficulty") or "").strip().lower()
    try:
        dungeon_id = int(raw_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    if difficulty not in DUNGEON_DIFFICULTIES:
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        # FOR UPDATE: serialize concurrent dungeon actions per player (the bot
        # auto-runs dungeons in parallel) so the qi debit + loot transfer below
        # can't deadlock / lost-update against each other or pill/use (same root).
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if get_current_hp(player) <= 0:
            return _json({"ok": False, "reason": "hp_too_low"}, status=200)

        dungeon = (await session.execute(
            select(DungeonCatalog).where(DungeonCatalog.id == dungeon_id)
        )).scalar_one_or_none()
        if not dungeon:
            return _err("dungeon_not_found", 404)

        realm = int(player.realm or 0)
        if not (int(dungeon.min_realm) <= realm <= int(dungeon.max_realm)):
            return _json({"ok": False, "reason": "realm_locked",
                          "min_realm": int(dungeon.min_realm)}, status=200)

        # MV-1: recusa honesta — o portal fica noutro continente (o cliente
        # esconde, o servidor garante).
        from core.dungeon_regions import region_gate as _dng_region_gate
        _rg = _dng_region_gate(dungeon, player)
        if _rg:
            return _json({"ok": False, **_rg}, status=200)

        # QoL-relatos — uma masmorra de cada vez. ANTES do pre-check de qi: senão
        # um jogador sem qi e a meio de outra run ouviria "falta qi" quando o
        # bloqueio real é a run aberta (Lei §1 — a recusa diz o motivo CERTO).
        # `exclude` deixa o `already_in_run` do MA-30b (:4959) dono do caso
        # da MESMA masmorra — dois motivos distintos, dois textos distintos.
        from core.dungeon_run_engine import active_run as _dng_active_run
        _open = await _dng_active_run(session, user_id, exclude=dungeon_id)
        if _open:
            return _json({"ok": False, "reason": "run_elsewhere",
                          "run": _open}, status=200)

        # Pre-check qi defensively — _do_dungeon_floor's localized "no_qi"
        # narration cannot be detected via substring match (chat-side bug).
        eff_qi = _dungeon_eff_qi_cost(int(dungeon.qi_cost_per_floor), realm)
        if float(player.qi or 0) < eff_qi:
            return _json({"ok": False, "reason": "no_qi",
                          "current_qi": int(player.qi or 0),
                          "qi_cost": eff_qi}, status=200)

        # 層 4.3 — com a onda, o "antes" lê-se aqui: só colunas, trancado, ANTES
        # de a rota carregar a linha (`core/masmorra.ler_antes`). Sem a onda:
        # nem consulta nem trinco a mais.
        from core import masmorra as _masmorra
        from core.portas import onda_on as _onda_on
        _antes = await _masmorra.ler_antes(session, user_id, dungeon) if _onda_on() else None

        pd_row = (await session.execute(
            select(PlayerDungeon).where(
                PlayerDungeon.player_id == user_id,
                PlayerDungeon.dungeon_id == dungeon_id,
            )
        )).scalar_one_or_none()
        if not pd_row:
            from database.models import PlayerDungeon as PDModel
            pd_row = PDModel(
                player_id=user_id, dungeon_id=dungeon_id,
                current_floor=0, max_floor_reached=0,
                expedition_bag={}, best_difficulty=0,
            )
            session.add(pd_row)
            await session.flush()

        # MA-30b — owner reported "auto-cleared on select / repeated taps":
        # re-entering a dungeon mid-run silently RESET current_floor=1 and
        # wiped progress. Refuse instead — UI should redirect to RunCard.
        if int(pd_row.current_floor or 0) > 0:
            return _json({
                "ok": False,
                "reason": "already_in_run",
                "current_floor": int(pd_row.current_floor or 0),
                "current_difficulty": pd_row.difficulty,
            }, status=200)

        diff_level = DUNGEON_DIFF_ORDER[difficulty]
        if diff_level > 1 and int(pd_row.best_difficulty or 0) < diff_level - 1:
            prev_key = DUNGEON_DIFFICULTIES[diff_level - 2]
            return _json({"ok": False, "reason": "diff_gate", "required": prev_key}, status=200)

        pd_row.difficulty = difficulty

        lang = player.language or "pt"
        try:
            won, _narration, loot = await _do_dungeon_floor(
                session, player, dungeon, target_floor=1, difficulty=difficulty,
                lang=lang, stance="balanced", focus_tech_id=0,
            )
        except Exception:
            logger.exception("_do_dungeon_floor crashed in api_dungeons_enter")
            await session.rollback()
            return _err("engine_error", 500)

        if won:
            pd_row.current_floor = 1
            pd_row.max_floor_reached = max(int(pd_row.max_floor_reached or 0), 1)
            pd_row.expedition_bag = _merge_bag(pd_row.expedition_bag or {}, loot)
            pd_row.last_attempt_at = datetime.now(timezone.utc)
            try:
                await track_quest(session, user_id, "dungeon_floor", 1)
            except Exception:
                logger.exception("dungeon_floor track_quest failed")
        else:
            lost_bag = pd_row.expedition_bag or {}
            survivors = _lose_90_percent(lost_bag)
            if survivors:
                await _transfer_bag_to_inventory(session, player, survivors)
            pd_row.current_floor = 0
            pd_row.expedition_bag = {}
            pd_row.difficulty = None
            pd_row.last_attempt_at = datetime.now(timezone.utc)

        floor_count = _dungeon_floor_count(dungeon, difficulty)
        envelope = await _dungeons_finalize_state(session, player, pd_row)
        named_items = await _resolve_bag_items(session, loot if won else {}, _pl_lang(player))
        # o andar 1 só conta como vencido no ramo da vitória — a morte não passa
        # andar nenhum (e a morte não acende)
        _g = await _masmorra.ganho_da_acao(session, user_id, dungeon, _antes,
                                           andar=1 if won else None)
        await session.commit()

    return _json({
        "ok": True,
        "won": bool(won),
        "dead": (not won),
        "floor": 1 if won else 0,
        "floor_count": floor_count,
        "completed": False,
        "loot_this_floor": loot if won else {},
        "loot_named_items": named_items,
        **envelope,
        **_masmorra.no_payload(_g),
    })


async def api_dungeons_advance(request: web.Request) -> web.Response:
    """Advance to the next floor of the active dungeon run, or finish it.

    Mirrors `dungeon_advance` in handlers/dungeons.py — including the
    "completed at this difficulty" branch that transfers the bag, marks
    the dungeon completed, and bumps best_difficulty + body_tempering.
    """
    from database.models import DungeonCatalog, PlayerDungeon
    from handlers.dungeons import (
        _do_dungeon_floor, _merge_bag, _lose_90_percent,
        _transfer_bag_to_inventory,
    )
    from core.combat_engine import get_current_hp
    from core.quest_engine import track_quest

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("dungeon_id")
    try:
        dungeon_id = int(raw_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        # FOR UPDATE: serialize concurrent dungeon actions per player (the bot
        # auto-runs dungeons in parallel) so the qi debit + loot transfer below
        # can't deadlock / lost-update against each other or pill/use (same root).
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if get_current_hp(player) <= 0:
            return _json({"ok": False, "reason": "hp_too_low"}, status=200)

        dungeon = (await session.execute(
            select(DungeonCatalog).where(DungeonCatalog.id == dungeon_id)
        )).scalar_one_or_none()
        if not dungeon:
            return _err("dungeon_not_found", 404)

        # 層 4.3 — com a onda, o "antes" lê-se aqui: só colunas, trancado, ANTES
        # de a rota carregar a linha (`core/masmorra.ler_antes`). Sem a onda:
        # nem consulta nem trinco a mais.
        from core import masmorra as _masmorra
        from core.portas import onda_on as _onda_on
        _antes = await _masmorra.ler_antes(session, user_id, dungeon) if _onda_on() else None

        pd_row = (await session.execute(
            select(PlayerDungeon).where(
                PlayerDungeon.player_id == user_id,
                PlayerDungeon.dungeon_id == dungeon_id,
            )
        )).scalar_one_or_none()
        if not pd_row or int(pd_row.current_floor or 0) == 0:
            return _json({"ok": False, "reason": "not_in_dungeon"}, status=200)

        difficulty = pd_row.difficulty or "normal"
        if difficulty not in DUNGEON_DIFFICULTIES:
            difficulty = "normal"
        floor_count = _dungeon_floor_count(dungeon, difficulty)
        next_floor = int(pd_row.current_floor) + 1

        # Completion path — bag is fully transferred, dungeon marked completed.
        if next_floor > floor_count:
            # MV-1 §5: roll extra de material nativo (hard/nightmare, gated).
            _regional = None
            try:
                from core.dungeon_regions import (
                    regional_bonus_line as _dng_tribute_line, roll_regional_bonus)
                _regional = roll_regional_bonus(dungeon, difficulty)
                if _regional:
                    pd_row.expedition_bag = _merge_bag(pd_row.expedition_bag or {}, _regional["loot"])
            except Exception:
                logger.exception("roll_regional_bonus failed (advance/complete)")
            final_bag = pd_row.expedition_bag or {}
            await _transfer_bag_to_inventory(session, player, final_bag)
            pd_row.current_floor = 0
            pd_row.expedition_bag = {}
            pd_row.completed = True
            diff_level = DUNGEON_DIFF_ORDER[difficulty]
            pd_row.best_difficulty = max(int(pd_row.best_difficulty or 0), diff_level)
            pd_row.difficulty = None
            pd_row.last_attempt_at = datetime.now(timezone.utc)
            try:
                from core.body_tempering_engine import add_tempering_progress
                tempering_base = max(10, floor_count * 3)
                tempering_mult = DUNGEON_DIFF_LOOT_MULT[difficulty]
                add_tempering_progress(player, int(tempering_base * tempering_mult))
            except Exception:
                logger.exception("add_tempering_progress failed (advance/complete)")
            try:
                from core.bp_engine import update_bp_mission
                await update_bp_mission(session, user_id, "complete_dungeon")
            except Exception:
                logger.exception("update_bp_mission failed (advance/complete)")
            try:
                from core.faction_engine import update_quest_progress as fac_quest_progress
                await fac_quest_progress(session, user_id, "dungeon_any")
                await fac_quest_progress(session, user_id, "dungeon",
                    target_filter={"dungeon_id": dungeon_id, "floor": floor_count, "difficulty": difficulty})
            except Exception:
                logger.exception("faction quest progress failed (complete)")
            # BUGFIX 2026-06-02 — mini-app dungeon completions weren't completing
            # the dungeon quests (objective_type "complete_dungeon"). The chat path
            # (handlers/dungeons.py:1227) calls track_dungeon_quest_progress on
            # completion; the mini-app advance branch was missing it, so trash-only
            # (and any non-boss) dungeon clears via the mini-app never fired
            # "dungeon_complete". (Boss floors settle via pve_duel_settle, which
            # already tracks it.)
            try:
                from core.dungeon_quest_engine import track_dungeon_quest_progress
                await track_dungeon_quest_progress(
                    session, user_id, dungeon_id,
                    "dungeon_complete", floor_count, difficulty, True,
                )
            except Exception:
                logger.exception("dungeon_quest_progress failed (complete, mini-app)")
            # Quick-wins 2026-06-10 — Abyssal Conqueror (#16). Mirror the
            # `dungeon_abyssal` hook that the chat completion path
            # (handlers/dungeons.py) and the boss-settle path
            # (core.pve_duel_settle._settle_dungeon_boss) already have, right
            # beside the v16.7 quest-progress hook above. NOTE: dungeon #4 is
            # boss-ending, so a real clear settles via _settle_dungeon_boss (which
            # fires this); this branch is the safety net for any non-boss / future
            # completion that resolves here. The thing that actually credits past
            # clearers like [jogador] (who cleared the Rift but never got the title) is
            # the RETROACTIVE grant in achievement_engine.sync_player_snapshot.
            # check_achievements is idempotent + collision-safe, so firing it here
            # AND via the boss/retroactive paths never double-unlocks or crashes.
            if dungeon_id == 4:
                try:
                    from core.achievement_engine import check_achievements
                    await check_achievements(session, user_id, "dungeon_abyssal", 1)
                except Exception:
                    logger.exception("dungeon_abyssal achievement failed (complete, mini-app)")
            ce_gained = 0
            if int(player.realm or 0) == 2:
                try:
                    from core.golden_core_engine import add_core_essence
                    ce_gained = add_core_essence(player, 3)
                except Exception:
                    logger.exception("add_core_essence failed (complete)")

            envelope = await _dungeons_finalize_state(session, player, pd_row)
            named_items = await _resolve_bag_items(session, final_bag, _pl_lang(player))
            # a conclusão sem chefe (o ramo de segurança — medido morto a 08/10:
            # 0 runs com current_floor >= floor_count): o último andar conta
            _g = await _masmorra.ganho_da_acao(session, user_id, dungeon, _antes,
                                               andar=floor_count)
            await session.commit()
            return _json({
                "ok": True,
                "completed": True,
                "won": True,
                "dead": False,
                "floor": floor_count,
                "floor_count": floor_count,
                "best_difficulty": int(pd_row.best_difficulty or 0),
                "best_difficulty_key": DUNGEON_DIFFICULTIES[(pd_row.best_difficulty or 1) - 1],
                "final_loot": final_bag,
                "loot_named_items": named_items,
                "core_essence_gained": int(ce_gained),
                **({"regional_bonus": {"continent": _regional["continent"],
                                       "continent_emoji": _regional["continent_emoji"],
                                       "hits": int(_regional.get("hits") or 1),
                                       "line": await _dng_tribute_line(session, _regional, _pl_lang(player))}}
                   if _regional else {}),
                **envelope,
                **_masmorra.no_payload(_g),
            })

        # Regular floor — pre-check qi, then run.
        eff_qi = _dungeon_eff_qi_cost(int(dungeon.qi_cost_per_floor), int(player.realm or 0))
        if float(player.qi or 0) < eff_qi:
            return _json({"ok": False, "reason": "no_qi",
                          "current_qi": int(player.qi or 0),
                          "qi_cost": eff_qi}, status=200)

        # v15.1.4 — BOSS FLOOR detection (last floor = boss). Spawn a
        # turn-based PvE duel instead of running simulate_combat. The
        # boss settle path (core.pve_duel_settle._settle_dungeon_boss)
        # handles bag transfer + completion stamp once the duel resolves.
        # Trash floors (1..floor_count-1) keep using simulate_combat to
        # preserve farm pace.
        is_boss_floor = (next_floor == floor_count)
        if is_boss_floor:
            from core.duel_engine import (start_duel_pve, check_and_handle_timeout,
                                          unlock_stuck_duels_for_player)
            from core.npc_loadouts import get_dungeon_boss_archetype
            from sqlalchemy import or_ as _or
            from database.models import DuelSession as _DS

            # ── 鎖 Destrancar ANTES de recusar (2026-09-04) ────────────────
            # v16.2.2 ([jogador], 2026-05-26) percebeu metade: duelos com o prazo
            # passado bloqueavam a criacao do chefe para sempre. A correccao de
            # entao chamava `check_and_handle_timeout` UMA vez sobre UM duelo —
            # e as duas coisas estavam curtas:
            #
            #  • `check_and_handle_timeout` resolve **uma ronda**, nao a luta: o
            #    `_resolve_round` volta a por `waiting_actions` com um
            #    `expires_at` novo, e o guard recusa na mesma. Luta de 8 rondas
            #    = 8 tentativas do jogador.
            #  • `.limit(1)` resolvia um duelo por chamada — e havia um jogador
            #    com QUINZE presos.
            #
            # MEDIDO a 2026-09-03: 27 duelos expirados, 13 jogadores trancados,
            # o mais antigo desde 23/05 (103 dias). Agora destranca-se TUDO o
            # que ja' expirou, ate' ao fim, antes de decidir. Uma luta viva (com
            # prazo por passar) nunca e' tocada, logo o bloqueio legitimo —
            # "estas mesmo a meio de um duelo" — continua a funcionar.
            try:
                await unlock_stuck_duels_for_player(session, user_id)
                await session.flush()
            except Exception:
                logger.exception("unlock_stuck_duels falhou user_id=%s", user_id)

            existing = (await session.execute(
                select(_DS).where(
                    _or(
                        _DS.attacker_id == user_id,
                        _DS.defender_id == user_id,
                    ),
                    _DS.state.in_(["waiting_actions", "pending_acceptance"]),
                ).limit(1)
            )).scalar_one_or_none()
            if existing is not None:
                return _json({
                    "ok": False, "reason": "duel_already_active",
                    "duel_id": str(existing.id),
                }, status=200)

            # Spend the qi cost for the boss floor (mirror trash floor
            # behaviour — Qi is consumed even for the boss).
            player.qi = max(0.0, float(player.qi or 0) - float(eff_qi))

            archetype = get_dungeon_boss_archetype(dungeon)
            # Fix 2026-07-14 (report [jogadores]): o boss escalava pelo
            # realm do JOGADOR (trash usa base_bp da dungeon; boss não usava
            # NADA da dungeon) → 2.2M de BP numa dungeon r0 EASY para um
            # jogador de realm alto, e paredes desproporcionais nos realms
            # baixos (bloqueava a essência do núcleo). Âncora nova: o tier da
            # PRÓPRIA dungeon (min_realm..min_realm+1). Quem está no realm da
            # dungeon luta EXATAMENTE o boss de sempre (min(realm, min+1) ==
            # realm); só o over-realm deixa de inflar o boss — melhoria-estrita.
            _dmin = int(dungeon.min_realm or 0)
            _boss_realm = max(_dmin, min(int(player.realm or 0), _dmin + 1))
            boss_duel = await start_duel_pve(
                session, player,
                archetype=archetype,
                difficulty=difficulty,
                source="dungeon_boss",
                context={
                    "dungeon_id": int(dungeon_id),
                    "floor": int(next_floor),
                    "floor_count": int(floor_count),
                },
                npc_realm=_boss_realm,
            )
            await session.commit()
            return _json({
                "ok": True,
                "is_boss_floor": True,
                "boss_duel_id": str(boss_duel.id),
                "redirect_to_duel": True,
                "boss_archetype": archetype,
                "boss_difficulty": difficulty,
                "floor": int(next_floor),
                "floor_count": int(floor_count),
                "won": False,
                "dead": False,
                "completed": False,
            })

        lang = player.language or "pt"
        try:
            won, _narration, loot = await _do_dungeon_floor(
                session, player, dungeon, target_floor=next_floor,
                difficulty=difficulty, lang=lang,
                stance="balanced", focus_tech_id=0,
            )
        except Exception:
            logger.exception("_do_dungeon_floor crashed in api_dungeons_advance")
            await session.rollback()
            return _err("engine_error", 500)

        if won:
            pd_row.current_floor = next_floor
            pd_row.max_floor_reached = max(int(pd_row.max_floor_reached or 0), next_floor)
            pd_row.expedition_bag = _merge_bag(pd_row.expedition_bag or {}, loot)
            pd_row.last_attempt_at = datetime.now(timezone.utc)
            try:
                await track_quest(session, user_id, "dungeon_floor", 1)
            except Exception:
                logger.exception("dungeon_floor track_quest failed (advance)")
            try:
                from core.body_tempering_engine import add_tempering_progress
                add_tempering_progress(player, max(2, int(5 * DUNGEON_DIFF_LOOT_MULT[difficulty])))
            except Exception:
                logger.exception("add_tempering_progress failed (advance)")
            # QoL-Feedback 2 2026-07-30 (report [jogador]: "Clear Mortal Catacombs
            # Floor 5" feito em nightmare no mini e nunca creditado): o ramo
            # de vitória POR ANDAR do mini não disparava NENHUM dos 4 hooks
            # que o chat dispara por andar (handlers/dungeons.py:1526-1549) —
            # faction quest com `floor`, dungeon quest `floor_win`, o
            # achievement dungeon_floors e a essência do núcleo no R2. Como o
            # chat é main-only, no s2 esses objetivos eram INALCANÇÁVEIS por
            # andar (só a conclusão total creditava). Espelho exato, cada um
            # em try/except (padrão deste endpoint).
            try:
                from core.faction_engine import update_quest_progress as _fac_qp
                await _fac_qp(session, user_id, "dungeon",
                              target_filter={"dungeon_id": dungeon_id,
                                             "floor": next_floor,
                                             "difficulty": difficulty})
            except Exception:
                logger.exception("faction quest progress failed (advance floor)")
            try:
                from core.dungeon_quest_engine import track_dungeon_quest_progress
                await track_dungeon_quest_progress(
                    session, user_id, dungeon_id,
                    "floor_win", next_floor, difficulty, False,
                )
            except Exception:
                logger.exception("dungeon_quest floor_win failed (advance)")
            try:
                from core.achievement_engine import check_achievements
                await check_achievements(session, user_id, "dungeon_floors", 1)
            except Exception:
                logger.exception("dungeon_floors achievement failed (advance)")
            if int(player.realm or 0) == 2:
                try:
                    from core.golden_core_engine import add_core_essence
                    add_core_essence(player, 3)
                except Exception:
                    logger.exception("add_core_essence failed (advance floor)")
        else:
            lost_bag = pd_row.expedition_bag or {}
            survivors = _lose_90_percent(lost_bag)
            if survivors:
                await _transfer_bag_to_inventory(session, player, survivors)
            pd_row.current_floor = 0
            pd_row.expedition_bag = {}
            pd_row.difficulty = None
            pd_row.last_attempt_at = datetime.now(timezone.utc)

        envelope = await _dungeons_finalize_state(session, player, pd_row)
        named_items = await _resolve_bag_items(session, loot if won else {}, _pl_lang(player))
        # o andar seguinte só conta como vencido no ramo da vitória
        _g = await _masmorra.ganho_da_acao(session, user_id, dungeon, _antes,
                                           andar=next_floor if won else None)
        await session.commit()

    return _json({
        "ok": True,
        "won": bool(won),
        "dead": (not won),
        "floor": next_floor if won else 0,
        "floor_count": floor_count,
        "completed": False,
        "loot_this_floor": loot if won else {},
        "loot_named_items": named_items,
        **envelope,
        **_masmorra.no_payload(_g),
    })


async def api_dungeons_retreat(request: web.Request) -> web.Response:
    """Retreat from an active dungeon run — claim 100% of the bag, no death penalty.
    Mirrors `dungeon_retreat`. Without it the mini-app would force the player to
    fight or die — which is worse UX than the chat handler."""
    from database.models import DungeonCatalog, PlayerDungeon
    from handlers.dungeons import _transfer_bag_to_inventory

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("dungeon_id")
    try:
        dungeon_id = int(raw_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        pd_row = (await session.execute(
            select(PlayerDungeon).where(
                PlayerDungeon.player_id == user_id,
                PlayerDungeon.dungeon_id == dungeon_id,
            )
        )).scalar_one_or_none()
        if not pd_row or int(pd_row.current_floor or 0) == 0:
            return _json({"ok": False, "reason": "not_in_dungeon"}, status=200)

        bag = pd_row.expedition_bag or {}
        floor_reached = int(pd_row.current_floor or 0)
        await _transfer_bag_to_inventory(session, player, bag)
        pd_row.current_floor = 0
        pd_row.expedition_bag = {}
        pd_row.difficulty = None
        pd_row.last_attempt_at = datetime.now(timezone.utc)
        envelope = await _dungeons_finalize_state(session, player, pd_row)
        named_items = await _resolve_bag_items(session, bag, _pl_lang(player))
        await session.commit()

    return _json({
        "ok": True,
        "retreated": True,
        "floor_reached": floor_reached,
        "claimed_bag": bag,
        "loot_named_items": named_items,
        **envelope,
    })


async def api_dungeons_sweep(request: web.Request) -> web.Response:
    """Auto-clear all floors of a previously completed dungeon at a chosen difficulty.

    Mirrors `dungeon_sweep_exec`. Requires the dungeon to be completed at least
    once (`pd.completed`) and the player to have beaten the chosen difficulty
    (`pd.best_difficulty >= diff_level`). No death risk; just qi cost.
    """
    from database.models import DungeonCatalog, PlayerDungeon, PillCatalog as PillCat, PlayerBuff
    from handlers.dungeons import (
        _roll_floor_loot, _apply_difficulty_loot_mult, _merge_bag,
        _transfer_bag_to_inventory,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("dungeon_id")
    difficulty = (payload.get("difficulty") or "").strip().lower()
    raw_count = payload.get("count", 1)
    try:
        dungeon_id = int(raw_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    if difficulty not in DUNGEON_DIFFICULTIES:
        return _err("bad_request", 400)
    # MA-30b — owner request: count picker 1/5/10/Max for sweep so the
    # player isn't forced to mash the button. Cap at 50 so no single
    # request can hog the worker for too long; client picker exposes
    # 1/5/10/Max where Max is `floor(qi / total_qi_per_sweep)`.
    try:
        sweep_count = int(raw_count) if raw_count is not None else 1
    except (TypeError, ValueError):
        sweep_count = 1
    sweep_count = max(1, min(50, sweep_count))

    async with get_session_factory()() as session:
        # Lock the player row FOR UPDATE so the auto-sweep spam (the bot runs
        # thousands of sweeps in parallel) serializes per player instead of
        # deadlocking / lost-updating the qi debit below (same class as pill/use).
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        dungeon = (await session.execute(
            select(DungeonCatalog).where(DungeonCatalog.id == dungeon_id)
        )).scalar_one_or_none()
        if not dungeon:
            return _err("dungeon_not_found", 404)

        pd_row = (await session.execute(
            select(PlayerDungeon).where(
                PlayerDungeon.player_id == user_id,
                PlayerDungeon.dungeon_id == dungeon_id,
            )
        )).scalar_one_or_none()
        if not pd_row or not pd_row.completed:
            return _json({"ok": False, "reason": "not_completed"}, status=200)

        diff_level = DUNGEON_DIFF_ORDER[difficulty]
        if int(pd_row.best_difficulty or 0) < diff_level:
            return _json({"ok": False, "reason": "diff_gate",
                          "required": difficulty}, status=200)

        # MV-1: sweep também respeita a geografia (recusa honesta).
        from core.dungeon_regions import (
            region_gate as _dng_region_gate,
            regional_bonus_line as _dng_tribute_line,
            roll_regional_bonus as _dng_roll_regional,
        )
        _rg = _dng_region_gate(dungeon, player)
        if _rg:
            return _json({"ok": False, **_rg}, status=200)

        # QoL-relatos — varrer OUTRA masmorra concluída fica livre; varrer aquela
        # onde você está dentro, não (o sweep entrega uma limpeza inteira
        # enquanto a run manual guarda o próprio saco — dupla contagem).
        # Aqui é o caminho de maior valor: sweep_count vai até 50 por pedido.
        from core.dungeon_run_engine import active_run as _dng_active_run
        _open = await _dng_active_run(session, user_id, only=dungeon_id)
        if _open:
            return _json({"ok": False, "reason": "run_here",
                          "run": _open}, status=200)

        floor_count = _dungeon_floor_count(dungeon, difficulty)
        realm = int(player.realm or 0)
        per_floor_qi = _dungeon_eff_qi_cost(int(dungeon.qi_cost_per_floor), realm)
        per_sweep_qi = per_floor_qi * floor_count
        total_qi = per_sweep_qi * sweep_count
        if float(player.qi or 0) < total_qi:
            return _json({"ok": False, "reason": "no_qi",
                          "current_qi": int(player.qi or 0),
                          "qi_cost": total_qi,
                          "qi_per_sweep": per_sweep_qi}, status=200)

        player.qi = max(0.0, float(player.qi or 0) - total_qi)

        # Roll loot for every floor (mirrors handler 1:1).
        try:
            from core.alchemy_engine import roll_recipe_drop
        except Exception:
            roll_recipe_drop = None  # type: ignore

        bag: dict = {}
        total_floors = floor_count * sweep_count
        for _ in range(total_floors):
            # 2026-06-12: `difficulty` was never passed here, so it defaulted
            # to "easy" and _filter_drops_by_difficulty stripped the
            # min_difficulty:"nightmare" entries — Eternal Spring Petal was
            # UNDROPPABLE via mini-app sweeps on dungeons 21/22/23 (the chat
            # sweep always passed it). Parity, not inflation.
            floor_loot = _roll_floor_loot(dungeon.drops or {}, difficulty,
                                          min_realm=int(dungeon.min_realm or 0))
            floor_loot = _apply_difficulty_loot_mult(floor_loot, difficulty)
            bag = _merge_bag(bag, floor_loot)
            if roll_recipe_drop and not bag.get("recipe_pill_id"):
                try:
                    # hard/nightmare → T4 (paridade com o handler; nota N-34)
                    _rt_max = 4 if difficulty in ("hard", "nightmare") else 3
                    rp_id = await roll_recipe_drop(session, user_id, (2, _rt_max), 0.08)
                    if rp_id:
                        bag["recipe_pill_id"] = rp_id
                        pill = await session.get(PillCat, rp_id)
                        bag["recipe_pill_name"] = (catalog_name(_pl_lang(player), "pill", pill)
                                       if pill else f"Recipe #{rp_id}")
                except Exception:
                    logger.exception("roll_recipe_drop failed in sweep")

        # Event multiplier (e.g. Meteor Shower).
        try:
            from handlers.events import get_event_multipliers
            event_mults = await get_event_multipliers(session)
            loot_mult = float(event_mults.get("loot_mult", 1.0) or 1.0)
        except Exception:
            loot_mult = 1.0
        if loot_mult > 1.0:
            scaled: dict = {}
            for k, v in bag.items():
                if k in ("herbs", "ores", "healing_pills") and isinstance(v, dict):
                    scaled[k] = {ik: max(1, int(iv * loot_mult)) for ik, iv in v.items()}
                elif k == "qi_pill_id":
                    scaled[k] = v  # D4: tier marker, never scale it
                elif isinstance(v, (int, float)):
                    scaled[k] = max(1, int(v * loot_mult))
                else:
                    scaled[k] = v
            bag = scaled

        # Fortune Incense — +5% stones.
        try:
            now_ts = datetime.now(timezone.utc)
            incense = (await session.execute(
                select(PlayerBuff).where(
                    PlayerBuff.player_id == user_id,
                    PlayerBuff.buff_type == "fortune_incense",
                    PlayerBuff.expires_at > now_ts,
                )
            )).scalar_one_or_none()
            if incense:
                bag["stones"] = int(bag.get("stones", 0) * 1.05)
        except Exception:
            logger.exception("fortune_incense check failed in sweep")

        # MV-1 §5: roll extra de material nativo POR SWEEP (hard/nightmare,
        # flag ON) — aditivo, antes do transfer para aparecer no loot.
        _regional = None
        try:
            _regional = _dng_roll_regional(dungeon, difficulty, runs=sweep_count)
            if _regional:
                bag = _merge_bag(bag, _regional["loot"])
        except Exception:
            logger.exception("roll_regional_bonus failed (sweep)")

        await _transfer_bag_to_inventory(session, player, bag)
        pd_row.last_attempt_at = datetime.now(timezone.utc)

        tempering_gained = 0
        try:
            from core.body_tempering_engine import add_tempering_progress
            base = max(10, floor_count * 3)
            tempering_gained = add_tempering_progress(
                player, int(base * DUNGEON_DIFF_LOOT_MULT[difficulty]) * sweep_count
            ) or 0
        except Exception:
            logger.exception("add_tempering_progress failed (sweep)")

        ce_gained = 0
        if realm == 2:
            try:
                from core.golden_core_engine import add_core_essence
                ce_gained = add_core_essence(player, 3 * floor_count * sweep_count)
            except Exception:
                logger.exception("add_core_essence failed (sweep)")

        try:
            from core.bp_engine import update_bp_mission
            await update_bp_mission(session, user_id, "complete_dungeon")
        except Exception:
            logger.exception("update_bp_mission failed (sweep)")

        # QoL 31/07 Item B (decisão [jogador], Lei §6): o sweep do mini credita os
        # MESMOS hooks do advance — paridade com o chat, que credita desde
        # 2026-04 (54ad520b). O gate lá em cima (pd_row.completed +
        # best_difficulty >= diff_level) JÁ prova que a dificuldade varrida
        # foi 100% completada ao menos uma vez (expressão canônica — o
        # max_floor_reached cru mentiria para runs antigas fechadas no boss,
        # ver o heal em api_dungeons_list). amount=sweep_count comprime as N
        # varreduras numa chamada por andar; o cap no objetivo vive DENTRO
        # dos engines. Cada hook em try/except (padrão deste endpoint).
        try:
            from core.faction_engine import update_quest_progress as _fac_qp
            await _fac_qp(session, user_id, "dungeon_any", amount=sweep_count)
            for _f in range(1, floor_count + 1):
                await _fac_qp(session, user_id, "dungeon", amount=sweep_count,
                              target_filter={"dungeon_id": dungeon_id,
                                             "floor": _f,
                                             "difficulty": difficulty})
        except Exception:
            logger.exception("faction quest progress failed (sweep)")
        try:
            from core.dungeon_quest_engine import track_dungeon_quest_progress
            for _f in range(1, floor_count + 1):
                await track_dungeon_quest_progress(
                    session, user_id, dungeon_id,
                    "floor_win", _f, difficulty, False, amount=sweep_count,
                )
            await track_dungeon_quest_progress(
                session, user_id, dungeon_id,
                "dungeon_complete", floor_count, difficulty, True,
            )
        except Exception:
            logger.exception("dungeon_quest progress failed (sweep)")
        try:
            from core.achievement_engine import check_achievements
            await check_achievements(session, user_id, "dungeon_floors", total_floors)
        except Exception:
            logger.exception("dungeon_floors achievement failed (sweep)")
        try:
            # ⚠️ FORA DO ESCOPO DESTA ONDA, achado pela caça-NameError por AST
            # (2026-08-09): `track_quest` NUNCA foi importado nesta função — os
            # outros 3 call sites do ficheiro fazem o import local (`:922`,
            # `:1863`, `:3146`). Como a chamada vive num `try/except Exception`
            # que só LOGA, a varredura do mini-app falhava em silêncio a cada
            # execução e NENHUM progresso de `dungeon_floor` era creditado por
            # ali. `py_compile` não apanha isto; a AST apanha.
            from core.quest_engine import track_quest
            await track_quest(session, user_id, "dungeon_floor", total_floors)
        except Exception:
            logger.exception("dungeon_floor track_quest failed (sweep)")

        envelope = await _dungeons_finalize_state(session, player, pd_row)
        named_items = await _resolve_bag_items(session, bag, _pl_lang(player))
        await session.commit()

    return _json({
        "ok": True,
        "floors_swept": total_floors,
        "sweep_count": sweep_count,
        "floors_per_sweep": floor_count,
        "qi_cost": total_qi,
        "qi_per_sweep": per_sweep_qi,
        **({"regional_bonus": {"continent": _regional["continent"],
                               "continent_emoji": _regional["continent_emoji"],
                               "hits": int(_regional.get("hits") or 1),
                               "line": await _dng_tribute_line(
                                   session, _regional,
                                   (player.language or "pt").lower())}}
           if _regional else {}),
        "loot": bag,
        "loot_summary": _bag_summary(bag),
        "loot_named_items": named_items,
        "tempering_gained": int(tempering_gained or 0),
        "core_essence_gained": int(ce_gained or 0),
        "loot_mult": loot_mult,
        **envelope,
    })


# ── Alchemy (MA-31) ───────────────────────────────────────────────────────────
# Heavenly Pill Tribulation state lives in-memory: 3-round mini-game lasts
# <60s, lost-on-deploy is acceptable (rare event, no persistent value), no
# migration needed. Keyed by player_id, TTL 10min.
_PILL_TRIBULATIONS: dict[int, dict] = {}
_PILL_TRIB_TTL_SECONDS = 600


def _trib_cleanup_expired() -> None:
    now_ts = datetime.now(timezone.utc).timestamp()
    stale = [pid for pid, st in _PILL_TRIBULATIONS.items()
             if now_ts - st.get("started_at_ts", 0) > _PILL_TRIB_TTL_SECONDS]
    for pid in stale:
        _PILL_TRIBULATIONS.pop(pid, None)


def _alchemy_cauldron_dict(pc, cauldron, lang: str = "pt") -> dict | None:
    if not pc or not cauldron:
        return None
    return {
        "id": int(cauldron.id),
        # 冶 3.1 — o caldeirão é o corpo da Alquimia e nunca teve tradução.
        "name": catalog_name(lang, "cauldron", cauldron),
        "emoji": cauldron.emoji or "⚗️",
        "grade": int(cauldron.grade),
        "durability": int(pc.durability or 0),
        "max_durability": int(cauldron.max_durability or 0),
        "success_bonus": float(cauldron.success_bonus or 0),
        "slots": int(cauldron.slots or 3),
        "is_equipped": bool(pc.is_equipped),
    }


async def api_alchemy_recipes(request: web.Request) -> web.Response:
    """Read endpoint — full alchemy state + recipe catalog grouped by tier.

    Bulk-fetches everything (no N+1): pills, herbs, cauldrons, masteries,
    resistances, ingredient inventory in single queries. Computes per-recipe
    success chance, blocked reasons, and ingredient owned counts.
    """
    from core.alchemy_engine import (
        get_alchemy_energy, get_or_create_alchemy_skill, get_or_create_soul_fire,
        get_equipped_cauldron, get_player_cauldrons, get_all_pills, get_all_herbs,
        get_unlocked_pill_ids, get_all_pill_masteries, get_all_pill_resistances,
        get_resistance_display, get_mastery_bonus, get_mastery_name,
        get_soul_fire_bonus, get_soul_fire_name,
        calculate_success_chance, get_tier_name, give_starter_cauldron,
        ensure_starter_recipes, ALCHEMY_TIERS, MAX_ALCHEMY_TIER,
        MAX_SOUL_FIRE_TIER, SOUL_FIRE_TIERS, SOUL_FIRE_MIN_REALM,
        ALCHEMY_MIN_REALM, alchemy_realm_locked,
    )
    from database.models import (
        PillCatalog as _PillCat, HerbCatalog as _HerbCat, PlayerInventory as _Inv,
    )
    from config import ALCHEMY_ENERGY_COSTS, ALCHEMY_ENERGY_VIP_REGEN

    user_id: int = request["user_id"]

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        lang = player.language or "pt"
        _cur_cont = getattr(player, "current_continent", None)
        # 冶 3.1 — o limiar é do motor (`ALCHEMY_MIN_REALM`), não um 1 escrito aqui.
        realm_locked = alchemy_realm_locked(player)

        # Side-effects: ensure starter rows exist (idempotent — handler does same).
        await give_starter_cauldron(session, user_id)
        await ensure_starter_recipes(session, user_id)

        # Bulk-fetch everything we need in parallel (no N+1)
        from core.monetization import get_player_vip_level
        vip_lvl = await get_player_vip_level(session, user_id)

        skill = await get_or_create_alchemy_skill(session, user_id)
        sf = await get_or_create_soul_fire(session, user_id, int(player.realm or 0))
        pc, cauldron = await get_equipped_cauldron(session, user_id)
        owned_cauldrons_rows = await get_player_cauldrons(session, user_id)
        all_pills = await get_all_pills(session)
        all_herbs = await get_all_herbs(session)
        unlocked_ids = await get_unlocked_pill_ids(session, user_id)
        masteries = await get_all_pill_masteries(session, user_id)
        resistances_map = await get_all_pill_resistances(session, user_id)

        # Bulk-fetch herb inventory (one query for all herbs)
        herb_inv_rows = (await session.execute(
            select(_Inv.item_id, _Inv.quantity).where(and_(
                _Inv.player_id == user_id,
                _Inv.item_type == "herb",
            ))
        )).all()
        herb_owned = {int(r[0]): int(r[1]) for r in herb_inv_rows}
        herb_by_id = {int(h.id): h for h in all_herbs}

        # U3 (v16.6): bulk-fetch owned PILL counts (SUM across quality rows — pills
        # stack per quality) so each recipe can show "X owned" in the craft list.
        pill_inv_rows = (await session.execute(
            select(_Inv.item_id, _Inv.quantity).where(and_(
                _Inv.player_id == user_id,
                _Inv.item_type == "pill",
            ))
        )).all()
        pill_owned: dict[int, int] = {}
        for r in pill_inv_rows:
            pill_owned[int(r[0])] = pill_owned.get(int(r[0]), 0) + int(r[1] or 0)

        energy_current, energy_max, regen_minutes = get_alchemy_energy(player, vip_lvl, skill.tier)

        # 火候 Ponto do Fogo — o que o POSTO comprou na chama, e o degrau seguinte.
        from core.alchemy_engine import get_flame_mastery as _gfm
        _fm_bonus, _fm_mult = _gfm(skill.tier)
        _flame_payload = {
            "tier": int(skill.tier),
            "max_bonus": int(_fm_bonus),
            "regen_pct": round((1.0 - _fm_mult) * 100),
        }
        if int(skill.tier) < MAX_ALCHEMY_TIER:
            _nb, _nm = _gfm(int(skill.tier) + 1)
            _flame_payload["next"] = {
                "tier_name": get_tier_name(int(skill.tier) + 1, lang),
                "max_bonus": int(_nb),
                "regen_pct": round((1.0 - _nm) * 100),
            }

        # QoL-Feedback 2026-07-29 Item D (MA-48): contagem de núcleos de besta
        # para o botão Alimentar a Chama. SUM (não .first()) — o inventário pode
        # ter mais de uma row do mesmo item_type (espelho do beasts/list).
        beast_cores = int((await session.execute(
            select(func.coalesce(func.sum(_Inv.quantity), 0)).where(and_(
                _Inv.player_id == user_id,
                _Inv.item_type == "beast_core",
            ))
        )).scalar() or 0)

        await session.commit()

    # 冶 3.1 — o retrato é o de `core/oficios.py`: a MESMA forma (e o mesmo
    # "quanto falta") que o resultado de uma feitura manda antes e depois.
    from core.oficios import retrato_alquimia, retrato_fogo, retrato_receita_pilula
    _ra = retrato_alquimia(skill)
    a_tier = _ra["tier"]
    a_xp = _ra["xp"]
    a_emoji = ALCHEMY_TIERS.get(a_tier, ALCHEMY_TIERS[1])["emoji"]
    a_at_max = _ra["at_max"]
    a_xp_to_next = _ra["xp_to_next"]

    # Soul fire
    _rf = retrato_fogo(sf)
    sf_tier = _rf["tier"]
    sf_at_max = _rf["at_max"]
    sf_unlocked = int(player.realm or 0) >= SOUL_FIRE_MIN_REALM
    sf_xp_to_next = _rf["xp_to_next"]
    sf_bonus_pct = get_soul_fire_bonus(sf_tier)

    # Cauldron payloads
    equipped_payload = _alchemy_cauldron_dict(pc, cauldron, lang)
    owned_payload = []
    for row_pc, row_cat in owned_cauldrons_rows:
        owned_payload.append(_alchemy_cauldron_dict(row_pc, row_cat, lang))

    # Mastery bonus from equipped cauldron + soul fire
    cauldron_for_calc = cauldron  # may be None
    soul_fire_bonus = sf_bonus_pct

    # MV-7 — bônus do Alquimista, computado UMA vez fora do loop (display =
    # roll: mesma função do craft; gated, 0.0 com flag OFF).
    try:
        from core.profession_engine import alchemy_success_bonus as _prof_alch_b
        prof_success_bonus = float(_prof_alch_b(player) or 0.0)
    except Exception:
        prof_success_bonus = 0.0

    # Build recipe groups by tier
    tier_groups: dict[int, list[_PillCat]] = {}
    for pill in all_pills:
        tier_groups.setdefault(int(pill.required_alchemy_tier or 1), []).append(pill)

    tiers_payload = []
    for tier_idx in sorted(tier_groups.keys()):
        tier_locked = tier_idx > a_tier
        tier_recipes = []

        for pill in tier_groups[tier_idx]:
            unlocked = int(pill.id) in unlocked_ids
            mastery = masteries.get(int(pill.id))
            m_info = retrato_receita_pilula(mastery)
            mastery_level = m_info["level"]
            mastery_crafts = m_info["crafts_count"]
            mastery_bonus = get_mastery_bonus(mastery_level)

            success_chance = calculate_success_chance(
                cauldron_for_calc, pill, a_tier, mastery_bonus, soul_fire_bonus,
                profession_bonus=prof_success_bonus,
            )

            energy_cost = int(ALCHEMY_ENERGY_COSTS.get(int(pill.required_alchemy_tier or 1), 10))

            # Ingredients with owned counts (bulk-fetched, no N+1)
            ingredients_payload = []
            ingredients_ok = True
            for ing in (pill.ingredients or []):
                herb_id = int(ing.get("herb_id", 0))
                qty = int(ing.get("qty", 0))
                owned = int(herb_owned.get(herb_id, 0))
                herb_obj = herb_by_id.get(herb_id)
                if owned < qty:
                    ingredients_ok = False
                # MV-9.5 — a receita cinzenta passa a dizer ONDE nasce o que
                # falta. Key CONDICIONAL (`origin_note` devolve None com a flag
                # OFF) ⇒ payload byte-idêntico para os 239 do `main`.
                _org = _origin_note("herb", herb_id, lang, _cur_cont)
                ingredients_payload.append({
                    "herb_id": herb_id,
                    "qty": qty,
                    "owned": owned,
                    "name": catalog_name(lang, "herb", herb_obj, fallback=f"Herb #{herb_id}"),
                    "emoji": (herb_obj.emoji if herb_obj else "🌿"),
                    "tier": int(herb_obj.tier) if herb_obj else 1,
                    "ok": owned >= qty,
                    **({"origin": _org} if _org else {}),
                })

            uses = int(resistances_map.get(int(pill.id), 0))
            res = get_resistance_display(uses) if uses > 0 else None

            blocked: list[str] = []
            if tier_locked:
                blocked.append("tier_locked")
            if not unlocked:
                blocked.append("recipe_locked")
            if int(player.realm or 0) < int(pill.min_realm or 0):
                blocked.append("realm_too_low")
            if not ingredients_ok:
                blocked.append("missing_ingredients")
            if energy_current < energy_cost:
                blocked.append("not_enough_energy")
            if not equipped_payload:
                blocked.append("no_cauldron")
            elif equipped_payload.get("durability", 0) <= 0:
                blocked.append("cauldron_broken")

            tier_recipes.append({
                "id": int(pill.id),
                "name": catalog_name(lang, "pill", pill),
                "art_key": catalog_art_key(pill),
                "emoji": pill.emoji or "💊",
                "description": catalog_desc(lang, "pill", pill),
                "difficulty": int(pill.difficulty or 1),
                "effect_type": pill.effect_type or "",
                "effect_value": float(pill.effect_value or 0),
                "duration_minutes": int(pill.duration_minutes or 0),
                "min_realm": int(pill.min_realm or 0),
                "required_alchemy_tier": int(pill.required_alchemy_tier or 1),
                "energy_cost": energy_cost,
                "unlocked": unlocked,
                "owned": int(pill_owned.get(int(pill.id), 0)),  # U3 (v16.6)
                "ingredients": ingredients_payload,
                "ingredients_ok": ingredients_ok,
                "mastery": {
                    "level": mastery_level,
                    "name": get_mastery_name(mastery_level, lang),
                    "crafts_count": mastery_crafts,
                    "next_crafts": m_info.get("next_crafts"),
                    "next_level": m_info.get("next_level"),
                    "at_max": bool(m_info.get("at_max")),
                    "bonus": mastery_bonus,
                },
                "success_chance": round(success_chance, 1),
                "resistance": res,
                "can_craft": len(blocked) == 0,
                "blocked_reasons": blocked,
            })

        tiers_payload.append({
            "tier": tier_idx,
            "name": get_tier_name(tier_idx, lang),
            "emoji": ALCHEMY_TIERS.get(tier_idx, ALCHEMY_TIERS[1])["emoji"],
            "locked": tier_locked,
            "is_current": tier_idx == a_tier,
            "recipes": tier_recipes,
        })

    return _json({
        "ok": True,
        "realm_locked": realm_locked,
        "min_realm_required": ALCHEMY_MIN_REALM,
        "alchemy": {
            "tier": a_tier,
            "tier_name": get_tier_name(a_tier, lang),
            "tier_emoji": a_emoji,
            "xp": a_xp,
            "xp_to_next": a_xp_to_next,
            "at_max": a_at_max,
            "max_tier": MAX_ALCHEMY_TIER,
        },
        "soul_fire": {
            "tier": sf_tier,
            "name": get_soul_fire_name(sf_tier, lang),
            "bonus_pct": sf_bonus_pct,
            "xp": int(sf.fire_exp or 0),
            "xp_to_next": sf_xp_to_next,
            "at_max": sf_at_max,
            "min_realm": SOUL_FIRE_MIN_REALM,
            "unlocked": sf_unlocked,
            "max_tier": MAX_SOUL_FIRE_TIER,
            # QoL-Feedback 2026-07-29 Item D (MA-48): núcleos para o feed.
            "cores": beast_cores,
        },
        "energy": {
            "current": int(energy_current),
            "max": int(energy_max),
            "regen_minutes": float(regen_minutes),
            "vip_level": int(vip_lvl),
            # 火候 (2026-08-18) — o eixo APRENDIDO da chama, para a mesma verdade
            # aparecer no mini-app e no chat. Chaves sempre presentes; tier 1 traz
            # bonus 0 e o degrau seguinte (nunca um "+0" celebrado).
            "flame": _flame_payload,
        },
        "equipped_cauldron": equipped_payload,
        "owned_cauldrons": owned_payload,
        "tiers": tiers_payload,
        "qi": int(player.qi or 0),
        "qi_capacity": int(player.qi_capacity or 0),
    })


async def api_alchemy_craft(request: web.Request) -> web.Response:
    """Write — craft a pill. Reuses core.alchemy_engine.craft_pill.

    Validates: realm gate, alchemy tier, recipe unlock, ingredients, cauldron
    durability, energy, meditation. On heavenly result, stages tribulation
    state in memory and returns `result: heavenly_tribulation_pending`.
    """
    from core.alchemy_engine import (
        craft_pill, get_or_create_alchemy_skill, get_unlocked_pill_ids,
        get_equipped_cauldron, check_ingredients, consume_alchemy_energy,
        grant_alchemy_xp, ALCHEMY_TIERS, MAX_ALCHEMY_TIER, XP_REWARDS,
        ALCHEMY_MIN_REALM, alchemy_realm_locked,
    )
    from database.models import PillCatalog as _PillCat
    from config import ALCHEMY_ENERGY_COSTS

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_pill_id = payload.get("pill_id")
    try:
        pill_id = int(raw_pill_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        # FOR UPDATE: serialize concurrent pill crafts per player (the bot
        # auto-crafts in parallel) so ingredient + alchemy-energy consumption
        # can't lost-update / deadlock — i.e. craft more pills than were paid for.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if alchemy_realm_locked(player):
            return _json({"ok": False, "reason": "realm_locked",
                          "min_realm": ALCHEMY_MIN_REALM}, status=200)

        # 2026-05-17: removed RESTRICTED_MEDITATION gate. Chat-side
        # `handlers/alchemy.py` allows crafting in any meditation state — the
        # workshop is stationary, doesn't break meditation. Owner [jogador] reported
        # the asymmetry: "app does not allow crafting if in meditation, text
        # menu allows". Aligned mini-app with chat semantics.

        pill = (await session.execute(
            select(_PillCat).where(_PillCat.id == pill_id)
        )).scalar_one_or_none()
        if not pill:
            return _err("pill_not_found", 404)

        if int(player.realm or 0) < int(pill.min_realm or 0):
            return _json({"ok": False, "reason": "realm_too_low",
                          "min_realm": int(pill.min_realm)}, status=200)

        skill = await get_or_create_alchemy_skill(session, user_id)
        a_tier = int(skill.tier)
        if a_tier < int(pill.required_alchemy_tier or 1):
            return _json({"ok": False, "reason": "tier_locked",
                          "required_tier": int(pill.required_alchemy_tier)}, status=200)

        unlocked_ids = await get_unlocked_pill_ids(session, user_id)
        if int(pill.id) not in unlocked_ids:
            return _json({"ok": False, "reason": "recipe_locked"}, status=200)

        ingredients_status = await check_ingredients(session, user_id, pill)
        if not all(info["has_enough"] for info in ingredients_status.values()):
            return _json({"ok": False, "reason": "missing_ingredients"}, status=200)

        pc, cauldron = await get_equipped_cauldron(session, user_id)
        if not pc or not cauldron:
            return _json({"ok": False, "reason": "no_cauldron"}, status=200)
        if int(pc.durability or 0) <= 0:
            return _json({"ok": False, "reason": "cauldron_broken"}, status=200)

        # Energy check + consume
        from core.monetization import get_player_vip_level
        vip_lvl = await get_player_vip_level(session, user_id)
        pill_tier = int(pill.required_alchemy_tier or 1)
        energy_cost = int(ALCHEMY_ENERGY_COSTS.get(pill_tier, 10))

        # Snapshot ingredients BEFORE craft (engine consumes them).
        ingredients_consumed = []
        for hid, info in ingredients_status.items():
            herb = info.get("herb")
            ingredients_consumed.append({
                "herb_id": int(hid),
                "qty": int(info.get("required", 0)),
                "name": catalog_name(_pl_lang(player), "herb", herb) if herb else f"Herb #{hid}",
                "emoji": herb.emoji if herb else "🌿",
            })

        energy_ok, energy_after, energy_max = consume_alchemy_energy(player, energy_cost, vip_lvl, skill.tier)
        if not energy_ok:
            return _json({"ok": False, "reason": "not_enough_energy",
                          "energy_current": int(energy_after), "energy_max": int(energy_max),
                          "energy_cost": energy_cost}, status=200)

        # 冶 3.1 — o "antes" do ofício, lido SEM criar nada e na MESMA transacção
        # da feitura (`core/oficios.py`). Só com a onda: o `main` não paga isto
        # e recebe o payload de hoje.
        from core import oficios as _of
        from core.portas import onda_on as _onda_on
        _antes_of = (await _of.ler_antes_alquimia(session, user_id, int(pill.id))
                     if _onda_on() else None)

        # Run engine
        try:
            craft_data = await craft_pill(session, player, pill, a_tier)
        except Exception:
            logger.exception("craft_pill engine crashed in api_alchemy_craft")
            await session.rollback()
            return _err("engine_error", 500)

        if craft_data.get("inventory_full"):
            # Engine pre-checked and aborted — restore energy + return.
            # NOTE: ingredients NOT consumed in this path (engine's contract).
            player.alchemy_energy = int(energy_after) + energy_cost
            await session.commit()
            return _json({"ok": False, "reason": "inventory_full"}, status=200)

        result_key = craft_data.get("result", "failure")
        success_chance = float(craft_data.get("success_chance", 0))
        durability_after = int(pc.durability or 0)
        durability_max = int(cauldron.max_durability or 0)

        # ── HEAVENLY → stage tribulation, return pending ──
        if result_key == "heavenly":
            # Engine already: consumed ingredients, incremented mastery, granted SF XP.
            # Add alchemy XP for heavenly + persist.
            xp_gain = XP_REWARDS.get("heavenly", 0)
            skill, leveled_up = await grant_alchemy_xp(session, user_id, "heavenly")
            await session.commit()

            # Stage in-memory tribulation state.
            _trib_cleanup_expired()
            _PILL_TRIBULATIONS[user_id] = {
                "pill_id": int(pill.id),
                # 名 2026-09-14 — o nome vai traduzido (para LER) e a chave vai
                # canonica (para ENCONTRAR a arte). Ver `catalog_art_key`.
                "pill_name": catalog_name(_pl_lang(player), "pill", pill),
                "pill_art_key": catalog_art_key(pill),
                "pill_emoji": pill.emoji or "💊",
                "pill_tier": pill_tier,
                "round": 1,
                "successes": 0,
                "history": [],
                "xp_gained": xp_gain,
                "started_at_ts": datetime.now(timezone.utc).timestamp(),
            }

            return _json({
                "ok": True,
                "result": "heavenly_tribulation_pending",
                "tribulation": {
                    "pill_id": int(pill.id),
                    "pill_name": catalog_name(_pl_lang(player), "pill", pill),
                    "pill_art_key": catalog_art_key(pill),
                    "pill_emoji": pill.emoji or "💊",
                    "pill_tier": pill_tier,
                    "round": 1,
                    "rounds_total": 3,
                    "successes": 0,
                    "pass_threshold": 2,
                    "history": [],
                },
                "ingredients_consumed": ingredients_consumed,
                "energy_after": int(player.alchemy_energy or 0),
                "energy_max": int(energy_max),
                "alchemy_xp_gained": xp_gain,
                "alchemy_tier": int(skill.tier),
                "alchemy_xp": int(skill.xp),
                "alchemy_leveled_up": bool(leveled_up),
                "delta": {"qi": int(player.qi or 0)},
                # 冶 3.1 — o ganho confirmado (chave CONDICIONAL, só com a onda).
                **_of.no_payload(_of.ganho_alquimia(
                    _antes_of, skill, craft_data.get("mastery"), craft_data.get("soul_fire"))),
            })

        # ── REGULAR results (success/perfect/divine/failure/explosion) ──
        # Quest tracking + downstream side-effects on success-tier outcomes.
        ce_added = 0
        ach_unlocked = []
        # TEC-1 §0.1 (pedido [jogador]) — XP do ofício VISÍVEL no resumo do craft.
        from core.profession_engine import prof_xp_delta, prof_xp_snapshot
        _prof_xp_before = prof_xp_snapshot(player)
        if result_key in ("success", "perfect", "divine"):
            try:
                from core.quest_engine import track_quest
                # QoL-relatos — peso pelo tier da pílula (canal próprio, nunca amount).
                await track_quest(session, user_id, "craft_pill",
                                  prof_weight_tier=pill_tier)
            except Exception:
                logger.exception("craft_pill track_quest failed")
            try:
                from core.bp_engine import update_bp_mission
                await update_bp_mission(session, user_id, "craft_pills")
            except Exception:
                logger.exception("update_bp_mission craft_pills failed")
            try:
                from core.faction_engine import update_quest_progress as fac_quest_progress
                await fac_quest_progress(session, user_id, "craft_pill")
                if result_key in ("perfect", "divine"):
                    await fac_quest_progress(session, user_id, "craft_pill_hq")
            except Exception:
                logger.exception("faction quest_progress craft_pill failed")
            if int(player.realm or 0) == 2:
                try:
                    from core.golden_core_engine import add_core_essence
                    essence_gain = {"success": 5, "perfect": 15, "divine": 30}.get(result_key, 5)
                    ce_added = add_core_essence(player, essence_gain) or 0
                except Exception:
                    logger.exception("add_core_essence failed in craft_pill")
            # Owner reported 2026-05-20: "pílulas de qualidade Perfeitas
            # não estejam sendo contadas para aumentar o progresso da
            # conquista de Pill Adept e Pill Emperor". Root cause: this
            # endpoint had every other side-effect (quest, bp, faction,
            # core essence) but was MISSING check_achievements. The chat
            # handler (handlers/alchemy.py:578) tracks correctly. So
            # every craft via mini-app since MA-31 didn't count toward
            # `pills_crafted` event. ALL qualities affected, not just
            # Perfect — owner spotted it on Perfect because that's the
            # tier they were polishing.
            try:
                from core.achievement_engine import check_achievements
                ach_unlocked = await check_achievements(session, user_id, "pills_crafted", 1) or []
            except Exception:
                logger.exception("check_achievements pills_crafted failed (single)")

        xp_gain = XP_REWARDS.get(result_key, 0)
        skill, leveled_up = await grant_alchemy_xp(session, user_id, result_key)

        # Mirror chat handler — when alchemy tier levels up, set BP mission progress.
        if leveled_up:
            try:
                from database.models import PlayerBPMission, BattlePassMission
                from config import CURRENT_SEASON
                _alch_missions = (await session.execute(
                    select(BattlePassMission).where(BattlePassMission.objective_type == "alchemy_tier")
                )).scalars().all()
                for _am in _alch_missions:
                    _pm = (await session.execute(
                        select(PlayerBPMission).where(
                            PlayerBPMission.player_id == user_id,
                            PlayerBPMission.mission_id == _am.id,
                            PlayerBPMission.season == CURRENT_SEASON,
                        )
                    )).scalar_one_or_none()
                    if _pm is None:
                        _pm = PlayerBPMission(
                            player_id=user_id, mission_id=_am.id,
                            season=CURRENT_SEASON, progress=0, is_completed=False, claimed=False,
                        )
                        session.add(_pm)
                    if not _pm.is_completed:
                        _pm.progress = min(int(skill.tier), int(_am.objective_value))
                        if _pm.progress >= int(_am.objective_value):
                            _pm.is_completed = True
                            from core.bp_engine import recalculate_bp_tier
                            await recalculate_bp_tier(session, user_id)
            except Exception:
                logger.exception("alchemy_tier BP mission update failed")

        # Refresh post-craft cauldron durability (engine may have docked it).
        durability_after = int(pc.durability or 0)

        await session.commit()

    a_tier_after = int(skill.tier)
    a_xp_to_next = _of.retrato_alquimia(skill)["xp_to_next"]  # 冶 3.1 — um so' "quanto falta"

    mastery = craft_data.get("mastery")
    soul_fire = craft_data.get("soul_fire")

    return _json({
        "ok": True,
        "result": result_key,
        "quality": craft_data.get("quality"),
        "potency_mult": float(craft_data.get("potency_mult", 0) or 0),
        "success_chance": round(success_chance, 1),
        "ingredients_consumed": ingredients_consumed if result_key != "failure" and result_key != "explosion" else ingredients_consumed,
        "energy_after": int(player.alchemy_energy or 0),
        "energy_max": int(energy_max),
        "durability_after": durability_after,
        "durability_max": durability_max,
        "alchemy_xp_gained": xp_gain,
        "alchemy_tier": a_tier_after,
        "alchemy_xp": int(skill.xp),
        "alchemy_xp_to_next": a_xp_to_next,
        "alchemy_leveled_up": bool(leveled_up),
        "mastery_level": int(mastery.mastery_level) if mastery else None,
        "mastery_crafts": int(mastery.crafts_count) if mastery else None,
        "mastery_leveled_up": bool(craft_data.get("mastery_leveled")),
        "soul_fire_tier": int(soul_fire.fire_tier) if soul_fire else None,
        "soul_fire_xp": int(soul_fire.fire_exp) if soul_fire else None,
        "soul_fire_leveled_up": bool(craft_data.get("soul_fire_leveled")),
        "core_essence_added": int(ce_added),
        "charm_used": bool(craft_data.get("charm_used")),
        # MV-7 — key CONDICIONAL (payload do main byte-idêntico).
        **({"extra_pill": True} if craft_data.get("extra_pill") else {}),
        # TEC-1 §0.1 + QoL-relatos — XP do ofício e o PESO que o produziu (todas
        # as keys condicionais; UM helper, ver _prof_xp_payload).
        **_prof_xp_payload(player, _prof_xp_before, pill_tier),
        "delta": {"qi": int(player.qi or 0)},
        # 冶 3.1 — o ganho confirmado (chave CONDICIONAL, só com a onda).
        **_of.no_payload(_of.ganho_alquimia(_antes_of, skill, mastery, soul_fire)),
    })


async def api_alchemy_tribulation_action(request: web.Request) -> web.Response:
    """Write — advance one round of the Heavenly Pill Tribulation mini-game.

    Reuses `roll_tribulation_round` + `apply_tribulation_failure` from the
    engine. State is in-memory (lost on deploy is fine — rare event, no
    persistent value, mini-game lasts <60s).
    """
    from core.alchemy_engine import (
        roll_tribulation_round, apply_tribulation_failure,
        PILL_TRIBULATION_CHOICES, PILL_TRIBULATION_ROUNDS,
        PILL_TRIBULATION_PASS_THRESHOLD,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    action = (payload.get("action") or "").strip().lower()
    if action not in PILL_TRIBULATION_CHOICES:
        return _err("invalid_action", 400)

    _trib_cleanup_expired()
    state = _PILL_TRIBULATIONS.get(user_id)
    if not state:
        return _json({"ok": False, "reason": "no_active_tribulation"}, status=200)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        choice_config = PILL_TRIBULATION_CHOICES[action]

        # Sacrifice: -10% Qi (current) per round
        qi_lost = 0
        if action == "sacrifice":
            qi_lost = int(float(player.qi or 0) * 0.10)
            player.qi = max(0, float(player.qi or 0) - qi_lost)

        passed = roll_tribulation_round(action)
        bonus = 1 if (passed and choice_config.get("bonus_on_success")) else 0

        state["history"].append({"action": action, "passed": passed})
        if passed:
            state["successes"] += 1 + bonus
        state["round"] += 1

        completed = state["round"] > PILL_TRIBULATION_ROUNDS
        round_payload = {"action": action, "passed": passed, "bonus_applied": bonus}

        if not completed:
            await session.commit()
            return _json({
                "ok": True,
                "round_result": round_payload,
                "tribulation": {
                    "pill_id": state["pill_id"],
                    "pill_name": state["pill_name"],
                    "pill_art_key": state.get("pill_art_key"),
                    "pill_emoji": state["pill_emoji"],
                    "pill_tier": state["pill_tier"],
                    "round": state["round"],
                    "rounds_total": PILL_TRIBULATION_ROUNDS,
                    "successes": state["successes"],
                    "pass_threshold": PILL_TRIBULATION_PASS_THRESHOLD,
                    "history": state["history"],
                },
                "qi_lost": qi_lost,
                "completed": False,
                "delta": {"qi": int(player.qi or 0)},
            })

        # ── Tribulation finished ──
        passed_overall = state["successes"] >= PILL_TRIBULATION_PASS_THRESHOLD
        pill_id = state["pill_id"]
        pill_name = state["pill_name"]
        pill_emoji = state["pill_emoji"]
        pill_tier = state["pill_tier"]
        history_final = list(state["history"])

        if passed_overall:
            from core.utils import add_item_to_inventory, _get_or_create_ring, _count_used_slots
            added = await add_item_to_inventory(session, user_id, "pill", pill_id, 1, "heavenly")
            if not added:
                ring = await _get_or_create_ring(session, user_id)
                used = await _count_used_slots(session, user_id)
                await session.commit()
                _PILL_TRIBULATIONS.pop(user_id, None)
                return _json({"ok": False, "reason": "inventory_full",
                              "used": int(used), "max": int(ring.max_slots)}, status=200)

            # QoL-relatos — a 4ª superfície de craft concedia XP de ofício em
            # SILÊNCIO (nunca emitiu prof_xp_gained). Com o peso, a celestial
            # T4/T5 vira o maior ganho do jogo — tem de ser dito (Lei §10).
            from core.profession_engine import prof_xp_delta, prof_xp_snapshot
            _prof_xp_before = prof_xp_snapshot(player)
            try:
                from core.quest_engine import track_quest
                # QoL-relatos — a tribulação também pesa (pill_tier vem do state).
                await track_quest(session, user_id, "craft_pill",
                                  prof_weight_tier=pill_tier)
            except Exception:
                logger.exception("track_quest craft_pill failed (tribulation)")
            try:
                from core.bp_engine import update_bp_mission
                await update_bp_mission(session, user_id, "craft_pills")
            except Exception:
                logger.exception("update_bp_mission failed (tribulation)")
            try:
                from core.faction_engine import update_quest_progress as fac_quest_progress
                await fac_quest_progress(session, user_id, "craft_pill")
                await fac_quest_progress(session, user_id, "craft_pill_hq")
            except Exception:
                logger.exception("faction quest_progress failed (tribulation)")
            # Round 6: same gap as the regular craft endpoints — heavenly
            # success path also forgot to call check_achievements. This is
            # the rarest path (heavenly tribulation success) but still
            # contributes to Pill Adept/Pill Emperor progress.
            try:
                from core.achievement_engine import check_achievements
                await check_achievements(session, user_id, "pills_crafted", 1)
            except Exception:
                logger.exception("check_achievements pills_crafted failed (tribulation)")

            await session.commit()
            _PILL_TRIBULATIONS.pop(user_id, None)

            return _json({
                "ok": True,
                "round_result": round_payload,
                "tribulation": {
                    "pill_id": pill_id, "pill_name": pill_name, "pill_emoji": pill_emoji,
                    "pill_tier": pill_tier,
                    "round": PILL_TRIBULATION_ROUNDS, "rounds_total": PILL_TRIBULATION_ROUNDS,
                    "successes": state["successes"],
                    "pass_threshold": PILL_TRIBULATION_PASS_THRESHOLD,
                    "history": history_final,
                },
                "completed": True,
                "passed": True,
                "pill_added": {
                    "id": pill_id, "name": pill_name, "emoji": pill_emoji,
                    "quality": "heavenly", "potency_mult": 5.0,
                },
                "qi_lost": qi_lost,
                # QoL-relatos — keys CONDICIONAIS (payload do main byte-idêntico).
                **_prof_xp_payload(player, _prof_xp_before, pill_tier),
                "delta": {"qi": int(player.qi or 0)},
            })

        # ── Failure ──
        penalties = await apply_tribulation_failure(session, player)
        await session.commit()
        _PILL_TRIBULATIONS.pop(user_id, None)

        return _json({
            "ok": True,
            "round_result": round_payload,
            "tribulation": {
                "pill_id": pill_id, "pill_name": pill_name, "pill_emoji": pill_emoji,
                "pill_tier": pill_tier,
                "round": PILL_TRIBULATION_ROUNDS, "rounds_total": PILL_TRIBULATION_ROUNDS,
                "successes": state["successes"],
                "pass_threshold": PILL_TRIBULATION_PASS_THRESHOLD,
                "history": history_final,
            },
            "completed": True,
            "passed": False,
            "penalty": {
                "durability_lost": int(penalties.get("durability_lost", 0)),
                "qi_lost": int(penalties.get("qi_lost", 0)) + qi_lost,
                "qi_loss_pct": 20,
            },
            "delta": {"qi": int(player.qi or 0)},
        })


async def api_alchemy_equip_cauldron(request: web.Request) -> web.Response:
    """Write — equip an owned cauldron, unequipping any previously equipped one.

    Mirrors the chat `equip_cauldron_callback`. No cost, no roll — just a
    swap. Returns the new equipped_cauldron payload.
    """
    from database.models import (
        PlayerCauldron as _PC, CauldronCatalog as _CauldronCat,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("cauldron_id")
    try:
        cauldron_id = int(raw_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        all_pc = (await session.execute(
            select(_PC).where(_PC.player_id == user_id)
        )).scalars().all()

        target = None
        for pc in all_pc:
            if int(pc.cauldron_id) == cauldron_id:
                target = pc
            pc.is_equipped = False

        if not target:
            return _json({"ok": False, "reason": "not_owned"}, status=200)

        target.is_equipped = True

        cauldron = (await session.execute(
            select(_CauldronCat).where(_CauldronCat.id == cauldron_id)
        )).scalar_one_or_none()

        await session.commit()

    return _json({
        "ok": True,
        "equipped_cauldron": _alchemy_cauldron_dict(target, cauldron, _pl_lang(player)),
    })


# ── /api/miniapp/alchemy/feed_core ────────────────────────────────────────────
async def api_alchemy_feed_core(request: web.Request) -> web.Response:
    """WRITE — feed 1 beast core to the Soul Fire (QoL-Feedback 2026-07-29
    Item D / MA-48, report [jogador]: a Chama vivia só no chat).

    Espelho de handlers/alchemy.feed_core_callback: gate de reino
    (SOUL_FIRE_MIN_REALM), sem núcleo = recusa disclosed, engine
    feed_beast_core_to_soul_fire = a única verdade (consome 1 núcleo, +XP,
    level-up). Sem side-effects extras — o handler do chat também não tem.
    Row-lock no player: serializa feeds concorrentes do mesmo jogador
    (o decremento do inventário no engine é read-modify-write).
    """
    from core.alchemy_engine import (
        SOUL_FIRE_MIN_REALM,
        feed_beast_core_to_soul_fire,
        get_soul_fire_bonus,
        get_soul_fire_name,
        MAX_SOUL_FIRE_TIER,
        SOUL_FIRE_TIERS,
    )
    from core.utils import normalize_lang

    user_id: int = request["user_id"]

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        lang = normalize_lang(player.language)

        realm = int(player.realm or 0)
        if realm < SOUL_FIRE_MIN_REALM:
            # O engine devolveria (sf, 0, False) aqui — recusa disclosed antes.
            return _json({"ok": False, "reason": "soul_fire_locked",
                          "min_realm": SOUL_FIRE_MIN_REALM}, status=200)

        # 冶 3.1 — o "antes" do Fogo, lido SEM criar nada (só com a onda).
        from core import oficios as _of
        from core.portas import onda_on as _onda_on
        _antes_fogo = await _of.ler_antes_fogo(session, user_id) if _onda_on() else None

        sf, xp_gained, leveled = await feed_beast_core_to_soul_fire(
            session, user_id, realm)
        if sf is None:
            return _json({"ok": False, "reason": "no_cores"}, status=200)

        # Contagem restante (SUM — pode haver mais de uma row de beast_core).
        cores_left = int((await session.execute(
            select(func.coalesce(func.sum(PlayerInventory.quantity), 0)).where(and_(
                PlayerInventory.player_id == user_id,
                PlayerInventory.item_type == "beast_core",
            ))
        )).scalar() or 0)

        await session.commit()

        _rf = _of.retrato_fogo(sf)
        sf_tier = _rf["tier"]
        at_max = _rf["at_max"]
        xp_after = _rf["xp"]
        return _json({
            "ok": True,
            "xp_gained": int(xp_gained),
            "xp_before": xp_after - int(xp_gained),
            "xp_after": xp_after,
            "leveled": bool(leveled),
            "cores_left": cores_left,
            "soul_fire": {
                "tier": sf_tier,
                "name": get_soul_fire_name(sf_tier, lang),
                "bonus_pct": get_soul_fire_bonus(sf_tier),
                "xp": xp_after,
                "xp_to_next": _rf["xp_to_next"],
                "at_max": at_max,
                "min_realm": SOUL_FIRE_MIN_REALM,
                "unlocked": True,
                "max_tier": MAX_SOUL_FIRE_TIER,
                "cores": cores_left,
            },
            # 冶 3.1 — o ganho do Fogo (chave CONDICIONAL, só com a onda). O
            # `xp_before` de cima é derivado e fica pelo `main`; este é lido.
            **_of.no_payload(_of.ganho(fogo=(_antes_fogo, _rf)) if _antes_fogo else None),
        })


# ── Cauldron repair + upgrade (Sprint v14.14g) ────────────────────────────────
# Mirror handlers.alchemy.repair_execute_callback / upgrade_confirm_callback.
# Both endpoints accept `dry_run: true` for preview (no engine call, no
# commit) so the UI can show cost/odds before the player taps confirm.

async def api_alchemy_cauldron_repair(request: web.Request) -> web.Response:
    """WRITE — repair durability of the equipped cauldron.

    Body:
      {"amount": int | "full", "dry_run"?: bool}

    amount:  durability points to restore (50 typical; 9999 ≡ "full" caps
             to max-current). "full" string accepted as alias.
    dry_run: returns the same cost math the engine would charge, without
             touching the DB. UI uses this to render the confirm modal.

    Engine: core.alchemy_engine.repair_cauldron — capped to max_durability,
    cost = ceil(repair_amount/10) * REPAIR_COST_PER_10 * cauldron.grade.
    """
    from core.alchemy_engine import (
        repair_cauldron, get_equipped_cauldron, REPAIR_COST_PER_10,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_amount = payload.get("amount")
    if raw_amount == "full" or raw_amount is None:
        amount = 9999
    else:
        try:
            amount = max(1, int(raw_amount))
        except (TypeError, ValueError):
            return _err("bad_request", 400)
    dry_run = bool(payload.get("dry_run"))

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        pc, cauldron = await get_equipped_cauldron(session, user_id)
        if not pc or not cauldron:
            return _json({"ok": False, "reason": "no_cauldron"}, status=200)

        max_dur = int(cauldron.max_durability or 0)
        cur_dur = int(pc.durability or 0)

        if cur_dur >= max_dur:
            return _json({"ok": False, "reason": "already_full"}, status=200)

        # Dry-run preview: replicate the engine math without mutating.
        if dry_run:
            actual_repair = min(amount, max_dur - cur_dur)
            cost_units = (actual_repair + 9) // 10
            cost = cost_units * REPAIR_COST_PER_10 * int(cauldron.grade or 1)
            await session.commit()
            return _json({
                "ok": True,
                "dry_run": True,
                "amount_requested": int(amount),
                "amount_actual": int(actual_repair),
                "current_durability": cur_dur,
                "max_durability": max_dur,
                "new_durability_preview": cur_dur + actual_repair,
                "cost": int(cost),
                "your_stones": int(player.spirit_stones or 0),
                "can_afford": int(player.spirit_stones or 0) >= int(cost),
                "grade": int(cauldron.grade or 1),
            })

        try:
            result = await repair_cauldron(session, player, pc, cauldron, amount)
        except Exception:
            logger.exception("repair_cauldron engine crashed in api_alchemy_cauldron_repair")
            await session.rollback()
            return _err("engine_error", 500)

        if not result.get("success"):
            err = result.get("error", "engine_error")
            # not_enough_stones surfaces `cost` for the UI to show "need X
            # more SS" — mirror chat repair_execute_callback message.
            extra = {}
            if err == "not_enough_stones":
                extra["cost"] = int(result.get("cost", 0))
                extra["your_stones"] = int(player.spirit_stones or 0)
            await session.rollback()
            return _json({"ok": False, "reason": err, **extra}, status=200)

        await session.commit()

    return _json({
        "ok": True,
        "dry_run": False,
        "repaired": int(result.get("repaired", 0)),
        "new_durability": int(result.get("new_durability", 0)),
        "max_durability": int(result.get("max_durability", max_dur)),
        "cost": int(result.get("cost", 0)),
        "equipped_cauldron": _alchemy_cauldron_dict(pc, cauldron, _pl_lang(player)),
        "delta": {"spirit_stones": int(player.spirit_stones or 0)},
    })


async def api_alchemy_cauldron_upgrade(request: web.Request) -> web.Response:
    """WRITE — upgrade the equipped cauldron to the next grade.

    Body: {"dry_run"?: bool}

    dry_run: returns ore costs + stones + success rate via
             `get_upgrade_cost_info`, plus next-cauldron preview stats.
             No commit, no mutation.
    else:    runs `upgrade_cauldron` engine — on success the equipped row
             swaps to the next-tier cauldron (durability reset to its new
             max). On failure (RNG roll) consumes 50% stones + 20 durability.

    Engine: core.alchemy_engine.upgrade_cauldron — handles ore consumption,
    stone debit, RNG roll, and the cauldron_id swap.
    """
    from core.alchemy_engine import (
        upgrade_cauldron, get_equipped_cauldron, get_upgrade_cost_info,
    )
    from database.models import (
        CauldronCatalog as _CauldronCat, PlayerOre as _PO,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    dry_run = bool(payload.get("dry_run"))

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        pc, cauldron = await get_equipped_cauldron(session, user_id)
        if not pc or not cauldron:
            return _json({"ok": False, "reason": "no_cauldron"}, status=200)

        grade = int(cauldron.grade or 0)

        if grade >= 7:
            return _json({"ok": False, "reason": "max_grade"}, status=200)

        # Dry run: preview cost + odds + next-tier stats.
        if dry_run:
            cost_info = await get_upgrade_cost_info(
                session, grade, (player.language or "pt").lower())
            if not cost_info:
                await session.commit()
                return _json({"ok": False, "reason": "max_grade"}, status=200)

            next_cat = (await session.execute(
                select(_CauldronCat).where(_CauldronCat.grade == grade + 1)
            )).scalar_one_or_none()

            # Annotate per-ore "owned" counts for UI checkmarks.
            ore_ids = [int(o["ore_id"]) for o in cost_info.get("ores", [])]
            owned_map: dict[int, int] = {}
            if ore_ids:
                po_rows = (await session.execute(
                    select(_PO).where(
                        _PO.player_id == user_id,
                        _PO.ore_id.in_(ore_ids),
                    )
                )).scalars().all()
                owned_map = {int(po.ore_id): int(po.quantity or 0) for po in po_rows}

            ores_payload = []
            ores_ok = True
            for o in cost_info.get("ores", []):
                oid = int(o["ore_id"])
                req = int(o["qty"])
                owned = int(owned_map.get(oid, 0))
                if owned < req:
                    ores_ok = False
                ores_payload.append({
                    "ore_id": oid,
                    "name": o.get("name"),
                    "emoji": o.get("emoji"),
                    "required": req,
                    "owned": owned,
                    "ok": owned >= req,
                })

            stones_req = int(cost_info.get("stones", 0))
            stones_ok = int(player.spirit_stones or 0) >= stones_req
            success_rate = float(cost_info.get("success_rate", 0.0))

            next_preview = None
            if next_cat:
                next_preview = {
                    "id": int(next_cat.id),
                    "name": catalog_name(_pl_lang(player), "cauldron", next_cat),
                    "emoji": next_cat.emoji or "⚗️",
                    "grade": int(next_cat.grade or 0),
                    "success_bonus": float(next_cat.success_bonus or 0),
                    "slots": int(next_cat.slots or 3),
                    "max_durability": int(next_cat.max_durability or 0),
                }

            await session.commit()
            return _json({
                "ok": True,
                "dry_run": True,
                "current": _alchemy_cauldron_dict(pc, cauldron, _pl_lang(player)),
                "next": next_preview,
                "ores": ores_payload,
                "ores_ok": ores_ok,
                "stones_required": stones_req,
                "stones_ok": stones_ok,
                "your_stones": int(player.spirit_stones or 0),
                "success_rate": success_rate,
                "can_attempt": ores_ok and stones_ok,
            })

        try:
            result = await upgrade_cauldron(session, player, pc, cauldron)
        except Exception:
            logger.exception("upgrade_cauldron engine crashed in api_alchemy_cauldron_upgrade")
            await session.rollback()
            return _err("engine_error", 500)

        if not result.get("success"):
            err = result.get("error", "engine_error")
            if err == "failed_roll":
                # Bad roll: engine already consumed ores + 50% stones +
                # 20 durability. Commit + report the loss to the UI; the
                # equipped cauldron payload still references the OLD grade
                # because the upgrade did not happen (only durability/stones
                # changed).
                await session.commit()
                return _json({
                    "ok": False,
                    "reason": "failed_roll",
                    "stones_lost": int(result.get("stones_lost", 0)),
                    "durability_lost": int(result.get("durability_lost", 0)),
                    "new_durability": int(result.get("new_durability", 0)),
                    "equipped_cauldron": _alchemy_cauldron_dict(pc, cauldron, _pl_lang(player)),
                    "delta": {"spirit_stones": int(player.spirit_stones or 0)},
                })
            await session.rollback()
            return _json({"ok": False, "reason": err}, status=200)

        # Engine returned `new_cauldron` (the next-tier CauldronCatalog) and
        # mutated `pc.cauldron_id` + `pc.durability` to match it. Build the
        # payload BEFORE commit so SQLAlchemy still has the in-memory rows.
        nc = result.get("new_cauldron")
        equipped_after = _alchemy_cauldron_dict(pc, nc, _pl_lang(player)) if nc else None
        stones_spent = int(result.get("stones_spent", 0))
        stones_after = int(player.spirit_stones or 0)
        await session.commit()

    return _json({
        "ok": True,
        "dry_run": False,
        "success": True,
        "stones_spent": stones_spent,
        "new_cauldron": equipped_after,
        "delta": {"spirit_stones": stones_after},
    })


# ── Forge / Artifacts (MA-32) ─────────────────────────────────────────────────
# All six forge/artifact endpoints reuse engines in `core.forge_engine` and
# the dismantle/lock/equip semantics from `handlers/inventory.py` +
# `handlers/artifacts.py`. The mini-app is the *driver*; the chat handlers are
# canonical (and continue to work) — these endpoints just expose the same
# transitions to the web UI.

# Spirit-stones reward per artifact grade on dismantle. Mirrors
# `handlers.inventory.DISMANTLE_BY_GRADE` exactly — keep in sync if that
# table ever changes (it hasn't since H-7).
FORGE_DISMANTLE_BY_GRADE = {
    0: 50, 1: 150, 2: 500, 3: 1_500,
    4: 5_000, 5: 15_000, 6: 50_000, 7: 200_000, 8: 750_000,
}


async def _lang_of(session, user_id: int) -> str:
    """A lingua do jogador com UMA coluna, para endpoints que nao carregam o
    `Player` inteiro. 名 2026-09-14 — o padrao `select(Player.language)` ja'
    estava copiado em 5 sitios; isto da'-lhe um nome.
    """
    row = (await session.execute(
        select(Player.language).where(Player.telegram_id == user_id)
    )).scalar_one_or_none()
    return (row or "pt").lower()


def _pl_lang(player) -> str:
    """A lingua do jogador, normalizada. 名 2026-09-14.

    Existe para que os 11 chamadores do `_artifact_payload` nao repitam
    `(player.language or "pt").lower()` onze vezes — onze copias de uma regra
    sao onze sitios onde ela pode divergir (Lei F-7 §2).
    """
    return (getattr(player, "language", None) or "pt").lower()


def _artifact_payload(art, cat, lang: str) -> dict:
    """Shape a PlayerArtifact + ArtifactCatalog row for the mini-app. Used by
    forge/equip/unequip/lock/dismantle responses so the client can patch its
    local state without a full inventory refetch."""
    from core.forge_engine import infer_artifact_quality
    return {
        # TAPETE QoL §5: same inferred craft quality as /inventory.
        "quality": infer_artifact_quality(
            art.custom_stats,
            cat.base_stats if cat else None,
            int(art.grade or 0),
            int(cat.grade) if cat and cat.grade is not None else None,
            bool(getattr(art, "has_spirit", False)),
        ),
        "id": int(art.id),
        "catalog_id": int(art.catalog_id),
        "name": (catalog_name(lang, "art", cat) if cat
                 else f"Artifact #{art.catalog_id}"),
        "art_key": catalog_art_key(cat),
        "emoji": (cat.emoji if cat else "🗡️") or "🗡️",
        "type": cat.type if cat else None,
        "grade": int(art.grade or 0),
        # U1 (v16.6): rarity word so the forge result cards read "G6 · Divine".
        "grade_name": ARTIFACT_GRADES.get(int(art.grade or 0), f"G{int(art.grade or 0)}"),
        "slot": art.slot,
        "is_equipped": bool(art.is_equipped),
        "locked": bool(getattr(art, "locked", False)),
        "has_spirit": bool(getattr(art, "has_spirit", False)),
        "spirit_name": getattr(art, "spirit_name", None),
        "enchant_rune": getattr(art, "enchant_rune", None),
        "stats": dict(art.custom_stats or {}),
        "min_realm": int(getattr(cat, "min_realm", 0)) if cat else 0,
        "description": (catalog_desc(lang, "art", cat) if cat else "") or "",
    }


def _forge_max_bulk(materials_status: dict) -> int:
    """How many crafts the player can afford with current ore inventory.
    Returns a per-material min (= floor(owned/required)) clamped to >=0."""
    if not materials_status:
        return 0
    caps = []
    for mat in materials_status.values():
        req = int(mat.get("required") or 0)
        owned = int(mat.get("owned") or 0)
        if req <= 0:
            continue
        caps.append(owned // req)
    return max(0, min(caps)) if caps else 0


async def api_forge_recipes(request: web.Request) -> web.Response:
    """READ — full forge catalog grouped by tier with per-recipe state.

    Bulk-fetches everything (no N+1): forge_skill, all_recipes, all artifacts
    referenced, all ores (small table), player_ores, masteries, soul_fire,
    sect bonuses. Per-recipe: success_chance, mastery progress, materials
    owned + required, blocked reasons, max bulk count.
    """
    from core.forge_engine import (
        get_or_create_forge_skill, get_all_forge_recipes, get_all_forge_masteries,
        get_forge_mastery_bonus, get_forge_mastery_name,
        calculate_recipe_success_chance, get_forge_tier_name, get_recipe_tier_name,
        FORGE_TIERS, MAX_FORGE_TIER, FORGE_RECIPE_TIER_INFO,
        FORGE_XP_CAP_PER_RECIPE_TIER,
    )
    from core.alchemy_engine import get_or_create_soul_fire
    from core.sect_engine import get_sect_bonuses
    from database.models import (
        PlayerOre as _PO, OreCatalog as _OC,
        ArtifactCatalog as _AC, ForgeRecipe as _FR,
    )

    user_id: int = request["user_id"]

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        lang = player.language or "pt"
        _cur_cont = getattr(player, "current_continent", None)

        # Forge skill (lazy-create)
        skill = await get_or_create_forge_skill(session, user_id)

        # Bulk-fetch everything in parallel as much as the session allows
        all_recipes = await get_all_forge_recipes(session)
        masteries = await get_all_forge_masteries(session, user_id)
        sf = await get_or_create_soul_fire(session, user_id, int(player.realm or 0))
        sect_bonuses = await get_sect_bonuses(session, user_id)

        # Bulk-fetch artifact catalog only for the IDs the recipes reference
        artifact_ids = {int(r.artifact_id) for r in all_recipes}
        artifacts_by_id: dict[int, _AC] = {}
        if artifact_ids:
            art_rows = (await session.execute(
                select(_AC).where(_AC.id.in_(artifact_ids))
            )).scalars().all()
            artifacts_by_id = {int(a.id): a for a in art_rows}

        # Ore catalog — small (~10 rows), full load is cheap
        all_ores = (await session.execute(select(_OC))).scalars().all()
        ore_by_id = {int(o.id): o for o in all_ores}

        # Player ore inventory (1 query)
        po_rows = (await session.execute(
            select(_PO).where(_PO.player_id == user_id)
        )).scalars().all()
        ore_owned = {int(po.ore_id): int(po.quantity or 0) for po in po_rows}

        # MV-7 — ⚒️ desconto do Ferreiro (UMA vez, fora do loop; 0.0 com flag
        # OFF → _prf_disc_qty devolve a qty intacta → payload byte-idêntico).
        try:
            from core.profession_engine import discounted_qty as _prf_disc_qty
            from core.profession_engine import forge_ore_discount as _prf_ore_disc
            _prf_forge_disc = float(_prf_ore_disc(player) or 0.0)
        except Exception:
            def _prf_disc_qty(q, d):  # noqa: ANN001 — fallback neutro
                return int(q or 0)
            _prf_forge_disc = 0.0

        await session.commit()

    # 冶 3.1 — o retrato de `core/oficios.py` (o mesmo do resultado da forja).
    from core.oficios import retrato_forja, retrato_receita_forja
    _rj = retrato_forja(skill)
    f_tier = _rj["tier"]
    f_xp = _rj["xp"]
    f_at_max = _rj["at_max"]
    f_xp_to_next = _rj["xp_to_next"]
    f_info = FORGE_TIERS.get(f_tier, FORGE_TIERS[1])
    f_emoji = f_info["emoji"]
    f_quality_bonus = int(f_info["quality_bonus"])
    f_ore_discount = float(f_info["ore_discount"])

    sf_tier = int(sf.fire_tier or 0)

    # Group recipes by tier
    tier_groups: dict[int, list] = {}
    for r in all_recipes:
        tier_groups.setdefault(int(r.tier or 1), []).append(r)

    tiers_payload = []
    for tier_idx in sorted(tier_groups.keys()):
        # Recipe accessible while player.tier+1 ≥ recipe.tier (engine rule)
        tier_locked = tier_idx > f_tier + 1
        recipes_payload = []

        for r in tier_groups[tier_idx]:
            blueprint = artifacts_by_id.get(int(r.artifact_id))
            if not blueprint:
                continue  # orphan recipe — skip

            # Materials with owned/required + ok
            # MV-7 — o required EXIBIDO usa a mesma matemática que o engine
            # debita (discounted_qty; lição MV-6: displayed == debited).
            mats_status: dict[int, dict] = {}
            mats_payload = []
            mats_ok = True
            for mat in (r.materials or []):
                ore_id = int(mat.get("ore_id", 0))
                req = _prf_disc_qty(int(mat.get("qty", 0)), _prf_forge_disc)
                owned = int(ore_owned.get(ore_id, 0))
                ore_obj = ore_by_id.get(ore_id)
                ok_mat = owned >= req
                if not ok_mat:
                    mats_ok = False
                mats_status[ore_id] = {"required": req, "owned": owned}
                # MV-9.5 — idem alquimia: a receita cinzenta da forja diz onde
                # nasce o minério que falta. Condicional ⇒ OFF-identity.
                _org = _origin_note("ore", ore_id, lang, _cur_cont)
                mats_payload.append({
                    "ore_id": ore_id,
                    "name": catalog_name(lang, "ore", ore_obj, fallback=f"Ore #{ore_id}"),
                    "emoji": (ore_obj.emoji if ore_obj else "🪨"),
                    "tier": int(ore_obj.tier) if ore_obj else 1,
                    "required": req,
                    "owned": owned,
                    "ok": ok_mat,
                    **({"origin": _org} if _org else {}),
                })

            # Mastery
            mastery = masteries.get(int(r.id))
            m_info = retrato_receita_forja(mastery)
            m_level = m_info["level"]
            m_count = m_info["forges_count"]
            m_bonus = float(get_forge_mastery_bonus(m_level))

            success_chance = float(calculate_recipe_success_chance(
                float(r.base_success_rate or 80.0), m_bonus, sf_tier, f_tier,
            ))

            # Blocked reasons (mirror engine gates exactly)
            blocked: list[str] = []
            if int(player.realm or 0) < int(r.required_realm or 0):
                blocked.append("realm_too_low")
            if tier_locked:
                blocked.append("forge_tier_too_low")
            if not mats_ok:
                blocked.append("not_enough_materials")

            # XP cap (H-7) — recipe still produces item but yields 0 XP
            xp_cap = int(FORGE_XP_CAP_PER_RECIPE_TIER.get(tier_idx, 999_999))
            xp_capped = f_xp >= xp_cap

            max_bulk = _forge_max_bulk(mats_status)

            recipes_payload.append({
                "id": int(r.id),
                "artifact_id": int(blueprint.id),
                # 冶 3.1 — o nome para LER, a chave para ENCONTRAR a arte (a
                # lição de 14/09: traduzir o nome sem mandar a chave apaga a peça).
                "artifact_name": catalog_name(lang, "art", blueprint),
                "artifact_art_key": catalog_art_key(blueprint),
                "artifact_emoji": (blueprint.emoji or "🗡️"),
                "artifact_grade": int(blueprint.grade or 0),
                "artifact_type": blueprint.type or "",
                "artifact_base_stats": dict(blueprint.base_stats or {}),
                "artifact_description": catalog_desc(lang, "art", blueprint),
                "tier": int(r.tier or 1),
                "required_realm": int(r.required_realm or 0),
                "base_success_rate": float(r.base_success_rate or 80.0),
                "bp_bonus": int(r.bp_bonus or 0),
                "materials": mats_payload,
                "materials_ok": mats_ok,
                "mastery": {
                    "level": m_level,
                    "name": get_forge_mastery_name(m_level, lang),
                    "forges_count": m_count,
                    "next_forges": m_info.get("next_forges"),
                    "next_level": m_info.get("next_level"),
                    "at_max": bool(m_info.get("at_max")),
                    "bonus": m_bonus,
                },
                "success_chance": round(success_chance, 1),
                "xp_capped": xp_capped,
                "xp_cap": xp_cap,
                "max_bulk": int(max_bulk),
                "can_craft": len(blocked) == 0,
                "blocked_reasons": blocked,
            })

        tiers_payload.append({
            "tier": tier_idx,
            "name": get_recipe_tier_name(tier_idx, lang),
            "emoji": FORGE_RECIPE_TIER_INFO.get(
                tier_idx, FORGE_RECIPE_TIER_INFO[1]
            )["emoji"],
            "locked": tier_locked,
            "is_current": tier_idx <= f_tier,
            "recipes": recipes_payload,
        })

    # Player ore inventory (sorted by tier asc)
    ores_payload = []
    for o in sorted(all_ores, key=lambda x: (int(x.tier), int(x.id))):
        oid = int(o.id)
        if int(ore_owned.get(oid, 0)) <= 0:
            continue
        ores_payload.append({
            "id": oid,
            "name": catalog_name(lang, "ore", o),
            "emoji": o.emoji or "🪨",
            "tier": int(o.tier),
            "qty": int(ore_owned.get(oid, 0)),
        })

    return _json({
        "ok": True,
        "forge": {
            "tier": f_tier,
            "tier_name": get_forge_tier_name(f_tier, lang),
            "tier_emoji": f_emoji,
            "xp": f_xp,
            "xp_to_next": f_xp_to_next,
            "at_max": f_at_max,
            "max_tier": MAX_FORGE_TIER,
            "total_forges": int(getattr(skill, "total_forges", 0) or 0),
            "divine_forges": int(getattr(skill, "divine_forges", 0) or 0),
            "quality_bonus": f_quality_bonus,
            "ore_discount": f_ore_discount,
        },
        "soul_fire_tier": sf_tier,
        "sect_bonus": {
            "forge_lvl": int(sect_bonuses.get("forge_lvl", 0) or 0),
            "forge_discount": float(sect_bonuses.get("forge_discount", 0) or 0),
        },
        # MV-7 — ⚒️ desconto REAL do Ferreiro (já refletido nos required acima;
        # key ausente com flag OFF/sem ofício → payload byte-idêntico).
        **({"prof_ore_discount": _prf_forge_disc} if _prf_forge_disc > 0 else {}),
        "tiers": tiers_payload,
        "ores": ores_payload,
    })


async def _track_forge_quests(
    session, user_id: int, divine: bool, perfect: bool, recipe_tier=None
) -> None:
    """Run quest/BP/faction tracking for a successful forge. Failures here
    are logged but never block the craft response — same pattern as alchemy.

    QoL-relatos — `recipe_tier` (1..5) é o peso do ofício e só o gancho de profissão
    o lê; o contador de quest continua a mover-se de 1 em 1.
    """
    try:
        from core.quest_engine import track_quest
        await track_quest(session, user_id, "forge_artifact",
                          prof_weight_tier=recipe_tier)
    except Exception:
        logger.exception("track_quest forge_artifact failed")
    try:
        from core.bp_engine import update_bp_mission
        await update_bp_mission(session, user_id, "forge_artifact")
    except Exception:
        logger.exception("update_bp_mission forge_artifact failed")
    try:
        from core.faction_engine import update_quest_progress as fac_quest_progress
        await fac_quest_progress(session, user_id, "craft_artifact")
        if perfect or divine:
            await fac_quest_progress(session, user_id, "craft_artifact_hq")
    except Exception:
        logger.exception("faction quest_progress craft_artifact failed")


async def api_forge_craft(request: web.Request) -> web.Response:
    """WRITE — single OR bulk forge craft. Reuses
    `core.forge_engine.forge_recipe_item` (canonical engine).

    Body:
      {"recipe_id": int}                 → single craft
      {"recipe_id": int, "count": int}   → bulk loop until count or out-of-mats

    Bulk semantics:
      - Loop calls engine N times within single transaction
      - Stops on first not_enough_materials / not_found / engine error
      - Aggregates: results breakdown, total XP gained, artifacts created,
        spirit awakenings, leveled-up flags (highest)
      - Always commits regardless (partial bulk still counts).
    """
    from core.forge_engine import forge_recipe_item, FORGE_TIERS, MAX_FORGE_TIER

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("recipe_id")
    raw_count = payload.get("count")
    try:
        recipe_id = int(raw_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    # Bulk count: clamp to sensible max so a runaway client can't stall the
    # event loop. 50 is enough for grinding T1/T2 ores; higher tiers are rare
    # enough that 50 covers any practical bulk session.
    BULK_MAX = 50
    try:
        count = max(1, min(BULK_MAX, int(raw_count) if raw_count is not None else 1))
    except (TypeError, ValueError):
        count = 1

    bulk = count > 1

    async with get_session_factory()() as session:
        # FOR UPDATE: serialize concurrent forge crafts per player (the bot
        # auto-forges in parallel) so the stone + material consumption can't
        # lost-update / deadlock — i.e. craft more artifacts than were paid for.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # Aggregate state across iterations
        results_breakdown = {"failure": 0, "success": 0, "perfect": 0, "divine": 0}
        artifacts_created = []
        total_xp_gain = 0
        any_skill_leveled = False
        any_mastery_leveled = False
        any_spirit_awakened = False
        any_charm_saved = False
        last_skill = None
        last_mastery = None
        crafts_done = 0
        early_stop_reason: str | None = None
        last_prof_discount = 0.0  # MV-7 — ⚒️ desconto do Ferreiro (constante no lote)
        # QoL-relatos — tier da RECEITA (1..5), constante no lote: o endpoint não
        # guardava a receita depois do loop (só skill/mastery/desconto).
        last_recipe_tier = None
        # TEC-1 §0.1 (pedido [jogador]) — XP do ofício VISÍVEL no resumo da forja.
        from core.profession_engine import prof_xp_delta, prof_xp_snapshot
        _prof_xp_before = prof_xp_snapshot(player)

        # 冶 3.1 — o "antes" da Forja, lido SEM criar nada (uma receita que não
        # existe tem de dizer `recipe_not_found`, não rebentar numa FK). Só com
        # a onda.
        from core import oficios as _of
        from core.portas import onda_on as _onda_on
        _antes_of = (await _of.ler_antes_forja(session, user_id, recipe_id)
                     if _onda_on() else None)

        from database.models import ArtifactCatalog as _AC

        for _i in range(count):
            try:
                craft_data = await forge_recipe_item(session, player, recipe_id)
            except Exception:
                logger.exception("forge_recipe_item engine crashed in api_forge_craft")
                await session.rollback()
                return _err("engine_error", 500)

            if not craft_data.get("success") and craft_data.get("error"):
                err = craft_data.get("error")
                # In bulk: first iteration error == hard fail; mid-iteration error
                # (e.g. ran out of mats) means we stop with what we did.
                if crafts_done == 0:
                    return _json({
                        "ok": False,
                        "reason": err,
                    }, status=200)
                early_stop_reason = err
                break

            crafts_done += 1
            last_prof_discount = float(craft_data.get("prof_discount", 0.0) or 0.0)
            last_recipe_tier = getattr(craft_data.get("recipe"), "tier", None)
            quality = craft_data.get("result", "failure")
            if quality not in results_breakdown:
                quality = "failure"
            results_breakdown[quality] = results_breakdown.get(quality, 0) + 1
            total_xp_gain += int(craft_data.get("xp_gain", 0) or 0)

            if craft_data.get("leveled_up"):
                any_skill_leveled = True
            if craft_data.get("mastery_leveled"):
                any_mastery_leveled = True
            if craft_data.get("spirit_awakened"):
                any_spirit_awakened = True
            if craft_data.get("charm_saved"):
                any_charm_saved = True
            last_skill = craft_data.get("skill") or last_skill
            last_mastery = craft_data.get("mastery") or last_mastery

            # Track new artifact + run quest hooks on success-tier outcomes
            if quality in ("success", "perfect", "divine") and craft_data.get("artifact"):
                new_art = craft_data["artifact"]
                blueprint = craft_data.get("blueprint")
                # Need a flush for the new art to get an ID
                await session.flush()
                artifacts_created.append(_artifact_payload(new_art, blueprint, _pl_lang(player)))

                await _track_forge_quests(
                    session, user_id,
                    divine=(quality == "divine"),
                    perfect=(quality == "perfect"),
                    recipe_tier=last_recipe_tier,
                )

        await session.commit()

    # Build aggregate response
    skill = last_skill
    # 冶 3.1 — o retrato de `core/oficios.py` (sem skill: o estado com que o
    # motor a cria, T1/0 — o mesmo fallback de antes).
    _rj = _of.retrato_forja(skill)
    f_tier = _rj["tier"]
    f_xp = _rj["xp"]
    f_at_max = _rj["at_max"]
    f_xp_to_next = _rj["xp_to_next"]

    mastery = last_mastery
    return _json({
        "ok": True,
        "bulk": bulk,
        "crafts_requested": count,
        "crafts_done": crafts_done,
        "early_stop_reason": early_stop_reason,
        "results": results_breakdown,
        "artifacts_created": artifacts_created,
        "spirit_awakened": any_spirit_awakened,
        "charm_saved": any_charm_saved,
        "xp_gain": total_xp_gain,
        "forge_tier": f_tier,
        "forge_xp": f_xp,
        "forge_xp_to_next": f_xp_to_next,
        "forge_at_max": f_at_max,
        "leveled_up": any_skill_leveled,
        "mastery_level": int(mastery.mastery_level) if mastery else None,
        "mastery_count": int(mastery.forges_count) if mastery else None,
        "mastery_leveled_up": any_mastery_leveled,
        # MV-7 — ⚒️ desconto do Ferreiro aplicado neste lote (key CONDICIONAL —
        # payload do main byte-idêntico; nota só quando muda o custo).
        **({"prof_discount": float(last_prof_discount)} if last_prof_discount > 0 else {}),
        # TEC-1 §0.1 + QoL-relatos — XP do ofício + peso do lote (condicionais).
        **_prof_xp_payload(player, _prof_xp_before, last_recipe_tier),
        # 冶 3.1 — o ganho confirmado da forja (chave CONDICIONAL, só com a onda).
        **_of.no_payload(_of.ganho_forja(_antes_of, last_skill, last_mastery)),
    })


async def _resolve_ore_refund(session, refunded: dict, lang: str = "pt") -> list[dict]:
    """U2 (v16.6): resolve a {ore_id: qty} refund into [{ore_id,name,emoji,qty}]
    for the mini-app to render. Empty list if nothing refunded."""
    if not refunded:
        return []
    from database.models import OreCatalog as _OC
    rows = (await session.execute(
        select(_OC).where(_OC.id.in_([int(k) for k in refunded.keys()]))
    )).scalars().all()
    nm = {o.id: (catalog_name(lang, "ore", o), o.emoji) for o in rows}
    out = []
    for oid, qty in refunded.items():
        if int(qty) <= 0:
            continue
        n, e = nm.get(int(oid), (f"Ore #{oid}", "🪨"))
        out.append({"ore_id": int(oid), "name": n, "emoji": e, "qty": int(qty)})
    return out


async def api_forge_dismantle(request: web.Request) -> web.Response:
    """WRITE — single OR bulk dismantle. Mirrors `_do_dismantle` and
    `_do_bulk_dismantle` in handlers.inventory.

    Body:
      {"artifact_id": int}                                   → single
      {"bulk": True, "cat_type": str, "grade": int, "exact": bool,
       "below_quality": "perfect"|"divine"|"spirit"|None}    → bulk

    Bulk filters: is_equipped=False, locked=False, type=cat_type, and either
    grade==N (exact) or grade<=N. `below_quality` (TAPETE QoL §5 item 1,
    [jogador]: "tudo G8 abaixo de Divino") additionally keeps only artifacts whose
    inferred craft quality ranks STRICTLY BELOW it. Capped by
    BULK_DISMANTLE_LIMIT env var.
    """
    from database.models import ArtifactCatalog as _AC
    from core.forge_engine import (
        ARTIFACT_QUALITY_ORDER, artifact_quality_rank, infer_artifact_quality,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    is_bulk = bool(payload.get("bulk"))

    async with get_session_factory()() as session:
        # Row-lock the player (claim_bounty pattern): serializes concurrent
        # dismantle calls so a double-fire can't refund the same artifacts
        # twice — the second tx waits, re-selects, finds the rows gone.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if not is_bulk:
            # ── Single ──
            try:
                art_id = int(payload.get("artifact_id"))
            except (TypeError, ValueError):
                return _err("bad_request", 400)

            row = (await session.execute(
                select(PlayerArtifact, _AC)
                .join(_AC, _AC.id == PlayerArtifact.catalog_id)
                .where(
                    PlayerArtifact.id == art_id,
                    PlayerArtifact.player_id == user_id,
                )
            )).first()
            if not row:
                return _json({"ok": False, "reason": "artifact_not_found"}, status=200)
            art, cat = row

            if art.is_equipped:
                return _json({"ok": False, "reason": "is_equipped"}, status=200)
            if getattr(art, "locked", False):
                return _json({"ok": False, "reason": "is_locked"}, status=200)

            grade = int(art.grade or 0)
            reward = int(FORGE_DISMANTLE_BY_GRADE.get(grade, 50))
            player.spirit_stones = int(player.spirit_stones or 0) + reward
            # U2 (v16.6): recover 25% of the artifact's crafting materials.
            from core.forge_engine import refund_recipe_materials
            refunded = await refund_recipe_materials(session, user_id, art.catalog_id, ratio=0.25)
            materials_gained = await _resolve_ore_refund(session, refunded, _pl_lang(player))
            artifact_id_returned = int(art.id)
            cat_name = catalog_name(_pl_lang(player), "art", cat)
            await session.delete(art)
            await session.commit()

            return _json({
                "ok": True,
                "bulk": False,
                "artifact_id": artifact_id_returned,
                "artifact_name": cat_name,
                "stones_gained": reward,
                "grade": grade,
                "materials_gained": materials_gained,
                "delta": {"spirit_stones": int(player.spirit_stones or 0)},
            })

        # ── Bulk ──
        cat_type = (payload.get("cat_type") or "").strip().lower()
        if cat_type not in ("weapon", "armor", "accessory"):
            return _err("bad_request", 400)
        try:
            max_grade = int(payload.get("grade"))
        except (TypeError, ValueError):
            return _err("bad_request", 400)
        exact = bool(payload.get("exact"))
        below_quality = payload.get("below_quality") or None
        if below_quality is not None and below_quality not in ("perfect", "divine", "spirit"):
            return _err("bad_request", 400)

        bulk_limit = int(os.getenv("BULK_DISMANTLE_LIMIT", "200"))

        stmt = (
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.player_id == user_id,
                _AC.type == cat_type,
                PlayerArtifact.is_equipped == False,  # noqa: E712
                PlayerArtifact.locked == False,  # noqa: E712
            )
        )
        stmt = (
            stmt.where(PlayerArtifact.grade == max_grade) if exact
            else stmt.where(PlayerArtifact.grade <= max_grade)
        )
        # Deterministic order so the BULK_DISMANTLE_LIMIT truncation always
        # takes the same (oldest) rows — review 2026-06-12.
        stmt = stmt.order_by(PlayerArtifact.id)
        rows = (await session.execute(stmt)).all()
        if below_quality is not None:
            # Spirit AND refined rows rank above every cut (artifact_quality_rank)
            # — a quality filter can never select them. Quality inference here
            # uses the SAME function as /inventory, so the client preview and
            # this execution agree by construction.
            cut = ARTIFACT_QUALITY_ORDER.index(below_quality)
            rows = [
                (a, c) for a, c in rows
                if artifact_quality_rank(infer_artifact_quality(
                    a.custom_stats, c.base_stats, int(a.grade or 0),
                    int(c.grade) if c.grade is not None else None,
                    bool(getattr(a, "has_spirit", False)),
                )) < cut
            ]
        arts = [a for a, _c in rows]
        truncated = False
        if len(arts) > bulk_limit:
            arts = arts[:bulk_limit]
            truncated = True

        if not arts:
            return _json({"ok": False, "reason": "no_targets",
                          "cat_type": cat_type, "grade": max_grade, "exact": exact,
                          "below_quality": below_quality}, status=200)

        from core.forge_engine import refund_recipe_materials
        total_stones = 0
        per_grade: dict[int, int] = {}
        ids_dismantled = []
        all_refunded: dict[int, int] = {}
        for a in arts:
            g = int(a.grade or 0)
            total_stones += int(FORGE_DISMANTLE_BY_GRADE.get(g, 50))
            per_grade[g] = per_grade.get(g, 0) + 1
            ids_dismantled.append(int(a.id))
            # U2 (v16.6): recover 25% of each crafted artifact's materials.
            refunded = await refund_recipe_materials(session, user_id, a.catalog_id, ratio=0.25)
            for oid, qty in refunded.items():
                all_refunded[oid] = all_refunded.get(oid, 0) + qty
            await session.delete(a)

        player.spirit_stones = int(player.spirit_stones or 0) + total_stones
        materials_gained = await _resolve_ore_refund(session, all_refunded, _pl_lang(player))
        await session.commit()

    return _json({
        "ok": True,
        "bulk": True,
        "cat_type": cat_type,
        "grade": max_grade,
        "exact": exact,
        "below_quality": below_quality,
        "count": len(arts),
        "stones_gained": total_stones,
        "per_grade": per_grade,
        "artifact_ids": ids_dismantled,
        "materials_gained": materials_gained,
        "truncated": truncated,
        "limit": bulk_limit,
        "delta": {"spirit_stones": int(player.spirit_stones or 0)},
    })


async def api_forge_dismantle_bulk(request: web.Request) -> web.Response:
    """WRITE — bulk dismantle by explicit artifact IDs.

    Sprint v14.7 Item 2 (owner round 2026-05-08): "Estaria bem tambem se
    a galera que forjou varios items decidir reciclar todos ou só
    selecionados ja direto ai" — recycle inline from the ForgeResultModal.

    Body: {"artifact_ids": [int, ...]}

    Validates ownership, skips equipped/locked rows, computes total stones
    via FORGE_DISMANTLE_BY_GRADE. Single round-trip avoids races vs. the
    per-item /forge/dismantle endpoint when recycling many at once.
    """
    from database.models import ArtifactCatalog as _AC

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_ids = payload.get("artifact_ids") or []
    if not isinstance(raw_ids, list) or not raw_ids:
        return _err("bad_request", 400)
    try:
        ids = [int(x) for x in raw_ids]
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    # Dedup + cap so a malicious or buggy client can't dismantle 50k rows
    # in one call. Same envelope as the legacy bulk endpoint.
    ids = list(dict.fromkeys(ids))
    bulk_limit = int(os.getenv("BULK_DISMANTLE_LIMIT", "200"))
    if len(ids) > bulk_limit:
        ids = ids[:bulk_limit]

    async with get_session_factory()() as session:
        # Row-lock (claim_bounty pattern) — see api_forge_dismantle.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        rows = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.id.in_(ids),
                PlayerArtifact.player_id == user_id,
                PlayerArtifact.is_equipped == False,  # noqa: E712
                PlayerArtifact.locked == False,  # noqa: E712
            )
        )).all()

        if not rows:
            return _json({"ok": False, "reason": "no_targets"}, status=200)

        from core.forge_engine import refund_recipe_materials
        total_stones = 0
        per_grade: dict[int, int] = {}
        ids_dismantled: list[int] = []
        all_refunded: dict[int, int] = {}
        for art, _cat in rows:
            g = int(art.grade or 0)
            total_stones += int(FORGE_DISMANTLE_BY_GRADE.get(g, 50))
            per_grade[g] = per_grade.get(g, 0) + 1
            ids_dismantled.append(int(art.id))
            # U2 (v16.6): recover 25% of each crafted artifact's materials.
            refunded = await refund_recipe_materials(session, user_id, art.catalog_id, ratio=0.25)
            for oid, qty in refunded.items():
                all_refunded[oid] = all_refunded.get(oid, 0) + qty
            await session.delete(art)

        player.spirit_stones = int(player.spirit_stones or 0) + total_stones
        materials_gained = await _resolve_ore_refund(session, all_refunded, _pl_lang(player))
        await session.commit()

    return _json({
        "ok": True,
        "bulk": True,
        "by_ids": True,
        "count": len(ids_dismantled),
        "stones_gained": total_stones,
        "per_grade": per_grade,
        "artifact_ids": ids_dismantled,
        "materials_gained": materials_gained,
        "skipped": len(ids) - len(ids_dismantled),
        "delta": {"spirit_stones": int(player.spirit_stones or 0)},
    })


# ── Forge: refine + enchant (Sprint v14.14g) ──────────────────────────────────
# Two endpoints expose `core.forge_engine.refine_artifact` / `enchant_artifact`
# which were engine-only since H-7 (no chat handler ever reached them — they
# count as "chat-only paper paths" in the audit because the engine functions
# exist but were unreachable from the running game). Surface them in the
# mini-app so the player can upgrade duplicates and apply runes.

async def _refine_summary(session, user_id: int, art) -> dict:
    """Look up how many free duplicates of this artifact (same catalog_id +
    same grade, not equipped, not the artifact itself) the player owns —
    used by the UI to preview "you have N duplicates available" before
    confirming the refine. Mirrors the duplicate-pick query in
    `core.forge_engine.refine_artifact` exactly so the chat and the preview
    agree on what counts as a usable duplicate.
    """
    if not art:
        return {"duplicates": 0, "at_max_grade": False}
    if int(art.grade or 0) >= 7:
        return {"duplicates": 0, "at_max_grade": True}
    dup_rows = (await session.execute(
        select(PlayerArtifact.id).where(
            PlayerArtifact.player_id == user_id,
            PlayerArtifact.catalog_id == art.catalog_id,
            PlayerArtifact.grade == art.grade,
            PlayerArtifact.id != art.id,
            PlayerArtifact.is_equipped == False,  # noqa: E712
        )
    )).all()
    return {"duplicates": len(dup_rows), "at_max_grade": False}


async def api_forge_refine(request: web.Request) -> web.Response:
    """WRITE — refine an artifact by consuming a duplicate. Wraps
    `core.forge_engine.refine_artifact` exactly: 60% success → +1 grade and
    re-scaled stats; failure consumes the duplicate unless a Forge Protection
    Charm buff is active (then the charm is consumed instead). Engine handles
    duplicate lookup and grade cap (G7).

    Body: {"artifact_id": int, "dry_run"?: bool}

    dry_run mode short-circuits engine call: returns ownership + duplicate
    count + max-grade flag so the UI can render the confirm modal without a
    blind write.
    """
    from core.forge_engine import refine_artifact
    from database.models import ArtifactCatalog as _AC

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        art_id = int(payload.get("artifact_id"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    dry_run = bool(payload.get("dry_run"))

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        row = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.id == art_id,
                PlayerArtifact.player_id == user_id,
            )
        )).first()
        if not row:
            return _json({"ok": False, "reason": "artifact_not_found"}, status=200)
        art, cat = row

        # Dry run: preview only — no engine call, no side effects.
        if dry_run:
            summary = await _refine_summary(session, user_id, art)
            # MV-7 — ⚒️ o dry_run DIZ a chance do refino grátis (Lei da
            # progressão visível: o perk existe se o jogador o vê). Gated —
            # 0.0 com flag OFF → key ausente → payload byte-idêntico.
            _prf_free = 0.0
            try:
                from core.profession_engine import free_refine_chance
                _prf_free = float(free_refine_chance(player) or 0.0)
            except Exception:
                _prf_free = 0.0
            await session.commit()
            return _json({
                "ok": True,
                "dry_run": True,
                "artifact": _artifact_payload(art, cat, _pl_lang(player)),
                "duplicates": int(summary["duplicates"]),
                "at_max_grade": bool(summary["at_max_grade"]),
                "success_chance": 60.0,
                **({"prof_free_chance": round(_prf_free * 100, 1)} if _prf_free > 0 else {}),
            })

        try:
            target, status_ = await refine_artifact(session, user_id, art_id)
        except Exception:
            logger.exception("refine_artifact engine crashed in api_forge_refine")
            await session.rollback()
            return _err("engine_error", 500)

        if status_ in ("artifact_not_found", "max_grade", "no_duplicate_found"):
            await session.rollback()
            return _json({"ok": False, "reason": status_}, status=200)

        # MV-7 — o proc do ofício ride no transiente antes do commit expirar o ORM.
        _prof_free_hit = bool(getattr(target, "_prof_free_refine", False)) or (status_ == "refine_fail_prof")

        await session.commit()

        # Re-fetch fresh joined row for the payload (target stats/grade
        # were mutated by the engine).
        row_fresh = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(PlayerArtifact.id == art_id)
        )).first()
        art_after, cat_after = (row_fresh or (target, cat))

    return _json({
        "ok": True,
        "dry_run": False,
        "status": status_,  # refine_success | refine_fail | refine_fail_protected | refine_fail_prof
        "success": status_ == "refine_success",
        "charm_saved": status_ == "refine_fail_protected",
        # MV-7 — ⚒️ o refino grátis procou (key CONDICIONAL — payload do main
        # byte-idêntico; o front só a lê quando truthy).
        **({"prof_free_refine": True} if _prof_free_hit else {}),
        "artifact": _artifact_payload(art_after, cat_after, _pl_lang(player)),
    })


async def api_forge_enchant(request: web.Request) -> web.Response:
    """WRITE — apply an enchant rune to an artifact. Wraps
    `core.forge_engine.enchant_artifact`. Valid rune types come from
    `config.ENCHANT_EFFECTS` (cb_boost, bp_boost, luck_boost, soul_boost).
    The engine overwrites any prior rune in place — same lossy semantics as
    the chat path (which never shipped a confirmation prompt either).

    Body: {"artifact_id": int, "rune_type": str}
    """
    from core.forge_engine import enchant_artifact
    from config import ENCHANT_EFFECTS as _ENCHANT_EFFECTS
    from database.models import ArtifactCatalog as _AC

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        art_id = int(payload.get("artifact_id"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    rune_type = str(payload.get("rune_type") or "").strip()
    if not rune_type or rune_type not in _ENCHANT_EFFECTS:
        return _json({"ok": False, "reason": "invalid_rune"}, status=200)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        try:
            target, status_ = await enchant_artifact(session, user_id, art_id, rune_type)
        except Exception:
            logger.exception("enchant_artifact engine crashed in api_forge_enchant")
            await session.rollback()
            return _err("engine_error", 500)

        if status_ in ("artifact_not_found", "invalid_rune"):
            await session.rollback()
            return _json({"ok": False, "reason": status_}, status=200)

        await session.commit()

        row_fresh = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(PlayerArtifact.id == art_id)
        )).first()
        art_after, cat_after = (row_fresh if row_fresh else (target, None))

    return _json({
        "ok": True,
        "status": status_,
        "rune_type": rune_type,
        "artifact": _artifact_payload(art_after, cat_after, _pl_lang(player)),
    })


async def api_artifact_equip(request: web.Request) -> web.Response:
    """WRITE — equip an artifact. Mirrors `equip_callback` semantics:
      - Validates min_realm gate (if any)
      - For accessory: auto-pick `accessory1` if free else `accessory2`
      - Optional `prefer_slot` for explicit accessory slot picker (the chat
        flow auto-picks; the mini-app exposes a picker when both are full)
      - Unequips any artifact currently in the chosen slot
      - Returns both the equipped artifact and the displaced artifact (if any)
        so the client can patch local state without refetch.
    """
    from sqlalchemy import update as sa_update
    from database.models import ArtifactCatalog as _AC

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        art_id = int(payload.get("artifact_id"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    prefer_slot = (payload.get("prefer_slot") or "").strip().lower()
    if prefer_slot and prefer_slot not in ("accessory1", "accessory2"):
        prefer_slot = ""

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        row = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.id == art_id,
                PlayerArtifact.player_id == user_id,
            )
        )).first()
        if not row:
            return _json({"ok": False, "reason": "artifact_not_found"}, status=200)
        art, cat = row

        if art.is_equipped:
            return _json({"ok": False, "reason": "already_equipped"}, status=200)

        # min_realm gate (mirrors equip_callback line 595-601)
        min_realm = int(getattr(cat, "min_realm", 0) or 0)
        if min_realm > 0 and int(player.realm or 0) < min_realm:
            return _json({
                "ok": False, "reason": "realm_too_low", "min_realm": min_realm,
            }, status=200)

        # Slot resolution
        slot = (cat.type or "").lower()
        if slot not in ("weapon", "armor", "accessory"):
            return _json({"ok": False, "reason": "invalid_slot_type"}, status=200)

        if slot == "accessory":
            # Check accessory1 first; mirrors chat handler's auto-pick
            acc1 = (await session.execute(
                select(PlayerArtifact).where(
                    PlayerArtifact.player_id == user_id,
                    PlayerArtifact.slot == "accessory1",
                    PlayerArtifact.is_equipped == True,  # noqa: E712
                )
            )).scalar_one_or_none()
            acc2 = (await session.execute(
                select(PlayerArtifact).where(
                    PlayerArtifact.player_id == user_id,
                    PlayerArtifact.slot == "accessory2",
                    PlayerArtifact.is_equipped == True,  # noqa: E712
                )
            )).scalar_one_or_none()

            if prefer_slot:
                slot = prefer_slot
            elif not acc1:
                slot = "accessory1"
            elif not acc2:
                slot = "accessory2"
            else:
                # Both occupied AND no explicit prefer_slot → ask client to pick
                return _json({
                    "ok": False,
                    "reason": "accessory_picker_required",
                    "slots": [
                        {"slot": "accessory1",
                         "occupied_by": _artifact_payload(acc1, None, _pl_lang(player)) if acc1 else None},
                        {"slot": "accessory2",
                         "occupied_by": _artifact_payload(acc2, None, _pl_lang(player)) if acc2 else None},
                    ],
                }, status=200)

        # Progressão Visível — the aggregated Poder de Combate BEFORE this equip
        # (DB still reflects the old set). Gated → `main` never pays it. This is the
        # clearest "did my number go up?" moment, so we return before→after.
        from database.db import feature_enabled_for_world
        _pv_on = feature_enabled_for_world("progressao_visivel")
        _cp_before = await _display_combat_power(session, player) if _pv_on else None

        # Find current occupant of the chosen slot (if any) for displaced payload
        displaced_row = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.player_id == user_id,
                PlayerArtifact.slot == slot,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            )
        )).first()

        # Unequip current occupant (mirror chat handler bulk-update pattern)
        await session.execute(
            sa_update(PlayerArtifact).where(
                PlayerArtifact.player_id == user_id,
                PlayerArtifact.slot == slot,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            ).values(is_equipped=False, slot=None)
        )

        art.is_equipped = True
        art.slot = slot
        await session.commit()

        # Poder de Combate AFTER (DB now reflects the new set). expire_on_commit
        # is False, so reading player post-commit is safe.
        _cp_after = await _display_combat_power(session, player) if _pv_on else None

    displaced_payload = None
    if displaced_row:
        d_art, d_cat = displaced_row
        # is_equipped flag was reset above; rebuild payload reflecting that
        d_art.is_equipped = False
        d_art.slot = None
        displaced_payload = _artifact_payload(d_art, d_cat, _pl_lang(player))

    return _json({
        "ok": True,
        "equipped": _artifact_payload(art, cat, _pl_lang(player)),
        "displaced": displaced_payload,
        "slot": slot,
        "power_delta": ({"before": _cp_before, "after": _cp_after} if _pv_on else None),
    })


async def api_artifact_unequip(request: web.Request) -> web.Response:
    """WRITE — unequip a specific artifact (preferred) or by slot (legacy)."""
    from database.models import ArtifactCatalog as _AC

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}

    raw_id = payload.get("artifact_id")
    raw_slot = (payload.get("slot") or "").strip().lower()

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        row = None
        if raw_id is not None:
            try:
                art_id = int(raw_id)
            except (TypeError, ValueError):
                return _err("bad_request", 400)
            row = (await session.execute(
                select(PlayerArtifact, _AC)
                .join(_AC, _AC.id == PlayerArtifact.catalog_id)
                .where(
                    PlayerArtifact.id == art_id,
                    PlayerArtifact.player_id == user_id,
                )
            )).first()
        elif raw_slot:
            if raw_slot not in ("weapon", "armor", "accessory1", "accessory2"):
                return _err("bad_request", 400)
            row = (await session.execute(
                select(PlayerArtifact, _AC)
                .join(_AC, _AC.id == PlayerArtifact.catalog_id)
                .where(
                    PlayerArtifact.player_id == user_id,
                    PlayerArtifact.slot == raw_slot,
                    PlayerArtifact.is_equipped == True,  # noqa: E712
                )
            )).first()
        else:
            return _err("bad_request", 400)

        if not row:
            return _json({"ok": False, "reason": "artifact_not_found_or_not_equipped"}, status=200)
        art, cat = row

        if not art.is_equipped:
            return _json({"ok": False, "reason": "not_equipped"}, status=200)

        # Progressão Visível — Poder de Combate before→after (a downgrade shows the
        # honest DROP; the number tells the truth both ways). Gated.
        from database.db import feature_enabled_for_world
        _pv_on = feature_enabled_for_world("progressao_visivel")
        _cp_before = await _display_combat_power(session, player) if _pv_on else None

        prev_slot = art.slot
        art.is_equipped = False
        art.slot = None
        await session.commit()

        _cp_after = await _display_combat_power(session, player) if _pv_on else None

    art.is_equipped = False
    art.slot = None
    return _json({
        "ok": True,
        "unequipped": _artifact_payload(art, cat, _pl_lang(player)),
        "slot": prev_slot,
        "power_delta": ({"before": _cp_before, "after": _cp_after} if _pv_on else None),
    })


async def api_alchemy_craft_bulk(request: web.Request) -> web.Response:
    """WRITE — bulk pill craft. Loops `craft_pill` up to `count` times in one
    transaction. Stops cleanly on:
      - heavenly result (stages tribulation as the single endpoint does)
      - inventory_full (refunds the in-flight energy cost)
      - missing_ingredients / not_enough_energy / cauldron_broken (mid-loop)

    Same engine + side-effect contract as `api_alchemy_craft`. Single-craft
    callers should keep using `/api/miniapp/alchemy/craft` to preserve the
    fine-grained per-craft response shape (quality cinematic, mastery progress
    etc.). This endpoint focuses on aggregate stats for the "Craft N" flow.
    """
    from core.alchemy_engine import (
        craft_pill, get_or_create_alchemy_skill, get_unlocked_pill_ids,
        get_equipped_cauldron, check_ingredients, consume_alchemy_energy,
        grant_alchemy_xp, ALCHEMY_TIERS, MAX_ALCHEMY_TIER, XP_REWARDS,
        ALCHEMY_MIN_REALM, alchemy_realm_locked,
    )
    from database.models import PillCatalog as _PillCat
    from config import ALCHEMY_ENERGY_COSTS

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_pill_id = payload.get("pill_id")
    raw_count = payload.get("count")
    try:
        pill_id = int(raw_pill_id)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    BULK_MAX_ALCH = 30  # cap per request — 30 pills is ~5min of normal play
    try:
        count = max(1, min(BULK_MAX_ALCH, int(raw_count) if raw_count is not None else 1))
    except (TypeError, ValueError):
        count = 1

    async with get_session_factory()() as session:
        # FOR UPDATE: serialize concurrent pill crafts per player (the bot
        # auto-crafts in parallel) so ingredient + alchemy-energy consumption
        # can't lost-update / deadlock — i.e. craft more pills than were paid for.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if alchemy_realm_locked(player):
            return _json({"ok": False, "reason": "realm_locked",
                          "min_realm": ALCHEMY_MIN_REALM}, status=200)

        # 2026-05-17: removed RESTRICTED_MEDITATION gate. Chat-side
        # `handlers/alchemy.py` allows crafting in any meditation state — the
        # workshop is stationary, doesn't break meditation. Owner [jogador] reported
        # the asymmetry: "app does not allow crafting if in meditation, text
        # menu allows". Aligned mini-app with chat semantics.

        pill = (await session.execute(
            select(_PillCat).where(_PillCat.id == pill_id)
        )).scalar_one_or_none()
        if not pill:
            return _err("pill_not_found", 404)

        if int(player.realm or 0) < int(pill.min_realm or 0):
            return _json({"ok": False, "reason": "realm_too_low",
                          "min_realm": int(pill.min_realm)}, status=200)

        skill = await get_or_create_alchemy_skill(session, user_id)
        a_tier = int(skill.tier)
        if a_tier < int(pill.required_alchemy_tier or 1):
            return _json({"ok": False, "reason": "tier_locked",
                          "required_tier": int(pill.required_alchemy_tier)}, status=200)

        unlocked_ids = await get_unlocked_pill_ids(session, user_id)
        if int(pill.id) not in unlocked_ids:
            return _json({"ok": False, "reason": "recipe_locked"}, status=200)

        from core.monetization import get_player_vip_level
        vip_lvl = await get_player_vip_level(session, user_id)
        pill_tier = int(pill.required_alchemy_tier or 1)
        energy_cost = int(ALCHEMY_ENERGY_COSTS.get(pill_tier, 10))

        # Aggregate state
        results_breakdown = {"failure": 0, "success": 0, "perfect": 0, "divine": 0, "explosion": 0}
        total_xp = 0
        total_energy_spent = 0
        crafts_done = 0
        early_stop_reason: str | None = None
        leveled_up_overall = False
        heavenly_pending = None
        ingredients_total: dict[int, dict] = {}
        ce_added_total = 0
        pills_crafted_count = 0  # round 6: aggregate for check_achievements call
        extra_pills_count = 0  # MV-7 — 🧪 pílulas extras do Alquimista no lote
        # TEC-1 §0.1 (pedido [jogador]) — XP do ofício VISÍVEL no resumo do lote.
        from core.profession_engine import prof_xp_delta, prof_xp_snapshot
        _prof_xp_before = prof_xp_snapshot(player)
        # 冶 3.1 — o "antes" do ofício, lido SEM criar nada e na MESMA transacção
        # da feitura (`core/oficios.py`). Só com a onda: o `main` não paga isto
        # e recebe o payload de hoje.
        from core import oficios as _of
        from core.portas import onda_on as _onda_on
        _antes_of = (await _of.ler_antes_alquimia(session, user_id, int(pill.id))
                     if _onda_on() else None)
        _ult_maestria = None
        _ult_fogo = None

        for _i in range(count):
            # Pre-check ingredients each iteration (engine consumes them)
            ing_status = await check_ingredients(session, user_id, pill)
            if not all(info["has_enough"] for info in ing_status.values()):
                early_stop_reason = "missing_ingredients" if crafts_done > 0 else None
                if crafts_done == 0:
                    return _json({"ok": False, "reason": "missing_ingredients"}, status=200)
                break

            # Cauldron durability check each iteration
            pc, cauldron = await get_equipped_cauldron(session, user_id)
            if not pc or not cauldron:
                if crafts_done == 0:
                    return _json({"ok": False, "reason": "no_cauldron"}, status=200)
                early_stop_reason = "no_cauldron"
                break
            if int(pc.durability or 0) <= 0:
                if crafts_done == 0:
                    return _json({"ok": False, "reason": "cauldron_broken"}, status=200)
                early_stop_reason = "cauldron_broken"
                break

            # Energy
            energy_ok, energy_after, energy_max = consume_alchemy_energy(player, energy_cost, vip_lvl, skill.tier)
            if not energy_ok:
                if crafts_done == 0:
                    return _json({"ok": False, "reason": "not_enough_energy",
                                  "energy_current": int(energy_after), "energy_max": int(energy_max),
                                  "energy_cost": energy_cost}, status=200)
                early_stop_reason = "not_enough_energy"
                break

            # Snapshot ingredients used this iteration
            for hid, info in ing_status.items():
                herb = info.get("herb")
                qty_this = int(info.get("required", 0))
                if hid in ingredients_total:
                    ingredients_total[hid]["qty"] += qty_this
                else:
                    ingredients_total[hid] = {
                        "herb_id": int(hid),
                        "qty": qty_this,
                        "name": catalog_name(_pl_lang(player), "herb", herb) if herb else f"Herb #{hid}",
                        "emoji": herb.emoji if herb else "🌿",
                    }

            try:
                craft_data = await craft_pill(session, player, pill, a_tier)
            except Exception:
                logger.exception("craft_pill engine crashed in api_alchemy_craft_bulk")
                await session.rollback()
                return _err("engine_error", 500)

            if craft_data.get("inventory_full"):
                # Refund the in-flight energy spend; ingredients were not consumed
                # this iteration (engine pre-checks).
                player.alchemy_energy = int(energy_after) + energy_cost
                # Roll back our last ingredient delta (engine didn't actually eat them)
                for hid, info in ing_status.items():
                    qty_this = int(info.get("required", 0))
                    if hid in ingredients_total:
                        ingredients_total[hid]["qty"] -= qty_this
                        if ingredients_total[hid]["qty"] <= 0:
                            ingredients_total.pop(hid, None)
                early_stop_reason = "inventory_full" if crafts_done > 0 else None
                if crafts_done == 0:
                    await session.commit()
                    return _json({"ok": False, "reason": "inventory_full"}, status=200)
                break

            crafts_done += 1
            total_energy_spent += energy_cost
            _ult_maestria = craft_data.get("mastery") or _ult_maestria
            _ult_fogo = craft_data.get("soul_fire") or _ult_fogo

            result_key = craft_data.get("result", "failure")
            if result_key not in results_breakdown:
                results_breakdown[result_key] = 0
            results_breakdown[result_key] += 1

            xp_gain = int(XP_REWARDS.get(result_key, 0) or 0)
            total_xp += xp_gain
            _skill, lvl_up = await grant_alchemy_xp(session, user_id, result_key)
            if lvl_up:
                leveled_up_overall = True

            # MV-7 — 🧪 agrega as pílulas extras do lote (disclosure no toast).
            if craft_data.get("extra_pill"):
                extra_pills_count += 1

            # Quest tracking on success outcomes
            if result_key in ("success", "perfect", "divine"):
                pills_crafted_count += 1  # round 6: aggregate for achievement check
                try:
                    from core.quest_engine import track_quest
                    # QoL-relatos — o lote é de UMA receita, tier uniforme.
                    await track_quest(session, user_id, "craft_pill",
                                      prof_weight_tier=pill_tier)
                except Exception:
                    logger.exception("craft_pill track_quest failed (bulk)")
                try:
                    from core.bp_engine import update_bp_mission
                    await update_bp_mission(session, user_id, "craft_pills")
                except Exception:
                    logger.exception("update_bp_mission craft_pills failed (bulk)")
                try:
                    from core.faction_engine import update_quest_progress as fac_quest_progress
                    await fac_quest_progress(session, user_id, "craft_pill")
                    if result_key in ("perfect", "divine"):
                        await fac_quest_progress(session, user_id, "craft_pill_hq")
                except Exception:
                    logger.exception("faction quest_progress craft_pill failed (bulk)")
                if int(player.realm or 0) == 2:
                    try:
                        from core.golden_core_engine import add_core_essence
                        essence_gain = {"success": 5, "perfect": 15, "divine": 30}.get(result_key, 5)
                        ce_added_total += int(add_core_essence(player, essence_gain) or 0)
                    except Exception:
                        logger.exception("add_core_essence failed in alchemy bulk")

            # Heavenly stops bulk — stage tribulation and return early
            if result_key == "heavenly":
                _trib_cleanup_expired()
                _PILL_TRIBULATIONS[user_id] = {
                    "pill_id": int(pill.id),
                    # 冶 3.1 — o MESMO nome e a MESMA chave de arte do craft
                    # simples: o lote mandava o nome cru e nenhuma chave, e a
                    # tribulação que nasce de um lote falava inglês.
                    "pill_name": catalog_name(_pl_lang(player), "pill", pill),
                    "pill_art_key": catalog_art_key(pill),
                    "pill_emoji": pill.emoji or "💊",
                    "pill_tier": pill_tier,
                    "round": 1,
                    "successes": 0,
                    "history": [],
                    "xp_gained": xp_gain,
                    "started_at_ts": datetime.now(timezone.utc).timestamp(),
                }
                heavenly_pending = {
                    "pill_id": int(pill.id),
                    "pill_name": catalog_name(_pl_lang(player), "pill", pill),
                    "pill_art_key": catalog_art_key(pill),
                    "pill_emoji": pill.emoji or "💊",
                    "pill_tier": pill_tier,
                    "round": 1,
                    "rounds_total": 3,
                    "successes": 0,
                    "pass_threshold": 2,
                    "history": [],
                }
                early_stop_reason = "heavenly_tribulation_pending"
                break

        # Round 6 (2026-05-20): owner reported Pill Adept/Pill Emperor not
        # incrementing on Perfect crafts via mini-app. This bulk endpoint
        # had every other side-effect but was MISSING check_achievements.
        # Aggregate count + single call (engine sums internally on the row).
        if pills_crafted_count > 0:
            try:
                from core.achievement_engine import check_achievements
                await check_achievements(session, user_id, "pills_crafted", pills_crafted_count)
            except Exception:
                logger.exception("check_achievements pills_crafted failed (bulk)")

        await session.commit()

        a_tier_after = int(skill.tier)
        a_xp_to_next = _of.retrato_alquimia(skill)["xp_to_next"]  # 冶 3.1 — um so' "quanto falta"
        _, energy_cur, energy_max = consume_alchemy_energy(player, 0, vip_lvl, a_tier_after)

    return _json({
        "ok": True,
        "bulk": True,
        "crafts_requested": count,
        "crafts_done": crafts_done,
        "early_stop_reason": early_stop_reason,
        "results": results_breakdown,
        "ingredients_consumed": list(ingredients_total.values()),
        "alchemy_xp_gained": total_xp,
        "alchemy_tier": a_tier_after,
        "alchemy_xp": int(skill.xp),
        "alchemy_xp_to_next": a_xp_to_next,
        "alchemy_leveled_up": bool(leveled_up_overall),
        "energy_after": int(energy_cur),
        "energy_max": int(energy_max),
        "energy_spent": total_energy_spent,
        "tribulation": heavenly_pending,
        "core_essence_added": int(ce_added_total),
        # MV-7 — key CONDICIONAL (payload do main byte-idêntico).
        **({"extra_pills": int(extra_pills_count)} if extra_pills_count > 0 else {}),
        # TEC-1 §0.1 + QoL-relatos — XP do ofício + peso do lote (condicionais).
        **_prof_xp_payload(player, _prof_xp_before, pill_tier),
        "delta": {"qi": int(player.qi or 0)},
        # 冶 3.1 — o ganho do LOTE inteiro (antes do 1.º, depois do último).
        **_of.no_payload(_of.ganho_alquimia(_antes_of, skill, _ult_maestria, _ult_fogo)),
    })


async def api_artifact_lock(request: web.Request) -> web.Response:
    """WRITE — toggle artifact lock. Locked items skip bulk dismantle and
    cannot be single-dismantled. Mirrors `_toggle_lock` in
    handlers/inventory.py."""
    from database.models import ArtifactCatalog as _AC

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        art_id = int(payload.get("artifact_id"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    # Optional force value: True/False to set explicitly. Default = toggle.
    force = payload.get("locked")
    if force is not None and not isinstance(force, bool):
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        row = (await session.execute(
            select(PlayerArtifact, _AC)
            .join(_AC, _AC.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.id == art_id,
                PlayerArtifact.player_id == user_id,
            )
        )).first()
        if not row:
            return _json({"ok": False, "reason": "artifact_not_found"}, status=200)
        art, cat = row

        new_state = bool(force) if force is not None else (not bool(getattr(art, "locked", False)))
        art.locked = new_state
        await session.commit()

    return _json({
        "ok": True,
        "artifact": _artifact_payload(art, cat, _pl_lang(player)),
        "locked": new_state,
    })


# ── /api/miniapp/home_summary ─────────────────────────────────────────────────
# MA-32b — single round-trip aggregator for the Hub-Home tab cards. Without
# this we'd hit /world_boss + /quests + /leaderboard + /announcements every
# time the player opens Home. One bulk query keeps the home tab snappy
# without lying about freshness (10s cache window is per-request, not stale).
async def api_home_summary(request: web.Request) -> web.Response:
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # ── Boss summary (mirrors api_world_boss tier resolution) ────────────
        from core.boss_engine import get_player_tier, ATTACK_COOLDOWN_SECONDS
        player_tier = get_player_tier(int(player.realm or 0))
        boss = (await session.execute(
            select(WorldBoss).where(
                WorldBoss.is_active == True,  # noqa: E712
                WorldBoss.tier == player_tier,
            )
            .order_by(desc(WorldBoss.started_at))
            .limit(1)
        )).scalar_one_or_none()
        if not boss:
            boss = (await session.execute(
                select(WorldBoss).where(WorldBoss.is_active == True)  # noqa: E712
                .order_by(desc(WorldBoss.started_at))
                .limit(1)
            )).scalar_one_or_none()

        boss_summary = None
        if boss:
            hp_pct = 0
            if (boss.hp or 0) > 0:
                hp_pct = max(0, min(100, round(100 * (boss.current_hp or 0) / boss.hp)))
            cd_remaining_ms = 0
            last_hit_row = (await session.execute(
                select(WorldBossDamage.last_hit)
                .where(WorldBossDamage.boss_id == boss.id, WorldBossDamage.player_id == user_id)
            )).first()
            if last_hit_row and last_hit_row[0]:
                last_ms = _ms(last_hit_row[0]) or 0
                now_ms = int(datetime.now(timezone.utc).timestamp() * 1000)
                cd_remaining_ms = max(0, ATTACK_COOLDOWN_SECONDS * 1000 - (now_ms - last_ms))
            boss_summary = {
                "name": catalog_name(await _lang_of(session, user_id), "boss", boss),
                "art_key": catalog_art_key(boss),
                "emoji": boss.emoji,
                "tier": boss.tier,
                "hp_pct": int(hp_pct),
                "cooldown_remaining_ms": int(cd_remaining_ms),
                "tier_mismatch": boss.tier != player_tier,
            }

        # ── Quests summary (count claimable & total) ──────────────────────────
        quest_rows = (await session.execute(
            select(PlayerQuest.is_completed, PlayerQuest.claimed)
            .join(QuestCatalog, QuestCatalog.id == PlayerQuest.quest_id)
            .where(PlayerQuest.player_id == user_id, QuestCatalog.is_active == True)  # noqa: E712
        )).all()
        quests_total = len(quest_rows)
        quests_ready = sum(1 for done, claimed in quest_rows if done and not claimed)

        # ── Sect summary (name + role, already on /player but we keep it
        # local so HomeTab doesn't have to wait for /player) ─────────────────
        sect_row = (await session.execute(
            select(Sect.name, SectMember.rank)
            .join(SectMember, SectMember.sect_id == Sect.id)
            .where(SectMember.player_id == user_id)
        )).first()
        sect_summary = (
            {"name": sect_row[0], "role": sect_row[1] or "member"} if sect_row else None
        )

        # ── Your rank (cultivation) — only if not in shadow_mode and
        # somewhere in the leaderboard universe. Cheap COUNT ahead of you. ──
        your_rank = None
        if not (player.shadow_mode or False):
            ahead = (await session.execute(
                select(func.count(Player.telegram_id)).where(
                    Player.shadow_mode == False,  # noqa: E712
                    # Strict ordering matching api_leaderboard (cultivation):
                    # prestige > realm > sub_layer > cultivation_base
                    (
                        (Player.prestige_level > (player.prestige_level or 0))
                        | (
                            (Player.prestige_level == (player.prestige_level or 0))
                            & (Player.realm > (player.realm or 0))
                        )
                        | (
                            (Player.prestige_level == (player.prestige_level or 0))
                            & (Player.realm == (player.realm or 0))
                            & (Player.sub_layer > (player.sub_layer or 0))
                        )
                        | (
                            (Player.prestige_level == (player.prestige_level or 0))
                            & (Player.realm == (player.realm or 0))
                            & (Player.sub_layer == (player.sub_layer or 0))
                            & (Player.cultivation_base > (player.cultivation_base or 0))
                        )
                    )
                )
            )).scalar_one()
            your_rank = int(ahead) + 1

        # ── Announcements: latest id + count over last 24h.  No
        # `last_seen_at` column exists, so the client tracks "seen" locally
        # via `latest_id` (LocalStorage). Server just returns hints. ─────────
        from datetime import timedelta
        cutoff = datetime.now(timezone.utc) - timedelta(hours=24)
        latest_ann_row = (await session.execute(
            select(GlobalAnnouncement.id, func.count(GlobalAnnouncement.id))
            .where(GlobalAnnouncement.created_at >= cutoff)
            .group_by(GlobalAnnouncement.id)
            .order_by(desc(GlobalAnnouncement.id))
            .limit(1)
        )).first()
        ann_recent_count = (await session.execute(
            select(func.count(GlobalAnnouncement.id))
            .where(GlobalAnnouncement.created_at >= cutoff)
        )).scalar_one()
        ann_summary = {
            "latest_id": int(latest_ann_row[0]) if latest_ann_row else 0,
            "recent_count": int(ann_recent_count or 0),
        }

        # ── 至 A CHEGADA (P2, 2026-09-16) — o que o jogador pode FAZER agora ──
        #
        # A chegada passa a ter **UM** botão, escolhido por precedência de estado
        # (direcção do Astra, MESA [016]):
        #   1. voltar ao duelo  2. ver a meditação  3. resolver recompensa
        #   4. avançar de reino  5. meditar
        #
        # MEDIDO antes de escrever: das cinco, o cliente já sabia confirmar
        # três — `is_meditating` (do `/cultivation`), `quests.ready` (aqui) e
        # "meditação possível" (ausência das outras). Faltavam **duas**, e sem
        # elas o botão mentia por omissão: um jogador a meio de um duelo que
        # abrisse a chegada não era mandado de volta (Lei §1 — preso sem
        # caminho), e quem podia avançar de reino via "Meditar".
        #
        # ⚠️ **AUSÊNCIA NÃO É ESTADO** — regra do próprio Astra, e está no
        # tratamento de erro: se uma das consultas falhar, a chave fica `None`
        # e o cliente **não usa esse ramo**, em vez de assumir "não há". Um
        # `except` que devolvesse `{"eligible": False}` seria a interface a
        # afirmar um facto que ninguém mediu.
        #
        # ⚠️ ADITIVO e sem migration: uma chave nova num READ que a chegada já
        # consulta de 30 em 30s. Cliente velho ignora-a. Zero round-trips novos
        # — era esse o ponto de a pôr aqui e não num endpoint próprio.
        acao = {"duelo": None, "avanco": None}
        try:
            from sqlalchemy import or_ as _or_duelo
            from database.models import DuelSession as _DS
            _d = (await session.execute(
                select(_DS.id, _DS.state).where(
                    _or_duelo(_DS.attacker_id == user_id, _DS.defender_id == user_id),
                    _DS.state.in_(["waiting_actions", "pending_acceptance"]),
                ).order_by(desc(_DS.created_at)).limit(1)
            )).first()
            # A MESMA consulta que o `api_combat_duel_state` faz sem `duel_id`.
            acao["duelo"] = ({"duel_id": str(_d[0]), "state": str(_d[1])}
                             if _d else {"duel_id": None, "state": None})
        except Exception:
            logger.exception("home_summary: duelo activo falhou (user_id=%s)", user_id)
        try:
            _bt = await _breakthrough_state(session, player)
            acao["avanco"] = {
                "eligible": bool(_bt.get("eligible")),
                "blocker": _bt.get("blocker"),
            }
        except Exception:
            logger.exception("home_summary: estado de avanco falhou (user_id=%s)", user_id)

        # ── 至 P3 — OS DOIS ATALHOS DA CHEGADA ([016] §1) ──────────────────
        #
        # *"Dois, Técnicas e Equipamento: imagem do item equipado e nome. Sem
        # equipamento, marca própria e 'Nenhum equipado'."* — direcção do Astra.
        #
        # 🔴 `art_key` NÃO É UM EXTRA. O cliente constrói o URL da peça a
        # partir do NOME; desde que o nome passou a ir TRADUZIDO, o slug muda e
        # a arte deixa de ser encontrada — sem erro nenhum, só a carta virada ao
        # verso. Foi a descoberta mais cara de 2026-09-14: **229 peças por
        # língua invisíveis**. O nome é para LER, a chave é para ENCONTRAR.
        #
        # ⚠️ AUSÊNCIA É AUSÊNCIA: sem técnica activa ou sem arma equipada o
        # valor vai `None`, e o cliente escreve "nenhum" em vez de inventar.
        # Uma consulta que rebenta também dá `None` — e aí o atalho não
        # promete nada, que é a mesma regra do `acao` acima.
        # 🔴 NASCE VAZIO, e a chave so' existe quando se SABE. A 1a versao
        # punha `None` nas duas e o cliente escrevia "Nenhum equipado" — uma
        # AFIRMACAO. O owner apanhou-a a olhar: tinha a "Divine Cosmic Blade"
        # equipada e a chegada dizia que nao tinha nada.
        #   chave AUSENTE  -> nao sei (a consulta falhou)
        #   chave a `None` -> confirmei que nao ha' nenhum
        # E' a mesma regra que este lote poe no duelo: ausencia nao e' estado.
        atalhos = {}
        try:
            from database.models import PlayerTechnique, TechniqueCatalog
            _t = (await session.execute(
                select(TechniqueCatalog.id, TechniqueCatalog.name,
                       TechniqueCatalog.emoji, PlayerTechnique.mastery_level)
                .join(PlayerTechnique,
                      PlayerTechnique.technique_id == TechniqueCatalog.id)
                .where(PlayerTechnique.player_id == user_id,
                       PlayerTechnique.is_active_combat == True)  # noqa: E712
                .order_by(desc(PlayerTechnique.mastery_level))
                .limit(1)
            )).first()
            atalhos["tecnica"] = None          # consulta correu: confirmo o vazio
            if _t:
                _lang_at = _pl_lang(player)
                atalhos["tecnica"] = {
                    "name": catalog_text(_lang_at, "tech", int(_t[0]), "name", _t[1]),
                    "art_key": _t[1],          # o CANONICO, nunca o traduzido
                    "emoji": _t[2] or "",
                    "mastery_level": int(_t[3] or 0),
                }
        except Exception:
            logger.exception("home_summary: tecnica equipada falhou (user_id=%s)", user_id)
        try:
            from sqlalchemy import or_
            from database.models import ArtifactCatalog
            _a = (await session.execute(
                # 🔴 `PlayerArtifact` NAO TEM coluna `name` — nem no modelo nem
                # na base (medido: 12 colunas, e `name` nao e' uma delas). A 1a
                # versao pedia-a, a consulta REBENTAVA, e o `except` devolvia
                # `None` que o cliente escrevia como "Nenhum equipado". O owner
                # tinha a "Divine Cosmic Blade" equipada e a chegada negava-a.
                # ⚠️ E a minha leitura do modelo e' que estava errada: o regex
                # passou a fronteira da classe e colheu campos da seguinte
                # (`escopo de modulo nao e' a arvore toda`, licao de 15/09).
                # O nome de uma peca vive no CATALOGO; o `spirit_name` e' o
                # apelido que o jogador lhe deu, quando existe.
                select(PlayerArtifact.spirit_name, ArtifactCatalog.name,
                       ArtifactCatalog.emoji, PlayerArtifact.grade,
                       ArtifactCatalog.id)
                .join(ArtifactCatalog, ArtifactCatalog.id == PlayerArtifact.catalog_id)
                # ⚠️ `type` do CATALOGO **ou** `slot` do jogador. O `slot` diz
                # onde a peca esta' posta e e' `nullable`; o `type` diz o que ela
                # E'. Perguntar so' pelo `slot` perdia qualquer arma cuja coluna
                # estivesse por preencher — e foi assim que a "Divine Cosmic
                # Blade" do owner desapareceu da chegada dele.
                # (Medido no `main`: 0 de 761 equipados com slot nulo. Mas o
                # `s2` e' outra base, e a regra da casa e' nao penalizar dados
                # do beta.)
                .where(PlayerArtifact.player_id == user_id,
                       PlayerArtifact.is_equipped == True,  # noqa: E712
                       or_(PlayerArtifact.slot == "weapon",
                           ArtifactCatalog.type == "weapon"))
                .limit(1)
            )).first()
            atalhos["arma"] = None             # consulta correu: confirmo o vazio
            if _a:
                _lang_at = _pl_lang(player)
                # ⚠️ O nome PRÓPRIO (forjado pelo jogador) manda no que se LÊ;
                # a arte continua a vir do catálogo canónico.
                atalhos["arma"] = {
                    "name": _a[0] or catalog_text(_lang_at, "art", int(_a[4]), "name", _a[1]),
                    "art_key": _a[1],          # o CANONICO do catálogo
                    "emoji": _a[2] or "",
                    "grade": int(_a[3] or 0),
                }
        except Exception:
            logger.exception("home_summary: arma equipada falhou (user_id=%s)", user_id)

        return _json({
            "boss": boss_summary,
            "atalhos": atalhos,
            "quests": {"ready": int(quests_ready), "total": int(quests_total)},
            "sect": sect_summary,
            "your_rank": your_rank,
            "spirit_jade": int(player.spirit_jade or 0),
            "spirit_stones": int(player.spirit_stones or 0),
            "announcements": ann_summary,
            "acao": acao,
        })


# ── /api/miniapp/profile ──────────────────────────────────────────────────────
# MA-32b — public profile lookup. Triggered by tapping a player in the
# Ranking tab. Lookup key is `dao_name` (already public; unique=True in DB).
# We deliberately DO NOT expose the target's telegram_id — `dao_name` is the
# only identifier the requester ever sees. shadow_mode==True returns 404,
# same response as "not found" so an attacker can't probe who's hidden.
async def api_profile(request: web.Request) -> web.Response:
    # Auth gate: middleware already rejected unauthenticated requests; we
    # don't need user_id locally because the response is the same regardless
    # of who is asking (no "you vs other" rendering on a public profile).
    payload = request["payload"]
    target_dao_name = (payload.get("target_dao_name") or "").strip()
    if not target_dao_name or len(target_dao_name) > 32:
        return _err("not_found", 404)

    async with get_session_factory()() as session:
        target = (await session.execute(
            select(Player).where(Player.dao_name == target_dao_name)
        )).scalar_one_or_none()
        # Indistinguishable response: not found ≡ shadow ≡ no dao_name.
        # Preserves invisibility; no oracle on existence.
        if not target or target.shadow_mode:
            return _err("not_found", 404)

        sect_row = (await session.execute(
            select(Sect.name, Sect.id, SectMember.rank, SectMember.contribution_points)
            .join(SectMember, SectMember.sect_id == Sect.id)
            .where(SectMember.player_id == target.telegram_id)
        )).first()
        sect_summary = None
        if sect_row:
            sect_summary = {
                "name": sect_row[0],
                "role": sect_row[2] or "member",
                "contribution": int(sect_row[3] or 0),
            }

        # Equipped artifacts (4 visible slots: weapon/armor/accessory1/2).
        # Skip mount/cauldron — those live in their own UIs.
        eq_rows = (await session.execute(
            select(
                PlayerArtifact.id, PlayerArtifact.catalog_id, PlayerArtifact.grade,
                PlayerArtifact.slot, PlayerArtifact.has_spirit, PlayerArtifact.spirit_name,
                PlayerArtifact.custom_stats,
                ArtifactCatalog.name, ArtifactCatalog.type, ArtifactCatalog.emoji,
            )
            .join(ArtifactCatalog, ArtifactCatalog.id == PlayerArtifact.catalog_id)
            .where(
                PlayerArtifact.player_id == target.telegram_id,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            )
        )).all()
        equipped = []
        for (aid, cat_id, grade, slot, has_sp, sp_name, custom, name, atype, emoji) in eq_rows:
            if slot not in {"weapon", "armor", "accessory1", "accessory2"}:
                continue
            equipped.append({
                "slot": slot,
                "name": name,
                "emoji": emoji or "🗡️",
                "grade": int(grade or 0),
                "type": atype,
                "has_spirit": bool(has_sp),
                "spirit_name": sp_name,
                "stats": dict(custom or {}),
            })

        realm_name, realm_emoji = _realm_label(target.realm or 0)
        threshold = get_threshold(target.realm or 0, target.sub_layer or 1)

        return _json({
            # Echo dao_name so the client doesn't have to remember which
            # target it asked for (avoids race after rapid re-clicks).
            "dao_name": target.dao_name,
            "realm": int(target.realm or 0),
            "realm_name": realm_name,
            "realm_emoji": realm_emoji,
            "sub_layer": int(target.sub_layer or 1),
            "active_title": target.active_title,
            "prestige_level": int(target.prestige_level or 0),
            "battle_power": int(target.battle_power or 0),
            "cultivation_base": float(target.cultivation_base or 0),
            "cb_threshold": float(threshold),
            "soul_strength": int(target.soul_strength or 0),
            "perception": int(target.perception or 0),
            "luck": int(target.luck or 0),
            "body_tempering_level": int(target.body_tempering_level or 0),
            "foundation_quality": target.foundation_quality,
            "core_quality": target.core_quality,
            "sect": sect_summary,
            "equipped": equipped,
            "joined_at_ms": _ms(target.created_at),
            # last_online intentionally coarsened — we only return the
            # millisecond timestamp; the client renders relative time
            # ("há 3 dias"). Don't expose exact precision either way.
            "last_online_ms": _ms(target.last_online),
            # NEVER include: telegram_id, spirit_jade, spirit_stones, qi,
            # alchemy_energy, sect treasury, raw inventory, achievements
            # blob — privacy + monetization data must not leak.
        })


# ─────────────────────────────────────────────────────────────────────────────
# MA-44a (2026-05-09) — Rebirth (Prestige) preview + attempt for the mini-app.
# Reuses `core.prestige_engine` (canonical) — this layer only formats the
# preview payload and proxies the attempt. Chat-side handler in
# `handlers/prestige.py` predates this and broadcasts globally; the mini-app
# endpoint deliberately skips broadcasting (no `context.bot` available here)
# to keep the request lightweight. A player who wants the global announcement
# effect can still rebirth via `/renascer` in the chat.
# ─────────────────────────────────────────────────────────────────────────────

async def api_rebirth_preview(request: web.Request) -> web.Response:
    """Read-only preview of what a Rebirth would do RIGHT NOW.

    Returns eligibility, current/next prestige level, multiplier delta, the
    list of techniques the player could choose to retain (one max), and a
    high-level summary of what is preserved vs reset. Mirrors the gates of
    `core.prestige_engine.can_prestige`.
    """
    from core.prestige_engine import (
        PRESTIGE_REQ_REALM, PRESTIGE_REQ_SUB_LAYER,
        can_prestige, get_prestige_multiplier, get_prestige_title,
    )
    from database.models import (
        PlayerDaoFragment, PlayerTechnique, TechniqueCatalog,
    )

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        cur_realm = int(player.realm or 0)
        cur_sub = int(player.sub_layer or 0)
        eligible = can_prestige(player)
        cur_level = int(player.prestige_level or 0)
        next_level = cur_level + 1
        cur_mult = get_prestige_multiplier(cur_level)
        next_mult = get_prestige_multiplier(next_level)
        cur_pp = int(player.prestige_points or 0)

        techs_rows = (await session.execute(
            select(PlayerTechnique, TechniqueCatalog).join(
                TechniqueCatalog, PlayerTechnique.technique_id == TechniqueCatalog.id
            ).where(PlayerTechnique.player_id == user_id)
        )).all()
        techniques = [
            {
                "id": int(ct.id),
                "name": ct.name,
                "emoji": ct.emoji or "⚔️",
                "element": ct.element,
                "grade": pt.grade,
                "mastery_level": int(pt.mastery_level or 1),
            }
            for (pt, ct) in techs_rows
        ]

        completed_dao = (await session.execute(
            select(func.count(PlayerDaoFragment.dao_law_id)).where(
                PlayerDaoFragment.player_id == user_id,
                PlayerDaoFragment.is_completed == True,  # noqa: E712
            )
        )).scalar_one() or 0

        lang = player.language or "pt"
        next_title = get_prestige_title(next_level, lang)

        # QoL 09/08 Item D (report [jogador]) — a geografia dita ANTES do tap, igual
        # ao `/renascer` do chat: renascer põe realm 0 e NÃO muda o continente,
        # e com `dungeons_regionais` ON há continentes sem porta nenhuma até ao
        # reino 3/5. String server-resolved (as 2 superfícies imprimem a mesma).
        from core.dungeon_regions import rebirth_portal_warning as _reb_warn
        portal_warning = await _reb_warn(session, player, lang)

        blockers = []
        if not eligible:
            blockers.append({
                "key": "not_max_realm",
                "req_realm": PRESTIGE_REQ_REALM,
                "req_sub_layer": PRESTIGE_REQ_SUB_LAYER,
                "current_realm": cur_realm,
                "current_sub_layer": cur_sub,
            })

    return _json({
        "ok": True,
        "eligible": bool(eligible),
        "blockers": blockers,
        "current_realm": cur_realm,
        "current_sub_layer": cur_sub,
        "current_prestige_level": cur_level,
        "next_prestige_level": next_level,
        "current_multiplier_pct": int(round((cur_mult - 1.0) * 100)),
        "next_multiplier_pct": int(round((next_mult - 1.0) * 100)),
        "current_prestige_points": cur_pp,
        "prestige_points_after": cur_pp + 100,
        "next_title": next_title,
        # Item D — key CONDICIONAL. Uma key sempre-presente quebrava a
        # OFF-identity do payload (lição MV-7): com `dungeons_regionais` OFF —
        # que é o caso de `main` e dos seus 239 — este preview sai byte-idêntico
        # ao de ontem. O cliente lê `data.portal_warning &&`, que trata
        # `undefined` de graça.
        **({"portal_warning": portal_warning} if portal_warning else {}),
        "techniques": techniques,
        "completed_dao_count": int(completed_dao),
        "req_realm": PRESTIGE_REQ_REALM,
        "req_sub_layer": PRESTIGE_REQ_SUB_LAYER,
    })


async def api_rebirth_attempt(request: web.Request) -> web.Response:
    """Execute Rebirth via `core.prestige_engine.process_prestige`.

    Body: `{retained_technique_id?: int|null}`. Server validates `can_prestige`
    again before mutating. On success: returns new prestige_level, title,
    multiplier_pct, unequipped_count. Achievements check is mirrored from the
    chat handler (`prestige_count` quest hook). Broadcast is intentionally
    skipped here.
    """
    from core.prestige_engine import (
        can_prestige, process_prestige, get_prestige_title,
        get_prestige_multiplier,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_tech = payload.get("retained_technique_id")
    retained_tech_id: int | None
    if raw_tech is None or raw_tech == "":
        retained_tech_id = None
    else:
        try:
            retained_tech_id = int(raw_tech)
        except (TypeError, ValueError):
            return _err("bad_request", 400)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if not can_prestige(player):
            return _json({"ok": False, "reason": "not_eligible",
                          "current_realm": int(player.realm or 0),
                          "current_sub_layer": int(player.sub_layer or 0)},
                         status=200)

        try:
            _, unequipped_count = await process_prestige(
                session, player, retained_tech_id
            )
        except ValueError:
            return _json({"ok": False, "reason": "not_eligible"}, status=200)
        except Exception:
            logger.exception("process_prestige crashed in api_rebirth_attempt")
            await session.rollback()
            return _err("engine_error", 500)

        ach_unlocked = []
        try:
            from core.achievement_engine import check_achievements
            ach_unlocked = await check_achievements(
                session, user_id, "prestige_count", int(player.prestige_level or 0)
            ) or []
        except Exception:
            logger.exception("achievement_engine.check_achievements failed (rebirth)")

        await session.commit()

        lang = player.language or "pt"
        new_level = int(player.prestige_level or 0)
        new_mult = get_prestige_multiplier(new_level)
        new_title = get_prestige_title(new_level, lang)

    return _json({
        "ok": True,
        "prestige_level": new_level,
        "prestige_points": int(player.prestige_points or 0),
        "multiplier_pct": int(round((new_mult - 1.0) * 100)),
        "title": new_title,
        "unequipped_count": int(unequipped_count or 0),
        "achievements_unlocked": [
            {"id": int(a.id), "name": getattr(a, "name", None)} for a in ach_unlocked
        ],
    })


# ─────────────────────────────────────────────────────────────────────────────
# v14.14l (2026-05-29) — Gacha endpoints for the mini-app. Reuses
# `core.monetization.perform_gacha_pull` / `get_gacha_pity` (canonical).
# Mirror /gacha chat command (handlers/gacha.py) — same engine, JSON-friendly
# response shape. Two endpoints:
#   - gacha/banners (READ) — list active banners + pity per banner
#   - gacha/pull   (WRITE) — {banner_id, count: 1|10, use_tickets?: bool}
# ─────────────────────────────────────────────────────────────────────────────

async def api_gacha_banners(request: web.Request) -> web.Response:
    """READ — active gacha banners + per-player pity counters."""
    from core.monetization import get_gacha_pity, ensure_default_banner, GACHA_COST, gacha_enabled
    if not gacha_enabled():
        # 開 a tela diz porquê em vez de mostrar uma lista vazia (Lei §1).
        return _json({"ok": False, "reason": "err_gacha_official_only"})
    from database.models import GachaBanner, PlayerInventory as _PInv

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        await ensure_default_banner(session)

        banners = (await session.execute(
            select(GachaBanner).where(GachaBanner.is_active == True)  # noqa: E712
        )).scalars().all()

        # Gacha tickets currency (separate from jade).
        tickets_row = (await session.execute(
            select(_PInv.quantity).where(
                _PInv.player_id == user_id,
                _PInv.item_type == "gacha_ticket",
                _PInv.item_id == 0,
            )
        )).scalar_one_or_none()
        tickets = int(tickets_row or 0)

        banners_out: list[dict] = []
        for b in banners:
            pity = await get_gacha_pity(session, user_id, b.id)
            banners_out.append({
                "id": b.id,
                "name": b.name,
                "description": b.description,
                "pity_at": int(b.pity_at or 0),
                "pity_current": int(pity or 0),
                "is_default": b.id == "ancient_chest_01",
            })

    cost_10 = int(GACHA_COST * 10 * 0.9)
    return _json({
        "ok": True,
        "spirit_jade": int(player.spirit_jade or 0),
        "tickets": tickets,
        "cost_per_pull": int(GACHA_COST),
        "cost_per_10": cost_10,
        "banners": banners_out,
    })


async def api_vip_claim_milestone(request: web.Request) -> web.Response:
    """WRITE — claim a VIP spending milestone reward. Body: `{threshold: int}`.

    Mirror chat handler `_handle_vip_milestone_claim` (handlers/shop.py): same
    eligibility check (total_spent_eur ≥ threshold + not already claimed) +
    same reward grant logic (jade/stones/fragments/title) + claimed_ms append.
    """
    from core.monetization import VIP_MILESTONES
    from database.models import PlayerVIP
    from sqlalchemy.orm.attributes import flag_modified

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        threshold = int(payload.get("threshold"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    rewards = VIP_MILESTONES.get(threshold)
    if not rewards:
        return _json({"ok": False, "reason": "invalid_milestone"})

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        vip_record = (await session.execute(
            select(PlayerVIP).where(PlayerVIP.player_id == user_id)
        )).scalar_one_or_none()

        if not vip_record or float(vip_record.total_spent_eur or 0) < threshold:
            return _json({"ok": False, "reason": "not_eligible",
                          "threshold": threshold,
                          "total_spent_eur": float(vip_record.total_spent_eur or 0) if vip_record else 0.0})

        claimed_ms = list(vip_record.vip_milestones_claimed or [])
        if threshold in claimed_ms:
            return _json({"ok": False, "reason": "already_claimed"})

        if rewards.get("jade"):
            from core.monetization import grant_jade
            await grant_jade(session, player, int(rewards["jade"]))
        if rewards.get("stones"):
            player.spirit_stones = int(player.spirit_stones or 0) + int(rewards["stones"])
        if rewards.get("fragments"):
            player.celestial_fragments = int(player.celestial_fragments or 0) + int(rewards["fragments"])
        title_added = None
        if rewards.get("title"):
            titles = list(player.unlocked_titles or [])
            if rewards["title"] not in titles:
                titles.append(rewards["title"])
                player.unlocked_titles = titles
                flag_modified(player, "unlocked_titles")
                title_added = rewards["title"]

        claimed_ms.append(threshold)
        vip_record.vip_milestones_claimed = claimed_ms
        flag_modified(vip_record, "vip_milestones_claimed")
        await session.commit()

    return _json({
        "ok": True,
        "threshold": threshold,
        "label": rewards.get("label"),
        "jade": int(rewards.get("jade", 0)),
        "stones": int(rewards.get("stones", 0)),
        "fragments": int(rewards.get("fragments", 0)),
        "title": title_added,
    })


async def api_gacha_pull(request: web.Request) -> web.Response:
    """WRITE — execute a gacha pull (1 or 10).

    Body: `{banner_id: str, count: 1|10, use_tickets?: bool}`. Engine handles
    jade/ticket debit + pool roll + pity + inventory grant. Failure reasons:
    `err_jade_insufficient` / `err_tickets_insufficient` / `err_banner_not_found`.
    """
    from core.monetization import perform_gacha_pull, get_gacha_pity, GACHA_COST
    from database.models import GachaBanner

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}

    banner_id = payload.get("banner_id")
    if not isinstance(banner_id, str) or not banner_id:
        return _err("bad_request", 400)

    try:
        count = int(payload.get("count", 1))
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    if count not in (1, 10):
        return _err("bad_count", 400)

    use_tickets = bool(payload.get("use_tickets") or False)

    async with get_session_factory()() as session:
        res = await perform_gacha_pull(session, user_id, count, banner_id, use_tickets=use_tickets)
        if not res.get("success"):
            await session.rollback()
            return _json({"ok": False, "reason": res.get("error_key", "engine_error")})

        # v15.1.2 — bell notification if the pull contained any legendary (top
        # rarity). Persistent so the player can revisit the moment. Dedup by
        # pull timestamp + first legendary index.
        try:
            legendary_drops = [r for r in (res.get("results") or [])
                               if str(r.get("rarity") or "").lower() == "legendary"]
            if legendary_drops:
                from core.notification_engine import notify as _notify_g
                from datetime import datetime as _dt, timezone as _tz
                first = legendary_drops[0]
                await _notify_g(
                    session, user_id, "gacha_legendary",
                    title_key="notif_gacha_legendary_title",
                    body_key="notif_gacha_legendary_body",
                    payload={"name": first.get("name") or "?",
                             "count": len(legendary_drops)},
                    ref_id=f"gacha:{_dt.now(_tz.utc).timestamp():.0f}",
                    icon="🌟",
                    target_tab="shop",
                    priority=1,
                )
        except Exception:
            logger.exception("gacha legendary notify failed for user=%s", user_id)

        await session.commit()

        # Refresh pity + player snapshot for the UI.
        new_pity = await get_gacha_pity(session, user_id, banner_id)
        player = (await session.execute(
            select(Player.spirit_jade).where(Player.telegram_id == user_id)
        )).scalar_one_or_none() or 0

    # Engine returns: {success, results:[{name, rarity, is_pity, type?, art_grade?, ...}], new_pity, remaining_jade}
    return _json({
        "ok": True,
        "results": res.get("results", []),
        "new_pity": int(res.get("new_pity") or new_pity or 0),
        "remaining_jade": int(res.get("remaining_jade") or player or 0),
        "cost": int(res.get("cost") or (count * GACHA_COST if not use_tickets else 0)),
        "used_tickets": use_tickets,
    })


# ─────────────────────────────────────────────────────────────────────────────
# v14.14c (2026-05-28) — Prestige Shop: read + buy.
# Catálogo canónico em `core.prestige_shop_engine.PRESTIGE_SHOP_CATALOG`.
# Esta camada apenas formata + chama engine. Reason codes do "ok=False":
#   unknown_item · prestige_locked · cap_reached · not_enough_points
# ─────────────────────────────────────────────────────────────────────────────

async def api_prestige_shop(request: web.Request) -> web.Response:
    """Read-only listing of the Prestige Shop catalog with per-player state."""
    from core.prestige_shop_engine import get_shop_view
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        view = await get_shop_view(session, player)
    return _json({"ok": True, **view})


async def api_prestige_buy(request: web.Request) -> web.Response:
    """Purchase a Prestige Shop item.

    Body: ``{item_id: str}``. Engine handles validation + cost debit +
    side-effects + ledger row atomically.
    """
    from core.prestige_shop_engine import buy_shop_item, get_shop_view
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    item_id = payload.get("item_id")
    if not isinstance(item_id, str) or not item_id:
        return _err("bad_request", 400)

    async with get_session_factory()() as session:
        # SEC (2026-06-01): lock the player row so concurrent prestige buys can't
        # over-spend prestige points or bypass the per-item purchase cap.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        res = await buy_shop_item(session, player, item_id)
        if not res.get("ok"):
            return _json(res)

        await session.commit()

        # Return refreshed shop view + new player snapshot so the UI can
        # update the catalog state without a separate /shop round-trip.
        view = await get_shop_view(session, player)

    # v15.1.5-hf5 — surface auto_equipped so the mini-app can show a
    # toast "Título equipado: {title}" when the purchase grants AND
    # auto-equips a title in one shot.
    applied = res.get("applied") or {}
    auto_equipped_title = None
    if applied.get("kind") == "title" and applied.get("auto_equipped"):
        auto_equipped_title = applied.get("title")
    return _json({
        "ok": True,
        "item_id": res["item_id"],
        "cost": res["cost"],
        "applied": applied,
        "auto_equipped_title": auto_equipped_title,
        "new_count": res["new_count"],
        "remaining_points": res["remaining_points"],
        "shop": view,
    })


