async def api_sect_donate(request: web.Request) -> web.Response:
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        amount = int(payload.get("amount"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    if amount <= 0:
        return _json({"ok": False, "reason": "bad_amount"})
    from core.sect_engine import donate_to_sect
    async with get_session_factory()() as session:
        res = await donate_to_sect(session, user_id, amount)
        if res.get("ok"):
            await session.commit()
        return _json(res)


async def api_sect_upgrade(request: web.Request) -> web.Response:
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    building = payload.get("building")
    from core.sect_engine import upgrade_building, get_player_sect_info, BUILDINGS
    if not isinstance(building, str) or building not in BUILDINGS:
        return _err("bad_request", 400)
    from core import guilda as _guilda
    from core.portas import onda_on as _onda_on
    async with get_session_factory()() as session:
        # 幫 4.2 — a melhoria é a ÚNICA porta do mini-app que muda o nível de uma
        # instalação. Com a onda o "antes" lê-se trancado ANTES de a guilda ser
        # carregada (`core/guilda.ler_antes`): a entidade que o motor usa já é a
        # da linha trancada. Sem a onda: nem consulta nem trinco a mais.
        _antes = await _guilda.ler_antes(session, user_id, building) if _onda_on() else None
        info = await get_player_sect_info(session, user_id)
        if not info:
            return _json({"ok": False, "reason": "not_in_sect"})
        if info["member"].rank not in ("master", "elder"):
            return _json({"ok": False, "reason": "rank_too_low"})
        res = await upgrade_building(session, info["sect"].id, building, user_id)
        if res.get("success"):
            _g = await _guilda.ganho_da_acao(session, user_id, building, _antes)
            await session.commit()
            return _json({
                "ok": True, "building": building,
                "new_level": res["new_level"], "cost": res["cost"],
                **_guilda.no_payload(_g),
            })
        # engine returns {"success": False, "error": "..."} — convert to mini-app shape
        err = (res.get("error") or "").lower()
        if "stones" in err:
            return _json({"ok": False, "reason": "insufficient_stones",
                          "message": res["error"]})
        if "invalid" in err:
            return _json({"ok": False, "reason": "invalid_building"})
        return _json({"ok": False, "reason": "engine_error", "message": res.get("error")})


