async def api_sect_war_attack(request: web.Request) -> web.Response:
    """WRITE — v15.3 register the player's attack on a territory.

    Body: `{territory_id: int}`. Wraps `register_war_attack` (idempotent at
    the engine level — `attacked_players` is enforced). Mirrors the
    chat-side `sect_war_attack_callback` side-effects (contribution log +
    sect_wars achievement check).
    """
    from core.sect_engine import register_war_attack, get_player_sect_info, log_sect_contribution

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        territory_id = int(payload.get("territory_id") or 0)
    except (TypeError, ValueError):
        return _err("invalid_territory_id", 400)
    if not territory_id:
        return _err("invalid_territory_id", 400)

    try:
        async with get_session_factory()() as session:
            res = await register_war_attack(session, user_id, territory_id)
            ach_unlocked: list = []
            if res.get("success"):
                info = await get_player_sect_info(session, user_id)
                if info:
                    await log_sect_contribution(
                        session, user_id, info["sect"].id, "war",
                        int(res.get("bp_contributed", 0)),
                    )
                try:
                    from core.achievement_engine import check_achievements
                    ach_unlocked = await check_achievements(session, user_id, "sect_wars", 1) or []
                except Exception:
                    logger.exception("sect_war attack: achievement check failed")
            await session.commit()
            if not res.get("success"):
                return _json({"ok": False, "reason": res.get("error_key", "attack_failed")})
            return _json({
                "ok": True,
                "bp_contributed": int(res.get("bp_contributed", 0)),
                "sect_name": res.get("sect_name"),
                "territory_id": int(res.get("territory_id", territory_id)),
                "achievements": [
                    {"key": a.achievement_key, "name": a.name} if hasattr(a, "achievement_key") else {"key": str(a)}
                    for a in ach_unlocked
                ],
            })
    except Exception as e:
        logger.exception("sect/war_attack failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── Boss rankings (Sprint v14.7 Item 3) ───────────────────────────────────────

# Cron schedule lives in core/scheduler.py (`day_of_week="wed,sat"`, hour=18).
# Mirrored here so the client can show "Próximo spawn em ..." without needing
# to query the scheduler. Keep in sync if the cron config changes.
_BOSS_SPAWN_DOWS = (2, 5)  # Mon=0; Wed=2, Sat=5
_BOSS_SPAWN_HOUR_UTC = 18


def _next_boss_spawn(now: datetime) -> datetime:
    from datetime import timedelta as _td
    base = now.replace(hour=_BOSS_SPAWN_HOUR_UTC, minute=0, second=0, microsecond=0)
    for delta in range(0, 14):
        candidate = base + _td(days=delta)
        if candidate.weekday() in _BOSS_SPAWN_DOWS and candidate > now:
            return candidate
    return base + _td(days=7)


async def api_boss_rankings(request: web.Request) -> web.Response:
    """READ — full boss directory (3 tiers × 3 bosses) with damage rankings.

    Sprint v14.7 Item 3 (owner round 2026-05-08): "ranking visivel é
    interessante do dano por boss e mostrar a lista de boss de todos os
    graus com o ranking por cada 1".

    For each named boss in WORLD_BOSS_POOL, finds the most recent spawn
    (active or ended) and surfaces top-10 damage dealers from
    `WorldBossDamage`. Reuses `core/boss_engine` constants — does NOT
    reimplement aggregation. Includes `next_spawn_ms` mirroring the
    Wed/Sat 18:00 UTC cron in `core/scheduler.py`.
    """
    from core.boss_engine import TIER_ORDER, TIER_EMOJIS, get_player_tier
    from database.seeds.boss_seeds import WORLD_BOSS_POOL

    user_id: int = request["user_id"]
    now = datetime.now(timezone.utc)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        tiers_out = []
        for tier in TIER_ORDER:
            catalog_in_tier = [b for b in WORLD_BOSS_POOL if b.get("tier") == tier]
            tier_bosses = []
            for catalog in catalog_in_tier:
                name = catalog["name"]
                latest = (await session.execute(
                    select(WorldBoss)
                    .where(WorldBoss.name == name)
                    .order_by(desc(WorldBoss.started_at))
                    .limit(1)
                )).scalar_one_or_none()

                if latest is None:
                    tier_bosses.append({
                        "name": name,
                        "emoji": catalog.get("emoji", "🐉"),
                        "tier": tier,
                        "is_active": False,
                        "boss_id": None,
                        "current_hp": 0,
                        "max_hp": 0,
                        "phase": None,
                        "started_at_ms": None,
                        "expires_at_ms": None,
                        "ended_at_ms": None,
                        "rankings": [],
                        "ever_spawned": False,
                    })
                    continue

                rows = (await session.execute(
                    select(
                        Player.dao_name, Player.username, Player.realm,
                        WorldBossDamage.total_damage, WorldBossDamage.hits,
                        WorldBossDamage.player_id,
                    )
                    .join(Player, Player.telegram_id == WorldBossDamage.player_id)
                    .where(WorldBossDamage.boss_id == latest.id)
                    .order_by(desc(WorldBossDamage.total_damage))
                    .limit(10)
                )).all()

                rankings = []
                for i, (dn, un, realm, dmg, hits, pid) in enumerate(rows):
                    rankings.append({
                        "rank": i + 1,
                        "name": dn or un or "Cultivator",
                        "realm": int(realm or 0),
                        "realm_emoji": _realm_label(int(realm or 0))[1],
                        "total_damage": int(dmg or 0),
                        "hits": int(hits or 0),
                        "is_you": pid == user_id,
                    })

                tier_bosses.append({
                    "name": name,
                    "emoji": catalog.get("emoji") or latest.emoji or "🐉",
                    "tier": tier,
                    "is_active": bool(latest.is_active),
                    "boss_id": int(latest.id),
                    "current_hp": int(latest.current_hp),
                    "max_hp": int(latest.hp),
                    "phase": latest.phase,
                    "started_at_ms": _ms(latest.started_at),
                    "expires_at_ms": _ms(latest.expires_at),
                    "ended_at_ms": _ms(latest.ended_at),
                    "rankings": rankings,
                    "ever_spawned": True,
                })

            tiers_out.append({
                "tier": tier,
                "tier_emoji": TIER_EMOJIS.get(tier, ""),
                "bosses": tier_bosses,
            })

        next_spawn = _next_boss_spawn(now)

        return _json({
            "tiers": tiers_out,
            "next_spawn_ms": int(next_spawn.timestamp() * 1000),
            "player_tier": get_player_tier(int(player.realm or 0)),
        })


# ── Notifications inbox (Sprint v14.7 Item 4) ─────────────────────────────────

async def api_notifications_inbox(request: web.Request) -> web.Response:
    """READ — live aggregation of pending player-state notifications.

    Sprint v14.7 Item 4 (owner round 2026-05-08): "as notificacoes
    tambem do jogador quests e tudo mais" — surface in-app via bell
    icon instead of relying solely on Telegram DMs.

    NOT a persistent table. This is a LOOKUP-ONLY view of the same
    triggers wired in v14.5 Notifications Pack — `PlayerQuest`,
    `PlayerBuff`, `Tribulation`, `Player.cultivation_base`,
    `Player.alchemy_energy_updated_at`. Each branch is independent;
    a failure in one logs and continues.
    """
    from datetime import timedelta as _td

    from config import (
        REALM_NAMES,
        TRIBULATION_COOLDOWN_FAILURE_LIGHT,
        get_threshold,
    )
    from core.alchemy_engine import get_alchemy_energy
    from core.monetization import get_player_vip_level
    from database.models import PlayerBuff, Tribulation

    user_id: int = request["user_id"]
    now = datetime.now(timezone.utc)
    items: list[dict] = []

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # Quests ready to claim
        try:
            quest_rows = (await session.execute(
                select(QuestCatalog.id, QuestCatalog.name, QuestCatalog.emoji)
                .join(PlayerQuest, PlayerQuest.quest_id == QuestCatalog.id)
                .where(
                    PlayerQuest.player_id == user_id,
                    PlayerQuest.is_completed == True,  # noqa: E712
                    PlayerQuest.claimed == False,  # noqa: E712
                    QuestCatalog.is_active == True,  # noqa: E712
                )
                .limit(20)
            )).all()
            for qid, qname, qemoji in quest_rows:
                items.append({
                    "type": "quest_ready",
                    "icon": qemoji or "🎯",
                    "title_key": "notif_inbox_quest_title",
                    "body_key": "notif_inbox_quest_body",
                    "params": {"name": qname or ""},
                    "target_tab": "quests",
                    "ref_id": int(qid),
                    "priority": 1,
                })
        except Exception:
            logger.exception("notif_inbox: quest scan failed")

        # Faction quests ready to claim (Sprint v14.12b — owner feedback
        # 2026-05-23): owner completed an objective mid-run and didn't
        # know it was done. Surface in bell so they don't have to
        # remember to open /faccao manually.
        try:
            from database.models import (
                PlayerFactionQuest as _PFQ,
                FactionQuestCatalog as _FQC,
            )
            fac_quest_rows = (await session.execute(
                select(_FQC.id, _FQC.name, _FQC.emoji)
                .join(_PFQ, _PFQ.quest_id == _FQC.id)
                .where(
                    _PFQ.player_id == user_id,
                    _PFQ.is_completed == True,  # noqa: E712
                    _PFQ.claimed == False,  # noqa: E712
                )
                .limit(10)
            )).all()
            for fqid, fqname, fqemoji in fac_quest_rows:
                items.append({
                    "type": "faction_quest_ready",
                    "icon": fqemoji or "🔱",
                    "title_key": "notif_inbox_fac_quest_title",
                    "body_key": "notif_inbox_fac_quest_body",
                    "params": {"name": fqname or ""},
                    "target_tab": "faction",
                    "ref_id": int(fqid),
                    "priority": 1,
                })
        except Exception:
            logger.exception("notif_inbox: faction quest scan failed")

        # Breakthrough ready
        try:
            cap_realm = (
                (player.realm or 0) >= len(REALM_NAMES) - 1
                and (player.sub_layer or 0) >= 9
            )
            if not cap_realm:
                threshold = get_threshold(int(player.realm or 0), int(player.sub_layer or 0))
                if (player.cultivation_base or 0) >= threshold:
                    realm_name = REALM_NAMES[min(int(player.realm or 0), len(REALM_NAMES) - 1)]
                    items.append({
                        "type": "breakthrough_ready",
                        "icon": "⚡",
                        "title_key": "notif_inbox_breakthrough_title",
                        "body_key": "notif_inbox_breakthrough_body",
                        "params": {
                            "realm": realm_name,
                            "sub": int(player.sub_layer or 0) + 1,
                        },
                        "target_tab": "cultivation",
                        "priority": 0,
                    })
        except Exception:
            logger.exception("notif_inbox: breakthrough scan failed")

        # Tribulation cooldown done (most recent failure per realm) —
        # only surface for trib rows that are still RELEVANT:
        #   (a) the player's current realm is BELOW the trib's target realm
        #       (otherwise they've already advanced past it via another path);
        #   (b) no NEWER trib for the same realm exists with a non-failed status
        #       (pending/in_progress/completed = the failure was superseded).
        # Owner report 2026-05-20 (post-v14.9 deploy): inbox showed 3 stale
        # "Tribulation available" entries for Mahayana / Void Refinement /
        # Body Integration when player was already in True Immortal realm 9.
        # Without these guards every old failure haunts the inbox forever.
        try:
            cutoff = now - _td(seconds=int(TRIBULATION_COOLDOWN_FAILURE_LIGHT or 0))
            player_realm = int(player.realm or 0)
            trib_rows = (await session.execute(
                select(Tribulation)
                .where(
                    Tribulation.player_id == user_id,
                    Tribulation.status == "failed",
                    Tribulation.completed_at != None,  # noqa: E711
                    Tribulation.completed_at <= cutoff,
                    # (a) Player hasn't advanced past this realm yet.
                    Tribulation.realm > player_realm,
                )
                .order_by(desc(Tribulation.completed_at))
                .limit(10)
            )).scalars().all()
            seen_realms: set[int] = set()
            for trib in trib_rows:
                if trib.realm in seen_realms:
                    continue
                seen_realms.add(trib.realm)
                # (b) Skip if a later trib for the same realm exists with a
                # non-failed status — the failure was superseded.
                superseded = (await session.execute(
                    select(Tribulation.id).where(
                        Tribulation.player_id == user_id,
                        Tribulation.realm == trib.realm,
                        Tribulation.status.in_(["pending", "in_progress", "completed"]),
                        Tribulation.started_at > trib.completed_at,
                    ).limit(1)
                )).scalar_one_or_none()
                if superseded is not None:
                    continue
                realm_name = REALM_NAMES[min(trib.realm, len(REALM_NAMES) - 1)]
                items.append({
                    "type": "trib_cooldown_done",
                    "icon": "⛈️",
                    "title_key": "notif_inbox_trib_title",
                    "body_key": "notif_inbox_trib_body",
                    "params": {"realm": realm_name},
                    "target_tab": "cultivation",
                    "priority": 1,
                })
        except Exception:
            logger.exception("notif_inbox: trib scan failed")

        # Alchemy energy at cap
        try:
            if player.alchemy_energy_updated_at is not None:
                vip_lvl = await get_player_vip_level(session, user_id)
                from core.alchemy_engine import get_alchemy_tier
                a_tier = await get_alchemy_tier(session, user_id)
                current_e, max_e, _ = get_alchemy_energy(player, vip_lvl, a_tier)
                if current_e >= max_e:
                    items.append({
                        "type": "alchemy_full",
                        "icon": "⚗️",
                        "title_key": "notif_inbox_alchemy_title",
                        "body_key": "notif_inbox_alchemy_body",
                        "params": {"current": int(current_e), "max": int(max_e)},
                        "target_tab": "crafting",
                        "priority": 2,
                    })
        except Exception:
            logger.exception("notif_inbox: alchemy scan failed")

        # PvP incoming pending challenges (v14.9 round 3 — bell-surfaced)
        try:
            from database.models import PVPChallenge
            pvp_rows = (await session.execute(
                select(PVPChallenge)
                .where(
                    PVPChallenge.target_id == user_id,
                    PVPChallenge.status == "pending",
                    PVPChallenge.expires_at > now,
                )
                .order_by(desc(PVPChallenge.created_at))
                .limit(5)
            )).scalars().all()
            for ch_row in pvp_rows:
                challenger_row = (await session.execute(
                    select(Player.dao_name).where(Player.telegram_id == ch_row.challenger_id)
                )).first()
                challenger_name = challenger_row[0] if challenger_row else "?"
                wager = int(ch_row.wager or 0)
                items.append({
                    "type": "pvp_incoming",
                    "icon": "⚔️",
                    "title_key": "notif_inbox_pvp_title",
                    "body_key": "notif_inbox_pvp_body" if wager == 0 else "notif_inbox_pvp_body_wager",
                    "params": {
                        "challenger": challenger_name,
                        "wager": wager,
                    },
                    "target_tab": "combat",
                    "ref_id": str(ch_row.id),
                    "priority": 0,  # high — players want to react fast
                })
        except Exception:
            logger.exception("notif_inbox: pvp scan failed")

        # PvP unseen outcomes (round 4 — challenger needs to see who won).
        # Owner: "Enviei combate pro cara dentro do app nao saiu log nem
        # mensagem nem nada, eu nao sei quem ganhou ou quem perdeu". Surface
        # outcomes the player hasn't seen yet — tap → drill into combat tab,
        # which then auto-opens the result modal via inbox unseen_outcomes.
        try:
            from datetime import timedelta as _td
            from database.models import PVPChallenge
            cutoff_24h = now - _td(hours=24)
            unseen_rows = (await session.execute(
                select(PVPChallenge)
                .where(
                    ((PVPChallenge.challenger_id == user_id)
                     & (PVPChallenge.challenger_seen_at == None))  # noqa: E711
                    | ((PVPChallenge.target_id == user_id)
                       & (PVPChallenge.target_seen_at == None)),  # noqa: E711
                    PVPChallenge.status.in_(["completed", "declined", "cancelled", "expired"]),
                    PVPChallenge.resolved_at != None,  # noqa: E711
                    PVPChallenge.resolved_at >= cutoff_24h,
                )
                .order_by(desc(PVPChallenge.resolved_at))
                .limit(10)
            )).scalars().all()
            for ch_row in unseen_rows:
                is_outgoing = (ch_row.challenger_id == user_id)
                opp_id = ch_row.target_id if is_outgoing else ch_row.challenger_id
                opp_row = (await session.execute(
                    select(Player.dao_name).where(Player.telegram_id == opp_id)
                )).first()
                opp_name = opp_row[0] if opp_row else "?"
                # Pick the right title/body keys based on outcome.
                if ch_row.status == "completed":
                    you_won = (ch_row.winner_id == user_id)
                    is_draw = (ch_row.winner_id is None)
                    if is_draw:
                        title_key = "notif_inbox_pvp_draw_title"
                        body_key = "notif_inbox_pvp_draw_body"
                        icon = "⚖️"
                    elif you_won:
                        title_key = "notif_inbox_pvp_won_title"
                        body_key = "notif_inbox_pvp_won_body"
                        icon = "🏆"
                    else:
                        title_key = "notif_inbox_pvp_lost_title"
                        body_key = "notif_inbox_pvp_lost_body"
                        icon = "💀"
                elif ch_row.status == "declined":
                    title_key = "notif_inbox_pvp_declined_title"
                    body_key = "notif_inbox_pvp_declined_body"
                    icon = "✗"
                elif ch_row.status == "cancelled":
                    title_key = "notif_inbox_pvp_cancelled_title"
                    body_key = "notif_inbox_pvp_cancelled_body"
                    icon = "✗"
                else:  # expired
                    title_key = "notif_inbox_pvp_expired_title"
                    body_key = "notif_inbox_pvp_expired_body"
                    icon = "⏱️"
                items.append({
                    "type": "pvp_outcome",
                    "icon": icon,
                    "title_key": title_key,
                    "body_key": body_key,
                    "params": {
                        "opponent": opp_name,
                        "wager": int(ch_row.wager or 0),
                    },
                    "target_tab": "combat",
                    "ref_id": str(ch_row.id),
                    "priority": 0,
                })
        except Exception:
            logger.exception("notif_inbox: pvp outcomes scan failed")

        # Beast expedition ready to collect (v14.13d 2026-05-25 — owner
        # round 2026-05-24: "expedition completion notification ausente").
        # Surfaces PlayerBeast.is_on_expedition=True AND expedition_returns_at
        # <= now. Reusing the inbox-poll pattern means zero migration + the
        # new NotifToastStack (v14.13c) auto-pops a push toast when this
        # item first appears. No pref filter — expedition return is
        # action-required (rewards expire if uncollected, per engine).
        try:
            from database.models import PlayerBeast as _PB, BeastCatalog as _BC
            exp_rows = (await session.execute(
                select(_PB.id, _PB.custom_name, _PB.catalog_id, _PB.expedition_type, _BC.name, _BC.emoji)
                .join(_BC, _BC.id == _PB.catalog_id)
                .where(
                    _PB.player_id == user_id,
                    _PB.is_on_expedition == True,  # noqa: E712
                    _PB.expedition_returns_at != None,  # noqa: E711
                    _PB.expedition_returns_at <= now,
                )
                .limit(5)
            )).all()
            # 獸 o sino diz o nome da besta na língua de quem o abre. A consulta
            # já trazia as duas colunas; o que faltava era o resolvedor.
            # ⚠️ Tuplo desempacotado, e não uma linha ORM — foi exactamente esta
            # forma que cegou o varredor de 14/09 na mochila. Por isso a chave
            # monta-se a partir do `cat_id`, com o nome cru como recurso.
            from core.i18n import catalog_text as _cat_t_b
            _lang_nb = (player.language or "pt").lower() if player else "pt"
            for beast_id, custom_name, cat_id, exp_type, cat_name, cat_emoji in exp_rows:
                _nome_b = (custom_name if (custom_name and custom_name != cat_name)
                           else _cat_t_b(_lang_nb, "beast", cat_id, "name",
                                         cat_name or "?"))
                items.append({
                    "type": "beast_expedition_ready",
                    "icon": cat_emoji or "🐾",
                    "title_key": "notif_inbox_beast_exp_title",
                    "body_key": "notif_inbox_beast_exp_body",
                    "params": {
                        "name": _nome_b,
                        "expedition": exp_type or "?",
                    },
                    "target_tab": "beasts",
                    "ref_id": int(beast_id),
                    "priority": 1,
                })
        except Exception:
            logger.exception("notif_inbox: beast expedition scan failed")

        # v14.14i — incoming Dao Partner proposals (pending, not expired).
        # Mini-app target learns of new proposals via this inbox branch +
        # NotifToastStack push toast (no Telegram DM from mini-app endpoints,
        # since the proposer flow runs without `context.bot`).
        try:
            from database.models import DaoPartnerProposal as _DPP
            partner_rows = (await session.execute(
                select(_DPP.id, _DPP.proposer_id, _DPP.expires_at)
                .where(
                    _DPP.target_id == user_id,
                    _DPP.status == "pending",
                    _DPP.expires_at > now,
                )
                .order_by(desc(_DPP.created_at))
                .limit(5)
            )).all()
            if partner_rows:
                proposer_ids = [r[1] for r in partner_rows]
                pname_rows = (await session.execute(
                    select(Player.telegram_id, Player.dao_name)
                    .where(Player.telegram_id.in_(proposer_ids))
                )).all()
                pname_map = {r[0]: r[1] for r in pname_rows}
                for prop_id, proposer_id, _expires in partner_rows:
                    items.append({
                        "type": "partner_proposal",
                        "icon": "💞",
                        "title_key": "notif_inbox_partner_title",
                        "body_key": "notif_inbox_partner_body",
                        "params": {
                            "proposer": (pname_map.get(proposer_id) or "?"),
                        },
                        "target_tab": "partner",
                        "ref_id": str(prop_id),
                        "priority": 0,
                    })
        except Exception:
            logger.exception("notif_inbox: partner proposal scan failed")

        # MA-39a — Incoming P2P trade requests (target side). Live branch, mirrors
        # the partner-proposal scan: surfaces only while the trade is pending +
        # unexpired, so it self-clears when the trade completes/cancels/expires.
        # The initiator learns of confirms/changes via the TradeModal poll; the
        # trade_completed/trade_cancelled persistent notifications cover them when
        # the modal is closed.
        try:
            trade_rows = (await session.execute(
                select(P2PTrade.id, P2PTrade.initiator_id, P2PTrade.expires_at)
                .where(
                    P2PTrade.target_id == user_id,
                    P2PTrade.status == "pending",
                    P2PTrade.expires_at > now,
                )
                .order_by(desc(P2PTrade.created_at))
                .limit(5)
            )).all()
            if trade_rows:
                t_initiator_ids = [r[1] for r in trade_rows]
                tname_rows = (await session.execute(
                    select(Player.telegram_id, Player.dao_name)
                    .where(Player.telegram_id.in_(t_initiator_ids))
                )).all()
                tname_map = {r[0]: r[1] for r in tname_rows}
                for trade_id_, t_init_id, _t_expires in trade_rows:
                    items.append({
                        "type": "trade_incoming",
                        "icon": "🤝",
                        "title_key": "notif_inbox_trade_title",
                        "body_key": "notif_inbox_trade_body",
                        "params": {"initiator": (tname_map.get(t_init_id) or "?")},
                        "target_tab": "market",
                        "ref_id": str(trade_id_),
                        "priority": 1,
                    })
        except Exception:
            logger.exception("notif_inbox: trade incoming scan failed")

        # Buffs expiring within 5 min
        try:
            window_end = now + _td(minutes=5)
            buff_rows = (await session.execute(
                select(PlayerBuff)
                .where(
                    PlayerBuff.player_id == user_id,
                    PlayerBuff.expires_at > now,
                    PlayerBuff.expires_at <= window_end,
                )
                .order_by(PlayerBuff.expires_at)
                .limit(5)
            )).scalars().all()
            # v15.1.x hotfix (2026-05-15): owner reported snake_case leaking
            # into the toast body ("convenience_shop expira em 30s"). The raw
            # source/buff_type was being injected straight into {label}.
            # Server-side resolves to a clean translated label via i18n with
            # title-cased fallback — NEVER let snake_case reach the user
            # (memory feedback_no_raw_snakecase).
            from core.i18n import t as _i18n_t
            _lang = (player.language or "pt").lower()
            if _lang not in ("pt", "en", "es"):
                _lang = "pt"

            def _pretty_label(buff) -> str:
                src = buff.source or buff.buff_type or ""
                if not src:
                    return "?"
                # A2 ([jogador] 2026-06-16): formation buffs carry source="formation:<key>"
                # — resolve to the localized formation name (mirrors
                # notifications_engine.py:107-108, which already does this for the DM)
                # instead of leaking "Formation:Dao Mirror" via the title-case fallback.
                if src.startswith("formation:"):
                    fk = src[len("formation:"):]
                    resolved = _i18n_t(_lang, f"formation_name_{fk}")
                    if resolved and resolved != f"formation_name_{fk}":
                        return "🔯 " + resolved
                # Try i18n keys in order of specificity, then title-case fallback.
                for key in (f"buff_src_{src}", f"buff_type_{src}", f"pill_effect_{src}"):
                    resolved = _i18n_t(_lang, key)
                    if resolved and resolved != key:
                        return resolved
                return src.replace("_", " ").title()

            for buff in buff_rows:
                remaining = max(0, int((buff.expires_at - now).total_seconds()))
                items.append({
                    "type": "buff_expiring",
                    "icon": "💊",
                    "title_key": "notif_inbox_buff_title",
                    "body_key": "notif_inbox_buff_body",
                    "params": {
                        "label": _pretty_label(buff),
                        "seconds": remaining,
                    },
                    "target_tab": "inventory",
                    "priority": 3,
                })
        except Exception:
            logger.exception("notif_inbox: buff scan failed")

        # v15.1.2 — Persistent notifications (achievement_unlock, title_unlock,
        # duel_challenge, duel_result, gacha_new_banner, etc). UNION'd with the
        # live-state branches above. Persistent items survive between sessions
        # so the player can see what happened while offline.
        try:
            from core.notification_engine import list_inbox as _np_list_inbox
            lang_for_persist = (player.language or "pt").lower()
            if lang_for_persist not in ("pt", "en", "es"):
                lang_for_persist = "pt"
            persistent = await _np_list_inbox(session, user_id, lang_for_persist, limit=30)
            for n in persistent:
                items.append({
                    "type": n["kind"],
                    "icon": n["icon"],
                    "title": n["title"],
                    "body": n["body"],
                    "target_tab": n.get("target_tab"),
                    "priority": n.get("priority", 5),
                    # Persistent-only fields used by the bell UI for dismiss/seen.
                    "notification_id": n["id"],
                    "persistent": True,
                    "seen": n["seen"],
                    "created_at": n.get("created_at"),
                })
        except Exception:
            logger.exception("notif_inbox: persistent scan failed")

        # v14.13c — Sprint Item 2 (toast popups): include the player's
        # notification prefs in the response so the client can decide whether
        # to emit a TOAST when a new inbox item arrives (vs only DM
        # filtering). Cheap — 1 row lookup; defaults to all-on if no row.
        # Mirrors PREF_KEYS canonical map. Inbox types NOT in PREF_KEYS
        # (quest_ready, faction_quest_ready, pvp_*) default to TOAST-ON
        # client-side.
        try:
            from core.notification_prefs import get_prefs as _np_get_prefs
            prefs = await _np_get_prefs(session, user_id)
        except Exception:
            logger.exception("notif_inbox: prefs lookup failed")
            prefs = {}

    items.sort(key=lambda it: (it.get("priority", 9), it.get("type", "")))

    # Round 5 (2026-05-20): pre-render `title` + `body` server-side using the
    # player's language. Owner reported screenshot with raw keys
    # (`notif_inbox_pvp_won_title`) — root cause was stale browser cache
    # from Telegram WebView holding old i18n.json. UI client falls back to
    # these server-rendered strings when the i18n key isn't found in
    # STRINGS[LANG]. Cheap O(N) loop — N is at most ~20 items.
    try:
        from core.i18n import t as i18n_t
        lang = (player.language or "pt").lower()
        if lang not in ("pt", "en", "es"):
            lang = "pt"
        for it in items:
            params = it.get("params") or {}
            tk = it.get("title_key")
            bk = it.get("body_key")
            if tk:
                resolved = i18n_t(lang, tk, **params)
                # i18n.t returns the key itself if missing — only set fallback
                # if we got a real translation back.
                if resolved and resolved != tk:
                    it["title"] = resolved
            if bk:
                resolved = i18n_t(lang, bk, **params)
                if resolved and resolved != bk:
                    it["body"] = resolved
    except Exception:
        logger.exception("notif_inbox: server-side render failed")

    return _json({
        "items": items,
        "count": len(items),
        "prefs": prefs,
    })


# ── v15.1.2 — Notification Hub: mark-seen / dismiss endpoints ─────────────────

async def api_notifications_mark_seen(request: web.Request) -> web.Response:
    """WRITE — mark a single persistent notification as seen.

    Body: `{ notification_id: str }`. No-op (ok=true) if already seen or
    if id doesn't belong to caller.
    """
    from core.notification_engine import mark_seen as _np_mark_seen
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    nid = payload.get("notification_id")
    if not nid:
        return _err("invalid_notification_id", 400)
    try:
        async with get_session_factory()() as session:
            ok = await _np_mark_seen(session, user_id, nid)
            await session.commit()
            return _json({"ok": True, "updated": bool(ok)})
    except Exception as e:
        logger.exception("notifications/mark_seen failed user=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]})


async def api_notifications_mark_all_seen(request: web.Request) -> web.Response:
    """WRITE — mark ALL unseen persistent notifications as seen."""
    from core.notification_engine import mark_all_seen as _np_mark_all
    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            n = await _np_mark_all(session, user_id)
            await session.commit()
            return _json({"ok": True, "updated": int(n)})
    except Exception as e:
        logger.exception("notifications/mark_all_seen failed user=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]})


async def api_notifications_dismiss(request: web.Request) -> web.Response:
    """WRITE — soft-delete a single notification from the inbox.

    Body: `{ notification_id: str }`. Sets dismissed_at; row stays in DB
    for audit but won't surface in the inbox or count toward bell badge.
    """
    from core.notification_engine import dismiss as _np_dismiss
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    nid = payload.get("notification_id")
    if not nid:
        return _err("invalid_notification_id", 400)
    try:
        async with get_session_factory()() as session:
            ok = await _np_dismiss(session, user_id, nid)
            await session.commit()
            return _json({"ok": True, "updated": bool(ok)})
    except Exception as e:
        logger.exception("notifications/dismiss failed user=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]})


async def api_notifications_dismiss_all(request: web.Request) -> web.Response:
    """WRITE — clear the entire persistent inbox (soft-delete)."""
    from core.notification_engine import dismiss_all as _np_dismiss_all
    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            n = await _np_dismiss_all(session, user_id)
            await session.commit()
            return _json({"ok": True, "updated": int(n)})
    except Exception as e:
        logger.exception("notifications/dismiss_all failed user=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]})


# ── Tribulation (Sprint v14.8 MA-34) ──────────────────────────────────────────
# Mini-app preview/attempt/history for the Tribulation flow. The chat-side
# `handlers/tribulation.py` _build_trib_preview helper (Q-13 v14.6) is the
# reference for the structured fields below — we reuse the same engine
# functions (estimate_success_chance, calculate_dao_chance, simulate_round,
# determine_outcome, build_phases_display) instead of reimplementing.
#
# Scope of MA-34: this MVP handles the THUNDER phase end-to-end (preview +
# server-side rounds simulation + outcome). Heart Demon and Dao phases are
# multi-step interactive flows whose chat-side UIs are battle-tested; rather
# than fork them, the response surfaces `next_phase: "heart_demon"|"dao"` so
# the UI can prompt "continue in chat" — same pattern MA-29 used for
# `tribulation_pending`. Future sprint can port HD/Dao to the mini-app
# without changing the contract here.

async def _build_tribulation_preview_payload(session, player, trib) -> dict:
    """Pure-data analogue of handlers/tribulation._build_trib_preview.
    Returns the structured fields the mini-app renders. Each block is
    independently try/except'd — a failure in one (e.g. dao bonuses) will
    not erase the rest. Mirrors the lesson from N-31/N-34.
    """
    from core.game_logic import calculate_total_stats, get_player_equipment_stats
    from core.tribulation_engine import (
        calculate_rounds,
        get_tribulation_power,
        estimate_success_chance,
        calculate_dao_chance,
        get_required_phases,
        get_next_phase,
    )
    from database.models import PlayerArtifact, PlayerBuff, PlayerDaoFragment

    target_realm_idx = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
    target_realm_name = REALM_NAMES[target_realm_idx]

    payload: dict = {
        "trib_id": str(trib.id),
        "status": trib.status,
        "target_realm": target_realm_idx,
        "target_realm_name": target_realm_name,
        "target_realm_emoji": (REALM_EMOJIS[target_realm_idx] if 0 <= target_realm_idx < len(REALM_EMOJIS) else "🪨"),
        "current_realm": int(player.realm or 0),
        "current_sub_layer": int(player.sub_layer or 1),
        "started_at_ms": _ms(trib.started_at),
        "expires_at_ms": _ms(trib.expires_at) if hasattr(trib, "expires_at") else None,
        "rounds_total": 0,
        "rounds_survived": int(trib.rounds_survived or 0),
        "stats": None,
        "chances": None,
        "dao": None,
        "buffs": [],
        "fail": {
            "light_pct": 20,
            "grave_pct": 50,
            "cooldown_seconds": int(__import__("config").TRIBULATION_COOLDOWN_FAILURE_LIGHT),
        },
    }

    # Phases progress
    required_phases = get_required_phases(target_realm_idx)
    completed_names = {p for p in (trib.phases_completed or []) if isinstance(p, str)}
    next_phase = get_next_phase(trib.phases_completed or [], target_realm_idx)
    phases_out = []
    for ph in required_phases:
        phases_out.append({
            "phase": ph,
            "completed": ph in completed_names,
            "is_next": ph == next_phase,
        })
    payload["phases"] = phases_out
    payload["next_phase"] = next_phase

    # Stats + thunder chance estimate
    try:
        arts = (await session.execute(
            select(PlayerArtifact).where(
                PlayerArtifact.player_id == player.telegram_id,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            )
        )).scalars().all()
        equip_stats = get_player_equipment_stats(arts)
        stats = calculate_total_stats(player, equip_stats)
        # Onda E — the tribulation preview stats AND the survival odds read the Alma when a
        # flag is ON: your built-up EFFECTIVE soul (Dao/gear/foundation/companion) honestly
        # helps you SURVIVE the tribulation (the same effective soul the profile shows) —
        # the whole point of the unification. OFF (main) → legacy equip-only → byte-identical.
        # OWNER NOTE: on ON worlds the odds IMPROVE vs the old equip-only soul (intended:
        # "o que constróis morde de verdade"); keep the flags OFF for a world to revert.
        from database.db import feature_enabled_for_world as _ffe_tp
        if _ffe_tp("combate_unificado") or _ffe_tp("progressao_visivel"):
            from core.cultivator_soul import compute_cultivator_soul
            _tsoul = await compute_cultivator_soul(session, player)
            _t_soul, _t_bp, _t_perc = int(_tsoul["soul_strength"]), int(_tsoul["display_power"]), int(_tsoul["perception"])
        else:
            _t_soul = int(stats.get("soul_strength", 0))
            _t_bp = int(stats.get("total_battle_power", 0))
            _t_perc = int(stats.get("perception", player.perception or 0))
        payload["stats"] = {
            "soul_strength": _t_soul,
            "battle_power": _t_bp,
            "perception": _t_perc,
        }

        rounds_total = calculate_rounds(target_realm_idx - 1)
        # TEC-5 — o peso karmico endurece os ceus (flag `forbidden_path`; sem ela
        # o multiplicador e 1.0). O MESMO numero que a tentativa vai rolar.
        trib_power = get_tribulation_power(target_realm_idx - 1, int(player.karma or 0))
        payload["rounds_total"] = int(rounds_total)
        payload["trib_power"] = int(trib_power)
        try:
            from core.forbidden_path_engine import tribulation_karma_mult
            _kmult = float(tribulation_karma_mult(int(player.karma or 0)))
            if _kmult != 1.0:
                # Key CONDICIONAL — a tela DIZ porque os ceus estao mais duros.
                payload["karma_severity"] = {"mult": _kmult, "karma": int(player.karma or 0)}
        except Exception:
            logger.debug("trib karma severity projection failed", exc_info=True)

        from core.sect_engine import get_sect_bonuses
        sect_bonuses = await get_sect_bonuses(session, player.telegram_id)
        defense_mult = float(sect_bonuses.get("defense_mult", 0.0))

        from core.body_tempering_engine import get_celestial_body_bonuses
        body_bonuses = get_celestial_body_bonuses(getattr(player, "body_tempering_level", 0) or 0)
        defense_mult += float(body_bonuses.get("trib_survival_bonus", 0.0))
        payload["defense_mult"] = defense_mult

        soul_int = _t_soul if _t_soul > 0 else 1
        payload["chances"] = {
            "resist": estimate_success_chance(soul_int, trib_power, "resist", rounds_total, defense_mult=defense_mult),
            "dodge":  estimate_success_chance(soul_int, trib_power, "dodge",  rounds_total, defense_mult=defense_mult),
            "absorb": estimate_success_chance(soul_int, trib_power, "absorb", rounds_total, defense_mult=defense_mult),
        }
        # MV-11 天时 — O TEMPO DO CEU. Key CONDICIONAL (molde `karma_severity`
        # tres blocos acima): flag OFF -> `sky_view` devolve None -> a key NAO
        # existe no payload (nunca `null`), logo a identidade byte-a-byte do
        # `main` fica intacta. `soul_int` de proposito: e a MESMA alma com que
        # as 3 chances acima foram calculadas, senao o antes->depois do ceu
        # discordaria dos numeros ao lado dele. try PROPRIO: uma falha aqui nao
        # pode levar consigo `chances`/`stats` (o `except` de fora so loga e a
        # tela ficaria sem os numeros todos).
        try:
            from core.tianshi_engine import sky_view
            # ⚠️ `lang` NAO e parametro desta funcao (assinatura: session,
            # player, trib) — resolve-se aqui, no idioma da casa para este
            # endpoint family (`(player.language or "pt").lower()`).
            _sky_blk = sky_view((player.language or "pt").lower(),
                                soul=soul_int, power=trib_power,
                                rounds=rounds_total, defense_mult=defense_mult)
            if _sky_blk:
                payload["tianshi"] = _sky_blk
        except Exception:
            logger.debug("trib tianshi projection failed", exc_info=True)
    except Exception:
        logger.exception("trib_preview_payload: stats/thunder block failed for player %s", player.telegram_id)

    # Dao chance (only for realms requiring "dao" phase)
    if "dao" in required_phases:
        try:
            frag_rows = (await session.execute(
                select(PlayerDaoFragment).where(PlayerDaoFragment.player_id == player.telegram_id)
            )).scalars().all()
            fragments_by_law = [
                {
                    "fragments_count": f.fragments_count,
                    "is_completed": f.is_completed,
                    "insight_level": f.insight_level,
                }
                for f in frag_rows
            ]
            trib_bonus = 0.0
            try:
                from core.dao_laws_engine import get_dao_laws_bonuses
                laws_b = await get_dao_laws_bonuses(session, player.telegram_id, player.realm)
                trib_bonus = float(laws_b.get("tribulation_bonus", 0.0))
            except Exception:
                pass
            dao_info = calculate_dao_chance(player, fragments_by_law, tribulation_bonus=trib_bonus)
            payload["dao"] = {
                "chance": float(dao_info.get("chance", 0)),
                "total_fragments": int(dao_info.get("total_fragments", 0)),
                "required": int(dao_info.get("required", 0)),
                "can_attempt": bool(dao_info.get("can_attempt", False)),
                "penalties": list(dao_info.get("penalties", [])),
                "perfect_bonus": bool(dao_info.get("perfect_bonus", False)),
                "tribulation_bonus": bool(dao_info.get("tribulation_bonus", False)),
            }
        except Exception:
            logger.exception("trib_preview_payload: dao block failed for player %s", player.telegram_id)

    # Active talisman buffs
    try:
        now_utc = datetime.now(timezone.utc)
        buff_rows = (await session.execute(
            select(PlayerBuff).where(
                PlayerBuff.player_id == player.telegram_id,
                PlayerBuff.expires_at > now_utc,
                PlayerBuff.buff_type.in_(["trib_insurance", "trib_blessing", "revive"]),
            )
        )).scalars().all()
        seen: set[str] = set()
        for b in buff_rows:
            if b.buff_type in seen:
                continue
            seen.add(b.buff_type)
            payload["buffs"].append({
                "type": b.buff_type,
                "expires_at_ms": _ms(b.expires_at),
                "value": float(b.buff_value or 0.0),
            })
    except Exception:
        logger.exception("trib_preview_payload: buffs block failed for player %s", player.telegram_id)

    return payload


async def api_tribulation_preview(request: web.Request) -> web.Response:
    """READ — preview of the player's pending or in-progress tribulation.
    Returns null when no row exists, mirroring `/tribulacao` chat behaviour.
    Reuses _build_tribulation_preview_payload above (engine-level reuse).
    """
    from datetime import timedelta as _td
    from database.models import Tribulation

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # COMPAT: same dedupe pattern as `/tribulacao` chat handler.
        active = (await session.execute(
            select(Tribulation)
            .where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["pending", "in_progress"]),
            )
            .order_by(desc(Tribulation.started_at))
        )).scalars().all()
        trib = active[0] if active else None

        if not trib:
            return _json({"trib": None})

        # Compute expiry from started_at + window (Tribulation model has no
        # expires_at column).
        from config import TRIBULATION_WINDOW_HOURS
        expires_at = trib.started_at + _td(hours=TRIBULATION_WINDOW_HOURS) if trib.started_at else None

        payload = await _build_tribulation_preview_payload(session, player, trib)
        if expires_at is not None:
            payload["expires_at_ms"] = _ms(expires_at)

        return _json({"trib": payload})


async def api_tribulation_attempt(request: web.Request) -> web.Response:
    """WRITE — execute the THUNDER phase server-side.

    Body: `{ strategy: "resist"|"dodge"|"absorb" }`.

    Reuses `core.tribulation_engine.simulate_round` per round and
    `determine_outcome` for the final tally — same calls the chat
    handler does. Persists rounds_total/rounds_survived/strategy/phases
    completed identically. Buffs (trib_blessing, trib_insurance, revive)
    are honoured exactly as the chat path.

    Heart Demon and Dao phases are multi-step interactive flows; on
    success of thunder, response includes `next_phase` so the client
    can hint the player to continue via /tribulacao chat command. The
    chat flow stays canonical for those phases — we don't fork it.
    """
    from sqlalchemy.orm.attributes import flag_modified
    from config import TRIBULATION_COOLDOWN_FAILURE_LIGHT, get_threshold
    from core.tribulation_engine import (
        STRATEGIES,
        TRIBULATION_PASSED_OUTCOMES,
        calculate_rounds,
        get_tribulation_power,
        simulate_round,
        determine_outcome,
        get_required_phases,
        get_next_phase,
    )
    from database.models import PlayerArtifact, PlayerBuff, Tribulation

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    strategy = str(payload.get("strategy") or "").lower()
    if strategy not in STRATEGIES:
        return _err("invalid_strategy", 400)

    async with get_session_factory()() as session:
        # Lock the player row to SERIALIZE concurrent trib POSTs (mirrors the
        # boss endpoint). Without it, two racing requests both pass the pending
        # trib check and each fire the realm-up grant + karma wire = double
        # +karma / double stat-grant (Track A item 4 review finding).
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        trib = (await session.execute(
            select(Tribulation)
            .where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["pending", "in_progress"]),
            )
            .order_by(desc(Tribulation.started_at))
            .limit(1)
        )).scalar_one_or_none()
        if not trib:
            return _err("no_active_tribulation", 404)

        target_realm = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
        next_phase_now = get_next_phase(trib.phases_completed or [], target_realm)
        if next_phase_now != "thunder":
            # Mini-app only handles thunder. HD/Dao must continue via chat.
            return _json({
                "ok": False,
                "reason": "phase_requires_chat",
                "next_phase": next_phase_now,
            }, status=200)

        # Lift trib into in_progress like trib_start_ does.
        if trib.status == "pending":
            trib.status = "in_progress"
        trib.strategy = strategy

        # Load equipment + stats (mirror _run_thunder_phase).
        from core.game_logic import calculate_total_stats, get_player_equipment_stats
        arts = (await session.execute(
            select(PlayerArtifact).where(
                PlayerArtifact.player_id == user_id,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            )
        )).scalars().all()
        equip_stats = get_player_equipment_stats(arts)
        stats = calculate_total_stats(player, equip_stats)

        from core.sect_engine import get_sect_bonuses
        sect_bonuses = await get_sect_bonuses(session, player.telegram_id)
        defense_mult = float(sect_bonuses.get("defense_mult", 0.0))

        from core.body_tempering_engine import get_celestial_body_bonuses
        body_bonuses = get_celestial_body_bonuses(getattr(player, "body_tempering_level", 0) or 0)
        defense_mult += float(body_bonuses.get("trib_survival_bonus", 0.0))

        # Trib Blessing buff (consumed on this attempt).
        now_utc = datetime.now(timezone.utc)
        bless_buff = (await session.execute(
            select(PlayerBuff).where(
                PlayerBuff.player_id == user_id,
                PlayerBuff.buff_type == "trib_blessing",
                PlayerBuff.expires_at > now_utc,
            )
        )).scalar_one_or_none()
        blessing_bonus = 0.0
        if bless_buff:
            blessing_bonus = float(bless_buff.buff_value or 0.0)
            await session.delete(bless_buff)
            await session.flush()

        rounds_total = calculate_rounds(target_realm - 1)
        # TEC-5 — severidade por |karma| (gated): a MESMA que a preview mostrou.
        trib_power = get_tribulation_power(target_realm - 1, int(player.karma or 0))
        soul = int(stats.get("soul_strength", 1))

        rounds_log = []
        survived = 0
        for r in range(1, rounds_total + 1):
            res = await simulate_round(
                soul, trib_power, strategy,
                defense_mult=defense_mult,
                blessing_bonus=blessing_bonus,
            )
            if res["success"]:
                survived += 1
            rounds_log.append({
                "round": r,
                "success": bool(res["success"]),
                "damage": int(res["damage"]),
                "survival_chance": float(res.get("survival_chance", 0.0)),
                "message_key": res.get("message"),
            })

        outcome = determine_outcome(strategy, survived, rounds_total)
        trib.rounds_total = rounds_total
        trib.rounds_survived = survived

        result_block: dict = {
            "outcome": outcome,
            "rounds": rounds_log,
            "rounds_total": rounds_total,
            "rounds_survived": survived,
            "strategy": strategy,
            "blessing_bonus": blessing_bonus,
        }

        if outcome in TRIBULATION_PASSED_OUTCOMES:
            phases = list(trib.phases_completed or [])
            if "thunder" not in phases:
                phases.append("thunder")
            trib.phases_completed = phases
            flag_modified(trib, "phases_completed")

            strat = STRATEGIES[strategy]
            bp_bonus = float(strat.get("bp_bonus", 0.0))
            soul_bonus = float(strat.get("soul_bonus", 0.0))
            bp_gain = 0
            soul_gain = 0
            if bp_bonus > 0:
                new_bp = int((player.battle_power or 0) * (1 + bp_bonus))
                bp_gain = new_bp - int(player.battle_power or 0)
                player.battle_power = new_bp
            if soul_bonus > 0:
                new_soul = int((player.soul_strength or 0) * (1 + soul_bonus))
                soul_gain = new_soul - int(player.soul_strength or 0)
                player.soul_strength = new_soul
            result_block["bp_gain"] = bp_gain
            result_block["soul_gain"] = soul_gain

            next_phase = get_next_phase(trib.phases_completed, target_realm)
            result_block["next_phase"] = next_phase

            # Auto-grant realm advancement if thunder was the only phase.
            granted = None
            if next_phase is None:
                from config import get_threshold as _gt, REALM_NAMES as _RN
                threshold = _gt(player.realm, player.sub_layer)
                bonus = 1.1 + (target_realm * 0.05)
                player.cultivation_base = max(0, float(player.cultivation_base or 0) - threshold)
                old_realm = int(player.realm or 0)
                player.realm = target_realm
                player.sub_layer = 1
                player.battle_power = int((player.battle_power or 0) * bonus)
                player.soul_strength = int((player.soul_strength or 0) * bonus)
                player.perception = int((player.perception or 0) * bonus)
                player.luck = int((player.luck or 0) * bonus)
                player.qi_capacity = float(player.qi_capacity or 100) * bonus
                trib.status = "completed"
                trib.outcome = "success"
                trib.completed_at = now_utc
                # BUG [jogador] 2026-08-11 — resistência a pílulas é POR REINO; o único
                # reset vivia no ramo de breakthrough simples (inalcançável r>=4).
                try:
                    from core.alchemy_engine import reset_medicine_resistance
                    await reset_medicine_resistance(session, user_id)
                except Exception:
                    logger.warning("trib_attempt: medicine resistance reset failed", exc_info=True)
                try:
                    from core.bp_engine import update_bp_mission
                    await update_bp_mission(session, user_id, "win_tribulation")
                except Exception:
                    logger.exception("trib_attempt: update_bp_mission failed")
                # MV-2 §0 — weekly quest 12 (faucet órfão): espelha o wire do chat.
                try:
                    from core.quest_engine import track_quest
                    await track_quest(session, user_id, "tribulation_survive", 1)
                except Exception:
                    logger.exception("trib_attempt: tribulation_survive track failed")
                granted = {
                    "realm_up": True,
                    "old_realm": old_realm,
                    "new_realm": target_realm,
                    "new_realm_name": _RN[target_realm],
                    "new_realm_emoji": (REALM_EMOJIS[target_realm] if 0 <= target_realm < len(REALM_EMOJIS) else "🪨"),
                    "bonus_mult": bonus,
                }
                # D5 (v16.6): guaranteed first Dao Law on reaching realm 5.
                try:
                    from core.dao_laws_engine import grant_first_law_on_unlock
                    _fl_msg = await grant_first_law_on_unlock(
                        session, user_id, target_realm,
                        perception=int(player.perception or 100), lang=(player.language or "pt"))
                    if _fl_msg:
                        granted["dao_first_law"] = _fl_msg
                except Exception:
                    logger.exception("trib_attempt: D5 first-law grant failed")
            result_block["granted"] = granted
            # Track A item 4 — Karma: surviving a heavenly trial (+10). GATED on
            # an actual realm-up (granted truthy = thunder was the only phase);
            # a mere thunder-phase pass of a PHASED trib must NOT fire it — that
            # realm-up flows through _trib_grant_realm_advancement (wired there),
            # so gating here prevents a double +10.
            if granted:
                try:
                    from core.karma_engine import apply_tribulation_karma
                    await apply_tribulation_karma(
                        session, user_id, survived=True,
                        metadata={"trib_id": str(trib.id), "target_realm": int(target_realm)})
                except Exception:
                    logger.warning("trib_attempt: karma survive-wire failed", exc_info=True)
        else:
            # Failure — apply CB penalty + buff handling identical to chat.
            trib.outcome = outcome
            trib.status = "failed"
            trib.completed_at = now_utc
            threshold = get_threshold(player.realm, player.sub_layer)

            from core.alchemy_engine import get_active_buffs
            buffs = await get_active_buffs(session, user_id)
            revive_buff = next((b for b in buffs if b.buff_type == "revive"), None)
            insurance_buff = next((b for b in buffs if b.buff_type == "trib_insurance"), None)

            triggered = None
            if revive_buff:
                player.qi = int((player.qi_capacity or 100) * 0.5)
                await session.delete(revive_buff)
                await session.flush()
                triggered = "revive"
            elif insurance_buff:
                player.cultivation_base = float(threshold) * 0.95
                await session.delete(insurance_buff)
                await session.flush()
                triggered = "insurance"
            elif outcome == "failure_grave":
                player.cultivation_base = float(threshold) * 0.50
            else:
                player.cultivation_base = float(threshold) * 0.80
            # Track A item 4 — Karma: a failed trial breeds resentment (-10).
            try:
                from core.karma_engine import apply_tribulation_karma
                await apply_tribulation_karma(
                    session, user_id, survived=False, metadata={"trib_id": str(trib.id)})
            except Exception:
                logger.warning("trib_attempt: karma fail-wire failed", exc_info=True)
            result_block["triggered_talisman"] = triggered
            result_block["cb_after"] = float(player.cultivation_base or 0)
            result_block["cooldown_seconds"] = int(TRIBULATION_COOLDOWN_FAILURE_LIGHT)

        await session.commit()

        return _json({
            "ok": True,
            **result_block,
            "delta": {
                "realm": int(player.realm or 0),
                "sub_layer": int(player.sub_layer or 1),
                "cultivation_base": float(player.cultivation_base or 0),
                "qi": float(player.qi or 0),
                "qi_capacity": float(player.qi_capacity or 100),
                "battle_power": int(player.battle_power or 0),
                "soul_strength": int(player.soul_strength or 0),
                "perception": int(player.perception or 0),
                "luck": int(player.luck or 0),
            },
        })


async def api_tribulation_history(request: web.Request) -> web.Response:
    """READ — last N tribulations for the player.
    Mirrors `historico_tribulacao` chat handler shape but exposes more
    columns (started_at, target_realm, strategy, rounds) for the UI.
    """
    from database.models import Tribulation

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        limit = max(1, min(50, int(payload.get("limit", 10))))
    except (TypeError, ValueError):
        limit = 10

    async with get_session_factory()() as session:
        rows = (await session.execute(
            select(Tribulation)
            .where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["completed", "failed", "expired"]),
            )
            .order_by(desc(Tribulation.completed_at).nulls_last(), desc(Tribulation.started_at))
            .limit(limit)
        )).scalars().all()

        items = []
        for r in rows:
            target = min(int(r.realm or 0), len(REALM_NAMES) - 1)
            phases_done = [p for p in (r.phases_completed or []) if isinstance(p, str)]
            items.append({
                "id": str(r.id),
                "status": r.status,
                "outcome": r.outcome,
                "target_realm": target,
                "target_realm_name": REALM_NAMES[target],
                "target_realm_emoji": (REALM_EMOJIS[target] if 0 <= target < len(REALM_EMOJIS) else "🪨"),
                "strategy": r.strategy,
                "rounds_total": int(r.rounds_total or 0),
                "rounds_survived": int(r.rounds_survived or 0),
                "phases_completed": phases_done,
                "started_at_ms": _ms(r.started_at),
                "completed_at_ms": _ms(r.completed_at),
            })

        return _json({"items": items, "count": len(items)})


# ── v15.1.3.h2 Heart Demon + Dao phases via mini-app ─────────────────────────
# Owner: "tribulacao nao era no miniapp? sempre tem que ser ali se vamos
# migrar trem que funcionar nos 2." — paridade total chat ↔ mini-app.
# Heart Demon: 3 questions, correct answers depend on dominant Dao element,
# perception gates a hint chip. Dao Trial: percentage roll based on fragments.
# Engine reuse 100% from core/tribulation_engine + handlers/tribulation's
# helpers (_get_dominant_dao_element + _grant_realm_advancement equivalents
# replicated inline so we don't import a chat handler from a web endpoint).

async def _trib_get_dominant_dao_element(session, user_id: int) -> str | None:
    """Mirror handlers/tribulation._get_dominant_dao_element."""
    from database.models import PlayerDaoFragment, DaoLawCatalog
    stmt = (
        select(PlayerDaoFragment, DaoLawCatalog)
        .join(DaoLawCatalog, PlayerDaoFragment.dao_law_id == DaoLawCatalog.id)
        .where(PlayerDaoFragment.player_id == user_id, PlayerDaoFragment.fragments_count > 0)
        .order_by(desc(PlayerDaoFragment.fragments_count))
    )
    rows = (await session.execute(stmt)).all()
    if not rows:
        return None
    _, law = rows[0]
    return law.element


async def _trib_total_perception(session, player) -> int:
    """Compute effective perception including equipment + pill buffs (mirror
    handlers/tribulation._send_heart_demon_question logic)."""
    from database.models import PlayerArtifact
    from core.game_logic import calculate_total_stats, get_player_equipment_stats
    try:
        arts = (await session.execute(
            select(PlayerArtifact).where(
                PlayerArtifact.player_id == player.telegram_id,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            )
        )).scalars().all()
        equip_stats = get_player_equipment_stats(arts)
        stats = calculate_total_stats(player, equip_stats)
        total_perception = stats.get("perception", player.perception or 0)
        from core.alchemy_engine import get_active_buffs
        active_buffs = await get_active_buffs(session, player.telegram_id)
        for _b in active_buffs:
            if _b.buff_type == "perception_boost":
                total_perception *= float(_b.buff_value or 1.0)
        return int(total_perception)
    except Exception:
        return int(player.perception or 0)


async def _trib_grant_realm_advancement(session, player, trib) -> dict:
    """Mirror handlers/tribulation._grant_realm_advancement. Returns granted
    info dict. Caller commits."""
    from config import get_threshold as _gt
    target_realm = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
    threshold = _gt(player.realm, player.sub_layer)
    bonus = 1.1 + (target_realm * 0.05)
    old_realm = int(player.realm or 0)
    player.cultivation_base = max(0, float(player.cultivation_base or 0) - threshold)
    player.realm = target_realm
    player.sub_layer = 1
    player.battle_power = int((player.battle_power or 0) * bonus)
    player.soul_strength = int((player.soul_strength or 0) * bonus)
    player.perception = int((player.perception or 0) * bonus)
    player.luck = int((player.luck or 0) * bonus)
    player.qi_capacity = float(player.qi_capacity or 100) * bonus
    trib.status = "completed"
    trib.outcome = "success"
    trib.completed_at = datetime.now(timezone.utc)
    # BUG [jogador] 2026-08-11 — resistência a pílulas é POR REINO; o único reset
    # vivia no ramo de breakthrough simples (inalcançável realm>=4).
    try:
        from core.alchemy_engine import reset_medicine_resistance
        await reset_medicine_resistance(session, player.telegram_id)
    except Exception:
        logger.warning("trib realm grant: medicine resistance reset failed", exc_info=True)
    try:
        from core.bp_engine import update_bp_mission
        await update_bp_mission(session, player.telegram_id, "win_tribulation")
    except Exception:
        logger.exception("trib realm grant: update_bp_mission failed")
    # MV-2 §0 — weekly quest 12 (faucet órfão): espelha o wire do chat.
    try:
        from core.quest_engine import track_quest
        await track_quest(session, player.telegram_id, "tribulation_survive", 1)
    except Exception:
        logger.exception("trib realm grant: tribulation_survive track failed")
    # Dao fragment rewards (mirror chat handler — 1..3 random fragments).
    dao_rewards = []
    try:
        from core.dao_engine import grant_random_fragments
        import random as _r
        dao_rewards = await grant_random_fragments(session, player.telegram_id, _r.randint(1, 3), player.realm)
    except Exception:
        logger.exception("trib realm grant: dao fragments failed")
    # D5 (v16.6): guaranteed first Dao Law on reaching realm 5.
    first_law_msg = None
    try:
        from core.dao_laws_engine import grant_first_law_on_unlock
        first_law_msg = await grant_first_law_on_unlock(
            session, player.telegram_id, target_realm,
            perception=int(player.perception or 100), lang=(player.language or "pt"))
    except Exception:
        logger.exception("trib realm grant: D5 first-law grant failed")
    # Track A item 4 — Karma parity: the canonical (mini-app) realm-grant now
    # wires tribulation_survive (+10) like the chat path (handlers/tribulation
    # ._grant_realm_advancement). Most players survive trials HERE, so without
    # this the +10 was unreachable for the player base. Defensive — a karma
    # failure never aborts the breakthrough (helper owns a SAVEPOINT). Caller commits.
    try:
        from core.karma_engine import apply_tribulation_karma
        await apply_tribulation_karma(
            session, player.telegram_id, survived=True,
            metadata={"trib_id": str(trib.id), "target_realm": int(target_realm)})
    except Exception:
        logger.warning("trib realm grant: karma survive-wire failed", exc_info=True)
    return {
        "realm_up": True,
        "old_realm": old_realm,
        "new_realm": target_realm,
        "new_realm_name": REALM_NAMES[target_realm],
        "new_realm_emoji": (REALM_EMOJIS[target_realm] if 0 <= target_realm < len(REALM_EMOJIS) else "🪨"),
        "bonus_mult": bonus,
        "dao_rewards": dao_rewards or [],
        "dao_first_law": first_law_msg,
    }


async def api_tribulation_hd_state(request: web.Request) -> web.Response:
    """READ — current Heart Demon question state for the active tribulation.

    Returns the next unanswered question (q_idx, question_key, option_keys),
    the player's dominant Dao element + perception-hint visibility, score
    so far, and total_questions=3. If HD already done or no trib pending,
    returns null state.
    """
    from sqlalchemy.orm.attributes import flag_modified
    from core.tribulation_engine import (
        HD_QUESTIONS,
        get_heart_demon_correct_answers,
        get_heart_demon_state,
        set_heart_demon_state,
        get_next_phase,
        can_see_third_option,
    )
    from database.models import Tribulation

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        trib = (await session.execute(
            select(Tribulation).where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["pending", "in_progress"]),
            ).order_by(desc(Tribulation.started_at)).limit(1)
        )).scalar_one_or_none()
        if not trib:
            return _json({"ok": False, "reason": "no_active_tribulation"})

        target_realm = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
        if get_next_phase(trib.phases_completed or [], target_realm) != "heart_demon":
            return _json({"ok": False, "reason": "not_heart_demon_phase",
                          "next_phase": get_next_phase(trib.phases_completed or [], target_realm)})

        dominant = await _trib_get_dominant_dao_element(session, user_id)
        correct = get_heart_demon_correct_answers(dominant)

        phases = list(trib.phases_completed or [])
        hd_state = get_heart_demon_state(phases)
        if hd_state is None or hd_state.get("q", 0) >= 3:
            hd_state = {"q": 0, "score": 0, "ca": correct}
            phases = set_heart_demon_state(phases, hd_state)
            trib.phases_completed = phases
            flag_modified(trib, "phases_completed")
            await session.commit()

        q_idx = int(hd_state.get("q", 0))
        score = int(hd_state.get("score", 0))
        q_key, opt_keys = HD_QUESTIONS[q_idx]

        total_perception = await _trib_total_perception(session, player)
        can_see_third = can_see_third_option(total_perception, int(player.realm or 0))

        return _json({
            "ok": True,
            "trib_id": str(trib.id),
            "q_idx": q_idx,
            "score": score,
            "total_questions": len(HD_QUESTIONS),
            "question_key": q_key,
            "option_keys": opt_keys,
            "dominant_element": dominant,
            "perception_hint": can_see_third,
            "target_realm": target_realm,
            "target_realm_name": REALM_NAMES[target_realm],
            "target_realm_emoji": (REALM_EMOJIS[target_realm] if 0 <= target_realm < len(REALM_EMOJIS) else "🪨"),
        })


async def api_tribulation_hd_answer(request: web.Request) -> web.Response:
    """WRITE — record a Heart Demon answer + advance state.

    Body: `{ option_idx: 0|1|2 }`. If this was the 3rd question, evaluate
    pass/fail via the same score table the chat handler uses (0=fail,
    1=50%, 2=80%, 3=guaranteed). On pass, mark heart_demon done; if dao
    is the last remaining phase, return `{next_phase: "dao"}`; if it was
    the final phase, grant realm advancement. On fail, apply CB penalty
    + buff handling identical to chat (revive / insurance / failure_light).
    """
    import random as _r
    from sqlalchemy.orm.attributes import flag_modified
    from core.tribulation_engine import (
        HD_QUESTIONS,
        get_heart_demon_state,
        set_heart_demon_state,
        mark_heart_demon_done,
        get_next_phase,
    )
    from config import TRIBULATION_COOLDOWN_FAILURE_LIGHT, get_threshold
    from database.models import Tribulation

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        opt_idx = int(payload.get("option_idx"))
    except (TypeError, ValueError):
        return _err("invalid_option_idx", 400)
    if opt_idx not in (0, 1, 2):
        return _err("invalid_option_idx", 400)

    async with get_session_factory()() as session:
        # Lock the player row to serialize concurrent trib POSTs (see
        # api_tribulation_attempt) — prevents the double karma / stat grant.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        trib = (await session.execute(
            select(Tribulation).where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["pending", "in_progress"]),
            ).order_by(desc(Tribulation.started_at)).limit(1)
        )).scalar_one_or_none()
        if not trib:
            return _json({"ok": False, "reason": "no_active_tribulation"})

        target_realm = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
        if get_next_phase(trib.phases_completed or [], target_realm) != "heart_demon":
            return _json({"ok": False, "reason": "not_heart_demon_phase"})

        phases = list(trib.phases_completed or [])
        hd_state = get_heart_demon_state(phases)
        if hd_state is None:
            return _json({"ok": False, "reason": "hd_state_missing"})

        q_idx = int(hd_state.get("q", 0))
        if q_idx >= len(HD_QUESTIONS):
            return _json({"ok": False, "reason": "hd_already_done"})

        correct_answers = hd_state.get("ca") or [1, 1, 1]
        is_correct = (opt_idx == correct_answers[q_idx])
        if is_correct:
            hd_state["score"] = int(hd_state.get("score", 0)) + 1
        hd_state["q"] = q_idx + 1
        phases = set_heart_demon_state(phases, hd_state)
        trib.phases_completed = phases
        flag_modified(trib, "phases_completed")

        result_block = {
            "ok": True,
            "is_correct": is_correct,
            "score": int(hd_state["score"]),
            "q_idx": int(hd_state["q"]),
            "total_questions": len(HD_QUESTIONS),
        }

        # If 3rd question answered → evaluate.
        if hd_state["q"] >= len(HD_QUESTIONS):
            score = int(hd_state["score"])
            if score == 0:
                passed = False
            elif score == 1:
                passed = _r.random() < 0.50
            elif score == 2:
                passed = _r.random() < 0.80
            else:
                passed = True

            phases = mark_heart_demon_done(phases, passed)
            trib.phases_completed = phases
            flag_modified(trib, "phases_completed")
            result_block["phase_done"] = True
            result_block["phase_passed"] = passed

            if passed:
                next_phase = get_next_phase(phases, target_realm)
                result_block["next_phase"] = next_phase
                granted = None
                if next_phase is None:
                    granted = await _trib_grant_realm_advancement(session, player, trib)
                result_block["granted"] = granted
            else:
                # Failure path — same as chat: failure_light, CB penalty,
                # buff handling.
                trib.outcome = "failure_light"
                trib.status = "failed"
                trib.completed_at = datetime.now(timezone.utc)
                threshold = get_threshold(player.realm, player.sub_layer)
                from core.alchemy_engine import get_active_buffs
                _buffs = await get_active_buffs(session, user_id)
                revive_buff = next((b for b in _buffs if b.buff_type == "revive"), None)
                insurance_buff = next((b for b in _buffs if b.buff_type == "trib_insurance"), None)
                triggered = None
                if revive_buff:
                    player.qi = int((player.qi_capacity or 100) * 0.5)
                    await session.delete(revive_buff)
                    await session.flush()
                    triggered = "revive"
                elif insurance_buff:
                    player.cultivation_base = float(threshold) * 0.95
                    await session.delete(insurance_buff)
                    await session.flush()
                    triggered = "insurance"
                else:
                    player.cultivation_base = float(threshold) * 0.80
                # Track A item 4 — Karma: a failed Heart Demon trial breeds resentment (-10).
                try:
                    from core.karma_engine import apply_tribulation_karma
                    await apply_tribulation_karma(
                        session, user_id, survived=False, metadata={"trib_id": str(trib.id)})
                except Exception:
                    logger.warning("trib_hd: karma fail-wire failed", exc_info=True)
                result_block["triggered_talisman"] = triggered
                result_block["cb_after"] = float(player.cultivation_base or 0)
                result_block["cooldown_seconds"] = int(TRIBULATION_COOLDOWN_FAILURE_LIGHT)

        await session.commit()

        result_block["delta"] = {
            "realm": int(player.realm or 0),
            "sub_layer": int(player.sub_layer or 1),
            "cultivation_base": float(player.cultivation_base or 0),
            "qi": float(player.qi or 0),
            "qi_capacity": float(player.qi_capacity or 100),
            "battle_power": int(player.battle_power or 0),
            "soul_strength": int(player.soul_strength or 0),
            "perception": int(player.perception or 0),
            "luck": int(player.luck or 0),
        }
        return _json(result_block)


async def api_tribulation_dao_preview(request: web.Request) -> web.Response:
    """READ — Dao Trial preview (chance / fragments / penalties / can_attempt).

    Mirrors chat _show_dao_trial — calls calculate_dao_chance with the
    same 3000 Dao Laws tribulation bonus.
    """
    from core.tribulation_engine import calculate_dao_chance, get_next_phase
    from database.models import PlayerDaoFragment, Tribulation

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        trib = (await session.execute(
            select(Tribulation).where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["pending", "in_progress"]),
            ).order_by(desc(Tribulation.started_at)).limit(1)
        )).scalar_one_or_none()
        if not trib:
            return _json({"ok": False, "reason": "no_active_tribulation"})

        target_realm = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
        if get_next_phase(trib.phases_completed or [], target_realm) != "dao":
            return _json({"ok": False, "reason": "not_dao_phase",
                          "next_phase": get_next_phase(trib.phases_completed or [], target_realm)})

        frags = (await session.execute(
            select(PlayerDaoFragment).where(PlayerDaoFragment.player_id == user_id)
        )).scalars().all()
        fragments_by_law = [{
            "fragments_count": f.fragments_count,
            "is_completed": f.is_completed,
            "insight_level": f.insight_level,
        } for f in frags]

        trib_bonus = 0.0
        try:
            from core.dao_laws_engine import get_dao_laws_bonuses
            laws_b = await get_dao_laws_bonuses(session, user_id, player.realm)
            trib_bonus = float(laws_b.get("tribulation_bonus", 0.0))
        except Exception:
            pass
        dao_info = calculate_dao_chance(player, fragments_by_law, tribulation_bonus=trib_bonus)

        return _json({
            "ok": True,
            "trib_id": str(trib.id),
            "target_realm": target_realm,
            "target_realm_name": REALM_NAMES[target_realm],
            "target_realm_emoji": (REALM_EMOJIS[target_realm] if 0 <= target_realm < len(REALM_EMOJIS) else "🪨"),
            "chance": dao_info.get("chance", 0),
            "total_fragments": dao_info.get("total_fragments", 0),
            "required": dao_info.get("required", 0),
            "penalties": dao_info.get("penalties", []),
            "can_attempt": bool(dao_info.get("can_attempt")),
            "perfect_bonus": bool(dao_info.get("perfect_bonus")),
            "tribulation_bonus": bool(dao_info.get("tribulation_bonus")),
        })


async def api_tribulation_dao_attempt(request: web.Request) -> web.Response:
    """WRITE — execute the Dao Trial phase.

    Returns {ok, passed, granted? | triggered_talisman?, penalties[]}. On
    success with all phases complete, grants realm advancement same as
    thunder/heart_demon final-phase passes. On fail, applies CB penalty
    + buff handling identical to chat.
    """
    from sqlalchemy.orm.attributes import flag_modified
    import random as _r
    from core.tribulation_engine import calculate_dao_chance, get_next_phase
    from config import TRIBULATION_COOLDOWN_FAILURE_LIGHT, get_threshold
    from database.models import PlayerDaoFragment, Tribulation

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        # Lock the player row to serialize concurrent trib POSTs (see
        # api_tribulation_attempt) — prevents the double karma / stat grant.
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        trib = (await session.execute(
            select(Tribulation).where(
                Tribulation.player_id == user_id,
                Tribulation.status.in_(["pending", "in_progress"]),
            ).order_by(desc(Tribulation.started_at)).limit(1)
        )).scalar_one_or_none()
        if not trib:
            return _json({"ok": False, "reason": "no_active_tribulation"})

        target_realm = min(int(trib.realm or 0), len(REALM_NAMES) - 1)
        if get_next_phase(trib.phases_completed or [], target_realm) != "dao":
            return _json({"ok": False, "reason": "not_dao_phase"})

        frags = (await session.execute(
            select(PlayerDaoFragment).where(PlayerDaoFragment.player_id == user_id)
        )).scalars().all()
        fragments_by_law = [{
            "fragments_count": f.fragments_count,
            "is_completed": f.is_completed,
            "insight_level": f.insight_level,
        } for f in frags]
        trib_bonus = 0.0
        try:
            from core.dao_laws_engine import get_dao_laws_bonuses
            laws_b = await get_dao_laws_bonuses(session, user_id, player.realm)
            trib_bonus = float(laws_b.get("tribulation_bonus", 0.0))
        except Exception:
            pass
        dao_info = calculate_dao_chance(player, fragments_by_law, tribulation_bonus=trib_bonus)

        if not dao_info.get("can_attempt"):
            return _json({"ok": False, "reason": "not_enough_fragments",
                          "have": dao_info.get("total_fragments", 0),
                          "required": dao_info.get("required", 0)})

        passed = _r.random() < (float(dao_info.get("chance", 0)) / 100.0)
        result_block = {
            "ok": True,
            "passed": passed,
            "chance": float(dao_info.get("chance", 0)),
            "penalties": dao_info.get("penalties", []),
        }

        if passed:
            phases = list(trib.phases_completed or [])
            if "dao" not in phases:
                phases.append("dao")
            trib.phases_completed = phases
            flag_modified(trib, "phases_completed")
            next_phase = get_next_phase(phases, target_realm)
            result_block["next_phase"] = next_phase
            granted = None
            if next_phase is None:
                granted = await _trib_grant_realm_advancement(session, player, trib)
            result_block["granted"] = granted
        else:
            trib.outcome = "failure_light"
            trib.status = "failed"
            trib.completed_at = datetime.now(timezone.utc)
            threshold = get_threshold(player.realm, player.sub_layer)
            from core.alchemy_engine import get_active_buffs
            _buffs = await get_active_buffs(session, user_id)
            revive_buff = next((b for b in _buffs if b.buff_type == "revive"), None)
            insurance_buff = next((b for b in _buffs if b.buff_type == "trib_insurance"), None)
            triggered = None
            if revive_buff:
                player.qi = int((player.qi_capacity or 100) * 0.5)
                await session.delete(revive_buff)
                await session.flush()
                triggered = "revive"
            elif insurance_buff:
                player.cultivation_base = float(threshold) * 0.95
                await session.delete(insurance_buff)
                await session.flush()
                triggered = "insurance"
            else:
                player.cultivation_base = float(threshold) * 0.80
            # Track A item 4 — Karma: a failed Dao trial breeds resentment (-10).
            try:
                from core.karma_engine import apply_tribulation_karma
                await apply_tribulation_karma(
                    session, user_id, survived=False, metadata={"trib_id": str(trib.id)})
            except Exception:
                logger.warning("trib_dao: karma fail-wire failed", exc_info=True)
            result_block["triggered_talisman"] = triggered
            result_block["cb_after"] = float(player.cultivation_base or 0)
            result_block["cooldown_seconds"] = int(TRIBULATION_COOLDOWN_FAILURE_LIGHT)

        await session.commit()

        result_block["delta"] = {
            "realm": int(player.realm or 0),
            "sub_layer": int(player.sub_layer or 1),
            "cultivation_base": float(player.cultivation_base or 0),
            "qi": float(player.qi or 0),
            "qi_capacity": float(player.qi_capacity or 100),
            "battle_power": int(player.battle_power or 0),
            "soul_strength": int(player.soul_strength or 0),
            "perception": int(player.perception or 0),
            "luck": int(player.luck or 0),
        }
        return _json(result_block)


# ── Achievements (Sprint v14.8 MA-36) ─────────────────────────────────────────
# Mirrors handlers/achievements.py + core/achievement_engine. The mini-app
# spec talked about a `claim` endpoint but achievement bonuses (stat_bonus
# + title_granted) apply automatically the moment `unlocked_at` is set —
# there is no claim flow in the engine. The only manual interaction is
# equipping a title, so we expose `equip_title` as the mini-app analogue
# of "claim my reward". Decision documented in Sessions/2026-05-19.md.

async def api_achievements_list(request: web.Request) -> web.Response:
    """READ — full achievement catalog with per-player progress + active title.

    Pre-emptively syncs set-based achievements (realm/jade/prestige/beasts)
    so retroactive progress is reflected — same call `/conquistas` chat
    command does on entry.
    """
    from core.achievement_engine import (
        get_player_achievements, get_unlocked_titles, sync_player_snapshot,
        get_extra_titles_with_desc,
    )

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        try:
            await sync_player_snapshot(session, player)
            await session.commit()
        except Exception:
            logger.exception("achievements_list: sync_player_snapshot failed")

        items_raw = await get_player_achievements(session, user_id)
        unlocked_titles = await get_unlocked_titles(session, user_id)
        # TAPETE QoL §5 item 10 ([jogador]): JSONB extra titles (monetization/BP/
        # prestige) finally listed WITH a description. Server-resolved i18n.
        extra_titles = await get_extra_titles_with_desc(
            session, user_id, (player.language or "pt")
        )
        for et in extra_titles:
            et["equipped"] = bool(player.active_title == et["name"])

        items = []
        from core.achievement_engine import bonus_display as _ach_bonus_display
        unlocked_count = 0
        for ach, pa in items_raw:
            unlocked_at_ms = _ms(pa.unlocked_at) if (pa and pa.unlocked_at) else None
            progress = int(pa.progress) if pa else 0
            target = int(ach.target_value or 0)
            is_unlocked = unlocked_at_ms is not None
            if is_unlocked:
                unlocked_count += 1
            stat_bonus = ach.stat_bonus or {}
            items.append({
                "id": int(ach.id),
                "name": ach.name,
                "description": ach.description,
                "emoji": ach.emoji or "🏆",
                "event_type": ach.event_type,
                "target_value": target,
                "progress": progress,
                "pct": (min(100, int(round(100 * progress / target))) if target > 0 else 0),
                "is_unlocked": is_unlocked,
                "unlocked_at_ms": unlocked_at_ms,
                "title_granted": ach.title_granted,
                "title_equipped": bool(ach.title_granted and player.active_title == ach.title_granted),
                "stat_bonus": {k: float(v) for k, v in stat_bonus.items()},
                # QoL 04/08 — o que ESTE mundo realmente aplica (uma verdade:
                # achievement_engine.bonus_display). Lista vazia ⇒ o card mostra
                # a linha honorífica em vez do "+105%" que a main anunciava.
                "bonus_view": _ach_bonus_display(stat_bonus),
            })

        return _json({
            "items": items,
            "count": len(items),
            "unlocked_count": unlocked_count,
            "active_title": player.active_title,
            "unlocked_titles": unlocked_titles,
            "extra_titles": extra_titles,
        })


async def api_achievements_equip_title(request: web.Request) -> web.Response:
    """WRITE — equip (or remove) a title. Mirrors `ach_equip_*` callback.

    Body: `{ title: "Apex Cultivator" }` to equip; `{ title: null }` (or
    omit) to unequip.
    """
    from core.achievement_engine import equip_title

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    title = payload.get("title")
    if title is not None and not isinstance(title, str):
        return _err("invalid_title", 400)
    if isinstance(title, str):
        title = title.strip() or None

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        ok = await equip_title(session, user_id, title)
        if not ok:
            return _json({"ok": False, "reason": "title_not_unlocked"}, status=200)
        await session.commit()
        return _json({"ok": True, "active_title": player.active_title})


# ── Combat / Arena (Sprint v14.9 MA-35) ───────────────────────────────────────
# Mirrors handlers/combat.py + core/combat_engine.py. Engine reuse:
# `simulate_combat` and `generate_npc_fighter` are pure (no Telegram side
# effects), so the NPC duel endpoint can call them directly. Side effects
# (HP drain, cooldowns, loot, mastery XP, quest tracking) are replicated
# inline — same shape as the chat handler. PvP challenge/queue stays in the
# chat (interactive accept/decline flow), mirrored by `phase_requires_chat`
# on MA-34. UI surfaces it via banner hint.

async def _build_combat_loadout_payload(session, player) -> dict:
    """Build the full Combat tab payload — equipped/learned/learnable/scrolls,
    arena summary, NPC cooldown, and combat stats. Each block has its own
    try/except (lição N-31/N-34) — a failing sub-block must not hide the rest.
    """
    from database.models import (
        ArenaRanking,
        DaoLawCatalog,
        PlayerArtifact,
        PlayerDaoFragment,
        PlayerInventory,
        PlayerNPCCooldown,
        PlayerTechnique,
        TechniqueCatalog,
    )
    from core.scroll_economy_engine import grade_scroll_cost as _scr_grade_cost
    from core.combat_engine import (
        MASTERY_STAGES,
        TECHNIQUE_GRADES,
        GRADE_UPGRADE_REQS,
        get_grade_info,
        get_next_grade,
        get_max_combat_techniques,
        get_max_hp,
        get_current_hp,
        calculate_hp,
        CURRENT_SEASON,
    )
    from core.game_logic import calculate_total_stats, get_player_equipment_stats

    user_id = player.telegram_id
    payload: dict = {
        "techniques": {"learned": [], "learnable": [], "scrolls": []},
        "arena": None,
        "npc": {"cooldown_seconds": 0},
        "stats": {},
        "dao_locked": False,
    }

    # ── Techniques ────────────────────────────────────────────────────────
    try:
        learned_rows = (await session.execute(
            select(
                PlayerTechnique.technique_id,
                PlayerTechnique.mastery_level,
                PlayerTechnique.mastery_xp,
                PlayerTechnique.is_active_combat,
                PlayerTechnique.grade,
                TechniqueCatalog.name,
                TechniqueCatalog.emoji,
                TechniqueCatalog.effect_type,
                TechniqueCatalog.effect_value,
                TechniqueCatalog.effect_round,
                # 武 2.2 — o CUSTO. A tira de preparo (`CenaPreparo`) diz com o
                # que o jogador vai lutar ANTES de ele pagar a entrada, e sem
                # esta coluna o custo sairia `undefined` — que o cliente
                # imprimiria como **0 de Qi**, e "de graça" é pior do que
                # calado. O mesmo default defensivo do duelo (`or 10`).
                TechniqueCatalog.qi_cost,
                TechniqueCatalog.tech_type,
                TechniqueCatalog.req_realm,
                TechniqueCatalog.description,
                TechniqueCatalog.required_dao_law_id,
                TechniqueCatalog.required_dao_insight,
                # v15.2 — Intent affinity for the chip on each tech in CombatTab.
                TechniqueCatalog.intent_affinity,
                # Track A item 6 — element for the Art↔Root resonance flavor.
                TechniqueCatalog.element,
            )
            .join(TechniqueCatalog, TechniqueCatalog.id == PlayerTechnique.technique_id)
            .where(PlayerTechnique.player_id == user_id)
        )).all()

        # Track A item 6 — Art↔Root resonance (disclosure-only flavor, zero modifier).
        from core.root_engine import get_root_elements
        from core.technique_engine import technique_root_resonance, technique_gain_key
        root_set = set(get_root_elements(player))
        # 内功 ([jogador] 2026-08-11) — a frase "como esta arte ganha Compreensão" é
        # server-resolved (a MESMA do chat). `lang` não é parâmetro desta função.
        from core.i18n import t as _tech_t
        from core.i18n import catalog_text as _cat_t
        _tech_lang = (getattr(player, "language", None) or "pt").lower()
        _gain_hint_cache: dict = {}

        # 名 2026-09-08 — o nome e a descrição da arte deixam de sair CRUS.
        # `catalog_text` devolve `tech_<id>_name` quando existe e o nome do
        # catálogo quando não — ou seja, para uma arte ainda não traduzida a
        # tela fica EXACTAMENTE como está hoje. Ver a nota longa em `core/i18n.py`.
        def _tname(tid, raw):
            return _cat_t(_tech_lang, "tech", tid, "name", raw)

        def _tdesc(tid, raw):
            return _cat_t(_tech_lang, "tech", tid, "desc", raw)

        def _gain_hint(ttype) -> str:
            k = technique_gain_key(ttype)
            if k not in _gain_hint_cache:
                _gain_hint_cache[k] = _tech_t(_tech_lang, k)
            return _gain_hint_cache[k]

        # v16.4c — exclude house signature arts (sect_key) from the LEARNABLE
        # pool: they are learned via the Sect Hall (rank-gated, no scroll), not
        # the scroll path, so they must not show as "learnable but no scroll".
        # The `learned` list above is unaffected (a learned sect art still shows).
        all_techs = (await session.execute(
            select(TechniqueCatalog).where(TechniqueCatalog.sect_key.is_(None))
        )).scalars().all()

        scrolls_rows = (await session.execute(
            select(PlayerInventory).where(
                PlayerInventory.player_id == user_id,
                PlayerInventory.item_type == "technique_scroll",
                PlayerInventory.quantity > 0,
            )
        )).scalars().all()

        # Dao fragments + catalog (for tech locks).
        frags_rows = (await session.execute(
            select(PlayerDaoFragment).where(PlayerDaoFragment.player_id == user_id)
        )).scalars().all()
        frags = {r.dao_law_id: r.fragments_count for r in frags_rows}
        dao_laws_rows = (await session.execute(select(DaoLawCatalog))).scalars().all()
        dao_laws = {d.id: d for d in dao_laws_rows}

        learned_ids = {r[0] for r in learned_rows}

        def _serialize_learned(row) -> dict:
            (tid, mlevel, mxp, active, grade, name, emoji, eff_type, eff_value,
             eff_round, qi_cost, ttype, req_realm, desc, req_dao_id, req_dao_insight,
             intent_affinity, element) = row
            stage = MASTERY_STAGES.get(int(mlevel or 1), MASTERY_STAGES[1])
            next_stage = MASTERY_STAGES.get(int(mlevel or 1) + 1)
            grade_info = TECHNIQUE_GRADES.get(grade, TECHNIQUE_GRADES["common"])
            ng = get_next_grade(grade)
            upgrade = None
            if ng:
                reqs = GRADE_UPGRADE_REQS.get(ng) or {}
                upgrade = {
                    "next_grade": ng,
                    "min_mastery": int(reqs.get("min_mastery", 1)),
                    "stones": int(reqs.get("stones", 0)),
                    # TEC-2 — display = custo real (o mesmo helper que o débito).
                    "scrolls": _scr_grade_cost(int(reqs.get("scrolls", 0))),
                    "pill": reqs.get("pill"),
                    "requires_tribulation": bool(reqs.get("requires_tribulation", False)),
                    "ready": int(mlevel or 1) >= int(reqs.get("min_mastery", 1)),
                }
            return {
                "id": int(tid),
                "name": _tname(int(tid), name),
                # 🔴 武 2.2 — A CHAVE QUE FALTAVA, e faltava desde 2026-09-08.
                #
                # O `name` acima vai TRADUZIDO. O cliente constrói o URL da arte a
                # partir do nome (`pieceArt("technique", tech.name, tech.art_key)`),
                # e o slug de "Passo do Trovão" não está no índice — só o de
                # "Thunder Step" está. Sem esta linha a carta cai no VERSO, que é
                # um estado legítimo, e por isso ninguém dava por ela.
                #
                # MEDIDO a 2026-09-23, a chamar este construtor: **129 nomes por
                # língua → 0 encontravam arte** em `pt` e em `es`; em `en`, 129 de
                # 129. E o `learnable[]` ao lado já mandava a chave — a mesma
                # lista, dois donos, e só um deles corrigido a 14/09.
                #
                # ⚠️ A guarda de 14/09 estava VERDE por cima disto: ela contava que
                # toda chamada do cliente a `pieceArt` levava a chave — e levava.
                # `tech.art_key` é que era `undefined`, porque o SERVIDOR nunca o
                # mandava. Afirmar sobre a CHAMADA não é afirmar sobre o PAYLOAD.
                # A guarda nova (§28) chama esta função e mede o que ela devolve.
                #
                # O nome é para LER; a chave é para ENCONTRAR. Ver `catalog_art_key`.
                "art_key": name,
                "emoji": emoji or "⚔️",
                "tech_type": ttype,
                "effect_type": eff_type,
                "effect_value": float(eff_value or 0),
                "effect_round": int(eff_round or 0),
                "qi_cost": int(qi_cost or 10),
                "req_realm": int(req_realm or 0),
                "description": _tdesc(int(tid), desc),
                "is_active": bool(active),
                "grade": grade,
                "grade_emoji": grade_info["emoji"],
                "grade_mult": grade_info["mult"],
                "mastery_level": int(mlevel or 1),
                "mastery_xp": int(mxp or 0),
                "mastery_emoji": stage["emoji"],
                "mastery_mult": stage["mult"],
                "next_mastery_xp": int(next_stage["xp_req"]) if next_stage else None,
                # 内功 (report do [jogador] 2026-08-11) — a frase que DIZ como esta arte
                # ganha Compreensão, server-resolved (a MESMA do chat: dual-surface,
                # zero markdown). Antes, para as internas/de meditação, a única
                # fonte era absorver um pergaminho repetido e nenhuma tela o dizia.
                "gain_hint": _gain_hint(ttype) if next_stage else None,
                "upgrade": upgrade,
                # v15.2 — intent affinity chip + meta (emoji) for the loadout UI.
                "intent_affinity": intent_affinity,
                # Track A item 6 — Art↔Root resonance (null unless the art's element
                # is a Wuxing element the player's root carries). Flavor, zero modifier.
                "element": element,
                "root_resonance": technique_root_resonance(element, root_set),
            }

        # Map of {tech_id: scroll_qty} for quick lookup — learned rows tag
        # this so the detail modal can show "Absorver pergaminho ×N" CTAs.
        scroll_qty_by_tech = {int(s.item_id): int(s.quantity) for s in scrolls_rows}
        # Per-tier absorb XP (mirrors handlers/combat._handle_absorb_scroll).
        _absorb_xp_table = {0: 50, 1: 50, 2: 100, 3: 100, 4: 200, 5: 200, 6: 400, 7: 400}

        # TEC-1 — artes do Núcleo de OUTRA casa estão LOCKADAS (cross-sect §3):
        # chave CONDICIONAL `lib_locked` (lição MV-7 — flag OFF ⇒ payload do
        # main byte-idêntico). A UI esconde o equipar e mostra o 🔒 com o porquê.
        _lib_locked_ids: set = set()
        try:
            # TEC-3: piso do engine (sombra de `is_library_locked` — move junto).
            from core.sect_library_engine import LOCK_TIER_FLOOR as _lib_floor
            from core.sect_library_engine import biblioteca_on as _lib_on
            if _lib_on() and learned_ids:
                _lib_rows = (await session.execute(
                    select(TechniqueCatalog.id, TechniqueCatalog.sect_key).where(
                        TechniqueCatalog.id.in_(learned_ids),
                        TechniqueCatalog.library_tier >= _lib_floor,
                        TechniqueCatalog.sect_key.isnot(None),
                    )
                )).all()
                _psect = getattr(player, "sect_id", None)
                _lib_locked_ids = {int(r[0]) for r in _lib_rows if r[1] != _psect}
        except Exception:
            _lib_locked_ids = set()

        for row in learned_rows:
            entry = _serialize_learned(row)
            tid = entry["id"]
            qty = scroll_qty_by_tech.get(tid, 0)
            entry["owned_scroll_qty"] = qty
            entry["absorb_xp_per_scroll"] = int(_absorb_xp_table.get(int(entry["req_realm"]), 750))
            if tid in _lib_locked_ids:
                entry["lib_locked"] = True
            payload["techniques"]["learned"].append(entry)

        # Learnable: not-learned + meets realm/spirit_root + has scroll listed
        # separately in `has_scroll`. UI gates the Learn button on dao + scroll.
        learnable: list[dict] = []
        for tech in all_techs:
            if tech.id in learned_ids:
                continue
            if (tech.req_spirit_root is not None
                    and (player.spirit_root or 0) > tech.req_spirit_root):
                continue
            if (player.realm or 0) < (tech.req_realm or 0):
                continue
            has_scroll = any(s.item_id == tech.id for s in scrolls_rows)
            dao_met = True
            dao_block = None
            if tech.required_dao_law_id:
                law = dao_laws.get(tech.required_dao_law_id)
                cur = frags.get(tech.required_dao_law_id, 0)
                req = int(tech.required_dao_insight or 0)
                dao_met = cur >= req
                dao_block = {
                    "law_id": int(tech.required_dao_law_id),
                    "law_name": law.name if law else f"Dao #{tech.required_dao_law_id}",
                    "law_emoji": law.emoji if law else "☯️",
                    "current": int(cur),
                    "required": req,
                    "met": dao_met,
                }
            learnable.append({
                "id": int(tech.id),
                "name": _tname(int(tech.id), tech.name),
                "art_key": catalog_art_key(tech),
                "emoji": tech.emoji or "⚔️",
                "tech_type": tech.tech_type,
                "req_realm": int(tech.req_realm or 0),
                "description": _tdesc(int(tech.id), tech.description),
                "effect_type": tech.effect_type,
                "effect_value": float(tech.effect_value or 0),
                "has_scroll": has_scroll,
                "dao": dao_block,
                "can_learn": has_scroll and dao_met,
                # Track A item 6 — resonance flavor (zero modifier).
                "element": tech.element,
                "root_resonance": technique_root_resonance(tech.element, root_set),
            })
        payload["techniques"]["learnable"] = learnable

        # Scrolls (flat list for UI badges).
        scrolls_view = []
        for s in scrolls_rows:
            tech = next((t_ for t_ in all_techs if t_.id == s.item_id), None)
            scrolls_view.append({
                "tech_id": int(s.item_id),
                "qty": int(s.quantity),
                "name": _tname(int(s.item_id), tech.name) if tech else f"#{s.item_id}",
                # 武 2.2 — um pergaminho é a MESMA arte; a chave anda ao lado do
                # nome traduzido aqui também, pelo mesmo motivo do `learned[]`.
                # Nenhuma tela desenha a arte do pergaminho HOJE (medido: 3 dos 3
                # pontos de arte de técnica no cliente comem de `learned`/
                # `learnable`) — e é por isso que a chave entra AGORA: a que falta
                # no dia em que a tela nascer é a que ninguém vai procurar.
                # ⚠️ pelo `catalog_art_key`, que é a porta nomeada desta leitura —
                # nao por um `tech.name` à mão. A catraca dos nomes crus apanhou
                # a 1ª versão e ofereceu-me uma DECLARAÇÃO de excepção; uma lista
                # de excepções que só sobe é uma lista de desculpas, e já havia
                # dono para a pergunta.
                "art_key": catalog_art_key(tech) if tech else None,
                "emoji": tech.emoji if tech else "📜",
                "is_known": s.item_id in learned_ids,
            })
        payload["techniques"]["scrolls"] = scrolls_view

        # Surfaced Dao-locked hint flag for UI footer.
        payload["dao_locked"] = any(
            (tech.required_dao_law_id is not None
             and frags.get(tech.required_dao_law_id, 0) < (tech.required_dao_insight or 0))
            for tech in all_techs
        )
    except Exception:
        logger.exception("combat/loadout: techniques block failed")

    # ── Arena summary ─────────────────────────────────────────────────────
    try:
        ranking = (await session.execute(
            select(ArenaRanking).where(
                ArenaRanking.player_id == user_id,
                ArenaRanking.season == CURRENT_SEASON,
            )
        )).scalar_one_or_none()
        elo = int(ranking.elo_points) if ranking else 1000
        wins = int(ranking.wins) if ranking else 0
        losses = int(ranking.losses) if ranking else 0
        rank_pos = None
        if ranking:
            higher = (await session.execute(
                select(func.count()).select_from(ArenaRanking).where(
                    ArenaRanking.season == CURRENT_SEASON,
                    ArenaRanking.elo_points > ranking.elo_points,
                )
            )).scalar() or 0
            rank_pos = int(higher) + 1
        payload["arena"] = {
            "elo": elo,
            "wins": wins,
            "losses": losses,
            "season": int(CURRENT_SEASON),
            "rank": rank_pos,
        }
    except Exception:
        logger.exception("combat/loadout: arena block failed")

    # ── NPC cooldown (30 min) ────────────────────────────────────────────
    try:
        cd = (await session.execute(
            select(PlayerNPCCooldown).where(PlayerNPCCooldown.player_id == user_id)
        )).scalar_one_or_none()
        cd_seconds = 0
        fights_today = 0
        if cd:
            fights_today = int(cd.fights_today or 0)
            if cd.last_npc_fight:
                last = cd.last_npc_fight
                if last.tzinfo is None:
                    last = last.replace(tzinfo=timezone.utc)
                elapsed = (datetime.now(timezone.utc) - last).total_seconds()
                if elapsed < 1800:
                    cd_seconds = int(1800 - elapsed)
        payload["npc"] = {
            "cooldown_seconds": cd_seconds,
            "fights_today": fights_today,
            "cooldown_total_seconds": 1800,
        }
    except Exception:
        logger.exception("combat/loadout: npc block failed")

    # ── Combat stats (BP, HP, slot caps) ─────────────────────────────────
    try:
        arts = (await session.execute(
            select(PlayerArtifact).where(
                PlayerArtifact.player_id == user_id,
                PlayerArtifact.is_equipped == True,  # noqa: E712
            )
        )).scalars().all()
        equip_stats = get_player_equipment_stats(arts)
        total = calculate_total_stats(player, equip_stats)
        # Onda B — HP shown on the loadout screen == the arena (Alma-routed).
        cur_hp, max_hp = await _soul_hp_pair(session, player)
        # Onda E — the "Poder de Batalha" chip == the header's aggregated Poder de Combate
        # (Alma) when progressao_visivel ON; OFF → legacy total_battle_power (byte-identical).
        from database.db import feature_enabled_for_world as _ffe_cl
        _bp_disp = (await _display_combat_power(session, player)
                    if _ffe_cl("progressao_visivel") else int(total.get("total_battle_power", 0)))
        max_slots = get_max_combat_techniques(int(player.realm or 0))
        active_count = sum(1 for ln in payload["techniques"]["learned"]
                           if ln["is_active"] and ln["tech_type"] == "combat")
        payload["stats"] = {
            "battle_power": int(_bp_disp),
            "soul_strength": int(total.get("soul_strength", 0)),
            "perception": int(total.get("perception", 0)),
            "current_hp": int(cur_hp),
            "max_hp": int(max_hp),
            "hp_pct": int((cur_hp / max_hp) * 100) if max_hp > 0 else 100,
            "max_combat_slots": int(max_slots),
            "active_combat_count": int(active_count),
        }
    except Exception:
        logger.exception("combat/loadout: stats block failed")

    # O GOLPE PADRAO (report do [jogador] 10/09) — o bloco so' nasce com a flag ON.
    # ⚠️ Key CONDICIONAL de proposito: uma key sempre-presente quebra a
    # OFF-identity do payload (licao MV-7), e a tela sabe que a feature nao
    # existe neste mundo pela AUSENCIA do bloco — nunca por um `enabled: false`
    # que ela teria de lembrar-se de ler.
    try:
        from core.duel_engine import golpe_padrao_on
        if golpe_padrao_on():
            from core.forbidden_path_engine import is_forbidden as _is_forb
            _cur = int(getattr(player, "default_technique_id", 0) or 0)
            # ⚠️ Elegiveis = as artes de COMBATE equipadas que nao sao proibidas.
            # A arte proibida NAO aparece na lista, e a tela diz porque' (Lei §1:
            # esconder sem dizer e' que seria o beco). Ver o porque' inteiro em
            # `core/duel_engine.resolve_default_strike`.
            _elig, _forb = [], 0
            for _ln in payload.get("techniques", {}).get("learned", []):
                if _ln.get("tech_type") != "combat" or not _ln.get("is_active"):
                    continue
                if _is_forb(_ln.get("id")):
                    _forb += 1
                    continue
                _elig.append({"id": int(_ln["id"]), "name": _ln.get("name"),
                              "emoji": _ln.get("emoji")})
            _elig_ids = {e["id"] for e in _elig}
            payload["default_strike"] = {
                # ⚠️ o `current` REFLECTE o que o motor faria: um id gravado que
                # ja' nao esta' equipado dispara o golpe basico, portanto a tela
                # tem de mostrar o golpe basico — nao a escolha morta. Mostrar a
                # escolha morta seria a tela a prometer o que o motor nao cumpre.
                "current": _cur if _cur in _elig_ids else 0,
                "stored": _cur,
                "eligible": _elig,
                "forbidden_hidden": _forb,
            }
    except Exception:
        logger.exception("combat/loadout: default strike block failed")

    return payload


async def api_combat_default_strike(request: web.Request) -> web.Response:
    """WRITE — escolher a tecnica que o relogio dispara quando voce nao esta' la'.

    Body: `{ tech_id: int }` (0 = o golpe basico, que e' o comportamento de
    sempre). Report do [jogador] 10/09; decisao do owner 12/09.

    ⚠️ AS MESMAS TRAVAS DO MOTOR, aqui tambem — e de proposito. O motor recusa
    silenciosamente (cai no basico) porque nao tem a quem falar; ESTA porta
    recusa a DIZER porque', que e' onde o jogador esta' para ouvir. Se so' o
    motor travasse, ele guardaria a arte proibida, veria-a guardada, e nunca
    perceberia porque' ela nunca dispara.
    """
    user_id: int = request["user_id"]
    payload_in = request.get("payload") or {}
    try:
        tech_id = int(payload_in.get("tech_id") or 0)
    except (TypeError, ValueError):
        return _err("bad_request", 400)

    from core.duel_engine import golpe_padrao_on
    if not golpe_padrao_on():
        return _err("feature_off", 404)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        if tech_id:
            from core.forbidden_path_engine import is_forbidden
            if is_forbidden(tech_id):
                # ⚠️ O VETO, dito por palavras: o Caminho Proibido cobra karma e
                # ANOS DE VIDA por uso. Um automatico nao pode cobrar um preco
                # que o jogador nao escolheu naquele instante.
                return _json({"ok": False, "reason": "forbidden_never_auto"}, status=200)
            from database.models import PlayerTechnique, TechniqueCatalog
            # ⚠️ A coluna e' `is_active_combat`. Ate' 30/09 aqui estava
            # `is_active`, que NAO existe no modelo: escolher qualquer arte
            # rebentava com AttributeError ao montar a query => 500 no Beta,
            # 0 escolhas gravadas desde que a flag ligou. O arnes devolvia
            # `ok: true` sem chamar a rota, por isso o olhar nao o viu.
            # Guardas: `_test_relatos_0814.py` §9 (a rota CORRE de ponta a ponta) e
            # `scripts/_audit_orm_colunas.py` (toda a `Modelo.coluna` existe).
            row = (await session.execute(
                select(PlayerTechnique).join(
                    TechniqueCatalog, TechniqueCatalog.id == PlayerTechnique.technique_id
                ).where(
                    PlayerTechnique.player_id == user_id,
                    PlayerTechnique.technique_id == tech_id,
                    PlayerTechnique.is_active_combat.is_(True),
                    TechniqueCatalog.tech_type == "combat",
                ).limit(1)
            )).scalars().first()
            if row is None:
                return _json({"ok": False, "reason": "technique_not_equipped"}, status=200)

        player.default_technique_id = tech_id or None
        await session.commit()
        return _json({"ok": True, "default_technique_id": tech_id or 0})


