async def api_combat_learn_technique(request: web.Request) -> web.Response:
    """WRITE — consume a technique scroll to learn the technique.

    Body: `{ tech_id: int }`. Mirrors `_handle_learn_technique` in
    handlers/combat.py: validates realm/spirit_root/dao requirement, decrements
    scroll quantity, creates PlayerTechnique row, auto-equips when a combat slot
    is available.
    """
    from database.models import (
        DaoLawCatalog,
        PlayerDaoFragment,
        PlayerInventory,
        PlayerTechnique,
        TechniqueCatalog,
    )
    from core.combat_engine import get_max_combat_techniques

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        tech_id = int(payload.get("tech_id"))
    except (TypeError, ValueError):
        return _err("invalid_tech_id", 400)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        tech = (await session.execute(
            select(TechniqueCatalog).where(TechniqueCatalog.id == tech_id)
        )).scalar_one_or_none()
        if not tech:
            return _json({"ok": False, "reason": "tech_not_found"}, status=200)

        if (player.realm or 0) < (tech.req_realm or 0):
            return _json({"ok": False, "reason": "realm_too_low",
                          "req_realm": int(tech.req_realm or 0)}, status=200)

        if (tech.req_spirit_root is not None
                and (player.spirit_root or 0) > tech.req_spirit_root):
            return _json({"ok": False, "reason": "spirit_root_required"}, status=200)

        if tech.required_dao_law_id:
            frag = (await session.execute(
                select(PlayerDaoFragment).where(
                    PlayerDaoFragment.player_id == user_id,
                    PlayerDaoFragment.dao_law_id == tech.required_dao_law_id,
                )
            )).scalar_one_or_none()
            cur = int(frag.fragments_count) if frag else 0
            req = int(tech.required_dao_insight or 0)
            if cur < req:
                law = (await session.execute(
                    select(DaoLawCatalog).where(DaoLawCatalog.id == tech.required_dao_law_id)
                )).scalar_one_or_none()
                return _json({
                    "ok": False, "reason": "dao_required",
                    "dao_law_name": law.name if law else f"Dao #{tech.required_dao_law_id}",
                    "current": cur, "required": req,
                }, status=200)

        scroll = (await session.execute(
            select(PlayerInventory).where(
                PlayerInventory.player_id == user_id,
                PlayerInventory.item_type == "technique_scroll",
                PlayerInventory.item_id == tech_id,
                PlayerInventory.quantity > 0,
            )
        )).scalar_one_or_none()
        if not scroll:
            return _json({"ok": False, "reason": "no_scroll"}, status=200)

        existing = (await session.execute(
            select(PlayerTechnique).where(
                PlayerTechnique.player_id == user_id,
                PlayerTechnique.technique_id == tech_id,
            )
        )).scalar_one_or_none()
        if existing:
            return _json({"ok": False, "reason": "already_learned"}, status=200)

        scroll.quantity -= 1
        if scroll.quantity <= 0:
            await session.delete(scroll)

        auto_equip = True
        if tech.tech_type == "combat":
            max_slots = get_max_combat_techniques(int(player.realm or 0))
            active = (await session.execute(
                select(func.count())
                .select_from(PlayerTechnique)
                .join(TechniqueCatalog, TechniqueCatalog.id == PlayerTechnique.technique_id)
                .where(
                    PlayerTechnique.player_id == user_id,
                    PlayerTechnique.is_active_combat == True,  # noqa: E712
                    TechniqueCatalog.tech_type == "combat",
                )
            )).scalar() or 0
            if int(active) >= max_slots:
                auto_equip = False

        new_pt = PlayerTechnique(
            player_id=user_id,
            technique_id=tech_id,
            mastery_level=1,
            is_active_combat=auto_equip,
        )
        session.add(new_pt)
        await session.commit()

    # 名 2026-09-08 — o toast tem de falar a mesma língua que a carta que ele
    # acabou de mudar. Corrigir só a leitura deixaria "aprendeu Thunder Step"
    # por cima de uma carta a dizer "Passo do Trovão".
    from core.i18n import catalog_text as _cat_t
    return _json({
        "ok": True,
        "tech_id": int(tech_id),
        "name": _cat_t((player.language or "pt").lower(), "tech", int(tech_id), "name", tech.name),
        "emoji": tech.emoji or "⚔️",
        "auto_equipped": bool(auto_equip),
    })


async def api_combat_equip_technique(request: web.Request) -> web.Response:
    """WRITE — toggle is_active_combat for a learned technique.

    Body: `{ tech_id: int, equip: bool }`. Enforces realm slot cap on equip.
    Returns the updated active count so UI can reflect immediately.
    """
    from database.models import PlayerTechnique, TechniqueCatalog
    from core.combat_engine import get_max_combat_techniques

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        tech_id = int(payload.get("tech_id"))
    except (TypeError, ValueError):
        return _err("invalid_tech_id", 400)
    equip = bool(payload.get("equip", True))

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        pt = (await session.execute(
            select(PlayerTechnique).where(
                PlayerTechnique.player_id == user_id,
                PlayerTechnique.technique_id == tech_id,
            )
        )).scalar_one_or_none()
        if not pt:
            return _json({"ok": False, "reason": "not_learned"}, status=200)

        tech = (await session.execute(
            select(TechniqueCatalog).where(TechniqueCatalog.id == tech_id)
        )).scalar_one_or_none()
        if not tech:
            return _json({"ok": False, "reason": "tech_not_found"}, status=200)

        if equip:
            # TEC-1 — arte do Núcleo de OUTRA casa está lockada (cross-sect
            # §3): recusa disclosed. Gated: flag OFF ⇒ nunca avaliado (main
            # byte-idêntico).
            try:
                from core.sect_library_engine import biblioteca_on, is_library_locked
                if biblioteca_on() and is_library_locked(tech, player):
                    return _json({"ok": False, "reason": "lib_locked"}, status=200)
            except Exception:
                pass

        if equip and tech.tech_type == "combat":
            # Re-validate realm + spirit root (player may have rebirthed since).
            if (player.realm or 0) < (tech.req_realm or 0):
                return _json({"ok": False, "reason": "realm_too_low"}, status=200)
            if (tech.req_spirit_root is not None
                    and (player.spirit_root or 0) > tech.req_spirit_root):
                return _json({"ok": False, "reason": "spirit_root_required"}, status=200)
            max_slots = get_max_combat_techniques(int(player.realm or 0))
            active = (await session.execute(
                select(func.count())
                .select_from(PlayerTechnique)
                .join(TechniqueCatalog, TechniqueCatalog.id == PlayerTechnique.technique_id)
                .where(
                    PlayerTechnique.player_id == user_id,
                    PlayerTechnique.is_active_combat == True,  # noqa: E712
                    TechniqueCatalog.tech_type == "combat",
                )
            )).scalar() or 0
            if int(active) >= max_slots and not pt.is_active_combat:
                return _json({"ok": False, "reason": "slots_full",
                              "max_slots": int(max_slots)}, status=200)

        pt.is_active_combat = bool(equip)
        # 減 P7 — equipar uma arte de COMBATE e' a accao cuja frase a entrada
        # da aba explica ("Sua arte esta' pronta"). Desequipar nao conta, e uma
        # arte de meditacao tambem nao — nao e' dela que a frase fala.
        if equip and tech.tech_type == "combat":
            from core.explicacoes import marcar_apto as _explica_apto
            _explica_apto(player, "equipar")
        await session.commit()

        active_count = (await session.execute(
            select(func.count())
            .select_from(PlayerTechnique)
            .join(TechniqueCatalog, TechniqueCatalog.id == PlayerTechnique.technique_id)
            .where(
                PlayerTechnique.player_id == user_id,
                PlayerTechnique.is_active_combat == True,  # noqa: E712
                TechniqueCatalog.tech_type == "combat",
            )
        )).scalar() or 0

    return _json({
        "ok": True,
        "tech_id": int(tech_id),
        "is_active": bool(equip),
        "active_count": int(active_count),
    })


async def api_combat_grade_upgrade(request: web.Request) -> web.Response:
    """WRITE — upgrade a learned technique's grade (common→refined→perfected→
    transcendent→celestial). Mirrors `_handle_grade_upgrade` chat handler.

    Body: `{ tech_id: int }`. Validates min_mastery + spirit stones + scrolls
    + pill (Transcendence Pill for transcendent tier) + tribulation history
    (celestial tier). On success returns the new grade + multiplier so the
    UI can update without a full reload.
    """
    from database.models import (
        PillCatalog,
        PlayerInventory,
        PlayerTechnique,
        TechniqueCatalog,
        Tribulation,
    )
    from core.combat_engine import (
        GRADE_UPGRADE_REQS,
        get_grade_info,
        get_next_grade,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        tech_id = int(payload.get("tech_id"))
    except (TypeError, ValueError):
        return _err("invalid_tech_id", 400)

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        pt = (await session.execute(
            select(PlayerTechnique).where(
                PlayerTechnique.player_id == user_id,
                PlayerTechnique.technique_id == tech_id,
            )
        )).scalar_one_or_none()
        if not pt:
            return _json({"ok": False, "reason": "not_learned"}, status=200)

        tech = (await session.execute(
            select(TechniqueCatalog).where(TechniqueCatalog.id == tech_id)
        )).scalar_one_or_none()
        if not tech:
            return _json({"ok": False, "reason": "tech_not_found"}, status=200)

        next_g = get_next_grade(pt.grade)
        if not next_g:
            return _json({"ok": False, "reason": "max_grade"}, status=200)

        reqs = GRADE_UPGRADE_REQS.get(next_g) or {}
        if int(pt.mastery_level or 1) < int(reqs.get("min_mastery", 1)):
            return _json({
                "ok": False, "reason": "mastery_too_low",
                "required_mastery": int(reqs.get("min_mastery", 1)),
                "current_mastery": int(pt.mastery_level or 1),
            }, status=200)

        stones_cost = int(reqs.get("stones", 0))
        if stones_cost > 0 and int(player.spirit_stones or 0) < stones_cost:
            return _json({
                "ok": False, "reason": "insufficient_stones",
                "cost": stones_cost, "have": int(player.spirit_stones or 0),
            }, status=200)

        # TEC-2 — sob escassez o custo em pergaminhos é dividido (Lei §1: com o
        # faucet cortado, 10 duplicatas de UMA arte seriam inalcançáveis e o
        # refino de grau viraria conteúdo morto). Flag OFF ⇒ o custo original.
        from core.scroll_economy_engine import grade_scroll_cost
        scroll_cost = grade_scroll_cost(int(reqs.get("scrolls", 0)))
        scroll_inv = None
        if scroll_cost > 0:
            scroll_inv = (await session.execute(
                select(PlayerInventory).where(
                    PlayerInventory.player_id == user_id,
                    PlayerInventory.item_type == "technique_scroll",
                    PlayerInventory.item_id == tech_id,
                    PlayerInventory.quantity >= scroll_cost,
                )
            )).scalar_one_or_none()
            if not scroll_inv:
                return _json({
                    "ok": False, "reason": "insufficient_scrolls",
                    "cost": scroll_cost,
                }, status=200)

        pill_inv = None
        pill_name = reqs.get("pill")
        if pill_name:
            pill_cat = (await session.execute(
                select(PillCatalog).where(PillCatalog.name == pill_name)
            )).scalar_one_or_none()
            if pill_cat:
                pill_inv = (await session.execute(
                    select(PlayerInventory).where(
                        PlayerInventory.player_id == user_id,
                        PlayerInventory.item_type == "pill",
                        PlayerInventory.item_id == pill_cat.id,
                        PlayerInventory.quantity > 0,
                    )
                )).scalar_one_or_none()
            if not pill_inv:
                return _json({
                    "ok": False, "reason": "missing_pill",
                    "pill": pill_name,
                }, status=200)

        if reqs.get("requires_tribulation"):
            # ⚠️ A regra "passou a tribulacao" tem UM dono: a PERFEITA conta
            # (ate' 30/09 aqui so' 'success' contava — quem teve a perfeita era
            # recusado; o chat rebentava; o passe aceitava as duas).
            from core.tribulation_engine import tribulation_passed_clause
            trib = (await session.execute(
                select(Tribulation.id).where(
                    tribulation_passed_clause(user_id),
                ).limit(1)
            )).scalar_one_or_none()
            if not trib:
                return _json({"ok": False, "reason": "needs_tribulation"}, status=200)

        # Deduct costs.
        if stones_cost > 0:
            player.spirit_stones = int(player.spirit_stones or 0) - stones_cost
        if scroll_cost > 0 and scroll_inv:
            scroll_inv.quantity = int(scroll_inv.quantity or 0) - scroll_cost
            if scroll_inv.quantity <= 0:
                await session.delete(scroll_inv)
        if pill_inv:
            pill_inv.quantity = int(pill_inv.quantity or 0) - 1
            if pill_inv.quantity <= 0:
                await session.delete(pill_inv)

        old_g = pt.grade
        pt.grade = next_g
        await session.commit()

    info = get_grade_info(next_g)
    # QoL-Feedback 2026-07-29 Item B (Lei §10): o resultado diz o grau
    # antes→depois, não só o novo.
    old_info = get_grade_info(old_g)
    from core.i18n import catalog_text as _cat_t
    return _json({
        "ok": True,
        "tech_id": int(tech_id),
        "name": _cat_t((player.language or "pt").lower(), "tech", int(tech_id), "name", tech.name),
        "emoji": tech.emoji or "⚔️",
        "old_grade": old_g,
        "old_grade_emoji": old_info["emoji"],
        "old_grade_mult": old_info["mult"],
        "new_grade": next_g,
        "new_grade_emoji": info["emoji"],
        "new_grade_mult": info["mult"],
        "delta": {"spirit_stones": int(player.spirit_stones or 0)},
    })


async def api_combat_absorb_scroll(request: web.Request) -> web.Response:
    """WRITE — absorb a single (or all) scrolls of a known technique to gain
    mastery XP. Mirrors `_handle_absorb_scroll` + `_handle_absorb_all_scrolls`.

    Body: `{ tech_id: int, all: bool }`. When `all=true` consumes the entire
    stack in one round-trip.
    """
    from database.models import (
        PlayerInventory,
        PlayerTechnique,
        TechniqueCatalog,
    )
    from core.combat_engine import MASTERY_STAGES

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        tech_id = int(payload.get("tech_id"))
    except (TypeError, ValueError):
        return _err("invalid_tech_id", 400)
    consume_all = bool(payload.get("all", False))

    _absorb_xp_table = {0: 50, 1: 50, 2: 100, 3: 100, 4: 200, 5: 200, 6: 400, 7: 400}

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        pt = (await session.execute(
            select(PlayerTechnique).where(
                PlayerTechnique.player_id == user_id,
                PlayerTechnique.technique_id == tech_id,
            )
        )).scalar_one_or_none()
        if not pt:
            return _json({"ok": False, "reason": "not_learned"}, status=200)

        scroll = (await session.execute(
            select(PlayerInventory).where(
                PlayerInventory.player_id == user_id,
                PlayerInventory.item_type == "technique_scroll",
                PlayerInventory.item_id == tech_id,
                PlayerInventory.quantity > 0,
            )
        )).scalar_one_or_none()
        if not scroll:
            return _json({"ok": False, "reason": "no_scroll"}, status=200)

        tech = (await session.execute(
            select(TechniqueCatalog).where(TechniqueCatalog.id == tech_id)
        )).scalar_one_or_none()

        xp_per = int(_absorb_xp_table.get(int(tech.req_realm or 0), 750)) if tech else 50
        consumed = int(scroll.quantity) if consume_all else 1
        consumed = max(0, min(consumed, int(scroll.quantity)))
        if consumed <= 0:
            return _json({"ok": False, "reason": "no_scroll"}, status=200)
        total_xp = xp_per * consumed
        pt.mastery_xp = int(pt.mastery_xp or 0) + total_xp

        levelups: list[dict] = []
        while int(pt.mastery_level or 1) < 5:
            nxt = MASTERY_STAGES.get(int(pt.mastery_level or 1) + 1)
            if nxt and pt.mastery_xp >= nxt["xp_req"]:
                pt.mastery_level = int(pt.mastery_level or 1) + 1
                stage = MASTERY_STAGES[int(pt.mastery_level)]
                levelups.append({
                    "new_level": int(pt.mastery_level),
                    "new_mult": float(stage["mult"]),
                    "new_emoji": stage["emoji"],
                })
            else:
                break

        scroll.quantity = int(scroll.quantity) - consumed
        if scroll.quantity <= 0:
            await session.delete(scroll)

        await session.commit()

    from core.i18n import catalog_text as _cat_t
    return _json({
        "ok": True,
        "tech_id": int(tech_id),
        "name": (_cat_t((player.language or "pt").lower(), "tech", int(tech_id), "name", tech.name)
                 if tech else f"#{tech_id}"),
        "emoji": (tech.emoji if tech else "📜") or "📜",
        "consumed": int(consumed),
        "xp_gained": int(total_xp),
        "new_mastery_level": int(pt.mastery_level or 1),
        "new_mastery_xp": int(pt.mastery_xp or 0),
        "levelups": levelups,
    })


# ── PvP Duels (Sprint v14.9 round 3 — MA-35 PvP) ──────────────────────────────
# Owner request 2026-05-20: real PvP duels via mini-app. Flow:
#   1. Player A inputs Player B's dao_name + optional wager → POST challenge_create
#   2. Server creates PVPChallenge row (status=pending, expires_at=now+5min)
#   3. Player B's notif inbox bell shows the incoming challenge (via notif_inbox)
#   4. Player B opens ChallengeInboxModal → Accept / Decline
#      - Accept: server runs simulate_combat (engine reuse), persists rounds,
#        applies stats / mastery XP / arena ELO if applicable, returns result
#      - Decline: status='declined', no fight
#   5. Player A can Cancel any time before expiration
#   6. After 5min the row is filtered out by expires_at > now (no scheduler)
#
# Storage: new pvp_challenges table (migration 087). Chat handler uses
# context.bot_data dict; mini-app needs persistence + cross-process access.

PVP_CHALLENGE_TTL_SECONDS = 300  # 5 minutes
PVP_REALM_GAP = 3                # mirror REALM_HIERARCHY_GAP from handlers/combat


async def _serialize_pvp_challenge(session, row, player_self_id: int) -> dict:
    """Project a PVPChallenge row to JSON for the inbox modal."""
    challenger = (await session.execute(
        select(Player.dao_name, Player.realm, Player.sub_layer)
        .where(Player.telegram_id == row.challenger_id)
    )).first()
    target = (await session.execute(
        select(Player.dao_name, Player.realm, Player.sub_layer)
        .where(Player.telegram_id == row.target_id)
    )).first()
    expires_ms = _ms(row.expires_at) or 0
    challenger_realm = int(challenger[1] or 0) if challenger else 0
    target_realm = int(target[1] or 0) if target else 0

    is_outgoing = (row.challenger_id == player_self_id)
    my_seen_at = row.challenger_seen_at if is_outgoing else row.target_seen_at
    you_won = (row.winner_id is not None and row.winner_id == player_self_id)
    is_draw = (row.status == "completed" and row.winner_id is None)

    return {
        "id": str(row.id),
        "wager": int(row.wager or 0),
        "status": row.status,
        "expires_at_ms": expires_ms,
        "created_at_ms": _ms(row.created_at),
        "resolved_at_ms": _ms(row.resolved_at),
        "is_outgoing": is_outgoing,
        "challenger_id": int(row.challenger_id),
        "target_id": int(row.target_id),
        "challenger_dao_name": challenger[0] if challenger else "???",
        "challenger_realm": challenger_realm,
        "challenger_realm_emoji": REALM_EMOJIS[challenger_realm] if 0 <= challenger_realm < len(REALM_EMOJIS) else "🪨",
        "challenger_sub_layer": int(challenger[2] or 1) if challenger else 1,
        "target_dao_name": target[0] if target else "???",
        "target_realm": target_realm,
        "target_realm_emoji": REALM_EMOJIS[target_realm] if 0 <= target_realm < len(REALM_EMOJIS) else "🪨",
        "target_sub_layer": int(target[2] or 1) if target else 1,
        # Resolution / outcome fields (null while pending)
        "winner_id": int(row.winner_id) if row.winner_id else None,
        "you_won": you_won,
        "is_draw": is_draw,
        "seen_by_me": my_seen_at is not None,
        "seen_at_ms": _ms(my_seen_at),
    }


async def api_combat_challenge_create(request: web.Request) -> web.Response:
    """WRITE — create a pending PvP challenge by dao_name.

    Body: `{ target_dao_name: str, wager: int }`. Validates target exists +
    not shadow_mode + realm gap < 3 + wager funds (challenger can afford,
    capped at 50% of stones). Creates row with TTL = 5min. Idempotent vs
    duplicate outstanding pending challenges (returns existing).
    """
    from datetime import timedelta as _td
    from database.models import PVPChallenge

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_name = payload.get("target_dao_name")
    if not isinstance(raw_name, str) or not raw_name.strip():
        return _err("invalid_dao_name", 400)
    target_name = raw_name.strip()
    try:
        wager = max(0, int(payload.get("wager") or 0))
    except (TypeError, ValueError):
        return _err("invalid_wager", 400)

    async with get_session_factory()() as session:
        challenger = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not challenger:
            return _err("player_not_found", 404)

        # Lookup target by dao_name (case-insensitive). Filter shadow_mode.
        target = (await session.execute(
            select(Player)
            .where(
                func.lower(Player.dao_name) == target_name.lower(),
                Player.shadow_mode == False,  # noqa: E712
            )
        )).scalar_one_or_none()
        if not target:
            return _json({"ok": False, "reason": "target_not_found"}, status=200)
        if target.telegram_id == user_id:
            return _json({"ok": False, "reason": "cannot_self_challenge"}, status=200)

        # Hotfix "A Volta" 2026-07-07 (#12) — Selo de Supressão: conta selada
        # não INICIA nem RECEBE desafios (shadow_mode só cobria o alvo).
        from core.combat_engine import is_pvp_sealed
        if await is_pvp_sealed(session, user_id) or await is_pvp_sealed(session, target.telegram_id):
            return _json({"ok": False, "reason": "pvp_sealed"}, status=200)

        if abs(int(challenger.realm or 0) - int(target.realm or 0)) >= PVP_REALM_GAP:
            return _json({"ok": False, "reason": "realm_gap_too_large",
                          "max_gap": PVP_REALM_GAP}, status=200)

        if wager > 0:
            max_w_self = int((challenger.spirit_stones or 0) * 0.5)
            max_w_target = int((target.spirit_stones or 0) * 0.5)
            if (challenger.spirit_stones or 0) < wager:
                return _json({"ok": False, "reason": "wager_no_funds_self"}, status=200)
            if wager > max_w_self:
                return _json({"ok": False, "reason": "wager_over_self_cap",
                              "cap": int(max_w_self)}, status=200)
            if (target.spirit_stones or 0) < wager:
                return _json({"ok": False, "reason": "wager_no_funds_target"}, status=200)
            if wager > max_w_target:
                return _json({"ok": False, "reason": "wager_over_target_cap"}, status=200)

        now_utc = datetime.now(timezone.utc)
        # Idempotent: if there's already a pending challenge from me to this
        # target, return it (don't create a duplicate).
        existing = (await session.execute(
            select(PVPChallenge).where(
                PVPChallenge.challenger_id == user_id,
                PVPChallenge.target_id == target.telegram_id,
                PVPChallenge.status == "pending",
                PVPChallenge.expires_at > now_utc,
            ).limit(1)
        )).scalar_one_or_none()
        if existing:
            return _json({
                "ok": True, "duplicate": True,
                "challenge": await _serialize_pvp_challenge(session, existing, user_id),
            })

        ch = PVPChallenge(
            challenger_id=user_id,
            target_id=target.telegram_id,
            wager=int(wager),
            status="pending",
            created_at=now_utc,
            expires_at=now_utc + _td(seconds=PVP_CHALLENGE_TTL_SECONDS),
        )
        session.add(ch)
        await session.flush()
        await session.commit()

        return _json({
            "ok": True,
            "challenge": await _serialize_pvp_challenge(session, ch, user_id),
        })


async def api_combat_challenge_inbox(request: web.Request) -> web.Response:
    """READ — pending PvP challenges (incoming + outgoing) + resolved history
    + unseen outcomes for auto-modal-open on the challenger side.

    Auto-marks expired pending rows as 'expired' on read.
    Returns:
      - `incoming` / `outgoing`: pending lists (current behavior)
      - `resolved`: last 10 resolved (24h window) where I'm involved
      - `unseen_outcomes`: subset of resolved completed where my seen flag
        is null AND opponent already marked seen (i.e., already shown to
        them) — UI auto-opens CombatResultModal with these rows.
    """
    from datetime import timedelta as _td
    from database.models import PVPChallenge

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        now_utc = datetime.now(timezone.utc)

        # Sweep: mark stale pending rows as expired (cheap on-read cleanup).
        stale_rows = (await session.execute(
            select(PVPChallenge).where(
                PVPChallenge.status == "pending",
                PVPChallenge.expires_at <= now_utc,
                ((PVPChallenge.challenger_id == user_id) | (PVPChallenge.target_id == user_id)),
            )
        )).scalars().all()
        for r in stale_rows:
            r.status = "expired"
            r.resolved_at = now_utc
        if stale_rows:
            await session.flush()

        incoming_rows = (await session.execute(
            select(PVPChallenge)
            .where(
                PVPChallenge.target_id == user_id,
                PVPChallenge.status == "pending",
                PVPChallenge.expires_at > now_utc,
            )
            .order_by(desc(PVPChallenge.created_at))
            .limit(20)
        )).scalars().all()

        outgoing_rows = (await session.execute(
            select(PVPChallenge)
            .where(
                PVPChallenge.challenger_id == user_id,
                PVPChallenge.status == "pending",
                PVPChallenge.expires_at > now_utc,
            )
            .order_by(desc(PVPChallenge.created_at))
            .limit(20)
        )).scalars().all()

        # Resolved history — 24h window.
        history_cutoff = now_utc - _td(hours=24)
        resolved_rows = (await session.execute(
            select(PVPChallenge)
            .where(
                ((PVPChallenge.challenger_id == user_id) | (PVPChallenge.target_id == user_id)),
                PVPChallenge.status.in_(["completed", "declined", "cancelled", "expired"]),
                PVPChallenge.resolved_at >= history_cutoff,
            )
            .order_by(desc(PVPChallenge.resolved_at))
            .limit(10)
        )).scalars().all()

        await session.commit()

        incoming = [await _serialize_pvp_challenge(session, r, user_id) for r in incoming_rows]
        outgoing = [await _serialize_pvp_challenge(session, r, user_id) for r in outgoing_rows]
        resolved: list[dict] = []
        unseen_outcomes: list[dict] = []
        for r in resolved_rows:
            entry = await _serialize_pvp_challenge(session, r, user_id)
            resolved.append(entry)
            # Unseen completed outcomes get a richer payload with rounds — UI
            # uses these to auto-open CombatResultModal. v15.1.3: turn-based
            # duels live in DuelArenaModal (their rounds_data has a different
            # shape — action_log entries with side a/b dicts), so skip them
            # here to avoid feeding malformed rounds to the legacy result UI.
            is_turn_based = bool((r.rounds_data or {}).get("turn_based")) if r.rounds_data else False
            if r.status == "completed" and not entry["seen_by_me"] and not is_turn_based:
                rounds = (r.rounds_data or {}).get("rounds", []) if r.rounds_data else []
                opponent_dao = (entry["target_dao_name"] if entry["is_outgoing"]
                                else entry["challenger_dao_name"])
                opponent_realm = (entry["target_realm"] if entry["is_outgoing"]
                                  else entry["challenger_realm"])
                # Round 5: derive max-HP per side from the first round's
                # `attacker_hp` + max(rnd.attacker_hp + sum_damage_taken)
                # cheap reconstruction. Better: the first round's hp_round_start
                # values would be perfect but simulate_combat doesn't persist
                # them. Use the highest hp value seen across rounds as upper
                # bound (fight only goes down). If no rounds, default to 1.
                atk_max = 1
                def_max = 1
                for rnd in rounds:
                    if "attacker_hp" in rnd and rnd["attacker_hp"] > atk_max:
                        atk_max = rnd["attacker_hp"]
                    if "defender_hp" in rnd and rnd["defender_hp"] > def_max:
                        def_max = rnd["defender_hp"]
                # If a side died first round we don't see their max — fall
                # back to ~120% of the highest damage seen against them so
                # the bar visualisation still looks reasonable.
                for rnd in rounds:
                    for ev in (rnd.get("events") or []):
                        if ev.get("type") in ("attack", "pet_attack", "stalemate_break"):
                            who = ev.get("who")
                            dmg = int(ev.get("damage", 0))
                            if who == "attacker":
                                # damages defender
                                def_max = max(def_max, dmg * 2)
                            elif who == "defender":
                                atk_max = max(atk_max, dmg * 2)
                unseen_outcomes.append({
                    "challenge_id": entry["id"],
                    "is_outgoing": entry["is_outgoing"],
                    "you_won": entry["you_won"],
                    "is_draw": entry["is_draw"],
                    "wager": entry["wager"],
                    "opponent_dao_name": opponent_dao,
                    "opponent_realm": opponent_realm,
                    "rounds": rounds,
                    "total_rounds": len(rounds),
                    "attacker_max_hp": int(atk_max),
                    "defender_max_hp": int(def_max),
                    # `viewer_is_attacker` lets renderCombatEvent pick the
                    # right side label. simulate_combat ran with attacker=
                    # challenger, defender=target. So:
                    #   - challenger viewer (is_outgoing=true): viewer = attacker
                    #   - target viewer (is_outgoing=false): viewer = defender
                    "viewer_is_attacker": entry["is_outgoing"],
                    "winner": ("attacker" if r.winner_id == r.challenger_id
                               else ("defender" if r.winner_id == r.target_id else "draw")),
                })

        return _json({
            "incoming": incoming,
            "outgoing": outgoing,
            "resolved": resolved,
            "unseen_outcomes": unseen_outcomes,
            "incoming_count": len(incoming),
            "outgoing_count": len(outgoing),
            "unseen_count": len(unseen_outcomes),
            "ttl_seconds": PVP_CHALLENGE_TTL_SECONDS,
        })


async def api_combat_challenge_mark_seen(request: web.Request) -> web.Response:
    """WRITE — mark a resolved challenge as seen by the calling player.

    Body: `{ challenge_id: str }`. Idempotent — safe to call repeatedly.
    Used by the UI after the auto-opened result modal closes, and when the
    Histórico segment is opened (mark-all-seen for incoming list).
    """
    import uuid as _uuid
    from database.models import PVPChallenge

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    cid_raw = payload.get("challenge_id")
    try:
        cid = _uuid.UUID(str(cid_raw))
    except (ValueError, TypeError, AttributeError):
        return _err("invalid_challenge_id", 400)

    async with get_session_factory()() as session:
        ch = (await session.execute(
            select(PVPChallenge).where(PVPChallenge.id == cid)
        )).scalar_one_or_none()
        if not ch:
            return _json({"ok": False, "reason": "not_found"}, status=200)
        if ch.challenger_id != user_id and ch.target_id != user_id:
            return _json({"ok": False, "reason": "not_authorized"}, status=200)

        now_utc = datetime.now(timezone.utc)
        if ch.challenger_id == user_id and ch.challenger_seen_at is None:
            ch.challenger_seen_at = now_utc
        if ch.target_id == user_id and ch.target_seen_at is None:
            ch.target_seen_at = now_utc
        await session.commit()

    return _json({"ok": True, "challenge_id": str(cid)})


async def api_combat_challenge_respond(request: web.Request) -> web.Response:
    """WRITE — accept/decline/cancel a PvP challenge.

    Body: `{ challenge_id: str, action: "accept"|"decline"|"cancel" }`.

    On accept: locks both Player rows FOR UPDATE, re-validates wager funds,
    reuses `simulate_combat` + `_build_fighter` shape (artifacts + active
    techniques + buffs), applies side effects identical to chat handler
    `_handle_accept`: spirit_stones reward, mastery XP, arena ELO change
    when applicable (mode='arena' for now stays sparring — we set `mode`
    based on whether wager is set), CombatLog row, HP drain 30%, quest
    tracking, faction quest, body tempering, achievements check.

    Returns the same `result` shape as duel_npc so the UI can reuse
    CombatResultModal. PvP challenges always run as "sparring" mode for
    spirit_stones reward calculation; arena ELO changes stay scoped to
    the live queue (chat-side `/arena queue` flow) — NOT mini-app.
    """
    import uuid as _uuid
    from database.models import (
        ArenaRanking,
        CombatLog,
        PlayerArtifact,
        PlayerTechnique,
        PVPChallenge,
        TechniqueCatalog,
    )
    from core.combat_engine import (
        MASTERY_STAGES,
        apply_hp_drain,
        build_fighter_data,
        get_combat_buff_mults,
        get_current_hp,
        get_max_hp,
        simulate_combat,
    )

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    cid_raw = payload.get("challenge_id")
    action = str(payload.get("action") or "").lower()
    if action not in ("accept", "decline", "cancel"):
        return _err("invalid_action", 400)
    try:
        cid = _uuid.UUID(str(cid_raw))
    except (ValueError, TypeError, AttributeError):
        return _err("invalid_challenge_id", 400)

    async with get_session_factory()() as session:
        ch = (await session.execute(
            select(PVPChallenge).where(PVPChallenge.id == cid).with_for_update()
        )).scalar_one_or_none()
        if not ch:
            return _json({"ok": False, "reason": "not_found"}, status=200)

        now_utc = datetime.now(timezone.utc)
        if ch.status != "pending":
            return _json({"ok": False, "reason": "not_pending",
                          "current_status": ch.status}, status=200)
        if ch.expires_at <= now_utc:
            ch.status = "expired"
            ch.resolved_at = now_utc
            await session.commit()
            return _json({"ok": False, "reason": "expired"}, status=200)

        # Authorization: only target can accept/decline; only challenger can cancel.
        # Auto-mark seen for the actor — they obviously know the outcome.
        if action == "cancel":
            if ch.challenger_id != user_id:
                return _json({"ok": False, "reason": "not_authorized"}, status=200)
            ch.status = "cancelled"
            ch.resolved_at = now_utc
            ch.challenger_seen_at = now_utc
            await session.commit()
            return _json({"ok": True, "action": "cancel", "challenge_id": str(ch.id)})

        if action == "decline":
            if ch.target_id != user_id:
                return _json({"ok": False, "reason": "not_authorized"}, status=200)
            ch.status = "declined"
            ch.resolved_at = now_utc
            ch.target_seen_at = now_utc
            await session.commit()
            return _json({"ok": True, "action": "decline", "challenge_id": str(ch.id)})

        # ── accept: spawn turn-based duel (v15.1.3) ──────────────────────
        # The legacy instant `simulate_combat` resolve is replaced by a
        # DuelSession that the mini-app drives via DuelArenaModal. Wager
        # stays escrowed on PVPChallenge; settle_pvp_duel pays out + applies
        # side-effects on the duel's terminal state.
        if ch.target_id != user_id:
            return _json({"ok": False, "reason": "not_authorized"}, status=200)

        # Lock both player rows.
        players_rows = (await session.execute(
            select(Player).where(
                Player.telegram_id.in_([ch.challenger_id, ch.target_id])
            ).with_for_update()
        )).scalars().all()
        pmap = {p.telegram_id: p for p in players_rows}
        challenger = pmap.get(ch.challenger_id)
        target = pmap.get(ch.target_id)
        if not challenger or not target:
            return _json({"ok": False, "reason": "player_not_found"}, status=200)

        # HP gate: reject if target HP zero.
        if get_current_hp(target) <= 0:
            return _json({"ok": False, "reason": "hp_depleted"}, status=200)
        if get_current_hp(challenger) <= 0:
            ch.status = "cancelled"
            ch.resolved_at = now_utc
            await session.commit()
            return _json({"ok": False, "reason": "challenger_hp_depleted"}, status=200)

        # Hotfix "A Volta" 2026-07-07 (#12) — Selo de Supressão: re-check
        # defensivo no accept (o selo pode ter sido aplicado após o create).
        from core.combat_engine import is_pvp_sealed as _is_sealed
        if await _is_sealed(session, challenger.telegram_id) or await _is_sealed(session, target.telegram_id):
            ch.status = "cancelled"
            ch.resolved_at = now_utc
            await session.commit()
            return _json({"ok": False, "reason": "pvp_sealed"}, status=200)

        # Re-validate wager (challenger's stones may have dropped since).
        wager = int(ch.wager or 0)
        if wager > 0:
            if (challenger.spirit_stones or 0) < wager:
                ch.status = "cancelled"
                ch.resolved_at = now_utc
                await session.commit()
                return _json({"ok": False, "reason": "wager_no_funds_challenger"}, status=200)
            if (target.spirit_stones or 0) < wager:
                return _json({"ok": False, "reason": "wager_no_funds_self"}, status=200)
            # Escrow — pool is held until settle_pvp_duel pays it out.
            challenger.spirit_stones = int(challenger.spirit_stones or 0) - wager
            target.spirit_stones = int(target.spirit_stones or 0) - wager

        # Block if either side is already in another open duel (concurrency
        # safety — prevents double-duel from a stale challenge accept).
        from sqlalchemy import or_ as _or
        from core.duel_engine import start_duel as _start_duel
        from database.models import DuelSession as _DS

        active = (await session.execute(
            select(_DS).where(
                _or(
                    _DS.attacker_id.in_([challenger.telegram_id, target.telegram_id]),
                    _DS.defender_id.in_([challenger.telegram_id, target.telegram_id]),
                ),
                _DS.state.in_(["waiting_actions", "pending_acceptance"]),
            ).limit(1)
        )).scalar_one_or_none()
        if active is not None:
            # Refund wager — we don't proceed with the accept.
            if wager > 0:
                challenger.spirit_stones = int(challenger.spirit_stones or 0) + wager
                target.spirit_stones = int(target.spirit_stones or 0) + wager
            await session.commit()
            return _json({"ok": False, "reason": "duel_already_active",
                          "duel_id": str(active.id)}, status=200)

        # Spawn the duel. start_duel sets state='pending_acceptance' by
        # default; here both players have already consented (challenger
        # sent it, target just accepted), so we auto-promote to live.
        duel = await _start_duel(session, challenger, target)
        duel.state = "waiting_actions"
        from datetime import timedelta as _td
        from core.duel_engine import ROUND_TIMEOUT_SECONDS as _ROUND_TO
        duel.expires_at = now_utc + _td(seconds=_ROUND_TO)
        duel.action_log = (duel.action_log or []) + [{
            "round": 0,
            "type": "accepted",
            "source": "pvp_challenge",
            "accepted_by": user_id,
        }]

        # Link both directions for the settle path.
        ch.duel_id = duel.id
        ch.status = "accepted"
        ch.target_seen_at = now_utc

        await session.commit()

        # Build response — UI uses redirect_to_duel to switch from the
        # PvP Inbox (CombatArenaPanel) to the DuelArenaModal directly.
        return _json({
            "ok": True,
            "action": "accept",
            "challenge_id": str(ch.id),
            "duel_id": str(duel.id),
            "redirect_to_duel": True,
            "wager": int(wager),
            "is_pvp": True,
            "opponent_dao_name": challenger.dao_name or challenger.display_name or "?",
            "opponent_realm": int(challenger.realm or 0),
        })


# ─── v15.1 Turn-Based Duel endpoints (qi consumption, simultaneous rounds) ──

async def api_combat_duel_create(request: web.Request) -> web.Response:
    """WRITE — create a turn-based duel between two players.

    Body: `{ target_dao_name: str }`. Validates target exists, realm gap < 3,
    both alive (HP>0), neither already in an active duel. Creates a
    DuelSession with state='waiting_actions', round 1. Both players poll
    `duel_state` to see HP/Qi bars + submit actions via `duel_submit`.
    """
    from sqlalchemy import or_
    from core.duel_engine import start_duel
    from core.combat_engine import get_current_hp
    from database.models import DuelSession

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_name = payload.get("target_dao_name")
    if not isinstance(raw_name, str) or not raw_name.strip():
        return _err("invalid_dao_name", 400)
    target_name = raw_name.strip()

    try:
        async with get_session_factory()() as session:
            attacker = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not attacker:
                return _err("player_not_found", 404)

            target = (await session.execute(
                select(Player).where(
                    func.lower(Player.dao_name) == target_name.lower(),
                    Player.shadow_mode == False,  # noqa: E712
                ).with_for_update()
            )).scalar_one_or_none()
            if not target:
                return _json({"ok": False, "reason": "target_not_found"})
            if target.telegram_id == user_id:
                return _json({"ok": False, "reason": "cannot_self_challenge"})

            if abs(int(attacker.realm or 0) - int(target.realm or 0)) >= PVP_REALM_GAP:
                return _json({"ok": False, "reason": "realm_gap_too_large", "max_gap": PVP_REALM_GAP})

            # Hotfix "A Volta" 2026-07-07 (#12) — Selo de Supressão: conta
            # selada não inicia nem recebe duelos diretos.
            from core.combat_engine import is_pvp_sealed
            if await is_pvp_sealed(session, user_id) or await is_pvp_sealed(session, target.telegram_id):
                return _json({"ok": False, "reason": "pvp_sealed"})

            if get_current_hp(attacker) <= 0:
                return _json({"ok": False, "reason": "hp_depleted"})
            if get_current_hp(target) <= 0:
                return _json({"ok": False, "reason": "target_hp_depleted"})

            # Block if either side already has an open duel
            # (pending acceptance counts — can't double-challenge).
            active = (await session.execute(
                select(DuelSession).where(
                    or_(
                        DuelSession.attacker_id.in_([user_id, target.telegram_id]),
                        DuelSession.defender_id.in_([user_id, target.telegram_id]),
                    ),
                    DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
                ).limit(1)
            )).scalar_one_or_none()
            # v16.2.2 hotfix — resolve expired duels first (mesmo padrão
            # do boss + npc_duel_create). Stale rows whose `expires_at`
            # is past lock the player out of new challenges indefinitely.
            if active is not None:
                try:
                    from core.duel_engine import check_and_handle_timeout
                    changed = await check_and_handle_timeout(session, active)
                except Exception:
                    logger.exception("check_and_handle_timeout failed for duel=%s", active.id)
                    changed = False
                if changed:
                    await session.flush()
                    active = (await session.execute(
                        select(DuelSession).where(
                            or_(
                                DuelSession.attacker_id.in_([user_id, target.telegram_id]),
                                DuelSession.defender_id.in_([user_id, target.telegram_id]),
                            ),
                            DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
                        ).limit(1)
                    )).scalar_one_or_none()
            if active is not None:
                return _json({"ok": False, "reason": "duel_already_active", "duel_id": str(active.id)})

            duel = await start_duel(session, attacker, target)
            await session.commit()
            return _json({"ok": True, "duel_id": str(duel.id)})
    except Exception as e:
        logger.exception("combat/duel_create failed for user_id=%s target=%s", user_id, target_name)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_combat_npc_duel_create(request: web.Request) -> web.Response:
    """WRITE — v15.1.4 — create a turn-based PvE duel against an NPC archetype.

    Body: `{ difficulty: "easy"|"normal"|"hard"|"nightmare",
             archetype?: "bandit"|"sect_disciple"|"beast"|"demon"|"boss" }`.

    Replaces the instant `combat/duel_npc` path for the mini-app NPC Hunt
    flow. `combat/duel_npc` stays available for chat handlers + legacy
    use (engine-reuse preservation). Reuses `start_duel_pve` — defender_id
    is NULL, duel.state starts at 'waiting_actions' immediately (no
    acceptance step; there's no human defender).

    Validation mirrors `api_combat_duel_npc`: cooldown (30 min between
    NPC fights), HP gate, qi gate, meditation gate. The qi cost from
    NPC_DIFFICULTIES is consumed on duel creation (mirror of legacy);
    the duel's Combat Pool (combat_qi_a/b) is separate from this.

    v15.1.5 hotfix: wrapped in try/except so any engine failure (e.g. the
    Tang BP-overflow class of bugs) returns a JSON 500 instead of a raw
    HTTP 500 — the mini-app surfaces an actionable error toast.
    """
    from core.combat_engine import NPC_DIFFICULTIES, get_current_hp
    from core.duel_engine import start_duel_pve
    from core.npc_loadouts import NPC_ARCHETYPES
    from database.models import DuelSession, PlayerNPCCooldown
    from sqlalchemy import or_

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    diff = str(payload.get("difficulty") or "").lower()
    archetype_raw = payload.get("archetype")

    if diff not in NPC_DIFFICULTIES:
        return _err("invalid_difficulty", 400)

    # Resolve archetype: explicit override (must be valid) or derive
    # from player realm tier.
    if archetype_raw:
        archetype = str(archetype_raw).lower()
        if archetype not in NPC_ARCHETYPES:
            return _err("invalid_archetype", 400)
    else:
        archetype = None  # filled below from realm

    try:
      async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        # Realm-tier archetype derivation when not explicitly chosen.
        if archetype is None:
            r = int(player.realm or 0)
            if r >= 7:
                archetype = "boss"
            elif r >= 5:
                archetype = "demon"
            elif r >= 3:
                archetype = "sect_disciple"
            else:
                archetype = "bandit"

        if get_current_hp(player) <= 0:
            return _json({"ok": False, "reason": "hp_depleted"}, status=200)

        # NPC fight cooldown (shared with legacy /duel_npc — same row).
        cd = (await session.execute(
            select(PlayerNPCCooldown).where(PlayerNPCCooldown.player_id == user_id)
        )).scalar_one_or_none()
        now = datetime.now(timezone.utc)
        if cd:
            if cd.last_reset_date != now.date():
                cd.fights_today = 0
                cd.last_reset_date = now.date()
            if cd.last_npc_fight:
                last = cd.last_npc_fight
                if last.tzinfo is None:
                    last = last.replace(tzinfo=timezone.utc)
                elapsed = (now - last).total_seconds()
                if elapsed < 1800:
                    return _json({
                        "ok": False, "reason": "cooldown",
                        "remaining_seconds": int(1800 - elapsed),
                    }, status=200)
        else:
            cd = PlayerNPCCooldown(
                player_id=user_id,
                fights_today=0,
                last_reset_date=now.date(),
            )
            session.add(cd)

        # Qi gate (NPC_DIFFICULTIES.qi_cost — same as legacy).
        diff_data = NPC_DIFFICULTIES[diff]
        qi_cost = int(diff_data["qi_cost"])
        if float(player.qi or 0) < qi_cost:
            return _json({
                "ok": False, "reason": "qi_insufficient",
                "qi_cost": qi_cost, "qi": float(player.qi or 0),
            }, status=200)

        # Block if already in another open duel (PvP or PvE).
        existing = (await session.execute(
            select(DuelSession).where(
                or_(
                    DuelSession.attacker_id == user_id,
                    DuelSession.defender_id == user_id,
                ),
                DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
            ).limit(1)
        )).scalar_one_or_none()
        # v16.2.2 hotfix (same as boss path) — resolve expired duels before
        # blocking. Stale rows whose `expires_at` is past should not lock
        # the player out of new combat indefinitely.
        if existing is not None:
            try:
                from core.duel_engine import check_and_handle_timeout
                changed = await check_and_handle_timeout(session, existing)
            except Exception:
                logger.exception("check_and_handle_timeout failed for duel=%s", existing.id)
                changed = False
            if changed:
                await session.flush()
                existing = (await session.execute(
                    select(DuelSession).where(
                        or_(
                            DuelSession.attacker_id == user_id,
                            DuelSession.defender_id == user_id,
                        ),
                        DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
                    ).limit(1)
                )).scalar_one_or_none()
        if existing is not None:
            return _json({
                "ok": False, "reason": "duel_already_active",
                "duel_id": str(existing.id),
            }, status=200)

        # Consume qi + tick cooldown atomically with the duel creation.
        player.qi = max(0.0, float(player.qi or 0) - qi_cost)
        cd.last_npc_fight = now
        cd.fights_today = int(cd.fights_today or 0) + 1

        duel = await start_duel_pve(
            session, player,
            archetype=archetype,
            difficulty=diff,
            source="npc_hunt",
            context={"difficulty": diff, "archetype": archetype},
        )
        await session.commit()
        return _json({
            "ok": True,
            "duel_id": str(duel.id),
            "archetype": archetype,
            "difficulty": diff,
            "qi_cost": int(qi_cost),
            "redirect_to_duel": True,
        })
    except Exception as e:
        logger.exception("combat/npc_duel_create failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


