# Onda 3 — NPC Cultivators + Heaven's Whispers endpoints
# ══════════════════════════════════════════════════════════════════════════

async def _merge_npc_leaderboard(session, kind: str, entries: list[dict]) -> list[dict]:
    """Splice anonymized NPC cultivators into a leaderboard (honest is_npc flag),
    re-sort by the kind's key, re-rank 1..N (cap 50). Additive — player rows keep
    their shape (is_npc defaults False)."""
    try:
        from core.npc_cultivator_engine import get_leaderboard_npcs
        npc_rows = await get_leaderboard_npcs(session, kind, limit=50, realm_label=_realm_label)
    except Exception:
        logger.debug("npc leaderboard merge failed", exc_info=True)
        return entries
    if not npc_rows:
        for e in entries:
            e.setdefault("is_npc", False)
        return entries
    for e in entries:
        e.setdefault("is_npc", False)
    combined = list(entries) + npc_rows
    if kind == "power":
        combined.sort(key=lambda e: int(e.get("battle_power", 0) or 0), reverse=True)
    else:  # cultivation
        combined.sort(key=lambda e: (
            int(e.get("prestige", 0) or 0),
            int(e.get("realm", 0) or 0),
            int(e.get("sub_layer", 0) or 0),
            float(e.get("cultivation_base", 0) or 0),
        ), reverse=True)
    combined = combined[:50]
    for i, e in enumerate(combined):
        e["rank"] = i + 1
    return combined


async def _fetch_player_lang(session, user_id: int) -> str:
    try:
        row = (await session.execute(
            select(Player.language).where(Player.telegram_id == user_id)
        )).first()
        lang = (row[0] if row else "pt") or "pt"
        lang = lang.lower()
        return lang if lang in ("pt", "en", "es") else "pt"
    except Exception:
        return "pt"


async def api_combat_npc_cultivator_fight(request: web.Request) -> web.Response:
    """WRITE — Onda 3 — challenge a persistent NPC cultivator (turn-based duel,
    pve_source='npc_cultivator'). Body {npc_id?}; if omitted a FAIR same-tier
    opponent is auto-picked. Uses a SEPARATE cooldown from the NPC-hunt farm."""
    from core.combat_engine import NPC_DIFFICULTIES, get_current_hp
    from core.duel_engine import start_duel_pve, check_and_handle_timeout
    from core.npc_cultivator_engine import (
        cultivator_cooldown_remaining, get_npc_cultivator, pick_encounter_npc,
        project_npc_for_profile, rehydrate_npc_fighter,
    )
    from database.models import DuelSession, PlayerNPCCooldown
    from sqlalchemy import or_

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    npc_id_raw = payload.get("npc_id")
    try:
      async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id).with_for_update()
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        if get_current_hp(player) <= 0:
            return _json({"ok": False, "reason": "hp_depleted"}, status=200)

        now = datetime.now(timezone.utc)
        cd = (await session.execute(
            select(PlayerNPCCooldown).where(PlayerNPCCooldown.player_id == user_id)
        )).scalar_one_or_none()
        if cd:
            remaining = cultivator_cooldown_remaining(cd, now)
            if remaining > 0:
                return _json({"ok": False, "reason": "cooldown", "remaining_seconds": remaining}, status=200)
        else:
            cd = PlayerNPCCooldown(player_id=user_id, fights_today=0, last_reset_date=now.date())
            session.add(cd)

        qi_cost = int(NPC_DIFFICULTIES.get("normal", {}).get("qi_cost", 10))
        if float(player.qi or 0) < qi_cost:
            return _json({"ok": False, "reason": "qi_insufficient",
                          "qi_cost": qi_cost, "qi": float(player.qi or 0)}, status=200)

        # Resolve the opponent (explicit or fair auto-pick).
        if npc_id_raw:
            npc = await get_npc_cultivator(session, int(npc_id_raw))
            if npc is None or npc.status != "active":
                return _json({"ok": False, "reason": "npc_unavailable"}, status=200)
        else:
            npc = await pick_encounter_npc(session, player)
            if npc is None:
                return _json({"ok": False, "reason": "no_opponent"}, status=200)

        # Block if already in an open duel (reuse the stale-resolve pattern).
        existing = (await session.execute(
            select(DuelSession).where(
                or_(DuelSession.attacker_id == user_id, DuelSession.defender_id == user_id),
                DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
            ).limit(1)
        )).scalar_one_or_none()
        if existing is not None:
            try:
                changed = await check_and_handle_timeout(session, existing)
            except Exception:
                logger.exception("check_and_handle_timeout failed for duel=%s", existing.id)
                changed = False
            if changed:
                await session.flush()
                existing = (await session.execute(
                    select(DuelSession).where(
                        or_(DuelSession.attacker_id == user_id, DuelSession.defender_id == user_id),
                        DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
                    ).limit(1)
                )).scalar_one_or_none()
        if existing is not None:
            return _json({"ok": False, "reason": "duel_already_active",
                          "duel_id": str(existing.id)}, status=200)

        lang = (player.language or "pt").lower()
        npc_profile = project_npc_for_profile(
            npc, lang, realm_label=_realm_label, viewer_karma=int(player.karma or 0))
        fb = rehydrate_npc_fighter(npc)

        # MV-6 — O RIVAL bate mais forte (+12%/derrota, cap +60%; strike-only,
        # o MESMO lever do NPC_CULTIVATOR_POWER_SCALE — em cima dele). Aditivo
        # + gated (flag OFF ou NPC ≠ rival → fighter intocado); o taunt
        # pré-duelo ride na resposta (a memória fala antes da espada).
        rival_taunt_line = None
        try:
            if int(getattr(player, "rival_npc_id", 0) or 0) == int(npc.id):
                from core.reputation_engine import (
                    apply_rival_scaling, reputacao_on, rival_taunt)
                state = dict(player.rival_state or {})
                # Presença (review MV-6): a escala/taunt só quando ele ESTÁ
                # aqui (returned/spared) — ausente, é um duelo NPC comum (a
                # janela de volta é o ritmo do arco; o settle usa o MESMO gate).
                if reputacao_on() and (state.get("returned") or state.get("spared")):
                    fb = apply_rival_scaling(fb, state)
                    rival_taunt_line = rival_taunt(state, lang)
        except Exception:
            logger.exception("rival scaling failed npc=%s", npc.id)

        player.qi = max(0.0, float(player.qi or 0) - qi_cost)
        cd.last_cultivator_fight = now
        duel = await start_duel_pve(
            session, player,
            archetype="npc_cultivator", difficulty="normal",
            source="npc_cultivator", context={"npc_id": int(npc.id)},
            fighter_b_override=fb,
        )
        await session.commit()
        return _json({
            "ok": True, "duel_id": str(duel.id), "qi_cost": int(qi_cost),
            "npc": npc_profile, "redirect_to_duel": True,
            **({"rival_taunt": rival_taunt_line} if rival_taunt_line else {}),
        })
    except Exception as e:
        logger.exception("combat/npc_cultivator_fight failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_combat_npc_cultivator_resolve(request: web.Request) -> web.Response:
    """WRITE — Onda 3 — apply the post-duel spare/execute moral choice (karma).
    Body {duel_id, outcome:'spare'|'execute'}. Idempotent per duel."""
    import uuid as _uuid
    from core.npc_cultivator_engine import apply_combat_moral_choice

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    duel_id_raw = payload.get("duel_id")
    outcome = str(payload.get("outcome") or "").lower()
    if not duel_id_raw:
        return _err("missing_duel_id", 400)
    try:
        duel_id = _uuid.UUID(str(duel_id_raw))
    except Exception:
        return _err("invalid_duel_id", 400)
    try:
        async with get_session_factory()() as session:
            result = await apply_combat_moral_choice(session, duel_id, user_id, outcome)
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("combat/npc_cultivator_resolve failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_npc_profile(request: web.Request) -> web.Response:
    """READ — Onda 3 — an honest NPC-cultivator profile (ProfileModal). Track A
    item 3 adds a ``bounty`` disclosure block (Lei §1): whether the viewer may
    post a contract on this (dark-karma) NPC + the rules shown before posting."""
    from core.npc_cultivator_engine import get_npc_cultivator, project_npc_for_profile
    from core.bounty_engine import player_bounty_context
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    npc_id_raw = payload.get("npc_id")
    if not npc_id_raw:
        return _err("missing_npc_id", 400)
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        lang = (player.language or "pt").lower()
        npc = await get_npc_cultivator(session, int(npc_id_raw))
        if npc is None:
            return _json({"ok": False, "reason": "not_found"}, status=200)
        # MV-6 — se ESTE NPC é o rival do viewer, o perfil carrega a memória
        # (taunt + escala honesta). Gated + additive: flag OFF/não-rival →
        # key ausente → payload byte-idêntico.
        rival_block = None
        try:
            if int(getattr(player, "rival_npc_id", 0) or 0) == int(npc.id):
                from core.reputation_engine import (
                    reputacao_on, rival_power_mult, rival_taunt)
                _st = dict(player.rival_state or {})
                # Presença (review MV-6): o banner acompanha o card — só
                # quando returned/spared (ausente = duelo NPC comum).
                if reputacao_on() and (_st.get("returned") or _st.get("spared")):
                    rival_block = {
                        "defeats": int(_st.get("defeats", 1) or 1),
                        "spared": bool(_st.get("spared")),
                        "power_bonus_pct": int(round((rival_power_mult(_st) - 1.0) * 100)),
                        "taunt": rival_taunt(_st, lang),
                    }
        except Exception:
            logger.exception("npc_profile rival block failed")
        return _json({
            "ok": True,
            "npc": project_npc_for_profile(
                npc, lang, realm_label=_realm_label, viewer_karma=int(player.karma or 0)),
            "bounty": await player_bounty_context(session, player, npc),
            **({"rival": rival_block} if rival_block else {}),
        })


async def api_world_npc_list(request: web.Request) -> web.Response:
    """READ — Onda 3 — encounterable NPC cultivators near the player (browse +
    challenge). Realm-windowed, same-continent preferred, capped."""
    from core.npc_cultivator_engine import ENCOUNTER_REALM_WINDOW, project_npc_for_profile
    from database.models import NpcCultivator
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        lang = (player.language or "pt").lower()
        realm = int(player.realm or 0)
        continent = player.current_continent
        rows = (await session.execute(
            select(NpcCultivator).where(
                NpcCultivator.status == "active",
                NpcCultivator.realm >= max(0, realm - ENCOUNTER_REALM_WINDOW),
                NpcCultivator.realm <= realm + ENCOUNTER_REALM_WINDOW,
            ).order_by(NpcCultivator.power.desc()).limit(40)
        )).scalars().all()
        # Prefer same-continent, then by power; cap to a browsable handful.
        rows.sort(key=lambda n: (0 if n.continent_key == continent else 1, -int(n.power or 0)))
        npcs = [project_npc_for_profile(n, lang, realm_label=_realm_label) for n in rows[:12]]
        return _json({"ok": True, "npcs": npcs, "count": len(npcs)})


async def api_world_whispers(request: web.Request) -> web.Response:
    """READ — Onda 3 — Heaven's Whispers feed (recent atmospheric world-events)."""
    from core.heavens_whispers_engine import list_recent_whispers
    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        lang = await _fetch_player_lang(session, user_id)
        whispers = await list_recent_whispers(session, limit=25, lang=lang)
        return _json({"whispers": whispers, "count": len(whispers)})


async def api_world_chronicle(request: web.Request) -> web.Response:
    """READ — World Pulse Fase 1 — the Chronicle (Registos Celestiais 天记).

    The append-only feed of what the world did on its own (sect raids, claims,
    inheritances, recruiting). Body {continent?} scopes the feed to a continent
    (+ global lines); omit for the full world feed. Server-resolved text per the
    reader's language (Lei §1 — the world is legible)."""
    from core.world_pulse_engine import list_recent_chronicle
    user_id: int = request["user_id"]
    try:
        body = await request.json() if request.body_exists else {}
    except Exception:
        body = {}
    continent = body.get("continent") if isinstance(body, dict) else None
    async with get_session_factory()() as session:
        lang = await _fetch_player_lang(session, user_id)
        # MV-8 — a latência de LEITURA: notícia de outro continente só aparece
        # depois de a estrada a trazer. ⚠️ A leitura do continente do viewer vive
        # DENTRO do gate: sem ele, `main` (flag OFF eterna) pagaria uma query
        # nova por abertura da Crônica — "OFF ⇒ zero query" vale para o caminho
        # inteiro, não só para o engine.
        viewer_cont = None
        try:
            from core.jianghu_engine import jianghu_on
            if jianghu_on():
                viewer_cont = (await session.execute(
                    select(Player.current_continent).where(Player.telegram_id == user_id)
                )).scalar()
        except Exception:
            logger.debug("world/chronicle: viewer continent lookup failed", exc_info=True)
        entries = await list_recent_chronicle(session, limit=40, lang=lang,
                                              continent=continent,
                                              viewer_continent=viewer_cont)
        return _json({"chronicle": entries, "count": len(entries)})


async def api_world_sect_population(request: web.Request) -> web.Response:
    """READ — Onda 3 — each house's population (NPC cultivators + real members)."""
    from sqlalchemy import func as _func
    from core.npc_cultivator_engine import count_sect_npc_population
    from core.world_sects_engine import WORLD_SECT_KEYS
    async with get_session_factory()() as session:
        npc_counts = await count_sect_npc_population(session)
        rows = (await session.execute(
            select(Player.sect_id, _func.count())
            .where(Player.sect_id.is_not(None))
            .group_by(Player.sect_id)
        )).all()
        player_counts = {s: int(n) for s, n in rows if s}
        out: dict[str, dict] = {}
        for k in WORLD_SECT_KEYS:
            npc = int(npc_counts.get(k, 0))
            pl = int(player_counts.get(k, 0))
            out[k] = {"npc": npc, "players": pl, "total": npc + pl}
        return _json({"population": out})


# ─── Onda 4a — Continental Plaza (Wànshì) + Bounty Board ─────────────────────

async def api_world_plaza(request: web.Request) -> web.Response:
    """READ — Onda 4a — the player's continental plaza (Wànshì): who's here
    (recently-online non-shadow players of THIS continent + the continent's NPC
    cultivators, bounded, honest 🤖), the continent's whisper feed, and the open
    bounty count. Continent-scoped + bounded — NOT the global ranking (the
    NPC_LEADERBOARD flag stays as the owner set it)."""
    from datetime import timedelta
    from core.continent_engine import CONTINENT_META, is_valid_continent
    from core.heavens_whispers_engine import list_recent_whispers
    from core.bounty_engine import bounty_board_count
    from core.i18n import t as i18n_t
    from database.models import NpcCultivator

    user_id: int = request["user_id"]
    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)
        lang = (player.language or "pt").lower()
        continent = player.current_continent if is_valid_continent(player.current_continent) else "linghe"

        # Presence — real, non-shadow players of this continent, recently online
        # (privacy: shadow_mode players never appear — same filter as the
        # leaderboard/snapshot). Self is excluded. Bounded.
        recent_cut = datetime.now(timezone.utc) - timedelta(days=14)
        prows = (await session.execute(
            select(Player).where(
                Player.shadow_mode == False,  # noqa: E712
                Player.current_continent == continent,
                Player.telegram_id != user_id,
                Player.last_online >= recent_cut,
            ).order_by(Player.last_online.desc()).limit(12)
        )).scalars().all()
        players = []
        for p in prows:
            rname, remoji = _realm_label(int(p.realm or 0))
            nm = p.dao_name  # public on this surface (same as the leaderboard)
            players.append({
                "dao_name": nm,
                "openable": bool(nm and nm != "Cultivator"),
                "realm": int(p.realm or 0), "realm_name": rname, "realm_emoji": remoji,
                "sub_layer": int(p.sub_layer or 1), "power": int(p.battle_power or 0),
            })

        # NPC cultivators of THIS continent (bounded, honest 🤖). Continent-scoped,
        # NOT realm-windowed — the plaza shows the region's notable cultivators.
        nrows = (await session.execute(
            select(NpcCultivator).where(
                NpcCultivator.status == "active",
                NpcCultivator.continent_key == continent,
            ).order_by(NpcCultivator.power.desc()).limit(10)
        )).scalars().all()
        from core.npc_cultivator_engine import project_npc_for_profile
        npcs = [project_npc_for_profile(n, lang, realm_label=_realm_label) for n in nrows]

        # Whisper feed scoped to this continent (+ global whispers), and the open
        # bounty count for the header.
        whispers = await list_recent_whispers(session, limit=12, lang=lang, continent=continent)
        bcount = await bounty_board_count(session, continent)

        # World Pulse Fase 1 — the Chronicle strip (Registos Celestiais), scoped
        # to this continent (+ global lines). A short preview; "ver tudo" opens
        # the full ChronicleModal.
        from core.world_pulse_engine import list_recent_chronicle
        # MV-8 — a tira da praça mostra 4: com `jianghu` ON a ordenação passa a
        # ler o `importance` (escrito por 20 call sites e lido por NINGUÉM até
        # agora), para uma ocupação não ser empurrada para fora por ruído de
        # rotina. O `continent` já escopa a query; aqui o viewer É o lugar.
        chronicle = await list_recent_chronicle(session, limit=6, lang=lang,
                                                continent=continent,
                                                viewer_continent=continent)

        # MV-2 — Tiandao: evento NESTE continente (linha local — fix do review,
        # Lei §1: quem chega ao lugar VÊ o evento mesmo sem o mapa v2) + rumor
        # de evento NOUTRO continente (gated — OFF: payload byte-idêntico).
        wev_rumors: list = []
        wev_local: list = []
        try:
            from core.tiandao_engine import (
                director_on as _wev_on, local_event_lines as _wev_ll, rumor_views as _wev_rv,
            )
            if _wev_on():
                wev_local = await _wev_ll(session, continent, lang)
                wev_rumors = await _wev_rv(session, continent, lang)
        except Exception:
            logger.exception("plaza tiandao rumor failed")

        # MV-4 §0 (dívida MV-3) — a linha do estado LOCAL na praça (o /viajar,
        # o mapa e o mercado já cobrem; a praça era o buraco). Gated + additive:
        # flag OFF → key ausente → payload byte-idêntico.
        rst_local = None
        try:
            from core.region_state_engine import local_state_view
            rst_local = await local_state_view(session, continent, lang)
        except Exception:
            logger.exception("plaza region state line failed")

        # MV-5 — o encontro na PRAÇA: um NPC da presença local "te chama".
        # Tenta mintar (pacer/cooldown no engine — a maioria dos opens é no-op)
        # e ride a oferta aberta no payload. Gated + additive: flag OFF → zero
        # queries novas → key ausente → payload byte-idêntico. O mint escreve →
        # commit explícito SÓ quando mintou.
        sty_offer = None
        try:
            from core.storylet_engine import quests_vivas_on, maybe_offer, open_offer_view
            if quests_vivas_on():
                minted = await maybe_offer(session, player, source="plaza")
                if minted is not None:
                    await session.commit()
                    sty_offer = minted
                else:
                    sty_offer = await open_offer_view(session, player, lang)
        except Exception:
            logger.exception("plaza storylet offer failed")

        # MV-6 — a rep LOCAL (chip + reverência/desprezo) e O RIVAL na praça
        # do jogador (a volta é per-player — presença 😤). Gated + additive:
        # flag OFF → keys ausentes → payload byte-idêntico.
        rep_local = None
        rival_card = None
        try:
            from core.reputation_engine import local_rep_view, rival_view
            rep_local = await local_rep_view(session, player, lang)
            rival_card = await rival_view(session, player, lang)
        except Exception:
            logger.exception("plaza reputation/rival failed")

        # MV-8 — a EMBOSCADA na praça (o 2º cano por volume). Só uma OFERTA:
        # o duelo, se houver, nasce do tap do jogador. Gated + additive → flag
        # OFF: key ausente, payload byte-idêntico.
        jh_ambush = None
        try:
            from core.jianghu_engine import ambush_offer
            jh_ambush = await ambush_offer(session, player, source="plaza", lang=lang)
        except Exception:
            logger.exception("plaza jianghu ambush failed")

        # MV-9 — A CIDADE: identidade (nome/intro/traço, server-resolved) + o
        # ENCARGO 城务 vigente + o meu estado nele. Gated + aditivo: flag OFF →
        # None → key ausente → payload byte-idêntico.
        city_block = None
        try:
            from core.city_engine import city_plaza_view
            city_block = await city_plaza_view(session, player, lang)
        except Exception:
            logger.exception("plaza city view failed")

        # MV-9.5 — A CARAVANA 商队: o velho da cidade, as rotas (com o custo em
        # MATERIAL e a origem dita), a carga em trânsito e o atlas de onde
        # nascem as coisas. Gated + aditivo: flag OFF → None → key ausente.
        # ⚠️ Este bloco CREDITA cargas chegadas (quem finaliza credita) — logo
        # suja a sessão. A praça já comita quando o MV-5 minta uma oferta
        # (`:13489`); para o crédito não ficar refém desse ramo, comita aqui
        # também quando houve entrega.
        caravan_block = None
        try:
            from core.caravan_engine import caravan_view
            caravan_block = await caravan_view(session, player, lang)
            if caravan_block and (caravan_block.get("delivered")
                                  or caravan_block.get("bag_full")):
                await session.commit()
        except Exception:
            logger.exception("plaza caravan view failed")

        # MV-11 天时 — O TEMPO DO CÉU na praça: ambiente, SEM números (não há
        # alma nem reino no contexto da praça, e inventar uma chance genérica
        # seria display-lie). Diz o que está no ar e o que vem a seguir. É PURO
        # e SÍNCRONO — zero query, zero await, mesmo com a flag ON. Gated +
        # aditivo: flag OFF → None → key ausente → payload byte-idêntico.
        sky_block = None
        try:
            from core.tianshi_engine import sky_plaza_view
            sky_block = sky_plaza_view(lang)
        except Exception:
            logger.exception("plaza tianshi view failed")

        def _city_name_key(block) -> str:
            """A key i18n do nome da cidade (fallback: a de sempre)."""
            try:
                from core.city_engine import CITY_META
                return str(CITY_META[(block or {})["key"]]["name_key"])
            except Exception:
                return "city_wanshi"

        meta = CONTINENT_META.get(continent) or {}
        chip = {
            "key": continent,
            "emoji": meta.get("emoji", "🗺️"),
            "name": i18n_t(lang, meta["name_key"]) if meta.get("name_key") else continent,
        }
        return _json({
            "ok": True,
            "continent": continent,
            "continent_chip": chip,
            # MV-9 — `city_key` era dado MORTO: um literal com ZERO leitores no
            # repo inteiro (ambos os renders chamavam `t('city_wanshi')` por
            # conta própria). Decisão explícita: FICA e passa a carregar o nome
            # — mas continua a ser uma **key de i18n**, o mesmo TIPO de antes,
            # para que um cliente antigo em cache que faça `t(d.city_key)` ainda
            # resolva um nome real em vez de imprimir um slug cru. Flag OFF →
            # exatamente `city_wanshi`, como sempre foi (identidade do `main`).
            "city_key": _city_name_key(city_block),
            **({"city": city_block} if city_block else {}),
            **({"caravan": caravan_block} if caravan_block else {}),
            "players": players,
            "npcs": npcs,
            "bounty_count": int(bcount),
            "whispers": whispers,
            "chronicle": chronicle,
            **({"world_event_local": wev_local} if wev_local else {}),
            **({"world_event_rumors": wev_rumors} if wev_rumors else {}),
            **({"region_state_local": rst_local} if rst_local else {}),
            **({"storylet_offer": sty_offer} if sty_offer else {}),
            **({"region_rep_local": rep_local} if rep_local else {}),
            **({"rival": rival_card} if rival_card else {}),
            **({"jianghu_ambush": jh_ambush} if jh_ambush else {}),
            **({"tianshi": sky_block} if sky_block else {}),
        })


