async def api_combat_bounty_claim(request: web.Request) -> web.Response:
    """WRITE — Onda 4a — claim a fulfilled bounty (the player won the named NPC's
    duel). Body {bounty_id:int, duel_id:str}. Idempotent + pays once + duel-proven
    (mirrors api_combat_npc_cultivator_resolve)."""
    import uuid as _uuid
    from core.bounty_engine import claim_bounty

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    bounty_id_raw = payload.get("bounty_id")
    duel_id_raw = payload.get("duel_id")
    if not bounty_id_raw:
        return _err("missing_bounty_id", 400)
    if not duel_id_raw:
        return _err("missing_duel_id", 400)
    try:
        duel_id = _uuid.UUID(str(duel_id_raw))
    except Exception:
        return _err("invalid_duel_id", 400)
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            result = await claim_bounty(session, player, int(bounty_id_raw), duel_id)
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("combat/bounty_claim failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_bounty_post(request: web.Request) -> web.Response:
    """WRITE — Track A item 3 — a player posts a contract on a dark-karma NPC
    ("colocar a cabeça a prêmio"). Body {npc_id:int, stones:int}. Debits
    spirit_stones (NEVER jade — Lei §4), NON-REFUNDABLE, anti-grief-bounded
    (min prize, max active, dark-karma-only, one-per-target). Row-locks the
    poster FOR UPDATE (mirrors api_combat_bounty_claim) so the open-count + the
    stone debit can't lost-update under a double-tap."""
    from core.bounty_engine import post_player_bounty
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    npc_id_raw = payload.get("npc_id")
    stones_raw = payload.get("stones")
    if not npc_id_raw:
        return _err("missing_npc_id", 400)
    try:
        npc_id = int(npc_id_raw)
    except (TypeError, ValueError):
        return _err("invalid_npc_id", 400)
    try:
        stones = int(stones_raw)
    except (TypeError, ValueError):
        return _err("invalid_stones", 400)
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            result = await post_player_bounty(session, player, npc_id, stones)
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("world/bounty_post failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


