async def api_world_travel_go(request: web.Request) -> web.Response:
    """WRITE — Onda 4b — travel to a continent. Body {continent:str}. Debits
    spirit_stones (NEVER jade — Lei §4) on its own cooldown, sets
    current_continent (the plaza/bounty/encounter/affinity follow). Idempotent
    + row-locked (mirrors api_combat_bounty_claim): the player row is locked
    FOR UPDATE so the stone debit can't lost-update, and travelling to the
    continent you're already in is a no-op disclosed reason that costs nothing.
    NEVER locks any existing farm — current_continent only ADDS context."""
    from core.travel_engine import do_travel
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    dest = payload.get("continent")
    if not dest or not isinstance(dest, str):
        return _err("missing_continent", 400)
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            result = await do_travel(session, player, dest.strip().lower())
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("world/travel_go failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_jianghu_ambush(request: web.Request) -> web.Response:
    """WRITE — MV-8 — resolve UMA emboscada do jiānghú.

    Body ``{npc_id:int, branch:"fight"|"bribe"|"flee"}``.

    ⚠️ **O lock vive AQUI, nunca no engine** (o contrato de `do_travel` /
    `claim_bounty`): não existe helper de débito de pedras neste projeto — os
    oito sinks fazem `player.spirit_stones = ... - cost` INLINE sobre uma row
    que o CALLER travou `.with_for_update()`. Sem o lock, um duplo-tap no botão
    💰 debitaria duas vezes. O commit também é daqui.
    """
    from core.jianghu_engine import ambush_resolve
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    branch = str(payload.get("branch") or "").strip().lower()
    try:
        npc_id = int(payload.get("npc_id"))
    except (TypeError, ValueError):
        return _err("missing_npc_id", 400)
    if branch not in ("fight", "bribe", "flee"):
        return _err("invalid_branch", 400)
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            # ⚠️ `normalize_lang` NÃO é import de módulo neste ficheiro — todo
            # endpoint o importa localmente. Usá-lo direto compila e explode em
            # runtime com NameError no primeiro tap real.
            from core.utils import normalize_lang as _norm
            lang = _norm(getattr(player, "language", None))
            result = await ambush_resolve(session, player, npc_id=npc_id,
                                          branch=branch, lang=lang)
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("world/jianghu_ambush failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_events(request: web.Request) -> web.Response:
    """READ — o "world snapshot" do mapa v2: eventos celestiais ativos (MV-2,
    gated `tiandao_director`) + estados regionais (MV-3, gated
    `estados_regionais` — flags INDEPENDENTES). name/desc server-resolved
    (padrão Chronicle). Ambas OFF → {ok, events: []} sem tocar em tabela
    nenhuma (o cliente gated nem chama; isto é a guarda server-side).
    Byte-shape preservado por flag: tiandao OFF → sem `continent`; estados
    OFF → sem `region_states` (chaves aditivas, padrão world_event_rumors)."""
    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            lang = (player.language or "pt").lower()
            from core.tiandao_engine import director_on, list_active_event_views
            out: dict = {"ok": True, "events": []}
            if director_on():
                out["events"] = await list_active_event_views(session, player=player, lang=lang)
                from core.dungeon_regions import player_continent as _pc
                out["continent"] = _pc(player)
            # MV-3 — badge de estado por ilha (server-resolved; OFF → key ausente).
            try:
                from core.region_state_engine import estados_on as _rst_on, state_views as _rst_views
                if _rst_on():
                    out["region_states"] = await _rst_views(session, lang)
            except Exception:
                logger.exception("world/events region states failed")
            # MV-6 — chip de rep por ilha (server-resolved; OFF → key ausente).
            try:
                from core.reputation_engine import rep_chip_map as _rep_map
                _reps = await _rep_map(session, player, lang)
                if _reps:
                    out["region_rep"] = _reps
            except Exception:
                logger.exception("world/events region rep failed")
            # TEC-4 — a Gruta do Legado ativa (flag `legacy_caves`, INDEPENDENTE
            # do Director; OFF → key ausente, shape byte-idêntico — padrão
            # multi-flag deste endpoint).
            try:
                from core.legacy_cave_engine import active_cave_view, legacy_caves_on
                if legacy_caves_on():
                    _cave = await active_cave_view(session, lang, player=player)
                    if _cave:
                        out["legacy_cave"] = _cave
            except Exception:
                logger.exception("world/events legacy cave failed")
            # MV-9 — o NOME da cidade de cada ilha (o hub v2 desenha 5 portas
            # por ilha e as 20 das ilhas remotas saíam mudas). Só nomes, sem
            # encargo: o hub é um mapa, não a praça. Flag OFF → key ausente,
            # shape byte-idêntico — padrão multi-flag deste endpoint.
            try:
                from core.city_engine import (
                    cidades_on as _cid_on, CITY_META as _CM, city_name as _cn,
                )
                if _cid_on():
                    out["cities"] = {
                        m["continent"]: {"key": k, "emoji": m["emoji"], "name": _cn(k, lang)}
                        for k, m in _CM.items()
                    }
            except Exception:
                logger.exception("world/events cities failed")
            return _json(out)
    except Exception as e:
        logger.exception("world/events failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


