async def api_world_explore_advance(request: web.Request) -> web.Response:
    """WRITE — Onda 5 — resolve a chosen direction (cache / trash fight / moral
    fork / Hidden-Monster duel). Body {direction:int, expected_depth:int?,
    choice:str?}. Debits qi (NEVER jade — Lei §4), grants MATERIALS only (never
    techniques — Lei §5), on its OWN cooldown. Idempotent + row-locked (mirrors
    api_world_travel_go): the player row is locked FOR UPDATE so the qi debit
    and loot can't lost-update under the players' automation; a stale/retried
    request is a disclosed no-op. A Hidden Monster returns redirect_to_duel +
    duel_id (the loot lands in the settle hook)."""
    from core.exploration_engine import advance
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    direction = payload.get("direction")
    if direction is None:
        return _err("missing_direction", 400)
    try:
        direction = int(direction)
    except (TypeError, ValueError):
        return _err("invalid_direction", 400)
    expected_depth = payload.get("expected_depth")
    if expected_depth is not None:
        try:
            expected_depth = int(expected_depth)
        except (TypeError, ValueError):
            expected_depth = None
    choice_id = payload.get("choice")
    if choice_id is not None:
        choice_id = str(choice_id)[:32]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            lang = (player.language or "pt").lower()
            result = await advance(
                session, player,
                direction_idx=direction, expected_depth=expected_depth,
                choice_id=choice_id, lang=lang, realm_label=_realm_label,
            )
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("world/explore_advance failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


