async def api_world_formation_activate(request: web.Request) -> web.Response:
    """WRITE — Onda 5 Fase 2 — activate a crafted Formação. Body
    {formation_id:int, target:"body"|"cavern"} — the player's CHOICE (Lei §1):
    "body" raises the timed PlayerBuff (combat/cultivation/Dao/exploration all
    read it); "cavern" sets the cavern slot (boosts idle yield / Dao
    comprehension). Refuses while the same effect/slot is live (anti-stack —
    the idempotency marker: a double-tap or retry is a disclosed no-op)."""
    from core.cavern_engine import set_cavern_formation
    from core.formation_engine import activate_on_body
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        formation_id = int(payload.get("formation_id"))
    except (TypeError, ValueError):
        return _err("invalid_formation_id", 400)
    target = str(payload.get("target") or "body").lower()
    if target not in ("body", "cavern"):
        return _err("invalid_target", 400)
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            if target == "cavern":
                result = await set_cavern_formation(session, player, formation_id)
            else:
                result = await activate_on_body(session, player, formation_id)
            await session.commit()
            return _json(result, status=200)
    except Exception as e:
        logger.exception("world/formation_activate failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


