async def api_world_body_temper(request: web.Request) -> web.Response:
    """WRITE — Sprint 3 — Cultivo do Corpo @ R0: temper the Carne Mortal one tier.
    Server-gated (refuses outside a `cultivo_corpo_r0` world and at R7+), row-locked,
    débito all-or-nothing in a single committed transaction (stones + a fraction of
    qi; NEVER qi_capacity). `main` (flag OFF) → refuses with body_temper_locked, so
    the 57 can never write mortal_body_level."""
    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            from database.db import feature_enabled_for_world
            if not feature_enabled_for_world("cultivo_corpo_r0"):
                return _json({"ok": False, "reason": "body_temper_locked"}, status=200)
            from core.body_tempering_engine import (
                MIN_REALM_REQUIRED, can_temper_mortal, perform_mortal_temper,
            )
            if (player.realm or 0) >= MIN_REALM_REQUIRED:
                return _json({"ok": False, "reason": "body_temper_apex"}, status=200)
            # Same effective qi cap the card priced the cost with (raw+equip×tempering).
            eff_qi_cap = await _effective_qi_cap(session, player)
            # MV-4 — refino ancorado: the SAME place mult the card disclosed
            # (corpo_profundo OFF → 1.0 without a query → byte-identical).
            _place_mult = 1.0
            try:
                from core.meridian_engine import refine_place_mult
                _place_mult = float((await refine_place_mult(session, player)).get("mult", 1.0) or 1.0)
            except Exception:
                logger.exception("body_temper refine_place failed")
            check = can_temper_mortal(player, eff_qi_cap=eff_qi_cap, place_mult=_place_mult)
            if not check["can"]:
                return _json({"ok": False, "reason": check["reason_key"],
                              "cost": check.get("cost")}, status=200)
            result = perform_mortal_temper(player, eff_qi_cap=eff_qi_cap, place_mult=_place_mult)
            if not result.get("success"):
                # Defensive: gate flipped between check and perform → no mutation done.
                return _json({"ok": False, "reason": result.get("reason_key", "body_temper_locked"),
                              "cost": result.get("cost")}, status=200)
            # 減 P7 — a forja da carne CONFIRMADA: a explicacao do Refino Mortal
            # pode recolher. So' esta camada — as outras tem a sua accao.
            from core.explicacoes import marcar_apto as _explica_apto
            _explica_apto(player, "corpo_mortal")
            await session.commit()
            return _json({"ok": True, **result}, status=200)
    except Exception as e:
        logger.exception("world/body_temper failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


