async def api_world_caravan(request: web.Request) -> web.Response:
    """MV-9.5 — a vitrine da Caravana (READ, mas CREDITA cargas chegadas).

    Molde `api_world_profession` para o gate, `api_world_city_encargo` para o
    lock. O commit é condicional: só quando houve entrega de verdade.
    """
    user_id: int = request["user_id"]
    try:
        from core.caravan_engine import caravan_view, caravana_on
        if not caravana_on():
            return _json({"ok": False, "reason": "crv_locked"}, status=200)
        async with get_session_factory()() as session:
            # FOR UPDATE porque a vitrine credita — duas abas abertas ao mesmo
            # tempo não podem entregar a mesma carga duas vezes.
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            lang = (player.language or "pt").lower()
            view = await caravan_view(session, player, lang)
            if view is None:
                return _json({"ok": False, "reason": "crv_locked"}, status=200)
            if view.get("delivered") or view.get("bag_full"):
                await session.commit()
            return _json({"ok": True, "view": view}, status=200)
    except Exception as e:
        logger.exception("world/caravan failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_caravan_send(request: web.Request) -> web.Response:
    """MV-9.5 — mandar vir uma carga. Escambo: nenhuma pedra atravessa o fluxo."""
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        # `int(None)` levanta — coagir explicitamente é o padrão de
        # `api_world_storylet_claim` (`:14344-14347`).
        target_kind = str(payload.get("kind") or "")
        pay_kind = str(payload.get("pay_kind") or "")
        target_id = int(payload.get("item_id") or 0)
        pay_id = int(payload.get("pay_id") or 0)
    except (TypeError, ValueError):
        return _err("invalid_payload", 400)
    if target_kind not in ("herb", "ore") or pay_kind not in ("herb", "ore") \
            or target_id <= 0 or pay_id <= 0:
        return _err("invalid_payload", 400)
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            from core.caravan_engine import caravan_view, send_load
            result = await send_load(
                session, player, target_kind=target_kind, target_id=target_id,
                pay_kind=pay_kind, pay_id=pay_id)
            if result.get("ok"):
                await session.commit()
                # Re-render na MESMA resposta (molde `profession_choose`): o
                # cliente não precisa de um 2º round-trip só para ver a carga
                # na estrada, e gastar 2 tokens do bucket de 15 por tap seria
                # comer o burst de quem também está a meditar.
                try:
                    view = await caravan_view(
                        session, player, (player.language or "pt").lower())
                    if view is not None:
                        result = {**result, "view": view}
                except Exception:
                    logger.debug("caravan re-render failed", exc_info=True)
            return _json(result, status=200)
    except Exception as e:
        logger.exception("world/caravan_send failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


