async def api_world_profession(request: web.Request) -> web.Response:
    """READ — MV-7 Profissões — a vista completa do ofício (server-resolved:
    cerimônia OU status com bônus vivos). Server-gated por `profissoes`
    (main → prf_locked, zero queries novas). Para o médico, inclui a lista de
    pílulas HP do anel (o alvo do heal_ally vem por dao_name no WRITE)."""
    user_id: int = request["user_id"]
    try:
        from core.profession_engine import get_profession_view, profissoes_on
        if not profissoes_on():
            return _json({"ok": False, "reason": "prf_locked"}, status=200)
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            lang = (player.language or "pt").lower()
            view = await get_profession_view(session, player, lang)
            if view is None:
                return _json({"ok": False, "reason": "prf_locked"}, status=200)
            if view.get("has") and view.get("key") == "medico":
                from database.models import PillCatalog, PlayerInventory
                rows = (await session.execute(
                    select(PlayerInventory, PillCatalog)
                    .join(PillCatalog, PillCatalog.id == PlayerInventory.item_id)
                    .where(PlayerInventory.player_id == user_id,
                           PlayerInventory.item_type == "pill",
                           PlayerInventory.quantity > 0,
                           PillCatalog.effect_type == "hp_restore")
                    .order_by(PillCatalog.id)
                )).all()
                view["hp_pills"] = [{
                    "inv_id": int(inv.id), "pill_id": int(cat.id),
                    "name": catalog_name(lang, "art", cat),
                    "emoji": getattr(cat, "emoji", None) or "💊",
                    "quality": getattr(inv, "quality", None) or "normal",
                    "qty": int(inv.quantity or 0),
                    "pct": int(float(cat.effect_value or 0) * 100),
                } for inv, cat in rows]
                # ── 🩺 QUEM SE PODE CURAR (sugestão do [jogador], 2026-08-12) ────
                # *"I need to input his name... Can we have a drop down showing
                # available cultivators for healing? It would make it a lot
                # easier than having to go out, look at the name, make sure
                # spelling is correct, go back out to verify and correct."*
                #
                # A metade das PÍLULAS já era um seletor; só o ALVO era texto
                # livre — e um texto livre validado por igualdade EXATA de
                # dao_name, que só respondia `prf_heal_not_found` sem dizer se
                # o nome estava errado, se a pessoa estava noutro continente,
                # se o reino era distante demais ou se ela já tinha HP cheio.
                # Adivinhar o nome de alguém não é decisão de jogo: é atrito.
                #
                # A lista é o espelho EXATO dos guardas do `heal_ally` (mesmo
                # continente · não é você · gap de reino · HP não cheio · não
                # shadow), calculada no servidor — assim ela nunca diverge das
                # recusas, que é como um seletor destes costuma ganhar bugs.
                # O alvo continua a viajar por `dao_name`: o mini-app nunca vê
                # telegram_id (privacidade — a mesma regra do trade P2P).
                try:
                    from datetime import timedelta as _td
                    from core.combat_engine import get_current_hp, get_max_hp
                    from core.profession_engine import PROF_HEAL_REALM_GAP
                    _cont = getattr(player, "current_continent", None) or "linghe"
                    _realm = int(player.realm or 0)
                    _cut = datetime.now(timezone.utc) - _td(days=14)
                    _cands = (await session.execute(
                        select(Player).where(
                            Player.shadow_mode == False,  # noqa: E712
                            Player.current_continent == _cont,
                            Player.telegram_id != user_id,
                            Player.dao_name.is_not(None),
                            Player.last_online >= _cut,
                        ).order_by(Player.last_online.desc()).limit(40)
                    )).scalars().all()
                    _targets = []
                    for _c in _cands:
                        if abs(int(_c.realm or 0) - _realm) >= PROF_HEAL_REALM_GAP:
                            continue
                        _mx = float(get_max_hp(_c))
                        _cu = float(get_current_hp(_c))
                        if _mx <= 0 or _cu >= _mx - 0.5:
                            continue      # HP cheio ⇒ `prf_heal_full`; não listar
                        _targets.append({
                            "dao_name": _c.dao_name,
                            "realm": int(_c.realm or 0),
                            "hp_pct": max(0, min(100, int(round(_cu / _mx * 100)))),
                        })
                        if len(_targets) >= 12:
                            break
                    view["heal_targets"] = _targets
                except Exception:
                    logger.debug("heal_targets projection failed", exc_info=True)
            return _json({"ok": True, "view": view}, status=200)
    except Exception as e:
        logger.exception("world/profession failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_profession_choose(request: web.Request) -> web.Response:
    """WRITE — MV-7 — cerimônia de escolha OU troca (switch=true; custo alto +
    XP zera, disclosure na UI antes do confirm). Row-locked + committed
    (padrão storylet_respond). `main` (flag OFF) → recusa prf_locked."""
    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    key = str(payload.get("key") or "")
    switching = bool(payload.get("switch"))
    try:
        from core.profession_engine import (choose_profession,
                                            get_profession_view, profissoes_on,
                                            switch_profession)
        if not profissoes_on():
            return _json({"ok": False, "reason": "prf_locked"}, status=200)
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            lang = (player.language or "pt").lower()
            fn = switch_profession if switching else choose_profession
            result = await fn(session, player, key, lang)
            if not result.get("ok"):
                return _json(result, status=200)
            await session.commit()
            view = await get_profession_view(session, player, lang)
            return _json({**result, "view": view}, status=200)
    except Exception as e:
        logger.exception("world/profession_choose failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


