async def api_world_ftue(request: web.Request) -> web.Response:
    """READ — FTUE espinha: the guided first-hour checklist (server-gated, DERIVED-state, no
    mutation). `main` (flag OFF) → {ftue_on: False} so the guide card stays hidden and the 57
    are untouched."""
    user_id: int = request["user_id"]
    try:
        from core.ftue_engine import ftue_on, project_ftue, grant_ftue_strike_technique
        if not ftue_on():
            return _json({"ok": True, "ftue_on": False}, status=200)
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            # MV-1 §0.3 — COMPAT: beta players. O grant da Beggar's Palm é de
            # nascimento; chars criados ANTES (s2) recebem-na aqui, lazy e
            # idempotente, enquanto o Mendigo ainda os guia (realm <= 1).
            # O card polla a cada 8s: dois polls simultâneos podem colidir na
            # PK composta — o rollback engole a corrida (o outro poll ganhou).
            if int(player.realm or 0) <= 1 and await grant_ftue_strike_technique(session, user_id):
                try:
                    await session.commit()
                except Exception:
                    await session.rollback()
            return _json({"ok": True, **project_ftue(player)}, status=200)
    except Exception as e:
        logger.exception("world/ftue failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_combat_duel_accept(request: web.Request) -> web.Response:
    """WRITE — defender accepts the pending challenge → duel becomes active.

    Body: `{ duel_id: str }`. Only the defender can call this. Idempotent:
    if duel is already 'waiting_actions', returns ok without mutating.
    """
    import uuid as _uuid
    from core.duel_engine import accept_duel
    from database.models import DuelSession

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        duel_uuid = _uuid.UUID(str(payload.get("duel_id") or ""))
    except (ValueError, TypeError):
        return _err("invalid_duel_id", 400)

    try:
        async with get_session_factory()() as session:
            duel = (await session.execute(
                select(DuelSession).where(DuelSession.id == duel_uuid).with_for_update()
            )).scalar_one_or_none()
            if not duel:
                return _json({"ok": False, "reason": "duel_not_found"})

            result = await accept_duel(session, duel, user_id)
            await session.commit()
            return _json(result)
    except Exception as e:
        logger.exception("combat/duel_accept failed for user_id=%s duel=%s", user_id, duel_uuid)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_combat_duel_submit(request: web.Request) -> web.Response:
    """WRITE — submit the player's action for the current round.

    Body: `{ duel_id: str, technique_id: int }`. technique_id=0 means basic
    strike (no qi cost, no bonus). v15.1.3 — `stance` is no longer accepted;
    the chosen technique encodes attack vs defense intent. If both players
    submitted, resolves the round atomically and the new state is reflected
    via duel_state.
    """
    import uuid as _uuid
    from core.duel_engine import submit_action
    from database.models import DuelSession

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}

    try:
        duel_uuid = _uuid.UUID(str(payload.get("duel_id") or ""))
    except (ValueError, TypeError):
        return _err("invalid_duel_id", 400)
    try:
        technique_id = int(payload.get("technique_id") or 0)
    except (TypeError, ValueError):
        return _err("invalid_technique_id", 400)

    try:
        async with get_session_factory()() as session:
            duel = (await session.execute(
                select(DuelSession).where(DuelSession.id == duel_uuid).with_for_update()
            )).scalar_one_or_none()
            if not duel:
                return _json({"ok": False, "reason": "duel_not_found"})

            result = await submit_action(session, duel, user_id, technique_id)
            await session.commit()
            return _json(result)
    except Exception as e:
        logger.exception("combat/duel_submit failed for user_id=%s duel=%s", user_id, duel_uuid)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_combat_duel_state(request: web.Request) -> web.Response:
    """READ — current duel state from the viewer's perspective.

    Body: `{ duel_id?: str }`. With no duel_id, looks up the player's
    currently-active duel (waiting_actions) — used by the UI to auto-open
    the arena modal when the defender first opens the tab.

    Hides opponent's pending action. Polled every 2s by the UI while
    state='waiting_actions'.
    """
    import uuid as _uuid
    from sqlalchemy import or_
    from core.duel_engine import get_duel_state, apply_post_duel_effects, check_and_handle_timeout
    from database.models import DuelSession

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    raw_id = payload.get("duel_id")

    try:
        async with get_session_factory()() as session:
            duel = None
            if raw_id:
                try:
                    duel_uuid = _uuid.UUID(str(raw_id))
                except (ValueError, TypeError):
                    return _err("invalid_duel_id", 400)
                duel = (await session.execute(
                    select(DuelSession).where(DuelSession.id == duel_uuid)
                )).scalar_one_or_none()
            else:
                # Look up the player's most recent open duel (pending challenge
                # OR live combat — both should auto-open on the defender's side).
                duel = (await session.execute(
                    select(DuelSession).where(
                        or_(
                            DuelSession.attacker_id == user_id,
                            DuelSession.defender_id == user_id,
                        ),
                        DuelSession.state.in_(["waiting_actions", "pending_acceptance"]),
                    ).order_by(DuelSession.created_at.desc()).limit(1)
                )).scalar_one_or_none()

            if not duel:
                return _json({"ok": True, "duel_id": None})
            if user_id not in (duel.attacker_id, duel.defender_id):
                return _json({"ok": False, "reason": "not_a_participant"})

            # v15.1b — any poll triggers timeout check. If the round/acceptance
            # window has expired, auto-fill missing actions and resolve so the
            # duel can never stall on an AFK player.
            if await check_and_handle_timeout(session, duel):
                await session.commit()

            # On the first read after a duel finishes, drain real HP. Idempotent:
            # apply_post_duel_effects only fires when resolved_at is set, and HP
            # is computed off duel hp_max - hp (already fixed at resolve time).
            # We guard with a tiny marker in action_log to avoid double-drain.
            if duel.state in ("finished", "forfeited"):
                # Onda 3 hardening — api_combat_duel_state is the ONLY path that
                # settles a finished PvE/PvP duel (submit/accept/forfeit defer it),
                # but it read the duel UNLOCKED. Under READ COMMITTED two overlapping
                # terminal polls (the arena 2s loop + the modal-close afterDuel())
                # could both pass the in-memory hp_drained / pve_settled guards on a
                # stale read and DOUBLE-apply the HP drain + settle reward (a real
                # economy leak — npc_cultivator stones, npc_hunt loot, dungeon_boss,
                # etc). Lock the DUEL row FOR UPDATE and re-read the marker off the
                # fresh row, mirroring the serialization submit/accept/forfeit use.
                locked = (await session.execute(
                    select(DuelSession).where(DuelSession.id == duel.id)
                    .with_for_update().execution_options(populate_existing=True)
                )).scalar_one_or_none()
                if locked is not None:
                    duel = locked
                already_drained = any(
                    isinstance(entry, dict) and entry.get("type") == "hp_drained"
                    for entry in (duel.action_log or [])
                )
                if not already_drained:
                    from sqlalchemy.orm.attributes import flag_modified
                    await apply_post_duel_effects(session, duel)
                    duel.action_log = (duel.action_log or []) + [{
                        "round": duel.round_idx,
                        "type": "hp_drained",
                    }]
                    flag_modified(duel, "action_log")
                    await session.commit()

            # 武 2.2 — a língua de QUEM OLHA. O log grava cru (dois lutadores,
            # duas línguas, um log) e é aqui que se interpreta — a lição de
            # 卷獸圖. Sem isto o duelo dizia "Thunder Step" a um jogador `pt`
            # cuja aba Técnicas lhe mostra "Passo do Trovão", e a arte da cena
            # não tinha chave por onde ser encontrada. UMA coluna, uma query.
            _duel_lang = await _lang_of(session, user_id)
            out = {"ok": True, **get_duel_state(duel, user_id, _duel_lang)}
            # QoL 31/07 Item C (dívida TEC-4): o espólio da gruta era MUDO no
            # mini — o settle roda aqui mesmo, o chat lê o marker, mas o modal
            # nunca via o loot. Key CONDICIONAL: só existe quando
            # pve_source="legacy_cave" E o settle já carimbou o payload
            # (OFF-identity byte-idêntica para todo outro duelo).
            # QoL 04/08 — o Tributo da Terra do CHEFE (o caminho que realmente
            # conclui a masmorra). Key condicional, do payload do settle.
            if duel.pve_source == "dungeon_boss":
                for _e in reversed(duel.action_log or []):
                    if isinstance(_e, dict) and _e.get("type") == "pve_settled":
                        _tl = (_e.get("payload") or {}).get("tribute_line")
                        if _tl:
                            out["tribute_line"] = _tl
                        # 層 4.3 — o que o chefe CONFIRMOU (o último andar, a
                        # dificuldade), gravado pelo settle na MESMA transacção.
                        # Key CONDICIONAL: só com a onda e só quando o settle a
                        # gravou — sem ela, o payload de hoje.
                        _mg = (_e.get("payload") or {}).get("masmorra_ganho")
                        if _mg:
                            from core import masmorra as _masmorra_ds
                            out.update(_masmorra_ds.no_payload(_mg))
                        break
            if duel.pve_source == "legacy_cave":
                for _e in reversed(duel.action_log or []):
                    if isinstance(_e, dict) and _e.get("type") == "pve_settled":
                        if _e.get("payload"):
                            out["legacy_cave_result"] = _e.get("payload")
                        break
            # TEC-5 — o custo do Caminho Proibido (karma + anos), do lado DESTE
            # espectador. O marker `fpd_cost` é o único carregador comum aos 3
            # settles (só o PvE tem payload no `pve_settled`). Keys CONDICIONAIS
            # — nenhum duelo sem arte proibida muda de shape.
            try:
                from core.forbidden_path_engine import read_forbidden_cost, side_of_player
                _side = side_of_player(duel, user_id)
                if _side:
                    _cost = read_forbidden_cost(duel, _side)
                    if _cost:
                        out["forbidden_cost"] = _cost
                if duel.pve_source == "heart_demon":
                    for _e in reversed(duel.action_log or []):
                        if isinstance(_e, dict) and _e.get("type") == "pve_settled":
                            if _e.get("payload"):
                                out["heart_demon_result"] = _e.get("payload")
                            break
            except Exception:
                logger.debug("duel_state forbidden block failed", exc_info=True)
            # 道 07/10 — o que os CINCO CAMINHOS ganharam nesta luta, do lado de
            # QUEM OLHA (o report do [jogador]: o caminho subia, nenhum ecrã o dizia).
            # Gravado pelo dono (`intent_engine.award_post_duel_intent_xp`) no
            # `pve_context`, na MESMA transacção do settle. Key CONDICIONAL: só
            # com a onda e só quando o settle a gravou — sem ela, o payload de hoje.
            try:
                from core.portas import onda_on as _onda_on_cg
                if user_id == duel.attacker_id and _onda_on_cg():
                    _cg = (duel.pve_context or {}).get("caminho_ganho")
                    if _cg:
                        out["caminho_ganho"] = _cg
            except Exception:
                logger.debug("duel_state caminho_ganho block failed", exc_info=True)
            return _json(out)
    except Exception as e:
        logger.exception("combat/duel_state failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


