async def api_arena_leaderboard(request: web.Request) -> web.Response:
    """READ — top-N arena rankings + caller's own rank/elo.

    Mirrors `_ranking_arena` chat handler but exposes additional fields the UI
    needs (realm/sub_layer/emoji per row, season, total_count).
    """
    from database.models import ArenaRanking
    from core.combat_engine import CURRENT_SEASON

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        limit = max(1, min(100, int(payload.get("limit", 50))))
    except (TypeError, ValueError):
        limit = 50

    async with get_session_factory()() as session:
        player = (await session.execute(
            select(Player).where(Player.telegram_id == user_id)
        )).scalar_one_or_none()
        if not player:
            return _err("player_not_found", 404)

        rows = (await session.execute(
            select(ArenaRanking, Player.dao_name, Player.username, Player.display_name,
                   Player.realm, Player.sub_layer, Player.shadow_mode,
                   Player.telegram_id)
            .join(Player, Player.telegram_id == ArenaRanking.player_id)
            .where(ArenaRanking.season == CURRENT_SEASON)
            .order_by(desc(ArenaRanking.elo_points))
            .limit(limit)
        )).all()

        items = []
        for i, (rk, dao_name, username, display_name, realm, sub_layer, shadow, tg_id) in enumerate(rows):
            shown_name = "???" if shadow else (dao_name or username or display_name or "Cultivator")
            r = int(realm or 0)
            items.append({
                "rank": i + 1,
                "dao_name": shown_name,
                "elo": int(rk.elo_points or 1000),
                "wins": int(rk.wins or 0),
                "losses": int(rk.losses or 0),
                "realm": r,
                "realm_name": REALM_NAMES[r] if 0 <= r < len(REALM_NAMES) else "Mortal",
                "realm_emoji": REALM_EMOJIS[r] if 0 <= r < len(REALM_EMOJIS) else "🪨",
                "sub_layer": int(sub_layer or 1),
                "is_you": int(tg_id) == user_id,
            })

        own = (await session.execute(
            select(ArenaRanking).where(
                ArenaRanking.player_id == user_id,
                ArenaRanking.season == CURRENT_SEASON,
            )
        )).scalar_one_or_none()
        my_rank = None
        if own:
            higher = (await session.execute(
                select(func.count()).select_from(ArenaRanking).where(
                    ArenaRanking.season == CURRENT_SEASON,
                    ArenaRanking.elo_points > own.elo_points,
                )
            )).scalar() or 0
            my_rank = int(higher) + 1

        total = (await session.execute(
            select(func.count()).select_from(ArenaRanking).where(
                ArenaRanking.season == CURRENT_SEASON,
            )
        )).scalar() or 0

        return _json({
            "items": items,
            "season": int(CURRENT_SEASON),
            "total_count": int(total),
            "my_rank": my_rank,
            "my_elo": int(own.elo_points) if own else 1000,
            "my_wins": int(own.wins) if own else 0,
            "my_losses": int(own.losses) if own else 0,
        })


# ── v15.1.5 — Arena ELO queue (DB-backed, shared with chat handler) ──────


async def api_arena_queue_join(request: web.Request) -> web.Response:
    """WRITE — enqueue the caller for arena matchmaking.

    Returns one of:
      {ok: true, state: 'waiting',  remaining_seconds, elo, elo_range}
      {ok: true, state: 'matched',  duel_id, opponent_dao_name}
      {ok: false, reason: 'hp_too_low' | 'in_active_duel'}
    """
    from core.arena_engine import join_queue, try_match, get_queue_status

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            res = await join_queue(session, player, chat_id=None, message_id=None)
            if not res.get("ok"):
                await session.commit()
                return _json({"ok": False, "reason": res.get("reason", "queue_join_failed")})

            # Already matched (mid-flight) → return matched directly.
            if res.get("state") == "matched":
                await session.commit()
                return _json({"ok": True, "state": "matched",
                              "duel_id": res.get("duel_id")})

            # Opportunistic match attempt — any 2 waiters in elo range pair now.
            spawned = await try_match(session)
            await session.commit()

            # Re-read status for a clean projection (try_match may have flipped us).
            async with get_session_factory()() as s2:
                status = await get_queue_status(s2, user_id)
                await s2.commit()

            if spawned is not None and status.get("state") == "matched":
                return _json({"ok": True, **status})
            return _json({"ok": True, **status})
    except Exception as e:
        logger.exception("arena/queue_join failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_arena_queue_leave(request: web.Request) -> web.Response:
    """WRITE — leave the queue while still 'waiting'.

    No-op if the player isn't waiting (status='matched' duels have to be
    forfeited via combat/duel_forfeit instead).
    """
    from core.arena_engine import leave_queue, get_queue_status

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            removed = await leave_queue(session, user_id)
            status = await get_queue_status(session, user_id)
            await session.commit()
            return _json({"ok": True, "removed": bool(removed), **status})
    except Exception as e:
        logger.exception("arena/queue_leave failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_arena_queue_status(request: web.Request) -> web.Response:
    """READ — poll the queue projection. Drives the CombatArenaPanel state.

    Polled every 3s by the mini-app while idle/waiting/matched. Also runs
    `check_expirations` + `try_match` opportunistically so a polling
    player surfaces the 'matched' state without needing the scheduler
    sweep to fire first.
    """
    from core.arena_engine import check_expirations, try_match, get_queue_status

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            await check_expirations(session)
            await try_match(session)
            status = await get_queue_status(session, user_id)
            await session.commit()
            return _json({"ok": True, **status})
    except Exception as e:
        logger.exception("arena/queue_status failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_intent_status(request: web.Request) -> web.Response:
    """READ — v15.2/v15.2b Intent System status block.

    Returns the 5-intent panel data with: true_rank (soul mastery, persists
    across prestige), effective_rank (capped by realm), realm_cap,
    passive_bonus, next_passive_bonus, matchup hints, XP curve.

      {ok: true,
       realm: int,
       intents: [{intent, emoji, color, true_rank, effective_rank,
                  realm_cap, capped, rank_name, next_rank_name, xp,
                  xp_curve, passive_bonus, next_passive_bonus,
                  vs_strong, vs_weak}],
       dominant: 'sword' | ... | null}
    """
    from core.intent_engine import get_player_intents

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            realm = int(getattr(player, "realm", 0) or 0) if player else 0
            intents = await get_player_intents(session, user_id, realm=realm)
            # Dominant = highest true_rank (tiebreak: most xp). None if all R0/0.
            dominant = None
            best = (-1, -1, None)
            for row in intents:
                key = (int(row.get("true_rank", 0)), int(row.get("xp", 0)), row.get("intent"))
                if key[0] > best[0] or (key[0] == best[0] and key[1] > best[1]):
                    if key[0] > 0 or key[1] > 0:
                        best = key
            dominant = best[2]
            await session.commit()
            return _json({"ok": True, "realm": realm,
                          "intents": intents, "dominant": dominant})
    except Exception as e:
        logger.exception("intent/status failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


async def api_intent_history(request: web.Request) -> web.Response:
    """READ — last N duels with intent matchup metadata.

    Body: `{limit?: int (default 10, max 25)}`. Returns
      {ok: true, history: [{log_id, mode, won, my_intent, opp_intent,
                            modifier_pct, matchup, ts}]}
    """
    from core.intent_engine import get_player_intent_history

    user_id: int = request["user_id"]
    try:
        body = await request.json() if request.body_exists else {}
    except Exception:
        body = {}
    limit = int(body.get("limit") or 10)
    limit = max(1, min(25, limit))
    try:
        async with get_session_factory()() as session:
            history = await get_player_intent_history(session, user_id, limit=limit)
            await session.commit()
            return _json({"ok": True, "history": history})
    except Exception as e:
        logger.exception("intent/history failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__, "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/world/continent_info ─────────────────────────────────────────
async def api_world_continent_info(request: web.Request) -> web.Response:
    """READ — v16.0 World Foundation: continent state for the mini-app.

    Returns the player's current+home continent plus the full five-
    continent directory (lore-localized) for the ContinentModal drill-in.
    The mini-app reads this on PlayerHeader chip click; the chip itself
    renders from the smaller payload embedded in `api_player`.

    Response shape:
      {ok, current: {key, emoji, name, subtitle, lore, elements},
           home:    {key, emoji, name},
           is_traveling: bool,
           travel_available: true,          # MV-9: a viagem shipou na Onda 4b;
                                            # este campo mentia desde então
           all_continents: [{key, emoji, name, subtitle, lore,
                             elements, locked, demonic_only,
                             spawn_allowed}]}

    Lei §1 (honest disclosure): every continent the player cannot yet
    reach surfaces with `locked: true` + i18n explanation, not a 404 or
    a silent omission.
    """
    from core.continent_engine import (
        CONTINENT_META,
        DEFAULT_SPAWN_CONTINENT,
        get_all_continents_for_display,
        is_valid_continent,
    )
    from core.i18n import t as i18n_t
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            lang = normalize_lang(player.language or "pt")

            cur_key = player.current_continent or DEFAULT_SPAWN_CONTINENT
            if not is_valid_continent(cur_key):
                cur_key = DEFAULT_SPAWN_CONTINENT
            home_key = player.home_continent or DEFAULT_SPAWN_CONTINENT
            if not is_valid_continent(home_key):
                home_key = DEFAULT_SPAWN_CONTINENT

            cur_meta = CONTINENT_META[cur_key]
            home_meta = CONTINENT_META[home_key]

            return _json({
                "ok": True,
                "current": {
                    "key": cur_key,
                    "emoji": cur_meta["emoji"],
                    "name": i18n_t(lang, cur_meta["name_key"]),
                    "subtitle": i18n_t(lang, cur_meta["subtitle_key"]),
                    "lore": i18n_t(lang, cur_meta["lore_key"]),
                    "elements": list(cur_meta["elements"]),
                },
                "home": {
                    "key": home_key,
                    "emoji": home_meta["emoji"],
                    "name": i18n_t(lang, home_meta["name_key"]),
                },
                "is_traveling": cur_key != home_key,
                # MV-9 §P6 — ERA UMA MENTIRA VIVA, sem flag nenhuma. A viagem
                # shipou na Onda 4b: as rotas `world/travel` e `world/travel_go`
                # estão registadas, o TravelModal está montado na raiz do app e
                # o `/viajar` existe no chat — mas ESTA tela, a única dedicada a
                # "onde estou", continuava a dizer aos 239 do main que "a
                # mecânica de viagem chega na v16.0b". O MV-9 constrói em cima
                # dela, então a dívida é desta onda (Lei §1).
                "travel_available": True,
                "all_continents": get_all_continents_for_display(lang),
            })
    except Exception as e:
        logger.exception("world/continent_info failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/world/lineage_info ───────────────────────────────────────────
async def api_world_lineage_info(request: web.Request) -> web.Response:
    """READ — v16.1 Sect Lineage: full 9-lineage directory + player's own.

    Returns the locale-resolved meta for all 9 ancestral lineages
    (8 righteous + Abyssal Depths), so the LineageChooserModal can render
    the picker grid. Also embeds the player's current sect lineage (when
    they belong to one) so the modal can mark "your sect" and skip the
    chooser if already set.

    Response shape::

        {
          ok,
          lineages: [{key, emoji, name, philosophy, tier, continent,
                      rival, bonuses[], is_demonic}],
          your_sect: {sect_id, sect_name, lineage_key, can_choose:bool},
          player_is_demonic: bool,
        }

    Lei §1: Abyssal Depths is always listed (with ``is_demonic: true``)
    so non-Demonic players see the option exists, then surface the
    locked badge in the UI — no silent omission.
    """
    from core.sect_lineage_engine import (
        _player_is_demonic,
        get_all_lineages_for_display,
        project_lineage_for_display,
    )
    from core.i18n import t as i18n_t  # noqa: F401  (re-used by display helper)
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            lang = normalize_lang(player.language or "pt")

            # Player's current sect, if any.
            sect_row = (await session.execute(
                select(Sect.id, Sect.name, Sect.lineage_key, SectMember.rank)
                .join(SectMember, SectMember.sect_id == Sect.id)
                .where(SectMember.player_id == user_id)
            )).first()

            your_sect = None
            if sect_row:
                sid, sname, skey, srank = sect_row
                your_sect = {
                    "sect_id": str(sid),
                    "sect_name": sname,
                    "lineage_key": skey,
                    "lineage_meta_resolved": project_lineage_for_display(skey, lang),
                    "rank": srank,
                    # Only master/elder may pick the lineage, and only when
                    # the sect doesn't already have one (irreversible).
                    "can_choose": (srank in ("master", "elder")) and (skey is None),
                }

            is_demonic = await _player_is_demonic(session, user_id)

            return _json({
                "ok": True,
                "lineages": get_all_lineages_for_display(lang),
                "your_sect": your_sect,
                "player_is_demonic": is_demonic,
            })
    except Exception as e:
        logger.exception("world/lineage_info failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/sect/lineage_choose ──────────────────────────────────────────
async def api_sect_lineage_choose(request: web.Request) -> web.Response:
    """WRITE — v16.1 set the sect lineage (master/elder only, irreversible).

    Body: ``{lineage_key: str}``.

    Wraps ``sect_lineage_engine.set_sect_lineage`` which performs:
      • caller rank check (master/elder),
      • demonic gating (Abyssal Depths requires Demonic faction),
      • SAVEPOINT-wrapped write.
    Reasons mapped 1:1 to client-side i18n keys (``invalid_lineage``,
    ``not_in_sect``, ``rank_too_low``, ``demonic_locked``,
    ``lineage_already_set``, ``sect_not_found``).
    """
    from core.sect_engine import get_player_sect_info
    from core.sect_lineage_engine import (
        is_valid_lineage, project_lineage_for_display, set_sect_lineage,
    )
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    lineage_key = payload.get("lineage_key")

    if not isinstance(lineage_key, str) or not is_valid_lineage(lineage_key):
        return _json({"ok": False, "reason": "invalid_lineage"})

    try:
        async with get_session_factory()() as session:
            info = await get_player_sect_info(session, user_id)
            if not info:
                return _json({"ok": False, "reason": "not_in_sect"})

            res = await set_sect_lineage(
                session,
                info["sect"].id,
                lineage_key,
                user_id,
            )
            if not res.get("ok"):
                # Engine returned a structured failure — pass through.
                return _json(res)

            await session.commit()

            # Project the resolved meta so the mini-app can update the
            # SectTab card immediately without a second round-trip.
            player_lang = normalize_lang(
                (await session.execute(
                    select(Player.language).where(Player.telegram_id == user_id)
                )).scalar_one_or_none() or "pt"
            )
            return _json({
                "ok": True,
                "lineage_key": lineage_key,
                "lineage_meta_resolved": project_lineage_for_display(
                    lineage_key, player_lang
                ),
            })
    except Exception as e:
        logger.exception("sect/lineage_choose failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/sect/lineage_status ──────────────────────────────────────────
