# ── /api/miniapp/world/path_info ──────────────────────────────────────────────
async def api_world_path_info(request: web.Request) -> web.Response:
    """READ — v16.2 Path Trinity: full 3-path directory + caller's state.

    Returns localized meta for all three paths (Righteous, Demonic, Rogue)
    so the PathPickModal/PathModal can render the picker grid. Embeds the
    caller's current path (NULL semantically "never picked") and a
    ``can_pick`` flag (true iff player is at ``PATH_PICK_MIN_REALM`` and
    path is NULL).

    Lei §1: Demonic Path always listed (with ``is_demonic: true``) — non-R3
    players see the option exists with the realm gate surfaced rather than
    a silent omission.
    """
    from core.path_engine import (
        PATH_PICK_MIN_REALM,
        get_all_paths_for_display,
        get_player_path,
        get_player_path_raw,
        project_path_for_display,
    )
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            lang = normalize_lang(player.language or "pt")
            current_realm = int(player.realm or 0)
            raw = await get_player_path_raw(session, user_id)
            resolved = await get_player_path(session, user_id)

            return _json({
                "ok": True,
                "paths": get_all_paths_for_display(lang),
                "your_path": {
                    "key": resolved,
                    "raw": raw,
                    "meta": project_path_for_display(resolved, lang),
                    # v16.2: first pick is free; path changes (re-picks)
                    # arrive in v16.3 with the karma cooldown spec.
                    "can_pick": (raw is None) and (current_realm >= PATH_PICK_MIN_REALM),
                    "gate_realm": PATH_PICK_MIN_REALM,
                    "current_realm": current_realm,
                },
            })
    except Exception as e:
        logger.exception("world/path_info failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/path/pick ────────────────────────────────────────────────────
async def api_path_pick(request: web.Request) -> web.Response:
    """DEAD-ROUTE since v16.2.1 (emergent-path pivot).

    Path is no longer player-picked. It emerges from karma + quest choices
    + actions, and crystallizes at R3+ via the v16.3 karma engine. The
    underlying :func:`path_engine.set_player_path` mutator is preserved
    for internal calls from the karma engine; only the *external* HTTP
    surface is closed so the mini-app picker can't bypass the design.

    Returns 410 Gone with a structured reason so any stale client still
    holding the picker UI (cached JS) degrades gracefully instead of
    silently writing.
    """
    return _json({
        "ok": False,
        "reason": "path_emergent_only",
        "hint": "Path emerges from karma + actions; manual pick is disabled.",
    }, status=410)


