# ── /api/miniapp/world/karma_info ─────────────────────────────────────────────
async def api_world_karma_info(request: web.Request) -> web.Response:
    """READ — v16.3 Karma Spine: full karma snapshot for the KarmaModal.

    Returns the player's current karma (value + label + band + emoji),
    the projected gauge data (-1000 ─── 0 ─── +1000 with marker position),
    the divergence flag (true if path+karma diverge), the recent karma
    events log (last 10), and the canonical event catalog for the "What
    changes my karma?" expandable list (Lei §1 honest disclosure).

    Response shape::

        {
          ok,
          karma:    {value, label, label_key, emoji, band, tier_color,
                     tribulation_modifier},
          gauge:    {min, max, value, position_pct},
          path:     {current, raw, crystallized_at_karma|null,
                     divergence: {diverged, threshold, grace_until_ms|null}},
          recent:   [{id, delta, event_type, label, new_value, created_at_ms}],
          catalog:  [{event_key, label, delta, sign}],  # canonical event list
        }
    """
    from core.karma_engine import (
        check_path_divergence,
        get_canonical_events_for_display,
        get_karma,
        get_recent_karma_events,
        project_karma_for_display,
        project_world_reactions,
    )
    from core.i18n import t as i18n_t
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            lang = normalize_lang(player.language or "pt")
            # 2026-05-26 hotfix — read karma + path directly off the loaded
            # `player` row instead of re-querying. Pure helper used here
            # to compute divergence so we keep the same payload shape as
            # `check_path_divergence` (diverged + threshold + current_*).
            from core.karma_engine import _divergence_for_path_and_karma
            karma_value = int(player.karma or 0)
            karma_proj = project_karma_for_display(karma_value, lang)
            _div_pure = _divergence_for_path_and_karma(player.path, karma_value)
            div = {
                "diverged": bool(_div_pure["diverged"]),
                "current_path": player.path,
                "current_karma": karma_value,
                "threshold": _div_pure["threshold"],
            }
            recent = await get_recent_karma_events(session, user_id, limit=10)

            # Project each recent event with its localized label.
            for ev in recent:
                ev_key = ev.get("event_type") or ""
                ev["label"] = i18n_t(lang, f"karma_event_{ev_key}")
                if ev["label"] == f"karma_event_{ev_key}":
                    ev["label"] = ev_key.replace("_", " ").title()

            # Gauge position: 0% = -1000, 50% = 0, 100% = +1000.
            from core.karma_engine import KARMA_MAX, KARMA_MIN
            span = KARMA_MAX - KARMA_MIN
            position_pct = ((karma_value - KARMA_MIN) / span) * 100.0 if span else 50.0

            # Crystallization karma para o card do PathModal.
            # QoL-Feedback 2 2026-07-30 (report [jogador] s2): a heurística
            # antiga lia o KarmaLog mais RECENTE de uma lista de eventos —
            # ou seja, o karma ATUAL rotulado como "cristalizou com karma X"
            # (display-lie: mostrava -970 para um caminho travado muito
            # antes). Agora só a linha `path_crystallized` (snapshot que o
            # crystallize grava) alimenta o card; cristalizações antigas sem
            # snapshot → null → o card NÃO aparece (ausência honesta > mentira).
            crystallization_karma: int | None = None
            try:
                from database.models import KarmaLog
                xl_row = (await session.execute(
                    select(KarmaLog)
                    .where(
                        KarmaLog.player_id == user_id,
                        KarmaLog.event_type == "path_crystallized",
                    )
                    .order_by(desc(KarmaLog.created_at))
                    .limit(1)
                )).scalar_one_or_none()
                if player.path and xl_row is not None:
                    crystallization_karma = int(xl_row.new_value or 0)
            except Exception:
                logger.debug("crystallization_karma lookup failed", exc_info=True)

            out = {
                "ok": True,
                "karma": karma_proj,
                "gauge": {
                    "min": KARMA_MIN,
                    "max": KARMA_MAX,
                    "value": karma_value,
                    "position_pct": round(position_pct, 2),
                },
                "path": {
                    "current": player.path,
                    "raw": player.path,
                    "crystallized_at_karma": crystallization_karma,
                    "divergence": {
                        "diverged": bool(div.get("diverged")),
                        "threshold": div.get("threshold"),
                        "grace_hours": 72,
                    },
                },
                "recent": recent,
                "catalog": get_canonical_events_for_display(lang),
                # Track A item 4 — "O que o mundo vê": current band + distance to
                # the next karmic threshold (crystallize/diverge) + the list of
                # world systems that react to karma (Lei §1 disclosure).
                "world_view": project_world_reactions(karma_value, player.path),
            }
            # TEC-5 — o estado do Rito do Coração-Demônio (key CONDICIONAL: flag
            # OFF ⇒ heart_demon_state devolve {"on": False} SEM query e a key
            # nem entra no payload ⇒ shape byte-idêntico nos mundos vivos).
            try:
                from core.forbidden_path_engine import (
                    heart_demon_state, knobs_payload, sect_cross_preview,
                )
                _hd = await heart_demon_state(session, player)
                if _hd.get("on"):
                    _hd["knobs"] = knobs_payload()
                    _hd["sect_cost"] = await sect_cross_preview(session, player)
                    out["heart_demon"] = _hd
            except Exception:
                logger.debug("karma_info heart_demon block failed", exc_info=True)
            return _json(out)
    except Exception as e:
        logger.exception("world/karma_info failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/world/karma_log ──────────────────────────────────────────────
async def api_world_karma_log(request: web.Request) -> web.Response:
    """READ — paginated karma_log for the KarmaModal drill-in.

    Body: ``{page: int}`` (1-indexed). Returns 10 events per page,
    ordered newest-first. Used when a player wants to scroll back
    through their karmic history (beyond the inline "last 10" shown
    in the main modal).
    """
    from core.karma_engine import get_recent_karma_events
    from core.i18n import t as i18n_t
    from core.utils import normalize_lang
    from database.models import KarmaLog

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        page = max(1, int(payload.get("page") or 1))
    except (TypeError, ValueError):
        page = 1
    per_page = 10
    offset = (page - 1) * per_page

    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            lang = normalize_lang(player.language or "pt")

            total = (await session.execute(
                select(func.count()).select_from(KarmaLog)
                .where(KarmaLog.player_id == user_id)
            )).scalar_one() or 0

            rows = (await session.execute(
                select(KarmaLog)
                .where(KarmaLog.player_id == user_id)
                .order_by(desc(KarmaLog.created_at))
                .offset(offset).limit(per_page)
            )).scalars().all()

            page_data: list[dict] = []
            for row in rows:
                created = row.created_at
                if created is not None and created.tzinfo is None:
                    created = created.replace(tzinfo=timezone.utc)
                ev_key = row.event_type or ""
                label = i18n_t(lang, f"karma_event_{ev_key}")
                if label == f"karma_event_{ev_key}":
                    label = ev_key.replace("_", " ").title()
                page_data.append({
                    "id": int(row.id),
                    "delta": int(row.delta or 0),
                    "new_value": int(row.new_value or 0),
                    "event_type": ev_key,
                    "label": label,
                    "created_at_ms": int(created.timestamp() * 1000) if created else None,
                })

            return _json({
                "ok": True,
                "page": page,
                "per_page": per_page,
                "total": int(total),
                "total_pages": max(1, (int(total) + per_page - 1) // per_page),
                "rows": page_data,
            })
    except Exception as e:
        logger.exception("world/karma_log failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/heart_demon/start ────────────────────────────────────────────
async def api_heart_demon_start(request: web.Request) -> web.Response:
    """WRITE — o Rito do Coração-Demônio 心魔.

    Usado pelo CTA do card de divergência do KarmaModal.

    **TEC-5 (2026-08-03)** deu corpo ao que a v16.3 reservou aqui pelo nome: com
    a flag `forbidden_path` ON este endpoint ABRE o Rito — um duelo PvE
    (`pve_source="heart_demon"`) contra O REFLEXO, o próprio cultivador. Vencer
    não decide nada sozinho: abre a ESCOLHA (⚔️ atravessar / 🧘 reafirmar) em
    ``/heart_demon/choose``.

    Com a flag OFF o comportamento da v16.3 fica INTACTO (a validação de
    divergência, o re-disparo dedup-safe da DM e a janela de graça) — é a
    superfície que os mundos vivos já veem.
    """
    from core.karma_engine import (
        KARMA_DIVERGENCE_GRACE_HOURS,
        apply_path_divergence_notification,
        check_path_divergence,
    )
    from core.forbidden_path_engine import forbidden_on, start_heart_demon_rite

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            # TEC-5 — com a flag ON o GATE é do engine (ele conhece as DUAS
            # portas do Reflexo: a divergência e a profundidade no próprio
            # caminho). Repetir aqui o check de divergência trancaria o Rito
            # para o demoníaco coerente — e com ele o Cofre inteiro.
            if forbidden_on():
                res = await start_heart_demon_rite(session, user_id)
                if res.get("ok"):
                    await session.commit()   # commit SÓ em ok (padrão TEC-3/4)
                return _json({**res, "rite": True})

            div = await check_path_divergence(session, user_id)
            if not div.get("diverged"):
                return _json({"ok": False, "reason": "not_diverged",
                              "current_path": div.get("current_path"),
                              "current_karma": div.get("current_karma")})

            res = await apply_path_divergence_notification(
                session, user_id,
                current_path=div.get("current_path") or "rogue",
                current_karma=int(div.get("current_karma") or 0),
            )
            await session.commit()

            return _json({
                "ok": True,
                "notified": bool(res.get("notified")),
                "grace_until_ms": res.get("grace_until_ms"),
                "grace_hours": KARMA_DIVERGENCE_GRACE_HOURS,
                "current_path": div.get("current_path"),
                "current_karma": int(div.get("current_karma") or 0),
            })
    except Exception as e:
        logger.exception("heart_demon/start failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── /api/miniapp/heart_demon/choose ───────────────────────────────────────────
async def api_heart_demon_choose(request: web.Request) -> web.Response:
    """WRITE (TEC-5) — a ESCOLHA depois de vencer o Reflexo.

    ``choice="cross"`` (⚔️ ATRAVESSAR) re-cristaliza o Caminho para o lado
    divergido — o ÚNICO destrancamento legítimo do one-shot de `players.path` —
    e o rito assume a consistência (a casa incompatível é deixada, com o preço
    −75 dito ANTES). ``choice="stand"`` (🧘 REAFIRMAR) mantém tudo e não custa
    nada. Os dois gravam o registro eterno que abre o Cofre Proibido.
    """
    from core.forbidden_path_engine import choose_heart_demon, forbidden_on

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    choice = str(payload.get("choice") or "").strip()
    try:
        async with get_session_factory()() as session:
            if not forbidden_on():
                return _json({"ok": False, "reason": "fpd_off"})
            res = await choose_heart_demon(session, user_id, choice)
            if res.get("ok"):
                await session.commit()
            return _json(res)
    except Exception as e:
        logger.exception("heart_demon/choose failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


# ── v16.4 — World Sects (9 NPC houses) ───────────────────────────────────────
async def api_world_sect_directory(request: web.Request) -> web.Response:
    """READ — v16.4: the 9 NPC sect directory with per-sect affinity.

    Powers WorldSectDirectoryModal. Each of the 9 houses is projected with its
    name/philosophy/bonuses (server-resolved i18n) PLUS the caller's affinity
    (0–100), the threshold (75), a ``recruitable`` flag, and a ``path_locked``
    flag (affinity == 0 ⇒ hard-gate path mismatch). The affinity is always
    visible (Lei §1 — transparency). Also embeds the caller's current NPC sect
    membership (``your_sect``) for the "you belong to X" banner.
    """
    from core.world_sects_engine import (
        get_all_sects_for_display, get_player_sect_full, project_sect_call,
    )
    from core.affinity_engine import (
        compute_all_affinity_breakdowns, compute_player_actions_signal,
        get_affinity_threshold,
        path_block_reason as _aff_block_reason,
    )
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            lang = normalize_lang(player.language or "pt")
            sects = get_all_sects_for_display(lang)
            # v16.4b — full per-component breakdown (Lei §1: the cultivator sees
            # exactly WHY a house courts them — path / continent / karma /
            # lineage / deeds). Actions signal computed once, fanned to all 9.
            breakdowns = await compute_all_affinity_breakdowns(session, user_id)
            signal = await compute_player_actions_signal(session, user_id)
            threshold = get_affinity_threshold()
            your = await get_player_sect_full(session, user_id, lang)

            # World Pulse Fase 1 — the house's LIVE state (strength/momentum/last
            # action), so the directory shows each house is alive (Lei §1).
            from core.world_pulse_engine import get_sect_pulse_map
            pulse_map = await get_sect_pulse_map(session, lang)

            for s in sects:
                bd = breakdowns.get(s["key"]) or {}
                score = int(bd.get("total", 0))
                s["affinity"] = score
                s["affinity_threshold"] = threshold
                s["recruitable"] = score >= threshold
                s["path_locked"] = not bool(bd.get("path_gate", False))
                # Fix 2026-07-28 (pergunta do jogador [jogador]) — o `path_locked`
                # dizia QUE estava barrado, nunca POR QUÊ nem COMO sair disso.
                # A key só existe quando há bloqueio (condicional — payload
                # inalterado para quem não está barrado).
                _blk = _aff_block_reason(getattr(player, "path", None), s["key"])
                if _blk:
                    s["path_block"] = _blk
                s["breakdown"] = bd
                s["pulse"] = pulse_map.get(s["key"])
                # Pedra 2 — O Chamado: the house's soul-derived invitation text
                # (server-resolved), shown when the cultivator answers in the
                # WorldSectJoinModal. Pure narrative + the affinity score (Lei §1).
                s["call"] = project_sect_call(s["key"], lang, score=score)

            return _json({
                "ok": True,
                "sects": sects,
                "threshold": threshold,
                "your_sect": your,
                "actions_signal": {
                    "righteous": int(signal.get("righteous", 0)),
                    "demonic": int(signal.get("demonic", 0)),
                    "choices": int(signal.get("choices", 0)),
                },
                "realm": int(player.realm or 0),
                "path": player.path,
                "current_continent": player.current_continent,
            })
    except Exception as e:
        logger.exception("world/sect_directory failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_recruiter_pending(request: web.Request) -> web.Response:
    """READ — v16.4: the caller's live (unresolved, unexpired) recruiter encounters."""
    from core.world_sects_engine import project_sect_for_display, project_sect_call
    from core.utils import normalize_lang
    from database.models import WorldSectRecruiterPending

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player_lang = (await session.execute(
                select(Player.language).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            lang = normalize_lang(player_lang or "pt")
            now = datetime.now(timezone.utc)
            rows = (await session.execute(
                select(WorldSectRecruiterPending).where(
                    WorldSectRecruiterPending.player_id == user_id,
                    WorldSectRecruiterPending.accepted_at.is_(None),
                    WorldSectRecruiterPending.declined_at.is_(None),
                    WorldSectRecruiterPending.expires_at > now,
                ).order_by(desc(WorldSectRecruiterPending.affinity_score))
            )).scalars().all()
            pending = [{
                "pending_id": r.id,
                "sect_id": r.sect_id,
                "affinity": int(r.affinity_score),
                "expires_at_ms": int(r.expires_at.timestamp() * 1000) if r.expires_at else None,
                "meta": project_sect_for_display(r.sect_id, lang),
                "call": project_sect_call(r.sect_id, lang, score=int(r.affinity_score or 0)),
            } for r in rows]
            return _json({"ok": True, "pending": pending})
    except Exception as e:
        logger.exception("world/recruiter_pending failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_sect_join_attempt(request: web.Request) -> web.Response:
    """WRITE — v16.4: accept a live recruiter encounter → join the NPC sect.

    Affinity (via the pending encounter) is the ONLY gate — there is no manual
    picker (Lei §2). Body: ``{pending_id}`` OR ``{sect_id}`` to disambiguate
    when several encounters are live; otherwise the highest-affinity live
    encounter is taken. The narrative Sect Trial is a v16.4b stub — for now
    accepting takes the cultivator in as a disciple immediately (Lei §1 — no
    dead-end). Fires Achievement #28 (Sect Heir) via the engine.
    """
    from core.world_sects_engine import join_player_to_sect
    from database.models import WorldSectRecruiterPending

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    pending_id = payload.get("pending_id")
    sect_id = payload.get("sect_id")

    try:
        async with get_session_factory()() as session:
            now = datetime.now(timezone.utc)
            q = select(WorldSectRecruiterPending).where(
                WorldSectRecruiterPending.player_id == user_id,
                WorldSectRecruiterPending.accepted_at.is_(None),
                WorldSectRecruiterPending.declined_at.is_(None),
                WorldSectRecruiterPending.expires_at > now,
            )
            if pending_id is not None:
                try:
                    q = q.where(WorldSectRecruiterPending.id == int(pending_id))
                except (TypeError, ValueError):
                    return _err("bad_request", 400)
            elif isinstance(sect_id, str) and sect_id:
                q = q.where(WorldSectRecruiterPending.sect_id == sect_id)

            pend = (await session.execute(
                q.order_by(desc(WorldSectRecruiterPending.affinity_score)).limit(1)
            )).scalar_one_or_none()
            if not pend:
                return _json({"ok": False, "reason": "recruiter_expired"})

            res = await join_player_to_sect(
                session, user_id, pend.sect_id,
                affinity_score=int(pend.affinity_score or 0),
                source="recruiter_miniapp",
            )
            if res.get("ok"):
                pend.accepted_at = now
                await session.commit()
            return _json(res)
    except Exception as e:
        logger.exception("world/sect_join_attempt failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


async def api_world_sect_trial_start(request: web.Request) -> web.Response:
    """WRITE — v16.4b: face the Elder (the REAL trial).

    Spawns a turn-based duel vs the house Elder (scaled to the cultivator's
    realm) for a live recruiter encounter and returns its ``duel_id`` — the
    client opens the standard ``DuelArenaModal`` to fight it. The outcome
    (join on win, 24h cooldown on loss) is resolved server-side when the duel
    settles. Idempotent: re-calling while a trial is in flight RESUMES the same
    duel. Body: ``{pending_id}`` OR ``{sect_id}`` (else highest-affinity live
    encounter).
    """
    from core.sect_trial_engine import start_sect_trial
    from database.models import WorldSectRecruiterPending

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    pending_id = payload.get("pending_id")
    sect_id = payload.get("sect_id")

    try:
        async with get_session_factory()() as session:
            now = datetime.now(timezone.utc)
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id).with_for_update()
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)

            q = select(WorldSectRecruiterPending).where(
                WorldSectRecruiterPending.player_id == user_id,
                WorldSectRecruiterPending.accepted_at.is_(None),
                WorldSectRecruiterPending.declined_at.is_(None),
                WorldSectRecruiterPending.expires_at > now,
            )
            if pending_id is not None:
                try:
                    q = q.where(WorldSectRecruiterPending.id == int(pending_id))
                except (TypeError, ValueError):
                    return _err("bad_request", 400)
            elif isinstance(sect_id, str) and sect_id:
                q = q.where(WorldSectRecruiterPending.sect_id == sect_id)

            pend = (await session.execute(
                q.order_by(desc(WorldSectRecruiterPending.affinity_score)).limit(1)
            )).scalar_one_or_none()
            if not pend:
                return _json({"ok": False, "reason": "recruiter_expired"})

            res = await start_sect_trial(session, player, pend)
            if res.get("ok"):
                await session.commit()
            return _json(res)
    except Exception as e:
        logger.exception("world/sect_trial_start failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


