async def api_world_sect_hall(request: web.Request) -> web.Response:
    """READ — v16.4c: the Sect Hall (members only).

    One round-trip for the whole interior: rank + contribution-to-next-rank +
    disclosed per-rank perks + the Library (each signature art flagged
    unlocked/learned by rank) + the member-gated Sect Quests (materialized on
    open, serialized like /quests so the same QuestChoiceModal + /quests/claim
    surface handle the moral forks). Non-members get {in_sect: False}.
    """
    from core.utils import normalize_lang
    from core.world_sects_engine import get_sect_hall_state, recompute_player_rank
    from core.quest_engine import ensure_sect_quests, get_player_sect_quests
    from core.i18n import t_optional as _t_opt
    from core import seita as _seita
    from core.portas import onda_on as _onda_on

    user_id: int = request["user_id"]
    try:
        async with get_session_factory()() as session:
            player = (await session.execute(
                select(Player).where(Player.telegram_id == user_id)
            )).scalar_one_or_none()
            if not player:
                return _err("player_not_found", 404)
            lang = normalize_lang(player.language or "pt")

            # 宗 4.1 — o Salão também PROMOVE (o portão de reino que caiu desde a
            # última contribuição): é uma porta que muda o posto, e com a onda a
            # promoção confirmada aqui acende a insígnia como qualquer outra. O
            # "antes" lê-se trancado ANTES do recompute (`core/seita.ler_antes`);
            # o recompute já trancava a linha a cada abertura — nada de novo.
            _antes = await _seita.ler_antes(session, user_id) if _onda_on() else None
            # Promote if a realm gate was cleared since the last contribution gain
            # (no-op for non-members / already-correct rank). Committed below.
            await recompute_player_rank(session, user_id)
            state = await get_sect_hall_state(session, user_id, lang)
            if not state.get("in_sect"):
                return _json({"ok": True, **state, "quests": []})
            _g = await _seita.ganho_da_acao(session, user_id, _antes)

            # Member-gated Sect Quests (materialize then list, same shape as /quests).
            await ensure_sect_quests(session, user_id)
            rows = await get_player_sect_quests(session, user_id)
            # Pedra 2 wave 2 — server-resolve the per-id i18n override so the
            # mini-app receives the Wuxia name/description ready in the player's
            # language (fallback = the stored string; silent for quests without
            # a localized key). Mirrors the chat _render_sect_quests localization.
            quests = [{
                "id": q.id,
                "name": catalog_name(lang, "q", q),
                "type": q.type,
                "emoji": q.emoji or "🏯",
                "description": catalog_desc(lang, "q", q),
                "objective_type": q.objective_type,
                "objective_value": q.objective_value,
                "progress": pq.progress,
                "is_completed": pq.is_completed,
                "claimed": pq.claimed,
                "rewards": q.rewards,
                "choices": q.choices,
                "chosen_choice_id": pq.chosen_choice_id,
            } for pq, q in rows]
            await session.commit()  # ensure_sect_quests may have created rows
            # a escada (o denominador das insígnias) e o ganho: chaves CONDICIONAIS
            # — sem a onda o payload do Salão é o de hoje, chave a chave
            return _json({"ok": True, **state, "quests": quests,
                          **_seita.escada_no_payload(), **_seita.no_payload(_g)})
    except Exception as e:
        logger.exception("world/sect_hall failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


