async def api_world_sect_tribute(request: web.Request) -> web.Response:
    """WRITE — v16.4c: tribute spirit stones for sect contribution (a stone sink
    + agency toward the next rank; auto-promotes if a threshold is crossed).
    Body: ``{stones}`` (the amount offered; only the affordable multiple of the
    tribute rate is consumed). Row-locked in the engine.
    """
    from core.world_sects_engine import tribute_stones
    from core import seita as _seita
    from core.portas import onda_on as _onda_on

    user_id: int = request["user_id"]
    payload = request.get("payload") or {}
    try:
        stones = int(payload.get("stones"))
    except (TypeError, ValueError):
        return _err("bad_request", 400)
    if stones <= 0:
        return _json({"ok": False, "reason": "tribute_too_small"}, status=200)

    try:
        async with get_session_factory()() as session:
            # 宗 4.1 — com a onda, o tributo confirmado leva `seita_ganho` (a
            # contribuição antes→depois e, se cruzou o limiar, o posto que acende).
            # Uma recusa nunca leva ganho.
            _antes = await _seita.ler_antes(session, user_id) if _onda_on() else None
            res = await tribute_stones(session, user_id, stones)
            if res.get("ok"):
                _g = await _seita.ganho_da_acao(session, user_id, _antes)
                await session.commit()
                return _json({**res, **_seita.no_payload(_g)})
            return _json(res)
    except Exception as e:
        logger.exception("world/sect_tribute failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


