async def api_combat_scrolls(request: web.Request) -> web.Response:
    """READ — TEC-2: a arca de pergaminhos + o que cada um VALE (doar/queimar).
    Flag OFF → {"on": False} SEM query (padrão sect_library: o modal dispara no
    mount e o cliente rende o legado quando "on" é falso)."""
    from core.scroll_economy_engine import escassez_on, list_scrolls
    from core.utils import normalize_lang

    user_id: int = request["user_id"]
    if not escassez_on():
        return _json({"ok": True, "on": False})
    try:
        async with get_session_factory()() as session:
            prow = (await session.execute(
                select(Player.language).where(Player.telegram_id == user_id)
            )).first()
            lang = normalize_lang((prow[0] if prow else None) or "pt")
            state = await list_scrolls(session, user_id, lang)
            return _json({"ok": True, **state})
    except Exception as e:
        logger.exception("combat/scrolls failed for user_id=%s", user_id)
        return _json({"ok": False, "reason": "internal_error",
                      "error_class": e.__class__.__name__,
                      "error_msg": str(e)[:200]}, status=200)


