    app.router.add_post("/api/miniapp/world_boss", api_world_boss)
    app.router.add_post("/api/miniapp/announcements", api_announcements)
    app.router.add_post("/api/miniapp/quests", api_quests)
    # Write actions (mutate state, validated by the same HMAC middleware)
