async def start_webserver(port: int = 8080) -> None:
    app = create_app()
    runner = web.AppRunner(app, access_log=None)
    await runner.setup()
    site = web.TCPSite(runner, "0.0.0.0", port)
    await site.start()
    logger.info("🌐 Webserver started on :%d (miniapp + API + website)", port)
